#!/usr/bin/env node
/**
 * FreshFlow POS — workspace generator.
 *
 * Writes the complete project to ./freshflow-pos and, if the `archiver` package is available,
 * also produces freshflow-pos.zip beside it.
 *
 *   node build-zip.js              write the project (and zip it when possible)
 *   node build-zip.js --out ./dir  write it somewhere else
 *   node build-zip.js --no-zip     skip the archive
 *
 * Then follow README.md to install and run.
 */
import { createWriteStream } from 'node:fs';
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';

const args = process.argv.slice(2);
const outIndex = args.indexOf('--out');
const outDir = path.resolve(outIndex === -1 ? '.' : args[outIndex + 1] ?? '.');
const makeZip = !args.includes('--no-zip');
const projectName = 'freshflow-pos';
const projectDir = path.join(outDir, projectName);

const FILES = {
".gitignore": "node_modules/\ndist/\nbuild/\n.env\n.env.local\n.env.*.local\n*.log\nnpm-debug.log*\n.DS_Store\n.vscode/\n.idea/\ncoverage/\n*.tgz\n",
"README.md": "# FreshFlow — grocery POS and back office\n\nA till that keeps selling when the internet drops, and a back office that answers \"how did today go?\"\n\n- **Public site**: landing page, pricing, and sign-up that creates a store with a one-month free trial.\n- **Register** (cashiers and admins): barcode scanning, quick codes, category browsing, weighing-scale support, held bills, cash/UPI/card payment, printed and WhatsApp receipts.\n- **Back office** (admins only): daily business report, category and product analytics, bill ledger with voids, inventory, categories, stock ledger, team management, and billing.\n\nBills completed during an outage are stored on the till and upload on their own once the connection returns. Nothing is lost and nothing is counted twice.\n\n## Multiple stores on one deployment\n\nEvery business is an **organization**. Users, categories, products, bills, stock and settings all belong to one, and every query is filtered by it, so two stores on the same server never see each other's data. Invoice numbers run 1, 2, 3… separately for each store.\n\nAnyone can create a store from `/signup`; the first account becomes its admin. Staff are then invited from Settings › Team, and each active account uses one seat on the plan.\n\n| Route | Who |\n| --- | --- |\n| `/` | Landing page, public |\n| `/pricing` | Plans and seat calculator, public |\n| `/signup` | Create a store, public |\n| `/login` | Sign in |\n| `/app` | Register (cashiers and admins) |\n| `/app/reports`, `/app/inventory`, `/app/billing`, `/app/settings` | Admins only |\n\n## Plans and payment\n\nPrices are per staff account, per month, in rupees:\n\n| Plan | Monthly | Yearly (billed 12 months up front) |\n| --- | --- | --- |\n| Free trial | ₹0 for 30 days, up to 3 users | — |\n| Standard | ₹850, **₹650** after the launch discount | ₹650, **₹550** after the launch discount |\n| Custom | ₹1,300, **₹1,000** after the launch discount | ₹1,000, **₹800** after the launch discount |\n\nChange the catalogue in `server/src/config/plans.js`; the pricing page, the billing page and the amount charged all read from it, so they can never disagree.\n\nPayment goes through **Razorpay**. Set `RAZORPAY_KEY_ID` and `RAZORPAY_KEY_SECRET` in `server/.env` to switch it on; without them the Billing page says payments are not configured and everything else still works. Add a webhook in the Razorpay dashboard pointing at `https://your-api/api/billing/webhook` (events `payment.captured` and `payment.failed`) with `RAZORPAY_WEBHOOK_SECRET` set, so a payment still lands if the customer closes the browser mid-way.\n\nPayments are only trusted after the signature check: the handover from checkout is verified as HMAC-SHA256 of `order_id|payment_id`, and webhooks are verified against the exact raw request body. A forged or replayed signature never changes a plan.\n\n**When a trial or plan ends**, the store keeps its data and cashiers keep billing — queued bills still upload, because they describe sales that already happened. What pauses is adding products, categories and staff, until a plan is chosen in Billing.\n\n## Categories are yours to build\n\nAdmins manage the category tree from Inventory › Categories: add a department such as **Meat**, give it an icon, and add sub-categories such as Poultry or Mutton under it. Cashiers browse those on the register straight away. A category that holds products, sub-categories, or appears on past bills is kept rather than deleted, so old receipts and reports stay accurate.\n\n## Requirements\n\n- Node.js 20.19 or newer\n- PostgreSQL 14 or newer (or Docker, see below)\n\n## Getting started\n\n```bash\n# 1. Install both apps\nnpm run setup\n\n# 2. Start PostgreSQL (skip if you already have one running)\ndocker compose up -d\n\n# 3. Configure the API\ncd server\ncp .env.example .env\n#    Edit .env and set JWT_SECRET to a long random string:\n#    node -e \"console.log(require('crypto').randomBytes(48).toString('hex'))\"\n\n# 4. Create the tables and load the starter catalog\nnpm run db:deploy\nnpm run db:seed\n\n# 5. Configure the web app\ncd ../client\ncp .env.example .env\n\n# 6. Run both (in separate terminals, from the project root)\nnpm run dev:server     # http://localhost:4000\nnpm run dev:client     # http://localhost:5173\n```\n\nOpen http://localhost:5173 and sign in with the accounts printed by the seed:\n\n| Role | Email | Password |\n| --- | --- | --- |\n| Admin | `admin@freshflow.local` | `Admin@12345` |\n| Cashier | `cashier@freshflow.local` | `Cashier@12345` |\n\nChange both passwords after the first sign-in (Settings › Team). The seed only creates accounts that don't already exist, so it is safe to re-run.\n\n## What each role can do\n\n| Area | Cashier | Admin |\n| --- | --- | --- |\n| Register, scanning, scale, held bills, payments | Yes | Yes |\n| Billing and plan changes | No | Yes |\n| Categories | No | Yes |\n| Bill discounts | Up to the configured limit (10% by default) | Any amount |\n| Daily business report and analytics | No | Yes |\n| Bill ledger and voids | No | Yes |\n| Inventory and stock ledger | No | Yes |\n| Store settings and team | No | Yes |\n\nRoles are enforced by the API, not just hidden in the interface: every restricted endpoint checks the role claim on the signed token against the account in the database, so a cashier's token cannot reach a report even if the request is made by hand. Changing someone's role or deactivating them takes effect on their next request.\n\n## How offline selling works\n\n1. A completed bill is written to IndexedDB on the till before anything else. At that point the sale is safe.\n2. The till tries to upload it. If that fails, the bill stays queued and retries on reconnect, every 30 seconds, and whenever the tab regains focus.\n3. Each bill carries a `clientId` generated on the till. The server treats a repeat upload of the same `clientId` as a duplicate and returns the original invoice, so retries never double-count revenue or stock.\n4. The server recalculates every bill from the items and rejects it if the total doesn't match, so a stale price list on a till cannot book the wrong revenue.\n\nThe sync panel (the status pill in any page header) shows what is waiting, what failed and why, and lets you retry or discard individual bills.\n\nMoney is handled as whole paise everywhere, in one shared calculation used by both the till and the server (`client/src/lib/pricing.js` and `server/src/utils/pricing.js` are the same file). Bill discounts are spread across lines with the largest-remainder method, so line amounts always add back up to the bill total exactly.\n\n## Hardware\n\nWeighing scales and receipt printers connect over the Web Serial API, which needs Chrome or Edge on a computer and a secure context (`https://` or `localhost`). Connect them in Settings › Hardware.\n\n- **Scale**: reads continuous output over USB or RS-232 and handles the common formats (`ST,GS,+ 1.250kg`, grams, pounds). Without a scale, the weigh dialog accepts manual entry with tare and ±250 g buttons.\n- **Printer**: prints 80 mm ESC/POS receipts. Without one, the browser print dialog produces the same receipt on any printer.\n\nUPI QR codes are generated on the till from the store's UPI ID (Settings › Payments) using the standard `upi://pay` format, so any UPI app can scan them. Until a UPI ID is set, the payment screen says so and cash or card still work.\n\n## Reports\n\nReports always compare the selected period against the period of equal length immediately before it. Days are the store's local days: set `REPORT_TIMEZONE` in `server/.env` to the store's timezone (`Asia/Kolkata` by default) and the bucketing stays correct regardless of where the server runs.\n\nThe category chart is built for large catalogs. Up to 40 categories it draws labelled rows; beyond that it packs one bar per category into a compact grid on a square-root scale, so a thousand-plus categories stay readable and comparable in a few hundred pixels instead of a thousand table rows. Verified at 1,207 categories, where the query returns in about 120 ms.\n\nTo try that scale yourself:\n\n```bash\ncd server\nSTRESS_CATEGORIES=1200 STRESS_BILLS=4000 npm run db:seed:stress\n```\n\nThat script refuses to run with `NODE_ENV=production`. It writes through the same code path as a real sale, so the numbers it produces are internally consistent.\n\n## Tests\n\n```bash\ncd server && npm test\n```\n\nCovers the bill engine: markdowns, percentage and flat discounts, the discount allocation adding up exactly, GST rounding, and gram-level quantity rounding.\n\n## Deploying\n\nBuild the web app and serve `client/dist` as static files:\n\n```bash\ncd client && npm run build\n```\n\nPoint the web server at the API under `/api` (the same-origin setup the app expects), or set `VITE_API_URL` at build time if the API lives elsewhere. On the API set `NODE_ENV=production`, a `JWT_SECRET` of at least 32 characters, `CORS_ORIGIN` to the site's URL, and `TRUST_PROXY=true` behind nginx or a load balancer. Run migrations with `npm run db:deploy`.\n\nThe web app registers a service worker in production builds so a till can reload during an outage and still open.\n\n## Regenerating the project\n\n`build-zip.js` contains the whole workspace inline. Running it writes a fresh copy of every file:\n\n```bash\nnode build-zip.js                # writes ./freshflow-pos (and a zip if `archiver` is installed)\nnode build-zip.js --out ./target # write it somewhere else\nnode build-zip.js --no-zip       # skip the archive\n```\n\nIt never touches `node_modules`, `dist` or your `.env`, so it is a clean way to restore a file you edited by accident.\n\n## Project layout\n\n```\nserver/\n  prisma/schema.prisma        Database schema\n  prisma/migrations/          SQL migrations\n  prisma/seed.js              Store profile, accounts, catalog\n  prisma/stress-seed.js       Load-test data generator\n  src/routes/                 HTTP endpoints, one file per resource\n  src/services/               Bill ingest, voids, reporting queries\n  src/middleware/auth.js      Token verification and role checks\n  src/utils/pricing.js        Bill calculation (shared with the client)\nclient/\n  src/pages/                  Register, reports, inventory, settings, login\n  src/components/pos/         Cart, scale, payment, receipt, held bills\n  src/components/charts/      Trend, payment split, category density\n  src/lib/sync.js             Outbox queue and upload engine\n  src/lib/idb.js              IndexedDB wrapper\n  src/store/                  Zustand stores\n```\n\n## Notes\n\n- The starter catalog uses Unsplash image URLs. If they are blocked or slow on your network, products fall back to a lettered tile; replace the URLs in Settings or per product.\n- Deactivating a product hides it from tills but keeps it on past bills, so old receipts and reports stay accurate. The same applies to categories that appear on past bills.\n- Voiding a bill returns its items to stock and records the reason against it; nothing is deleted.\n",
"docker-compose.yml": "# Local PostgreSQL for development.\n# Start it with:  docker compose up -d\n# The default DATABASE_URL in server/.env.example points at this container.\nservices:\n  db:\n    image: postgres:16-alpine\n    container_name: freshflow-db\n    restart: unless-stopped\n    environment:\n      POSTGRES_USER: postgres\n      POSTGRES_PASSWORD: postgres\n      POSTGRES_DB: freshflow\n    ports:\n      - '5432:5432'\n    volumes:\n      - freshflow-db-data:/var/lib/postgresql/data\n    healthcheck:\n      test: ['CMD-SHELL', 'pg_isready -U postgres -d freshflow']\n      interval: 5s\n      timeout: 5s\n      retries: 10\n\nvolumes:\n  freshflow-db-data:\n",
"package.json": "{\n  \"name\": \"freshflow-pos\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"description\": \"FreshFlow — grocery POS terminal and back office\",\n  \"scripts\": {\n    \"setup\": \"npm --prefix server install && npm --prefix client install\",\n    \"db:deploy\": \"npm --prefix server run db:deploy\",\n    \"db:seed\": \"npm --prefix server run db:seed\",\n    \"dev:server\": \"npm --prefix server run dev\",\n    \"dev:client\": \"npm --prefix client run dev\",\n    \"build\": \"npm --prefix client run build\",\n    \"test\": \"npm --prefix server test\"\n  }\n}\n",
"server/.env.example": "# PostgreSQL connection\nDATABASE_URL=\"postgresql://postgres:postgres@localhost:5432/freshflow\"\nDB_POOL_MAX=10\n\n# API\nPORT=4000\nNODE_ENV=development\n# Comma-separated list of allowed browser origins\nCORS_ORIGIN=\"http://localhost:5173\"\n# Set to true when running behind a reverse proxy (nginx, load balancer)\nTRUST_PROXY=false\n\n# Auth — use a long random string in production (min 32 chars), e.g. `openssl rand -hex 48`\nJWT_SECRET=\"replace-with-a-long-random-secret-at-least-32-characters\"\nJWT_EXPIRES_IN=\"12h\"\n\n# Reports bucket sales by this IANA timezone (store's local day)\nREPORT_TIMEZONE=\"Asia/Kolkata\"\n\n# Public address of the web app, used in links\nAPP_URL=\"http://localhost:5173\"\n\n# Razorpay — leave blank to run without online payments (the Billing page says so plainly).\n# Keys: Razorpay Dashboard → Settings → API Keys\nRAZORPAY_KEY_ID=\"\"\nRAZORPAY_KEY_SECRET=\"\"\n# Webhook secret: Dashboard → Settings → Webhooks, pointing at https://your-api/api/billing/webhook\n# with the payment.captured and payment.failed events selected\nRAZORPAY_WEBHOOK_SECRET=\"\"\n\n# Initial accounts created by `npm run db:seed` (change after first sign-in)\nSEED_ADMIN_NAME=\"Store Admin\"\nSEED_ADMIN_EMAIL=\"admin@freshflow.local\"\nSEED_ADMIN_PASSWORD=\"Admin@12345\"\nSEED_CASHIER_NAME=\"Front Desk Cashier\"\nSEED_CASHIER_EMAIL=\"cashier@freshflow.local\"\nSEED_CASHIER_PASSWORD=\"Cashier@12345\"\n# Optional: your real UPI ID so checkout QR codes work immediately\nSEED_UPI_VPA=\"\"\n",
"server/.gitignore": "node_modules/\ndist/\nbuild/\n.env\n.env.local\n.env.*.local\n*.log\nnpm-debug.log*\n.DS_Store\n.vscode/\n.idea/\ncoverage/\n*.tgz\n",
"server/package.json": "{\n  \"name\": \"freshflow-server\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"description\": \"FreshFlow Grocery POS & ERP API (Express + Prisma + PostgreSQL)\",\n  \"type\": \"module\",\n  \"main\": \"src/index.js\",\n  \"engines\": {\n    \"node\": \">=20.19.0\"\n  },\n  \"scripts\": {\n    \"dev\": \"node --watch src/index.js\",\n    \"start\": \"node src/index.js\",\n    \"postinstall\": \"prisma generate\",\n    \"db:generate\": \"prisma generate\",\n    \"db:migrate\": \"prisma migrate dev\",\n    \"db:deploy\": \"prisma migrate deploy\",\n    \"db:seed\": \"node prisma/seed.js\",\n    \"db:seed:stress\": \"node prisma/stress-seed.js\",\n    \"test\": \"node --test tests/pricing.test.js tests/billing.test.js\"\n  },\n  \"dependencies\": {\n    \"@prisma/adapter-pg\": \"7.10.0\",\n    \"@prisma/client\": \"7.10.0\",\n    \"bcryptjs\": \"^2.4.3\",\n    \"compression\": \"^1.7.5\",\n    \"cors\": \"^2.8.5\",\n    \"dotenv\": \"^16.4.7\",\n    \"express\": \"^4.21.2\",\n    \"express-rate-limit\": \"^7.5.0\",\n    \"helmet\": \"^8.0.0\",\n    \"jsonwebtoken\": \"^9.0.2\",\n    \"morgan\": \"^1.10.0\",\n    \"pg\": \"^8.13.1\",\n    \"zod\": \"^3.24.1\"\n  },\n  \"devDependencies\": {\n    \"prisma\": \"7.10.0\"\n  }\n}\n",
"server/prisma.config.ts": "import 'dotenv/config';\nimport { defineConfig } from 'prisma/config';\n\nexport default defineConfig({\n  schema: 'prisma/schema.prisma',\n  migrations: {\n    path: 'prisma/migrations',\n    seed: 'node prisma/seed.js',\n  },\n  datasource: {\n    // `prisma generate` does not need a live database, so allow it to run without one.\n    url: process.env.DATABASE_URL ?? '',\n  },\n});\n",
"server/prisma/schema.prisma": "// FreshFlow — multi-tenant grocery POS & ERP\n// Prisma ORM 7 (Rust-free client via @prisma/adapter-pg)\n//\n// Every business record belongs to an Organization (one retail business). All queries are\n// scoped by organizationId so two stores on the same deployment can never see each other's data.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  CASHIER\n  ADMIN\n}\n\nenum PaymentMethod {\n  CASH\n  UPI\n  CARD\n}\n\nenum TransactionStatus {\n  COMPLETED\n  VOIDED\n}\n\nenum StockMovementType {\n  SALE\n  VOID\n  RESTOCK\n  ADJUSTMENT\n}\n\nenum PlanTier {\n  TRIAL\n  STANDARD\n  CUSTOM\n}\n\nenum BillingInterval {\n  MONTHLY\n  YEARLY\n}\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELLED\n  EXPIRED\n}\n\nenum PaymentStatus {\n  CREATED\n  PAID\n  FAILED\n}\n\n/// One retail business. Everything else hangs off this.\nmodel Organization {\n  id             String            @id @default(uuid())\n  name           String\n  slug           String            @unique\n  /// Per-organization invoice counter, so each store's bills start at 1\n  invoiceSeq     Int               @default(0) @map(\"invoice_seq\")\n  createdAt      DateTime          @default(now()) @map(\"created_at\")\n  updatedAt      DateTime          @updatedAt @map(\"updated_at\")\n  users          User[]\n  categories     Category[]\n  products       Product[]\n  transactions   Transaction[]\n  stockMovements StockMovement[]\n  settings       StoreSetting?\n  subscription   Subscription?\n  payments       Payment[]\n\n  @@map(\"organizations\")\n}\n\nmodel Subscription {\n  id                String             @id @default(uuid())\n  organizationId    String             @unique @map(\"organization_id\")\n  organization      Organization       @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  plan              PlanTier           @default(TRIAL)\n  interval          BillingInterval    @default(MONTHLY)\n  /// Number of staff accounts the plan pays for\n  seats             Int                @default(3)\n  status            SubscriptionStatus @default(TRIALING)\n  pricePerUser      Decimal            @default(0) @map(\"price_per_user\") @db.Decimal(10, 2)\n  currency          String             @default(\"INR\")\n  trialEndsAt       DateTime?          @map(\"trial_ends_at\")\n  currentPeriodEnd  DateTime?          @map(\"current_period_end\")\n  razorpayOrderId   String?            @map(\"razorpay_order_id\")\n  razorpayPaymentId String?            @map(\"razorpay_payment_id\")\n  lastPaymentAt     DateTime?          @map(\"last_payment_at\")\n  createdAt         DateTime           @default(now()) @map(\"created_at\")\n  updatedAt         DateTime           @updatedAt @map(\"updated_at\")\n\n  @@map(\"subscriptions\")\n}\n\nmodel Payment {\n  id                String          @id @default(uuid())\n  organizationId    String          @map(\"organization_id\")\n  organization      Organization    @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  plan              PlanTier\n  interval          BillingInterval\n  seats             Int\n  amount            Decimal         @db.Decimal(12, 2)\n  currency          String          @default(\"INR\")\n  status            PaymentStatus   @default(CREATED)\n  razorpayOrderId   String          @unique @map(\"razorpay_order_id\")\n  razorpayPaymentId String?         @map(\"razorpay_payment_id\")\n  failureReason     String?         @map(\"failure_reason\")\n  createdAt         DateTime        @default(now()) @map(\"created_at\")\n  updatedAt         DateTime        @updatedAt @map(\"updated_at\")\n\n  @@index([organizationId, createdAt])\n  @@map(\"payments\")\n}\n\nmodel User {\n  id             String        @id @default(uuid())\n  organizationId String        @map(\"organization_id\")\n  organization   Organization  @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  name           String\n  email          String        @unique\n  passwordHash   String        @map(\"password_hash\")\n  role           Role          @default(CASHIER)\n  isActive       Boolean       @default(true) @map(\"is_active\")\n  createdAt      DateTime      @default(now()) @map(\"created_at\")\n  updatedAt      DateTime      @updatedAt @map(\"updated_at\")\n  transactions   Transaction[]\n\n  @@index([organizationId])\n  @@map(\"users\")\n}\n\n/// Two-level tree: departments (parentId = null) and their sub-categories. Admins manage these.\nmodel Category {\n  id             String            @id @default(uuid())\n  organizationId String            @map(\"organization_id\")\n  organization   Organization      @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  name           String\n  slug           String\n  icon           String?\n  sortOrder      Int               @default(0) @map(\"sort_order\")\n  parentId       String?           @map(\"parent_id\")\n  parent         Category?         @relation(\"CategoryTree\", fields: [parentId], references: [id], onDelete: SetNull)\n  children       Category[]        @relation(\"CategoryTree\")\n  products       Product[]\n  soldItems      TransactionItem[]\n  createdAt      DateTime          @default(now()) @map(\"created_at\")\n  updatedAt      DateTime          @updatedAt @map(\"updated_at\")\n\n  @@unique([organizationId, slug])\n  @@index([parentId])\n  @@map(\"categories\")\n}\n\nmodel Product {\n  id                String            @id @default(uuid())\n  organizationId    String            @map(\"organization_id\")\n  organization      Organization      @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  code              String\n  barcode           String?\n  name              String\n  description       String?\n  categoryId        String            @map(\"category_id\")\n  category          Category          @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n  price             Decimal           @db.Decimal(12, 2)\n  unit              String            @default(\"pcs\")\n  soldByWeight      Boolean           @default(false) @map(\"sold_by_weight\")\n  stock             Decimal           @default(0) @db.Decimal(14, 3)\n  lowStockThreshold Decimal           @default(5) @map(\"low_stock_threshold\") @db.Decimal(14, 3)\n  discountPercent   Decimal           @default(0) @map(\"discount_percent\") @db.Decimal(5, 2)\n  isQuickKey        Boolean           @default(false) @map(\"is_quick_key\")\n  imageUrl          String?           @map(\"image_url\")\n  isActive          Boolean           @default(true) @map(\"is_active\")\n  createdAt         DateTime          @default(now()) @map(\"created_at\")\n  updatedAt         DateTime          @updatedAt @map(\"updated_at\")\n  soldItems         TransactionItem[]\n  stockMovements    StockMovement[]\n\n  @@unique([organizationId, code])\n  @@unique([organizationId, barcode])\n  @@index([organizationId, name])\n  @@index([categoryId])\n  @@map(\"products\")\n}\n\nmodel Transaction {\n  id             String            @id @default(uuid())\n  organizationId String            @map(\"organization_id\")\n  organization   Organization      @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  /// Generated on the terminal; makes offline sync idempotent\n  clientId       String            @unique @map(\"client_id\")\n  /// Sequential within the organization\n  invoiceNo      Int               @map(\"invoice_no\")\n  terminalId     String            @map(\"terminal_id\")\n  cashierId      String            @map(\"cashier_id\")\n  cashier        User              @relation(fields: [cashierId], references: [id], onDelete: Restrict)\n  syncedById     String?           @map(\"synced_by_id\")\n  status         TransactionStatus @default(COMPLETED)\n  paymentMethod  PaymentMethod     @map(\"payment_method\")\n  customerPhone  String?           @map(\"customer_phone\")\n  subtotal       Decimal           @db.Decimal(12, 2)\n  itemDiscount   Decimal           @map(\"item_discount\") @db.Decimal(12, 2)\n  billDiscount   Decimal           @map(\"bill_discount\") @db.Decimal(12, 2)\n  discountReason String?           @map(\"discount_reason\")\n  taxRate        Decimal           @map(\"tax_rate\") @db.Decimal(5, 2)\n  taxableAmount  Decimal           @map(\"taxable_amount\") @db.Decimal(12, 2)\n  taxTotal       Decimal           @map(\"tax_total\") @db.Decimal(12, 2)\n  grandTotal     Decimal           @map(\"grand_total\") @db.Decimal(12, 2)\n  amountTendered Decimal?          @map(\"amount_tendered\") @db.Decimal(12, 2)\n  changeDue      Decimal?          @map(\"change_due\") @db.Decimal(12, 2)\n  wasOffline     Boolean           @default(false) @map(\"was_offline\")\n  soldAt         DateTime          @map(\"sold_at\")\n  syncedAt       DateTime          @default(now()) @map(\"synced_at\")\n  voidedAt       DateTime?         @map(\"voided_at\")\n  voidedById     String?           @map(\"voided_by_id\")\n  voidReason     String?           @map(\"void_reason\")\n  items          TransactionItem[]\n\n  @@unique([organizationId, invoiceNo])\n  @@index([organizationId, soldAt])\n  @@index([cashierId, soldAt])\n  @@map(\"transactions\")\n}\n\nmodel TransactionItem {\n  id                String      @id @default(uuid())\n  transactionId     String      @map(\"transaction_id\")\n  transaction       Transaction @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  productId         String      @map(\"product_id\")\n  product           Product     @relation(fields: [productId], references: [id], onDelete: Restrict)\n  categoryId        String      @map(\"category_id\")\n  category          Category    @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n  productName       String      @map(\"product_name\")\n  productCode       String      @map(\"product_code\")\n  unit              String\n  soldByWeight      Boolean     @map(\"sold_by_weight\")\n  quantity          Decimal     @db.Decimal(14, 3)\n  unitPrice         Decimal     @map(\"unit_price\") @db.Decimal(12, 2)\n  discountPercent   Decimal     @map(\"discount_percent\") @db.Decimal(5, 2)\n  lineSubtotal      Decimal     @map(\"line_subtotal\") @db.Decimal(12, 2)\n  lineDiscount      Decimal     @map(\"line_discount\") @db.Decimal(12, 2)\n  billDiscountShare Decimal     @map(\"bill_discount_share\") @db.Decimal(12, 2)\n  netAmount         Decimal     @map(\"net_amount\") @db.Decimal(12, 2)\n\n  @@index([transactionId])\n  @@index([productId])\n  @@index([categoryId])\n  @@map(\"transaction_items\")\n}\n\nmodel StockMovement {\n  id             String            @id @default(uuid())\n  organizationId String            @map(\"organization_id\")\n  organization   Organization      @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  productId      String            @map(\"product_id\")\n  product        Product           @relation(fields: [productId], references: [id], onDelete: Cascade)\n  type           StockMovementType\n  quantity       Decimal           @db.Decimal(14, 3)\n  reason         String?\n  referenceId    String?           @map(\"reference_id\")\n  userId         String?           @map(\"user_id\")\n  createdAt      DateTime          @default(now()) @map(\"created_at\")\n\n  @@index([productId, createdAt])\n  @@map(\"stock_movements\")\n}\n\nmodel StoreSetting {\n  id                    String       @id @default(uuid())\n  organizationId        String       @unique @map(\"organization_id\")\n  organization          Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  storeName             String       @map(\"store_name\")\n  tagline               String?\n  gstin                 String?\n  address               String?\n  phone                 String?\n  upiVpa                String?      @map(\"upi_vpa\")\n  upiPayeeName          String?      @map(\"upi_payee_name\")\n  currency              String       @default(\"INR\")\n  taxRate               Decimal      @default(5) @map(\"tax_rate\") @db.Decimal(5, 2)\n  maxCashierDiscountPct Decimal      @default(10) @map(\"max_cashier_discount_pct\") @db.Decimal(5, 2)\n  receiptFooter         String?      @map(\"receipt_footer\")\n  updatedAt             DateTime     @updatedAt @map(\"updated_at\")\n\n  @@map(\"store_settings\")\n}\n",
"server/prisma/seed.js": "/**\n * Seeds the production baseline: store profile, the two role accounts, the category tree and\n * the product catalog from the store blueprint. Safe to re-run (upserts; never touches sales).\n */\nimport 'dotenv/config';\nimport bcrypt from 'bcryptjs';\nimport { PrismaPg } from '@prisma/adapter-pg';\nimport { PrismaClient } from '@prisma/client';\n\nconst prisma = new PrismaClient({ adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL }) });\n\nconst img = (id) => `https://images.unsplash.com/${id}?auto=format&fit=crop&w=400&q=80`;\n\nconst CATEGORY_TREE = [\n  {\n    slug: 'fresh-produce', name: 'Fresh Produce', icon: '🥦', sortOrder: 1,\n    children: [\n      { slug: 'fresh-produce-fruits', name: 'Fruits', icon: '🍎', sortOrder: 1 },\n      { slug: 'fresh-produce-leafy-greens', name: 'Leafy Greens & Herbs', icon: '🥬', sortOrder: 2 },\n      { slug: 'fresh-produce-vegetables', name: 'Vegetables', icon: '🥕', sortOrder: 3 },\n    ],\n  },\n  { slug: 'dairy-bakery', name: 'Dairy & Bakery', icon: '🥛', sortOrder: 2 },\n  { slug: 'grains-staples', name: 'Grains & Staples', icon: '🌾', sortOrder: 3 },\n  { slug: 'snacks-drinks', name: 'Snacks & Drinks', icon: '🥨', sortOrder: 4 },\n  { slug: 'stationery-supplies', name: 'Stationery & Supplies', icon: '✏️', sortOrder: 5 },\n];\n\n// [code, name, categorySlug, barcode, price, unit, soldByWeight, stock, discount%, quickKey, image]\nconst PRODUCTS = [\n  ['101', 'Crisp Washington Apples', 'fresh-produce-fruits', '890123450001', 160, 'kg', true, 42.5, 0, true, 'photo-1560806887-1e4cd0b6cbd6'],\n  ['102', 'Organic Cavendish Bananas', 'fresh-produce-fruits', '890123450002', 48, 'kg', true, 28, 20, true, 'photo-1571771894821-ce9b6c11b08e'],\n  ['103', 'Farm Fresh Roma Tomatoes', 'fresh-produce-vegetables', '890123450003', 35, 'kg', true, 65, 0, true, 'photo-1592924357228-91a4daadcfea'],\n  ['104', 'Hass Avocados (Pack of 2)', 'fresh-produce-fruits', '890123450004', 190, 'pack', false, 15, 0, false, 'photo-1523049673857-eb18f1d7b578'],\n  ['105', 'Nagpur Sweet Oranges', 'fresh-produce-fruits', '890123450013', 80, 'kg', true, 35, 0, false, 'photo-1582979512210-99b6a53386f9'],\n  ['106', 'Ruby Red Pomegranate', 'fresh-produce-fruits', '890123450014', 175, 'kg', true, 22, 0, false, 'photo-1541344999736-83eca872f240'],\n  ['107', 'Fresh Hydroponic Spinach (Palak)', 'fresh-produce-leafy-greens', '890123450015', 30, 'bunch', false, 40, 0, true, 'photo-1576045057995-568f588f82fb'],\n  ['108', 'Organic Coriander Leaves (Dhaniya)', 'fresh-produce-leafy-greens', '890123450016', 20, 'bunch', false, 50, 0, true, 'photo-1588879462719-75702ee61586'],\n  ['109', 'Aromatic Fresh Mint (Pudina)', 'fresh-produce-leafy-greens', '890123450017', 15, 'bunch', false, 35, 0, false, 'photo-1628556270448-4d4e4148e1b1'],\n  ['110', 'Fresh Fenugreek Leaves (Methi)', 'fresh-produce-leafy-greens', '890123450018', 25, 'bunch', false, 30, 0, false, 'photo-1540420773420-3366772f4999'],\n  ['111', 'Nashik Red Onions', 'fresh-produce-vegetables', '890123450019', 38, 'kg', true, 80, 0, true, 'photo-1618512496248-a07fe83aa8cb'],\n  ['112', 'Farm Fresh Jyoti Potatoes', 'fresh-produce-vegetables', '890123450020', 30, 'kg', true, 95, 0, false, 'photo-1518977676601-b53f82aba655'],\n  ['113', 'Crisp English Cucumbers', 'fresh-produce-vegetables', '890123450021', 42, 'kg', true, 30, 0, false, 'photo-1604977042946-1eecc30f269e'],\n  ['114', 'Fresh Crunchy Carrots', 'fresh-produce-vegetables', '890123450022', 48, 'kg', true, 45, 0, false, 'photo-1598170845058-32b9d6a5da37'],\n  ['201', 'Farm Pasteurized Whole Milk (1L)', 'dairy-bakery', '890123450005', 68, 'pouch', false, 50, 0, true, 'photo-1563636619-e9143da7973b'],\n  ['202', 'Whole Wheat Sliced Bread (400g)', 'dairy-bakery', '890123450006', 45, 'pack', false, 24, 20, false, 'photo-1509440159596-0249088772ff'],\n  ['301', 'Royal Basmati Rice (5kg)', 'grains-staples', '890123450007', 540, 'bag', false, 30, 0, true, 'photo-1586201375761-83865001e31c'],\n  ['302', 'Organic Yellow Toor Dal (1kg)', 'grains-staples', '890123450008', 165, 'pack', false, 40, 0, false, 'photo-1546069901-ba9599a7e63c'],\n  ['401', 'Classic Potato Chips (150g)', 'snacks-drinks', '890123450009', 50, 'pack', false, 60, 0, false, 'photo-1566478989037-eec170784d0b'],\n  ['601', 'Hardbound Spiral Notebook (180 pgs)', 'stationery-supplies', '890123450010', 85, 'pcs', false, 35, 0, true, 'photo-1544716278-ca5e3f4abd8c'],\n  ['602', 'Quick-Dry Gel Pens (Pack of 5)', 'stationery-supplies', '890123450011', 120, 'pack', false, 50, 0, false, 'photo-1585336261026-8f5786372966'],\n  ['603', 'Pastel Sticky Notes (400 Sheets)', 'stationery-supplies', '890123450012', 65, 'pcs', false, 45, 0, false, 'photo-1586075010923-2dd4570fb338'],\n];\n\nasync function upsertUser(organizationId, name, email, password, role) {\n  const existing = await prisma.user.findUnique({ where: { email } });\n  if (existing) return { user: existing, created: false };\n  const user = await prisma.user.create({\n    data: { organizationId, name, email: email.toLowerCase(), role, passwordHash: await bcrypt.hash(password, 12) },\n  });\n  return { user, created: true };\n}\n\nconst TRIAL_DAYS = 30;\n\nasync function main() {\n  const env = process.env;\n\n  const organization = await prisma.organization.upsert({\n    where: { slug: 'freshflow-supermarket' },\n    update: {},\n    create: { name: 'FreshFlow Supermarket', slug: 'freshflow-supermarket' },\n  });\n  const organizationId = organization.id;\n\n  await prisma.subscription.upsert({\n    where: { organizationId },\n    update: {},\n    create: {\n      organizationId,\n      plan: 'TRIAL',\n      interval: 'MONTHLY',\n      seats: 3,\n      status: 'TRIALING',\n      pricePerUser: '0.00',\n      trialEndsAt: new Date(Date.now() + TRIAL_DAYS * 86_400_000),\n      currentPeriodEnd: new Date(Date.now() + TRIAL_DAYS * 86_400_000),\n    },\n  });\n\n  await prisma.storeSetting.upsert({\n    where: { organizationId },\n    update: {},\n    create: {\n      organizationId,\n      storeName: 'FreshFlow Supermarket',\n      tagline: 'Fresh quality, daily low prices',\n      gstin: '29AAAAA0000A1Z5',\n      address: '123 Retail Hub, MG Road, Bengaluru 560001',\n      phone: '+91 98765 43210',\n      upiVpa: env.SEED_UPI_VPA || null,\n      upiPayeeName: 'FreshFlow Supermarket',\n      taxRate: 5,\n      maxCashierDiscountPct: 10,\n      receiptFooter: 'Returns accepted within 7 days with this bill.',\n    },\n  });\n\n  const admin = await upsertUser(organizationId, env.SEED_ADMIN_NAME || 'Store Admin', env.SEED_ADMIN_EMAIL || 'admin@freshflow.local', env.SEED_ADMIN_PASSWORD || 'Admin@12345', 'ADMIN');\n  const cashier = await upsertUser(organizationId, env.SEED_CASHIER_NAME || 'Front Desk Cashier', env.SEED_CASHIER_EMAIL || 'cashier@freshflow.local', env.SEED_CASHIER_PASSWORD || 'Cashier@12345', 'CASHIER');\n\n  const categoryIds = {};\n  for (const top of CATEGORY_TREE) {\n    const { children = [], ...data } = top;\n    const parent = await prisma.category.upsert({\n      where: { organizationId_slug: { organizationId, slug: data.slug } },\n      update: {},\n      create: { ...data, organizationId },\n    });\n    categoryIds[data.slug] = parent.id;\n    for (const child of children) {\n      const c = await prisma.category.upsert({\n        where: { organizationId_slug: { organizationId, slug: child.slug } },\n        update: {},\n        create: { ...child, organizationId, parentId: parent.id },\n      });\n      categoryIds[child.slug] = c.id;\n    }\n  }\n\n  let createdProducts = 0;\n  for (const [code, name, slug, barcode, price, unit, soldByWeight, stock, discountPercent, isQuickKey, image] of PRODUCTS) {\n    const exists = await prisma.product.findUnique({\n      where: { organizationId_code: { organizationId, code } },\n      select: { id: true },\n    });\n    if (exists) continue;\n    await prisma.product.create({\n      data: {\n        organizationId,\n        code, name, barcode, unit, soldByWeight, isQuickKey,\n        categoryId: categoryIds[slug],\n        price: price.toFixed(2),\n        stock: stock.toFixed(3),\n        lowStockThreshold: soldByWeight ? '10.000' : '8.000',\n        discountPercent: discountPercent.toFixed(2),\n        imageUrl: img(image),\n        stockMovements: {\n          create: { organizationId, type: 'RESTOCK', quantity: stock.toFixed(3), reason: 'Opening stock', userId: admin.user.id },\n        },\n      },\n    });\n    createdProducts += 1;\n  }\n\n  console.log('Seed complete');\n  console.log(`  Store   ${organization.name} (30-day free trial, 3 seats)`);\n  console.log(`  Admin   ${admin.user.email}${admin.created ? `  (password: ${env.SEED_ADMIN_PASSWORD || 'Admin@12345'})` : '  (already existed)'}`);\n  console.log(`  Cashier ${cashier.user.email}${cashier.created ? `  (password: ${env.SEED_CASHIER_PASSWORD || 'Cashier@12345'})` : '  (already existed)'}`);\n  console.log(`  Products created: ${createdProducts} of ${PRODUCTS.length}`);\n  if (admin.created || cashier.created) console.log('  Change these passwords after first sign-in.');\n}\n\nmain()\n  .catch((err) => {\n    console.error(err);\n    process.exitCode = 1;\n  })\n  .finally(() => prisma.$disconnect());\n",
"server/prisma/stress-seed.js": "/**\n * LOAD-TEST DATA GENERATOR — not for production databases.\n * Creates N extra sub-categories (default 1,200) each with one product, then rings up bills over the\n * last 60 days through the real ingest service, so reports/charts can be verified at 1K+ categories.\n *\n *   STRESS_CATEGORIES=1200 STRESS_BILLS=4000 npm run db:seed:stress\n */\nimport 'dotenv/config';\nimport { prisma } from '../src/lib/prisma.js';\nimport { ingestTransaction } from '../src/services/transaction.service.js';\nimport { getSettings } from '../src/services/settings.service.js';\nimport { computeBill, fromPaise } from '../src/utils/pricing.js';\n\nif (process.env.NODE_ENV === 'production') {\n  console.error('Refusing to generate load-test data with NODE_ENV=production');\n  process.exit(1);\n}\n\nconst CATEGORY_COUNT = Number(process.env.STRESS_CATEGORIES || 1200);\nconst BILL_COUNT = Number(process.env.STRESS_BILLS || 4000);\nconst DAYS = 60;\n\nlet seed = 42;\nconst rand = () => ((seed = (seed * 16807) % 2147483647) - 1) / 2147483646;\nconst pick = (arr) => arr[Math.floor(rand() * arr.length)];\n\nasync function main() {\n  const admin = await prisma.user.findFirst({ where: { role: 'ADMIN', isActive: true }, orderBy: { createdAt: 'asc' } });\n  if (!admin) throw new Error('Run `npm run db:seed` first');\n  const organizationId = admin.organizationId;\n  const settings = await getSettings(organizationId, { fresh: true });\n\n  const dept = await prisma.category.upsert({\n    where: { organizationId_slug: { organizationId, slug: 'load-test-lines' } },\n    update: {},\n    create: { organizationId, slug: 'load-test-lines', name: 'Load-test lines', icon: '🧪', sortOrder: 99 },\n  });\n\n  const existing = await prisma.category.count({ where: { parentId: dept.id } });\n  for (let i = existing; i < CATEGORY_COUNT; i += 1) {\n    const n = String(i + 1).padStart(4, '0');\n    const cat = await prisma.category.create({\n      data: { organizationId, slug: `load-test-${n}`, name: `Line ${n}`, parentId: dept.id, sortOrder: i },\n    });\n    await prisma.product.create({\n      data: {\n        organizationId,\n        code: `LT${n}`,\n        name: `Load-test item ${n}`,\n        categoryId: cat.id,\n        price: (10 + Math.floor(rand() * 490)).toFixed(2),\n        unit: 'pcs',\n        stock: '100000.000',\n      },\n    });\n  }\n  console.log(`Categories ready: ${CATEGORY_COUNT}`);\n\n  const products = await prisma.product.findMany({ where: { organizationId, isActive: true }, select: { id: true, price: true, soldByWeight: true, discountPercent: true } });\n  // Skewed popularity so the Pareto view looks like a real store.\n  const weighted = products.flatMap((p, idx) => Array(Math.max(1, Math.round(40 / (1 + idx / 25)))).fill(p));\n\n  for (let b = 0; b < BILL_COUNT; b += 1) {\n    const lines = Array.from({ length: 1 + Math.floor(rand() * 6) }, () => {\n      const p = pick(weighted);\n      return {\n        productId: p.id,\n        quantity: p.soldByWeight ? Math.round((0.25 + rand() * 2) * 1000) / 1000 : 1 + Math.floor(rand() * 3),\n        unitPrice: Number(p.price),\n        discountPercent: Number(p.discountPercent),\n      };\n    });\n    const soldAt = new Date(Date.now() - rand() * DAYS * 86_400_000);\n    const billDiscount = { type: 'PERCENT', value: rand() < 0.1 ? 5 : 0 };\n    const bill = computeBill({ items: lines, billDiscount, taxRate: Number(settings.taxRate) });\n    const result = await ingestTransaction(\n      {\n        clientId: crypto.randomUUID(),\n        terminalId: 'LOADTEST',\n        soldAt: soldAt.toISOString(),\n        paymentMethod: pick(['UPI', 'UPI', 'CASH', 'CARD']),\n        taxRate: Number(settings.taxRate),\n        billDiscount,\n        grandTotal: fromPaise(bill.grandTotal),\n        items: lines,\n      },\n      admin,\n      settings,\n    );\n    if (result.status === 'rejected') throw new Error(result.error.message);\n    if ((b + 1) % 500 === 0) console.log(`Bills: ${b + 1}/${BILL_COUNT}`);\n  }\n  console.log('Load-test data ready');\n}\n\nmain()\n  .catch((err) => {\n    console.error(err);\n    process.exitCode = 1;\n  })\n  .finally(() => prisma.$disconnect());\n",
"server/prisma/migrations/migration_lock.toml": "# Please do not edit this file manually\n# It should be added in your version-control system (e.g., Git)\nprovider = \"postgresql\"\n",
"server/prisma/migrations/20260919000000_init/migration.sql": "-- CreateEnum\nCREATE TYPE \"Role\" AS ENUM ('CASHIER', 'ADMIN');\n\n-- CreateEnum\nCREATE TYPE \"PaymentMethod\" AS ENUM ('CASH', 'UPI', 'CARD');\n\n-- CreateEnum\nCREATE TYPE \"TransactionStatus\" AS ENUM ('COMPLETED', 'VOIDED');\n\n-- CreateEnum\nCREATE TYPE \"StockMovementType\" AS ENUM ('SALE', 'VOID', 'RESTOCK', 'ADJUSTMENT');\n\n-- CreateEnum\nCREATE TYPE \"PlanTier\" AS ENUM ('TRIAL', 'STANDARD', 'CUSTOM');\n\n-- CreateEnum\nCREATE TYPE \"BillingInterval\" AS ENUM ('MONTHLY', 'YEARLY');\n\n-- CreateEnum\nCREATE TYPE \"SubscriptionStatus\" AS ENUM ('TRIALING', 'ACTIVE', 'PAST_DUE', 'CANCELLED', 'EXPIRED');\n\n-- CreateEnum\nCREATE TYPE \"PaymentStatus\" AS ENUM ('CREATED', 'PAID', 'FAILED');\n\n-- CreateTable\nCREATE TABLE \"organizations\" (\n    \"id\" TEXT NOT NULL,\n    \"name\" TEXT NOT NULL,\n    \"slug\" TEXT NOT NULL,\n    \"invoice_seq\" INTEGER NOT NULL DEFAULT 0,\n    \"created_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updated_at\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"organizations_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"subscriptions\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"plan\" \"PlanTier\" NOT NULL DEFAULT 'TRIAL',\n    \"interval\" \"BillingInterval\" NOT NULL DEFAULT 'MONTHLY',\n    \"seats\" INTEGER NOT NULL DEFAULT 3,\n    \"status\" \"SubscriptionStatus\" NOT NULL DEFAULT 'TRIALING',\n    \"price_per_user\" DECIMAL(10,2) NOT NULL DEFAULT 0,\n    \"currency\" TEXT NOT NULL DEFAULT 'INR',\n    \"trial_ends_at\" TIMESTAMP(3),\n    \"current_period_end\" TIMESTAMP(3),\n    \"razorpay_order_id\" TEXT,\n    \"razorpay_payment_id\" TEXT,\n    \"last_payment_at\" TIMESTAMP(3),\n    \"created_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updated_at\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"subscriptions_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"payments\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"plan\" \"PlanTier\" NOT NULL,\n    \"interval\" \"BillingInterval\" NOT NULL,\n    \"seats\" INTEGER NOT NULL,\n    \"amount\" DECIMAL(12,2) NOT NULL,\n    \"currency\" TEXT NOT NULL DEFAULT 'INR',\n    \"status\" \"PaymentStatus\" NOT NULL DEFAULT 'CREATED',\n    \"razorpay_order_id\" TEXT NOT NULL,\n    \"razorpay_payment_id\" TEXT,\n    \"failure_reason\" TEXT,\n    \"created_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updated_at\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"payments_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"users\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"name\" TEXT NOT NULL,\n    \"email\" TEXT NOT NULL,\n    \"password_hash\" TEXT NOT NULL,\n    \"role\" \"Role\" NOT NULL DEFAULT 'CASHIER',\n    \"is_active\" BOOLEAN NOT NULL DEFAULT true,\n    \"created_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updated_at\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"users_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"categories\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"name\" TEXT NOT NULL,\n    \"slug\" TEXT NOT NULL,\n    \"icon\" TEXT,\n    \"sort_order\" INTEGER NOT NULL DEFAULT 0,\n    \"parent_id\" TEXT,\n    \"created_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updated_at\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"categories_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"products\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"code\" TEXT NOT NULL,\n    \"barcode\" TEXT,\n    \"name\" TEXT NOT NULL,\n    \"description\" TEXT,\n    \"category_id\" TEXT NOT NULL,\n    \"price\" DECIMAL(12,2) NOT NULL,\n    \"unit\" TEXT NOT NULL DEFAULT 'pcs',\n    \"sold_by_weight\" BOOLEAN NOT NULL DEFAULT false,\n    \"stock\" DECIMAL(14,3) NOT NULL DEFAULT 0,\n    \"low_stock_threshold\" DECIMAL(14,3) NOT NULL DEFAULT 5,\n    \"discount_percent\" DECIMAL(5,2) NOT NULL DEFAULT 0,\n    \"is_quick_key\" BOOLEAN NOT NULL DEFAULT false,\n    \"image_url\" TEXT,\n    \"is_active\" BOOLEAN NOT NULL DEFAULT true,\n    \"created_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updated_at\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"products_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"transactions\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"client_id\" TEXT NOT NULL,\n    \"invoice_no\" INTEGER NOT NULL,\n    \"terminal_id\" TEXT NOT NULL,\n    \"cashier_id\" TEXT NOT NULL,\n    \"synced_by_id\" TEXT,\n    \"status\" \"TransactionStatus\" NOT NULL DEFAULT 'COMPLETED',\n    \"payment_method\" \"PaymentMethod\" NOT NULL,\n    \"customer_phone\" TEXT,\n    \"subtotal\" DECIMAL(12,2) NOT NULL,\n    \"item_discount\" DECIMAL(12,2) NOT NULL,\n    \"bill_discount\" DECIMAL(12,2) NOT NULL,\n    \"discount_reason\" TEXT,\n    \"tax_rate\" DECIMAL(5,2) NOT NULL,\n    \"taxable_amount\" DECIMAL(12,2) NOT NULL,\n    \"tax_total\" DECIMAL(12,2) NOT NULL,\n    \"grand_total\" DECIMAL(12,2) NOT NULL,\n    \"amount_tendered\" DECIMAL(12,2),\n    \"change_due\" DECIMAL(12,2),\n    \"was_offline\" BOOLEAN NOT NULL DEFAULT false,\n    \"sold_at\" TIMESTAMP(3) NOT NULL,\n    \"synced_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"voided_at\" TIMESTAMP(3),\n    \"voided_by_id\" TEXT,\n    \"void_reason\" TEXT,\n\n    CONSTRAINT \"transactions_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"transaction_items\" (\n    \"id\" TEXT NOT NULL,\n    \"transaction_id\" TEXT NOT NULL,\n    \"product_id\" TEXT NOT NULL,\n    \"category_id\" TEXT NOT NULL,\n    \"product_name\" TEXT NOT NULL,\n    \"product_code\" TEXT NOT NULL,\n    \"unit\" TEXT NOT NULL,\n    \"sold_by_weight\" BOOLEAN NOT NULL,\n    \"quantity\" DECIMAL(14,3) NOT NULL,\n    \"unit_price\" DECIMAL(12,2) NOT NULL,\n    \"discount_percent\" DECIMAL(5,2) NOT NULL,\n    \"line_subtotal\" DECIMAL(12,2) NOT NULL,\n    \"line_discount\" DECIMAL(12,2) NOT NULL,\n    \"bill_discount_share\" DECIMAL(12,2) NOT NULL,\n    \"net_amount\" DECIMAL(12,2) NOT NULL,\n\n    CONSTRAINT \"transaction_items_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"stock_movements\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"product_id\" TEXT NOT NULL,\n    \"type\" \"StockMovementType\" NOT NULL,\n    \"quantity\" DECIMAL(14,3) NOT NULL,\n    \"reason\" TEXT,\n    \"reference_id\" TEXT,\n    \"user_id\" TEXT,\n    \"created_at\" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n\n    CONSTRAINT \"stock_movements_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateTable\nCREATE TABLE \"store_settings\" (\n    \"id\" TEXT NOT NULL,\n    \"organization_id\" TEXT NOT NULL,\n    \"store_name\" TEXT NOT NULL,\n    \"tagline\" TEXT,\n    \"gstin\" TEXT,\n    \"address\" TEXT,\n    \"phone\" TEXT,\n    \"upi_vpa\" TEXT,\n    \"upi_payee_name\" TEXT,\n    \"currency\" TEXT NOT NULL DEFAULT 'INR',\n    \"tax_rate\" DECIMAL(5,2) NOT NULL DEFAULT 5,\n    \"max_cashier_discount_pct\" DECIMAL(5,2) NOT NULL DEFAULT 10,\n    \"receipt_footer\" TEXT,\n    \"updated_at\" TIMESTAMP(3) NOT NULL,\n\n    CONSTRAINT \"store_settings_pkey\" PRIMARY KEY (\"id\")\n);\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"organizations_slug_key\" ON \"organizations\"(\"slug\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"subscriptions_organization_id_key\" ON \"subscriptions\"(\"organization_id\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"payments_razorpay_order_id_key\" ON \"payments\"(\"razorpay_order_id\");\n\n-- CreateIndex\nCREATE INDEX \"payments_organization_id_created_at_idx\" ON \"payments\"(\"organization_id\", \"created_at\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"users_email_key\" ON \"users\"(\"email\");\n\n-- CreateIndex\nCREATE INDEX \"users_organization_id_idx\" ON \"users\"(\"organization_id\");\n\n-- CreateIndex\nCREATE INDEX \"categories_parent_id_idx\" ON \"categories\"(\"parent_id\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"categories_organization_id_slug_key\" ON \"categories\"(\"organization_id\", \"slug\");\n\n-- CreateIndex\nCREATE INDEX \"products_organization_id_name_idx\" ON \"products\"(\"organization_id\", \"name\");\n\n-- CreateIndex\nCREATE INDEX \"products_category_id_idx\" ON \"products\"(\"category_id\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"products_organization_id_code_key\" ON \"products\"(\"organization_id\", \"code\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"products_organization_id_barcode_key\" ON \"products\"(\"organization_id\", \"barcode\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"transactions_client_id_key\" ON \"transactions\"(\"client_id\");\n\n-- CreateIndex\nCREATE INDEX \"transactions_organization_id_sold_at_idx\" ON \"transactions\"(\"organization_id\", \"sold_at\");\n\n-- CreateIndex\nCREATE INDEX \"transactions_cashier_id_sold_at_idx\" ON \"transactions\"(\"cashier_id\", \"sold_at\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"transactions_organization_id_invoice_no_key\" ON \"transactions\"(\"organization_id\", \"invoice_no\");\n\n-- CreateIndex\nCREATE INDEX \"transaction_items_transaction_id_idx\" ON \"transaction_items\"(\"transaction_id\");\n\n-- CreateIndex\nCREATE INDEX \"transaction_items_product_id_idx\" ON \"transaction_items\"(\"product_id\");\n\n-- CreateIndex\nCREATE INDEX \"transaction_items_category_id_idx\" ON \"transaction_items\"(\"category_id\");\n\n-- CreateIndex\nCREATE INDEX \"stock_movements_product_id_created_at_idx\" ON \"stock_movements\"(\"product_id\", \"created_at\");\n\n-- CreateIndex\nCREATE UNIQUE INDEX \"store_settings_organization_id_key\" ON \"store_settings\"(\"organization_id\");\n\n-- AddForeignKey\nALTER TABLE \"subscriptions\" ADD CONSTRAINT \"subscriptions_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"payments\" ADD CONSTRAINT \"payments_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"users\" ADD CONSTRAINT \"users_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"categories\" ADD CONSTRAINT \"categories_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"categories\" ADD CONSTRAINT \"categories_parent_id_fkey\" FOREIGN KEY (\"parent_id\") REFERENCES \"categories\"(\"id\") ON DELETE SET NULL ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"products\" ADD CONSTRAINT \"products_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"products\" ADD CONSTRAINT \"products_category_id_fkey\" FOREIGN KEY (\"category_id\") REFERENCES \"categories\"(\"id\") ON DELETE RESTRICT ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"transactions\" ADD CONSTRAINT \"transactions_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"transactions\" ADD CONSTRAINT \"transactions_cashier_id_fkey\" FOREIGN KEY (\"cashier_id\") REFERENCES \"users\"(\"id\") ON DELETE RESTRICT ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"transaction_items\" ADD CONSTRAINT \"transaction_items_transaction_id_fkey\" FOREIGN KEY (\"transaction_id\") REFERENCES \"transactions\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"transaction_items\" ADD CONSTRAINT \"transaction_items_product_id_fkey\" FOREIGN KEY (\"product_id\") REFERENCES \"products\"(\"id\") ON DELETE RESTRICT ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"transaction_items\" ADD CONSTRAINT \"transaction_items_category_id_fkey\" FOREIGN KEY (\"category_id\") REFERENCES \"categories\"(\"id\") ON DELETE RESTRICT ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"stock_movements\" ADD CONSTRAINT \"stock_movements_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"stock_movements\" ADD CONSTRAINT \"stock_movements_product_id_fkey\" FOREIGN KEY (\"product_id\") REFERENCES \"products\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n\n-- AddForeignKey\nALTER TABLE \"store_settings\" ADD CONSTRAINT \"store_settings_organization_id_fkey\" FOREIGN KEY (\"organization_id\") REFERENCES \"organizations\"(\"id\") ON DELETE CASCADE ON UPDATE CASCADE;\n",
"server/src/app.js": "import compression from 'compression';\nimport cors from 'cors';\nimport express from 'express';\nimport helmet from 'helmet';\nimport morgan from 'morgan';\nimport { env } from './config/env.js';\nimport { prisma } from './lib/prisma.js';\nimport { authenticate } from './middleware/auth.js';\nimport { errorHandler, notFoundHandler } from './middleware/error.js';\nimport authRoutes from './routes/auth.routes.js';\nimport billingRoutes, { webhookRouter } from './routes/billing.routes.js';\nimport publicRoutes from './routes/public.routes.js';\nimport categoryRoutes from './routes/categories.routes.js';\nimport productRoutes from './routes/products.routes.js';\nimport reportRoutes from './routes/reports.routes.js';\nimport settingsRoutes from './routes/settings.routes.js';\nimport transactionRoutes from './routes/transactions.routes.js';\nimport userRoutes from './routes/users.routes.js';\n\nexport function createApp() {\n  const app = express();\n\n  app.disable('x-powered-by');\n  if (env.trustProxy) app.set('trust proxy', 1);\n\n  app.use(helmet());\n  app.use(\n    cors({\n      origin(origin, callback) {\n        // Same-origin requests and non-browser clients send no Origin header.\n        if (!origin || env.corsOrigins.includes(origin)) return callback(null, true);\n        return callback(null, false);\n      },\n      methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],\n      allowedHeaders: ['Authorization', 'Content-Type'],\n      maxAge: 600,\n    }),\n  );\n  app.use(compression());\n  app.use(morgan(env.isProd ? 'combined' : 'dev'));\n\n  // The Razorpay webhook is signed over the exact bytes of the request, so it must be\n  // mounted with its own raw-body parser before the JSON parser touches anything.\n  app.use('/api/billing', webhookRouter);\n\n  app.use(express.json({ limit: '1mb' }));\n\n  const api = express.Router();\n\n  api.get('/health', async (_req, res) => {\n    try {\n      await prisma.$queryRaw`SELECT 1`;\n      res.json({ status: 'ok', database: 'up', time: new Date().toISOString() });\n    } catch {\n      res.status(503).json({ status: 'degraded', database: 'down', time: new Date().toISOString() });\n    }\n  });\n\n  api.use('/auth', authRoutes);\n  // Marketing site, pricing and sign-up: no session required.\n  api.use('/public', publicRoutes);\n  // Billing handles its own authentication (the webhook above is public).\n  api.use('/billing', billingRoutes);\n\n  // Everything below requires a valid session; each router declares which roles may use it.\n  api.use(authenticate);\n  api.use('/settings', settingsRoutes);\n  api.use('/categories', categoryRoutes);\n  api.use('/products', productRoutes);\n  api.use('/transactions', transactionRoutes);\n  api.use('/reports', reportRoutes);\n  api.use('/users', userRoutes);\n\n  app.use('/api', api);\n  app.use(notFoundHandler);\n  app.use(errorHandler);\n\n  return app;\n}\n",
"server/src/index.js": "import { env } from './config/env.js';\nimport { prisma } from './lib/prisma.js';\nimport { createApp } from './app.js';\n\nconst app = createApp();\n\nconst server = app.listen(env.port, () => {\n  console.log(`FreshFlow API listening on http://localhost:${env.port} (${env.nodeEnv}, reports in ${env.reportTimezone})`);\n});\n\nasync function shutdown(signal) {\n  console.log(`${signal} received — closing server`);\n  server.close(async () => {\n    await prisma.$disconnect();\n    process.exit(0);\n  });\n  setTimeout(() => process.exit(1), 10_000).unref();\n}\n\nprocess.on('SIGINT', () => shutdown('SIGINT'));\nprocess.on('SIGTERM', () => shutdown('SIGTERM'));\nprocess.on('unhandledRejection', (reason) => {\n  console.error('Unhandled promise rejection:', reason);\n});\n",
"server/src/config/env.js": "import 'dotenv/config';\n\nfunction required(name) {\n  const value = process.env[name];\n  if (!value) throw new Error(`Missing required environment variable: ${name}`);\n  return value;\n}\n\nfunction validTimezone(tz) {\n  try {\n    new Intl.DateTimeFormat('en-US', { timeZone: tz });\n    return tz;\n  } catch {\n    throw new Error(`REPORT_TIMEZONE \"${tz}\" is not a valid IANA timezone`);\n  }\n}\n\nconst nodeEnv = process.env.NODE_ENV || 'development';\nconst jwtSecret = required('JWT_SECRET');\n\nif (nodeEnv === 'production' && jwtSecret.length < 32) {\n  throw new Error('JWT_SECRET must be at least 32 characters in production');\n}\n\nexport const env = Object.freeze({\n  nodeEnv,\n  isProd: nodeEnv === 'production',\n  port: Number(process.env.PORT || 4000),\n  databaseUrl: required('DATABASE_URL'),\n  dbPoolMax: Number(process.env.DB_POOL_MAX || 10),\n  jwtSecret,\n  jwtExpiresIn: process.env.JWT_EXPIRES_IN || '12h',\n  corsOrigins: (process.env.CORS_ORIGIN || 'http://localhost:5173')\n    .split(',')\n    .map((s) => s.trim())\n    .filter(Boolean),\n  trustProxy: process.env.TRUST_PROXY === 'true',\n  reportTimezone: validTimezone(process.env.REPORT_TIMEZONE || 'Asia/Kolkata'),\n  appUrl: process.env.APP_URL || 'http://localhost:5173',\n  razorpayKeyId: process.env.RAZORPAY_KEY_ID || '',\n  razorpayKeySecret: process.env.RAZORPAY_KEY_SECRET || '',\n  razorpayWebhookSecret: process.env.RAZORPAY_WEBHOOK_SECRET || '',\n});\n",
"server/src/config/plans.js": "/**\n * Subscription catalogue. Prices are per user, per month, in INR.\n * `listPrice` is the published rate and `price` is what is actually charged today;\n * the difference is shown to the customer as the launch discount.\n *\n * Yearly plans are charged for 12 months up front at the lower monthly rate.\n */\nexport const TRIAL_DAYS = 30;\nexport const TRIAL_SEATS = 3;\nexport const MIN_SEATS = 1;\nexport const MAX_SEATS = 500;\n\nexport const PLANS = Object.freeze({\n  STANDARD: {\n    tier: 'STANDARD',\n    name: 'Standard',\n    blurb: 'Everything a single store needs to sell and stay on top of stock.',\n    features: [\n      'Unlimited bills and products',\n      'Offline selling with automatic sync',\n      'Barcode scanning and weighing scale',\n      'Daily business report and analytics',\n      'Inventory and stock ledger',\n      'UPI, cash and card payments',\n      'Email support',\n    ],\n    intervals: {\n      MONTHLY: { listPrice: 850, price: 650 },\n      YEARLY: { listPrice: 650, price: 550 },\n    },\n  },\n  CUSTOM: {\n    tier: 'CUSTOM',\n    name: 'Custom',\n    blurb: 'For chains and larger teams that need tailoring and priority help.',\n    features: [\n      'Everything in Standard',\n      'Custom categories, fields and receipt layout',\n      'Multiple registers and higher seat counts',\n      'Priority onboarding and data migration',\n      'Custom reports on request',\n      'Priority support',\n    ],\n    intervals: {\n      MONTHLY: { listPrice: 1300, price: 1000 },\n      YEARLY: { listPrice: 1000, price: 800 },\n    },\n  },\n});\n\nexport const isValidPlan = (tier, interval) => Boolean(PLANS[tier]?.intervals?.[interval]);\n\n/** Months charged up front for an interval. */\nexport const monthsFor = (interval) => (interval === 'YEARLY' ? 12 : 1);\n\n/**\n * What a subscription costs right now.\n * @returns {{pricePerUser:number, listPricePerUser:number, months:number, seats:number, total:number, listTotal:number, savings:number}}\n */\nexport function quote({ plan, interval, seats }) {\n  if (!isValidPlan(plan, interval)) throw new Error(`Unknown plan ${plan}/${interval}`);\n  const seatCount = Math.max(MIN_SEATS, Math.min(MAX_SEATS, Math.floor(Number(seats) || 0)));\n  const { price, listPrice } = PLANS[plan].intervals[interval];\n  const months = monthsFor(interval);\n  return {\n    plan,\n    interval,\n    seats: seatCount,\n    months,\n    pricePerUser: price,\n    listPricePerUser: listPrice,\n    total: price * seatCount * months,\n    listTotal: listPrice * seatCount * months,\n    savings: (listPrice - price) * seatCount * months,\n  };\n}\n\n/** Plain catalogue for the public pricing page. */\nexport const publicPlans = () => ({\n  trial: { days: TRIAL_DAYS, seats: TRIAL_SEATS },\n  currency: 'INR',\n  plans: Object.values(PLANS).map((p) => ({\n    tier: p.tier,\n    name: p.name,\n    blurb: p.blurb,\n    features: p.features,\n    intervals: p.intervals,\n  })),\n});\n",
"server/src/middleware/auth.js": "import jwt from 'jsonwebtoken';\nimport { env } from '../config/env.js';\nimport { prisma } from '../lib/prisma.js';\nimport { HttpError } from '../utils/http.js';\n\nexport const ROLES = Object.freeze({ CASHIER: 'CASHIER', ADMIN: 'ADMIN' });\n\nconst ISSUER = 'freshflow-pos';\nconst AUDIENCE = 'freshflow-pos-client';\n\nexport function signToken(user) {\n  return jwt.sign({ role: user.role, name: user.name, org: user.organizationId }, env.jwtSecret, {\n    subject: user.id,\n    issuer: ISSUER,\n    audience: AUDIENCE,\n    algorithm: 'HS256',\n    expiresIn: env.jwtExpiresIn,\n  });\n}\n\n/*\n * A signed token proves who the user was at sign-in. To make role changes and deactivations\n * take effect before the token expires, the claim is re-checked against the database,\n * cached briefly so busy terminals don't add a query to every request.\n */\nconst USER_CACHE_TTL_MS = 30_000;\nconst userCache = new Map();\n\nexport function invalidateUserCache(userId) {\n  userCache.delete(userId);\n}\n\nasync function loadAccount(userId) {\n  const hit = userCache.get(userId);\n  if (hit && hit.expires > Date.now()) return hit.account;\n  const account = await prisma.user.findUnique({\n    where: { id: userId },\n    select: {\n      id: true,\n      name: true,\n      role: true,\n      isActive: true,\n      organizationId: true,\n      organization: { select: { id: true, name: true, slug: true, subscription: true } },\n    },\n  });\n  userCache.set(userId, { account, expires: Date.now() + USER_CACHE_TTL_MS });\n  return account;\n}\n\nexport async function authenticate(req, _res, next) {\n  const [scheme, token] = (req.headers.authorization || '').split(' ');\n  if (scheme !== 'Bearer' || !token) {\n    return next(new HttpError(401, 'Sign in to continue', 'UNAUTHENTICATED'));\n  }\n\n  let claims;\n  try {\n    claims = jwt.verify(token, env.jwtSecret, { algorithms: ['HS256'], issuer: ISSUER, audience: AUDIENCE });\n  } catch (err) {\n    const message = err.name === 'TokenExpiredError' ? 'Your session has expired. Sign in again.' : 'Your session is not valid. Sign in again.';\n    return next(new HttpError(401, message, 'UNAUTHENTICATED'));\n  }\n\n  if (!claims.sub || !Object.values(ROLES).includes(claims.role)) {\n    return next(new HttpError(401, 'Your session is not valid. Sign in again.', 'UNAUTHENTICATED'));\n  }\n\n  try {\n    const account = await loadAccount(claims.sub);\n    if (!account || !account.isActive) {\n      return next(new HttpError(401, 'This account has been deactivated', 'ACCOUNT_DISABLED'));\n    }\n    if (account.role !== claims.role) {\n      return next(new HttpError(401, 'Your role has changed. Sign in again.', 'ROLE_CHANGED'));\n    }\n    if (claims.org && claims.org !== account.organizationId) {\n      return next(new HttpError(401, 'Your session is not valid. Sign in again.', 'UNAUTHENTICATED'));\n    }\n    req.user = {\n      id: account.id,\n      name: account.name,\n      role: account.role,\n      organizationId: account.organizationId,\n    };\n    req.organization = account.organization;\n    req.subscription = account.organization?.subscription ?? null;\n    return next();\n  } catch (err) {\n    return next(err);\n  }\n}\n\n/** Allow only the listed roles, based on the verified role claim. */\nexport const authorize = (...allowedRoles) => (req, _res, next) => {\n  if (!req.user) return next(new HttpError(401, 'Sign in to continue', 'UNAUTHENTICATED'));\n  if (!allowedRoles.includes(req.user.role)) {\n    return next(new HttpError(403, 'Your role does not have access to this area', 'FORBIDDEN'));\n  }\n  return next();\n};\n",
"server/src/middleware/error.js": "import { ZodError } from 'zod';\nimport { HttpError } from '../utils/http.js';\n\nfunction uniqueFields(err) {\n  const target = err.meta?.target ?? err.meta?.driverAdapterError?.cause?.constraint?.fields;\n  if (Array.isArray(target)) return target.join(', ');\n  if (typeof target === 'string') return target;\n  // Driver adapters report the index name, e.g. \"products_code_key\" → \"code\"\n  const index = err.meta?.driverAdapterError?.cause?.constraint?.index;\n  const table = err.meta?.driverAdapterError?.cause?.table;\n  if (typeof index === 'string') {\n    return index.replace(new RegExp(`^${table ?? '[a-z]+'}_`), '').replace(/_key$/, '').replace(/_/g, ' ');\n  }\n  return 'value';\n}\n\nexport function notFoundHandler(req, res) {\n  res.status(404).json({ error: { code: 'NOT_FOUND', message: `No endpoint for ${req.method} ${req.originalUrl}` } });\n}\n\n// eslint-disable-next-line no-unused-vars\nexport function errorHandler(err, req, res, next) {\n  if (res.headersSent) return next(err);\n\n  if (err instanceof ZodError) {\n    const first = err.issues[0];\n    const where = first?.path?.length ? `${first.path.join('.')}: ` : '';\n    return res.status(400).json({\n      error: {\n        code: 'VALIDATION_ERROR',\n        message: `${where}${first?.message ?? 'Invalid input'}`,\n        details: err.issues.map((i) => ({ path: i.path.join('.'), message: i.message })),\n      },\n    });\n  }\n\n  if (err instanceof HttpError) {\n    return res.status(err.status).json({ error: { code: err.code, message: err.message, details: err.details } });\n  }\n\n  if (err?.type === 'entity.parse.failed') {\n    return res.status(400).json({ error: { code: 'INVALID_JSON', message: 'Request body is not valid JSON' } });\n  }\n  if (err?.type === 'entity.too.large') {\n    return res.status(413).json({ error: { code: 'PAYLOAD_TOO_LARGE', message: 'Request body is too large' } });\n  }\n\n  switch (err?.code) {\n    case 'P2002':\n      return res.status(409).json({ error: { code: 'CONFLICT', message: `Another record already uses this ${uniqueFields(err)}` } });\n    case 'P2003':\n      return res.status(409).json({ error: { code: 'IN_USE', message: 'This record is referenced by other data and cannot be changed that way' } });\n    case 'P2025':\n      return res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Record not found' } });\n    default:\n      break;\n  }\n\n  console.error(`[${req.method} ${req.originalUrl}]`, err);\n  return res.status(500).json({ error: { code: 'INTERNAL', message: 'Unexpected server error' } });\n}\n",
"server/src/middleware/subscription.js": "import { subscriptionActive } from '../services/billing.service.js';\nimport { HttpError } from '../utils/http.js';\n\n/**\n * Blocks work that adds data once a trial or paid period has lapsed, while leaving\n * sign-in, billing and read-only screens reachable so the store can pay and carry on.\n * Bills already queued on a till are never rejected for this reason — they describe\n * sales that already happened.\n */\nexport function requireActiveSubscription(req, _res, next) {\n  if (subscriptionActive(req.subscription)) return next();\n  const isAdmin = req.user?.role === 'ADMIN';\n  return next(\n    new HttpError(\n      402,\n      isAdmin\n        ? 'Your subscription has ended. Choose a plan in Billing to carry on.'\n        : 'This store’s subscription has ended. Ask the store admin to renew it.',\n      'SUBSCRIPTION_REQUIRED',\n    ),\n  );\n}\n",
"server/src/middleware/validate.js": "/** Parse and replace req.params / req.query / req.body with zod-validated values. */\nexport const validate = (schemas) => (req, _res, next) => {\n  try {\n    for (const key of ['params', 'query', 'body']) {\n      if (schemas[key]) req[key] = schemas[key].parse(req[key] ?? {});\n    }\n    next();\n  } catch (err) {\n    next(err);\n  }\n};\n",
"server/src/services/billing.service.js": "import crypto from 'node:crypto';\nimport { env } from '../config/env.js';\nimport { MAX_SEATS, MIN_SEATS, monthsFor, PLANS, quote, TRIAL_DAYS, TRIAL_SEATS } from '../config/plans.js';\nimport { prisma } from '../lib/prisma.js';\nimport { HttpError } from '../utils/http.js';\n\nconst RAZORPAY_API = 'https://api.razorpay.com/v1';\n\nexport const razorpayConfigured = () => Boolean(env.razorpayKeyId && env.razorpayKeySecret);\n\nfunction authHeader() {\n  return `Basic ${Buffer.from(`${env.razorpayKeyId}:${env.razorpayKeySecret}`).toString('base64')}`;\n}\n\n/**\n * Razorpay signs the payment handover as HMAC-SHA256(\"<order_id>|<payment_id>\") with the key secret.\n * Comparison is timing-safe; a forged or replayed signature never activates a plan.\n */\nexport function verifyPaymentSignature({ orderId, paymentId, signature }, secret = env.razorpayKeySecret) {\n  if (!secret || !orderId || !paymentId || !signature) return false;\n  const expected = crypto.createHmac('sha256', secret).update(`${orderId}|${paymentId}`).digest('hex');\n  const given = Buffer.from(String(signature), 'utf8');\n  const mine = Buffer.from(expected, 'utf8');\n  return given.length === mine.length && crypto.timingSafeEqual(given, mine);\n}\n\n/** Webhooks are signed as HMAC-SHA256 over the exact raw body with the webhook secret. */\nexport function verifyWebhookSignature(rawBody, signature, secret = env.razorpayWebhookSecret) {\n  if (!secret || !signature || !rawBody) return false;\n  const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');\n  const given = Buffer.from(String(signature), 'utf8');\n  const mine = Buffer.from(expected, 'utf8');\n  return given.length === mine.length && crypto.timingSafeEqual(given, mine);\n}\n\nexport function trialSubscriptionData() {\n  const trialEndsAt = new Date(Date.now() + TRIAL_DAYS * 86_400_000);\n  return {\n    plan: 'TRIAL',\n    interval: 'MONTHLY',\n    seats: TRIAL_SEATS,\n    status: 'TRIALING',\n    pricePerUser: '0.00',\n    trialEndsAt,\n    currentPeriodEnd: trialEndsAt,\n  };\n}\n\n/** True while the organization may keep using the app. */\nexport function subscriptionActive(subscription) {\n  if (!subscription) return false;\n  if (!['TRIALING', 'ACTIVE', 'PAST_DUE'].includes(subscription.status)) return false;\n  const until = subscription.currentPeriodEnd ?? subscription.trialEndsAt;\n  if (!until) return false;\n  return new Date(until).getTime() > Date.now();\n}\n\nexport function describeSubscription(subscription, seatsUsed) {\n  const until = subscription?.currentPeriodEnd ?? subscription?.trialEndsAt ?? null;\n  const daysLeft = until ? Math.ceil((new Date(until).getTime() - Date.now()) / 86_400_000) : 0;\n  return {\n    plan: subscription?.plan ?? 'TRIAL',\n    planName: subscription?.plan === 'TRIAL' ? 'Free trial' : PLANS[subscription?.plan]?.name ?? 'Free trial',\n    interval: subscription?.interval ?? 'MONTHLY',\n    status: subscription?.status ?? 'EXPIRED',\n    seats: subscription?.seats ?? 0,\n    seatsUsed,\n    seatsLeft: Math.max(0, (subscription?.seats ?? 0) - seatsUsed),\n    pricePerUser: Number(subscription?.pricePerUser ?? 0),\n    currency: subscription?.currency ?? 'INR',\n    renewsOn: until,\n    daysLeft: Math.max(0, daysLeft),\n    active: subscriptionActive(subscription),\n    isTrial: (subscription?.plan ?? 'TRIAL') === 'TRIAL',\n  };\n}\n\n/** Seats must cover everyone who can currently sign in. */\nexport async function assertSeatsAvailable(organizationId, extra = 1) {\n  const [subscription, used] = await Promise.all([\n    prisma.subscription.findUnique({ where: { organizationId } }),\n    prisma.user.count({ where: { organizationId, isActive: true } }),\n  ]);\n  if (!subscription) throw new HttpError(402, 'This store has no subscription', 'SUBSCRIPTION_REQUIRED');\n  if (used + extra > subscription.seats) {\n    throw new HttpError(\n      402,\n      `Your plan covers ${subscription.seats} staff account${subscription.seats === 1 ? '' : 's'} and ${used} are in use. Add seats in Billing to invite more.`,\n      'SEAT_LIMIT',\n    );\n  }\n  return subscription;\n}\n\n/**\n * Create a Razorpay order for a plan change. Returns the order plus the key id the\n * browser checkout needs. The subscription is only updated once payment is verified.\n */\nexport async function createOrder({ organizationId, plan, interval, seats }) {\n  if (!razorpayConfigured()) {\n    throw new HttpError(\n      503,\n      'Online payment is not configured yet. Add RAZORPAY_KEY_ID and RAZORPAY_KEY_SECRET to the server environment.',\n      'RAZORPAY_NOT_CONFIGURED',\n    );\n  }\n  const activeUsers = await prisma.user.count({ where: { organizationId, isActive: true } });\n  if (seats < activeUsers) {\n    throw new HttpError(400, `You have ${activeUsers} active staff accounts. Choose at least that many seats, or deactivate people first.`);\n  }\n  const priced = quote({ plan, interval, seats });\n  const receipt = `sub_${Date.now().toString(36)}`;\n\n  const response = await fetch(`${RAZORPAY_API}/orders`, {\n    method: 'POST',\n    headers: { Authorization: authHeader(), 'Content-Type': 'application/json' },\n    body: JSON.stringify({\n      amount: Math.round(priced.total * 100), // paise\n      currency: 'INR',\n      receipt,\n      notes: { organizationId, plan, interval, seats: String(priced.seats) },\n    }),\n  });\n\n  if (!response.ok) {\n    const detail = await response.text();\n    console.error('Razorpay order failed:', response.status, detail);\n    throw new HttpError(502, 'Could not reach the payment provider. Try again in a moment.', 'RAZORPAY_ERROR');\n  }\n  const order = await response.json();\n\n  await prisma.payment.create({\n    data: {\n      organizationId,\n      plan,\n      interval,\n      seats: priced.seats,\n      amount: priced.total.toFixed(2),\n      status: 'CREATED',\n      razorpayOrderId: order.id,\n    },\n  });\n\n  return { order, quote: priced, keyId: env.razorpayKeyId };\n}\n\n/** Mark a payment paid and move the subscription onto the paid plan. */\nexport async function activatePaidPlan({ organizationId, razorpayOrderId, razorpayPaymentId }) {\n  return prisma.$transaction(async (db) => {\n    const payment = await db.payment.findUnique({ where: { razorpayOrderId } });\n    if (!payment) throw new HttpError(404, 'That payment is not recognised');\n    if (organizationId && payment.organizationId !== organizationId) {\n      throw new HttpError(403, 'That payment belongs to another store');\n    }\n    if (payment.status === 'PAID') {\n      const existing = await db.subscription.findUnique({ where: { organizationId: payment.organizationId } });\n      return { subscription: existing, alreadyApplied: true };\n    }\n\n    await db.payment.update({\n      where: { id: payment.id },\n      data: { status: 'PAID', razorpayPaymentId },\n    });\n\n    const months = monthsFor(payment.interval);\n    const current = await db.subscription.findUnique({ where: { organizationId: payment.organizationId } });\n    // Extend from the current expiry when it is still in the future, otherwise from today.\n    const base = current?.currentPeriodEnd && new Date(current.currentPeriodEnd) > new Date() && current.status === 'ACTIVE'\n      ? new Date(current.currentPeriodEnd)\n      : new Date();\n    const periodEnd = new Date(base);\n    periodEnd.setMonth(periodEnd.getMonth() + months);\n\n    const pricePerUser = PLANS[payment.plan].intervals[payment.interval].price;\n    const subscription = await db.subscription.update({\n      where: { organizationId: payment.organizationId },\n      data: {\n        plan: payment.plan,\n        interval: payment.interval,\n        seats: payment.seats,\n        status: 'ACTIVE',\n        pricePerUser: pricePerUser.toFixed(2),\n        currentPeriodEnd: periodEnd,\n        razorpayOrderId,\n        razorpayPaymentId,\n        lastPaymentAt: new Date(),\n      },\n    });\n    return { subscription, alreadyApplied: false };\n  });\n}\n\nexport async function markPaymentFailed(razorpayOrderId, reason) {\n  await prisma.payment.updateMany({\n    where: { razorpayOrderId, status: 'CREATED' },\n    data: { status: 'FAILED', failureReason: reason?.slice(0, 200) ?? null },\n  });\n}\n\nexport const seatBounds = { min: MIN_SEATS, max: MAX_SEATS };\n",
"server/src/services/organization.service.js": "import bcrypt from 'bcryptjs';\nimport { prisma } from '../lib/prisma.js';\nimport { HttpError } from '../utils/http.js';\nimport { trialSubscriptionData } from './billing.service.js';\n\nconst slugify = (s) =>\n  s\n    .toLowerCase()\n    .normalize('NFKD')\n    .replace(/[^\\w\\s-]/g, '')\n    .trim()\n    .replace(/[\\s_-]+/g, '-')\n    .slice(0, 50) || 'store';\n\nasync function uniqueSlug(name) {\n  const base = slugify(name);\n  for (let n = 1; n < 500; n += 1) {\n    const slug = n === 1 ? base : `${base}-${n}`;\n    const taken = await prisma.organization.findUnique({ where: { slug }, select: { id: true } });\n    if (!taken) return slug;\n  }\n  throw new HttpError(409, 'Could not create a unique store address');\n}\n\n/**\n * Sign up a new store: organization, its first admin, store settings and a free trial.\n * Created in one database transaction so a half-made store can never exist.\n */\nexport async function createOrganization({ storeName, name, email, password, phone }) {\n  const existing = await prisma.user.findUnique({ where: { email }, select: { id: true } });\n  if (existing) throw new HttpError(409, 'An account with this email already exists. Sign in instead.', 'EMAIL_TAKEN');\n\n  const slug = await uniqueSlug(storeName);\n  const passwordHash = await bcrypt.hash(password, 12);\n\n  return prisma.$transaction(async (db) => {\n    const organization = await db.organization.create({ data: { name: storeName, slug } });\n    const user = await db.user.create({\n      data: { organizationId: organization.id, name, email, passwordHash, role: 'ADMIN' },\n    });\n    await db.storeSetting.create({\n      data: { organizationId: organization.id, storeName, phone: phone || null },\n    });\n    const subscription = await db.subscription.create({\n      data: { organizationId: organization.id, ...trialSubscriptionData() },\n    });\n    return { organization, user, subscription };\n  });\n}\n",
"server/src/services/report.service.js": "import { Prisma } from '@prisma/client';\nimport { env } from '../config/env.js';\nimport { prisma } from '../lib/prisma.js';\nimport { bucketsFor, comparePeriods } from '../utils/dates.js';\n\nconst tz = () => env.reportTimezone;\n\n/**\n * SQL predicate: t.sold_at falls on local dates [from, to] in the report timezone.\n * sold_at is stored as UTC `timestamp(3)`, so convert local midnight → timestamptz → naive UTC.\n * Bounds are computed in Postgres (not JS) so they stay index-friendly and DST-correct.\n */\nfunction inPeriod(from, to, column = Prisma.sql`t.sold_at`) {\n  return Prisma.sql`(${column} >= ((${from}::date)::timestamp AT TIME ZONE ${tz()}::text AT TIME ZONE 'UTC')\n    AND ${column} < (((${to}::date) + 1)::timestamp AT TIME ZONE ${tz()}::text AT TIME ZONE 'UTC'))`;\n}\n\n/** Every reporting query is filtered to one organization. */\nconst ofOrg = (organizationId, column = Prisma.sql`t.organization_id`) => Prisma.sql`${column} = ${organizationId}::text`;\n\n/** UTC instants for a local-date period, for use with the regular Prisma query builder. */\nexport async function periodBounds(from, to) {\n  const [row] = await prisma.$queryRaw`\n    SELECT ((${from}::date)::timestamp AT TIME ZONE ${tz()}::text) AS \"start\",\n           (((${to}::date) + 1)::timestamp AT TIME ZONE ${tz()}::text) AS \"end\"`;\n  return { start: new Date(row.start), end: new Date(row.end) };\n}\n\nasync function kpis(organizationId, from, to) {\n  const [[totals], [volume]] = await Promise.all([\n    prisma.$queryRaw`\n      SELECT COUNT(*)::int AS orders,\n             COALESCE(SUM(t.grand_total), 0)::float8 AS revenue,\n             COALESCE(SUM(t.taxable_amount), 0)::float8 AS \"netSales\",\n             COALESCE(SUM(t.item_discount + t.bill_discount), 0)::float8 AS discounts,\n             COALESCE(SUM(t.tax_total), 0)::float8 AS tax\n      FROM transactions t\n      WHERE ${ofOrg(organizationId)} AND t.status = 'COMPLETED' AND ${inPeriod(from, to)}`,\n    prisma.$queryRaw`\n      SELECT COALESCE(SUM(i.quantity) FILTER (WHERE NOT i.sold_by_weight), 0)::float8 AS units,\n             COALESCE(SUM(i.quantity) FILTER (WHERE i.sold_by_weight), 0)::float8 AS \"weightKg\"\n      FROM transaction_items i\n      JOIN transactions t ON t.id = i.transaction_id\n      WHERE ${ofOrg(organizationId)} AND t.status = 'COMPLETED' AND ${inPeriod(from, to)}`,\n  ]);\n  return { ...totals, ...volume, avgBasket: totals.orders ? totals.revenue / totals.orders : 0 };\n}\n\nasync function series(organizationId, from, to, granularity) {\n  const rows = await prisma.$queryRaw`\n    SELECT to_char(date_trunc(${granularity}::text, (t.sold_at AT TIME ZONE 'UTC') AT TIME ZONE ${tz()}::text),\n                   'YYYY-MM-DD\"T\"HH24:00') AS bucket,\n           SUM(t.grand_total)::float8 AS revenue,\n           COUNT(*)::int AS orders\n    FROM transactions t\n    WHERE ${ofOrg(organizationId)} AND t.status = 'COMPLETED' AND ${inPeriod(from, to)}\n    GROUP BY 1\n    ORDER BY 1`;\n  const byKey = new Map(rows.map((r) => [r.bucket, r]));\n  return bucketsFor(from, to, granularity).map((b) => ({\n    key: b.key,\n    label: b.label,\n    revenue: byKey.get(b.key)?.revenue ?? 0,\n    orders: byKey.get(b.key)?.orders ?? 0,\n  }));\n}\n\nasync function paymentSplit(organizationId, from, to) {\n  const rows = await prisma.$queryRaw`\n    SELECT t.payment_method::text AS method, COUNT(*)::int AS orders, SUM(t.grand_total)::float8 AS revenue\n    FROM transactions t\n    WHERE ${ofOrg(organizationId)} AND t.status = 'COMPLETED' AND ${inPeriod(from, to)}\n    GROUP BY 1`;\n  return ['UPI', 'CASH', 'CARD'].map((method) => {\n    const row = rows.find((r) => r.method === method);\n    return { method, orders: row?.orders ?? 0, revenue: row?.revenue ?? 0 };\n  });\n}\n\nasync function inventorySnapshot(organizationId) {\n  const [row] = await prisma.$queryRaw`\n    SELECT COALESCE(SUM(GREATEST(p.stock, 0) * p.price), 0)::float8 AS value,\n           COUNT(*)::int AS skus,\n           COUNT(*) FILTER (WHERE p.stock <= 0)::int AS \"outOfStock\",\n           COUNT(*) FILTER (WHERE p.stock > 0 AND p.stock <= p.low_stock_threshold)::int AS \"lowStock\"\n    FROM products p\n    WHERE p.organization_id = ${organizationId}::text AND p.is_active`;\n  return row;\n}\n\nexport async function overviewReport(organizationId, from, to) {\n  const period = comparePeriods(from, to);\n  const [current, previous, curSeries, prevSeries, curSplit, prevSplit, inventory] = await Promise.all([\n    kpis(organizationId, period.from, period.to),\n    kpis(organizationId, period.prevFrom, period.prevTo),\n    series(organizationId, period.from, period.to, period.granularity),\n    series(organizationId, period.prevFrom, period.prevTo, period.granularity),\n    paymentSplit(organizationId, period.from, period.to),\n    paymentSplit(organizationId, period.prevFrom, period.prevTo),\n    inventorySnapshot(organizationId),\n  ]);\n  return {\n    period,\n    timezone: tz(),\n    kpis: { current, previous },\n    series: { current: curSeries, previous: prevSeries },\n    paymentSplit: { current: curSplit, previous: prevSplit },\n    inventory,\n  };\n}\n\n/**\n * Sales + stock per category for the period and the previous period. Returns every category\n * (built for 1,000+ rows); `level=top` rolls sub-categories into their department.\n */\nexport async function categoryReport(organizationId, from, to, level = 'leaf') {\n  const period = comparePeriods(from, to);\n  const cur = inPeriod(period.from, period.to);\n  const prev = inPeriod(period.prevFrom, period.prevTo);\n  const group = level === 'top' ? Prisma.sql`COALESCE(c.parent_id, c.id)` : Prisma.sql`c.id`;\n  const levelFilter =\n    level === 'top'\n      ? Prisma.sql`c.parent_id IS NULL`\n      : Prisma.sql`NOT EXISTS (SELECT 1 FROM categories ch WHERE ch.parent_id = c.id)`;\n\n  const rows = await prisma.$queryRaw`\n    WITH sales AS (\n      SELECT ${group} AS category_id,\n             SUM(i.net_amount) FILTER (WHERE ${cur})::float8 AS cur_revenue,\n             SUM(i.net_amount) FILTER (WHERE ${prev})::float8 AS prev_revenue,\n             SUM(i.quantity) FILTER (WHERE ${cur} AND NOT i.sold_by_weight)::float8 AS cur_units,\n             SUM(i.quantity) FILTER (WHERE ${cur} AND i.sold_by_weight)::float8 AS cur_weight,\n             COUNT(DISTINCT i.transaction_id) FILTER (WHERE ${cur})::int AS cur_orders\n      FROM transaction_items i\n      JOIN transactions t ON t.id = i.transaction_id\n      JOIN categories c ON c.id = i.category_id\n      WHERE t.status = 'COMPLETED' AND (${cur} OR ${prev})\n      GROUP BY 1\n    ),\n    stock AS (\n      SELECT ${group} AS category_id,\n             COUNT(*)::int AS skus,\n             SUM(GREATEST(p.stock, 0) * p.price)::float8 AS stock_value,\n             COUNT(*) FILTER (WHERE p.stock <= p.low_stock_threshold)::int AS low_stock\n      FROM products p\n      JOIN categories c ON c.id = p.category_id\n      WHERE p.organization_id = ${organizationId}::text AND p.is_active\n      GROUP BY 1\n    )\n    SELECT c.id, c.name, c.icon, pc.name AS \"parentName\",\n           COALESCE(s.cur_revenue, 0)::float8 AS revenue,\n           COALESCE(s.prev_revenue, 0)::float8 AS \"prevRevenue\",\n           COALESCE(s.cur_units, 0)::float8 AS units,\n           COALESCE(s.cur_weight, 0)::float8 AS \"weightKg\",\n           COALESCE(s.cur_orders, 0)::int AS orders,\n           COALESCE(k.skus, 0)::int AS skus,\n           COALESCE(k.stock_value, 0)::float8 AS \"stockValue\",\n           COALESCE(k.low_stock, 0)::int AS \"lowStock\"\n    FROM categories c\n    LEFT JOIN categories pc ON pc.id = c.parent_id\n    LEFT JOIN sales s ON s.category_id = c.id\n    LEFT JOIN stock k ON k.category_id = c.id\n    WHERE c.organization_id = ${organizationId}::text AND ${levelFilter}\n    ORDER BY revenue DESC, c.name ASC`;\n\n  const total = rows.reduce((sum, r) => sum + r.revenue, 0);\n  const prevTotal = rows.reduce((sum, r) => sum + r.prevRevenue, 0);\n  return { period, level, totals: { revenue: total, prevRevenue: prevTotal, categories: rows.length }, rows };\n}\n\nconst PRODUCT_SORTS = {\n  revenue: Prisma.sql`revenue DESC, p.name ASC`,\n  units: Prisma.sql`quantity DESC, p.name ASC`,\n  growth: Prisma.sql`(COALESCE(s.cur_revenue, 0) - COALESCE(s.prev_revenue, 0)) DESC, p.name ASC`,\n  stock: Prisma.sql`p.stock ASC, p.name ASC`,\n  name: Prisma.sql`p.name ASC`,\n};\n\n/** Itemised sales performance with remaining stock, paginated server-side. */\nexport async function productReport(organizationId, { from, to, q = '', sort = 'revenue', page = 1, pageSize = 25 }) {\n  const period = comparePeriods(from, to);\n  const cur = inPeriod(period.from, period.to);\n  const prev = inPeriod(period.prevFrom, period.prevTo);\n  const search = q.trim();\n  const orderBy = PRODUCT_SORTS[sort] ?? PRODUCT_SORTS.revenue;\n  const offset = (page - 1) * pageSize;\n\n  const rows = await prisma.$queryRaw`\n    WITH sales AS (\n      SELECT i.product_id,\n             SUM(i.net_amount) FILTER (WHERE ${cur}) AS cur_revenue,\n             SUM(i.net_amount) FILTER (WHERE ${prev}) AS prev_revenue,\n             SUM(i.quantity) FILTER (WHERE ${cur}) AS cur_qty\n      FROM transaction_items i\n      JOIN transactions t ON t.id = i.transaction_id\n      WHERE ${ofOrg(organizationId)} AND t.status = 'COMPLETED' AND (${cur} OR ${prev})\n      GROUP BY 1\n    )\n    SELECT p.id, p.code, p.name, p.unit, p.sold_by_weight AS \"soldByWeight\",\n           p.price::float8 AS price, p.stock::float8 AS stock,\n           p.low_stock_threshold::float8 AS \"lowStockThreshold\", p.is_active AS \"isActive\",\n           c.name AS \"categoryName\",\n           COALESCE(s.cur_revenue, 0)::float8 AS revenue,\n           COALESCE(s.prev_revenue, 0)::float8 AS \"prevRevenue\",\n           COALESCE(s.cur_qty, 0)::float8 AS quantity,\n           COUNT(*) OVER()::int AS \"totalCount\"\n    FROM products p\n    JOIN categories c ON c.id = p.category_id\n    LEFT JOIN sales s ON s.product_id = p.id\n    WHERE p.organization_id = ${organizationId}::text\n      AND (p.is_active OR s.product_id IS NOT NULL)\n      AND (${search}::text = '' OR p.name ILIKE ${`%${search}%`}::text OR p.code = ${search}::text OR p.barcode = ${search}::text)\n    ORDER BY ${orderBy}\n    LIMIT ${pageSize}::int OFFSET ${offset}::int`;\n\n  const total = rows[0]?.totalCount ?? 0;\n  return {\n    period,\n    page,\n    pageSize,\n    total,\n    rows: rows.map(({ totalCount, ...r }) => r),\n  };\n}\n",
"server/src/services/settings.service.js": "import { prisma } from '../lib/prisma.js';\n\nconst DEFAULTS = {\n  currency: 'INR',\n  taxRate: 5,\n  maxCashierDiscountPct: 10,\n};\n\nconst cache = new Map();\nconst TTL_MS = 15_000;\n\n/** Store settings are one row per organization; created with defaults on first read. */\nexport async function getSettings(organizationId, { fresh = false } = {}) {\n  const hit = cache.get(organizationId);\n  if (!fresh && hit && Date.now() - hit.at < TTL_MS) return hit.value;\n  const value = await prisma.storeSetting.upsert({\n    where: { organizationId },\n    update: {},\n    create: { organizationId, storeName: 'My Store', ...DEFAULTS },\n  });\n  cache.set(organizationId, { value, at: Date.now() });\n  return value;\n}\n\nexport async function updateSettings(organizationId, data) {\n  const value = await prisma.storeSetting.upsert({\n    where: { organizationId },\n    update: data,\n    create: { organizationId, ...DEFAULTS, ...data },\n  });\n  cache.set(organizationId, { value, at: Date.now() });\n  return value;\n}\n",
"server/src/services/transaction.service.js": "import { z } from 'zod';\nimport { prisma } from '../lib/prisma.js';\nimport { computeBill, fromPaise, roundQty, toPaise } from '../utils/pricing.js';\n\nconst money = (paise) => fromPaise(paise).toFixed(2);\nconst qty = (q) => roundQty(q).toFixed(3);\n\nexport const syncTransactionSchema = z.object({\n  clientId: z.string().uuid(),\n  terminalId: z.string().trim().min(1).max(40),\n  cashierId: z.string().uuid().optional(),\n  soldAt: z.string().datetime({ offset: true }),\n  paymentMethod: z.enum(['CASH', 'UPI', 'CARD']),\n  customerPhone: z\n    .string()\n    .trim()\n    .max(20)\n    .regex(/^[+\\d\\s-]*$/, 'Phone number can only contain digits, spaces, + and -')\n    .nullish(),\n  amountTendered: z.number().nonnegative().max(100_000_000).nullish(),\n  taxRate: z.number().min(0).max(50),\n  billDiscount: z\n    .object({\n      type: z.enum(['PERCENT', 'FLAT']),\n      value: z.number().min(0).max(100_000_000),\n      reason: z.string().trim().max(200).nullish(),\n    })\n    .default({ type: 'PERCENT', value: 0 }),\n  grandTotal: z.number().nonnegative(),\n  wasOffline: z.boolean().default(false),\n  items: z\n    .array(\n      z.object({\n        productId: z.string().uuid(),\n        quantity: z.number().positive().max(100_000),\n        unitPrice: z.number().nonnegative().max(10_000_000),\n        discountPercent: z.number().min(0).max(100).default(0),\n      }),\n    )\n    .min(1, 'A bill needs at least one item')\n    .max(500),\n});\n\nconst rejected = (clientId, code, message) => ({ clientId, status: 'rejected', error: { code, message } });\n\nfunction isUniqueViolation(err) {\n  return err?.code === 'P2002';\n}\n\n/**\n * Persist one bill from a terminal. Safe to call repeatedly with the same clientId:\n * a retry after a dropped connection returns the already-stored invoice instead of double-counting\n * revenue or stock. Returns { status: 'created' | 'duplicate' | 'rejected' }.\n */\nexport async function ingestTransaction(rawInput, actor, settings) {\n  const organizationId = actor.organizationId;\n  const parsed = syncTransactionSchema.safeParse(rawInput);\n  const clientId = typeof rawInput?.clientId === 'string' ? rawInput.clientId : null;\n  if (!parsed.success) {\n    const issue = parsed.error.issues[0];\n    return rejected(clientId, 'VALIDATION_ERROR', `${issue.path.join('.') || 'bill'}: ${issue.message}`);\n  }\n  const input = parsed.data;\n\n  const existing = await prisma.transaction.findUnique({\n    where: { clientId: input.clientId },\n    select: { id: true, invoiceNo: true, organizationId: true },\n  });\n  if (existing && existing.organizationId !== organizationId) {\n    return rejected(input.clientId, 'NOT_YOURS', 'That bill belongs to another store');\n  }\n  if (existing) return { clientId: input.clientId, status: 'duplicate', id: existing.id, invoiceNo: existing.invoiceNo };\n\n  const productIds = [...new Set(input.items.map((i) => i.productId))];\n  const products = await prisma.product.findMany({\n    where: { id: { in: productIds }, organizationId },\n    select: { id: true, code: true, name: true, unit: true, soldByWeight: true, categoryId: true },\n  });\n  const byId = new Map(products.map((p) => [p.id, p]));\n  const missing = productIds.filter((id) => !byId.has(id));\n  if (missing.length) {\n    return rejected(input.clientId, 'PRODUCT_NOT_FOUND', `${missing.length} item(s) on this bill are no longer in the catalog`);\n  }\n\n  for (const item of input.items) {\n    const product = byId.get(item.productId);\n    if (!product.soldByWeight && !Number.isInteger(item.quantity)) {\n      return rejected(input.clientId, 'INVALID_QUANTITY', `${product.name} is sold per ${product.unit} and needs a whole-number quantity`);\n    }\n  }\n\n  const bill = computeBill({ items: input.items, billDiscount: input.billDiscount, taxRate: input.taxRate });\n\n  if (bill.grandTotal !== toPaise(input.grandTotal)) {\n    return rejected(\n      input.clientId,\n      'TOTAL_MISMATCH',\n      `Bill total ${input.grandTotal.toFixed(2)} does not match the recalculated total ${money(bill.grandTotal)}`,\n    );\n  }\n\n  if (actor.role === 'CASHIER' && bill.billDiscountEffectivePct > Number(settings.maxCashierDiscountPct) + 0.005) {\n    return rejected(\n      input.clientId,\n      'DISCOUNT_LIMIT',\n      `Cashier discounts are limited to ${Number(settings.maxCashierDiscountPct)}% of the bill`,\n    );\n  }\n\n  let changeDue = null;\n  if (input.paymentMethod === 'CASH' && input.amountTendered != null) {\n    const tendered = toPaise(input.amountTendered);\n    if (tendered < bill.grandTotal) {\n      return rejected(input.clientId, 'INSUFFICIENT_TENDER', 'Cash received is less than the bill total');\n    }\n    changeDue = tendered - bill.grandTotal;\n  }\n\n  // Bills queued offline may be uploaded by whoever signs in next; keep the original cashier when valid.\n  let cashierId = actor.id;\n  if (input.cashierId && input.cashierId !== actor.id) {\n    const original = await prisma.user.findFirst({\n      where: { id: input.cashierId, organizationId },\n      select: { id: true },\n    });\n    if (original) cashierId = original.id;\n  }\n\n  const now = new Date();\n  const soldAt = new Date(input.soldAt);\n  const safeSoldAt = soldAt > now ? now : soldAt; // never trust a terminal clock that runs ahead\n\n  try {\n    const created = await prisma.$transaction(async (db) => {\n      // Invoice numbers run 1, 2, 3… within each store. The row lock from this update also\n      // serialises concurrent bills on the same store, so two tills cannot take the same number.\n      const [counter] = await db.$queryRaw`\n        UPDATE organizations SET invoice_seq = invoice_seq + 1\n        WHERE id = ${organizationId}::text\n        RETURNING invoice_seq AS \"invoiceNo\"`;\n      if (!counter) throw new Error('Organization not found while numbering the invoice');\n\n      const tx = await db.transaction.create({\n        data: {\n          organizationId,\n          invoiceNo: counter.invoiceNo,\n          clientId: input.clientId,\n          terminalId: input.terminalId,\n          cashierId,\n          syncedById: actor.id,\n          paymentMethod: input.paymentMethod,\n          customerPhone: input.customerPhone || null,\n          subtotal: money(bill.subtotal),\n          itemDiscount: money(bill.itemDiscount),\n          billDiscount: money(bill.billDiscount),\n          discountReason: bill.billDiscount > 0 ? input.billDiscount.reason || null : null,\n          taxRate: bill.taxRate.toFixed(2),\n          taxableAmount: money(bill.taxableAmount),\n          taxTotal: money(bill.taxTotal),\n          grandTotal: money(bill.grandTotal),\n          amountTendered: input.amountTendered != null ? Number(input.amountTendered).toFixed(2) : null,\n          changeDue: changeDue != null ? money(changeDue) : null,\n          wasOffline: input.wasOffline,\n          soldAt: safeSoldAt,\n          items: {\n            create: bill.lines.map((line) => {\n              const product = byId.get(line.productId);\n              return {\n                productId: product.id,\n                categoryId: product.categoryId,\n                productName: product.name,\n                productCode: product.code,\n                unit: product.unit,\n                soldByWeight: product.soldByWeight,\n                quantity: qty(line.quantity),\n                unitPrice: Number(line.unitPrice).toFixed(2),\n                discountPercent: line.discountPercent.toFixed(2),\n                lineSubtotal: money(line.lineSubtotal),\n                lineDiscount: money(line.lineDiscount),\n                billDiscountShare: money(line.billDiscountShare),\n                netAmount: money(line.netAmount),\n              };\n            }),\n          },\n        },\n        select: { id: true, invoiceNo: true },\n      });\n\n      const soldQty = new Map();\n      for (const line of bill.lines) soldQty.set(line.productId, roundQty((soldQty.get(line.productId) || 0) + line.quantity));\n\n      for (const [productId, quantity] of soldQty) {\n        await db.product.update({ where: { id: productId }, data: { stock: { decrement: qty(quantity) } } });\n      }\n\n      await db.stockMovement.createMany({\n        data: [...soldQty].map(([productId, quantity]) => ({\n          organizationId,\n          productId,\n          type: 'SALE',\n          quantity: qty(-quantity),\n          referenceId: tx.id,\n          userId: cashierId,\n          reason: `Invoice #${tx.invoiceNo}`,\n        })),\n      });\n\n      return tx;\n    });\n\n    return { clientId: input.clientId, status: 'created', id: created.id, invoiceNo: created.invoiceNo };\n  } catch (err) {\n    if (isUniqueViolation(err)) {\n      // Two uploads of the same bill raced; the other one won.\n      const winner = await prisma.transaction.findUnique({ where: { clientId: input.clientId }, select: { id: true, invoiceNo: true } });\n      if (winner) return { clientId: input.clientId, status: 'duplicate', id: winner.id, invoiceNo: winner.invoiceNo };\n    }\n    throw err;\n  }\n}\n\n/** Void a completed bill and return its items to stock. */\nexport async function voidTransaction(id, reason, actor) {\n  return prisma.$transaction(async (db) => {\n    const tx = await db.transaction.findFirst({\n      where: { id, organizationId: actor.organizationId },\n      include: { items: true },\n    });\n    if (!tx) return { error: 'NOT_FOUND' };\n    if (tx.status === 'VOIDED') return { error: 'ALREADY_VOIDED' };\n\n    const restock = new Map();\n    for (const item of tx.items) restock.set(item.productId, roundQty((restock.get(item.productId) || 0) + Number(item.quantity)));\n\n    for (const [productId, quantity] of restock) {\n      await db.product.update({ where: { id: productId }, data: { stock: { increment: qty(quantity) } } });\n    }\n    await db.stockMovement.createMany({\n      data: [...restock].map(([productId, quantity]) => ({\n        organizationId: actor.organizationId,\n        productId,\n        type: 'VOID',\n        quantity: qty(quantity),\n        referenceId: tx.id,\n        userId: actor.id,\n        reason: `Void of invoice #${tx.invoiceNo}: ${reason}`,\n      })),\n    });\n\n    const updated = await db.transaction.update({\n      where: { id },\n      data: { status: 'VOIDED', voidedAt: new Date(), voidedById: actor.id, voidReason: reason },\n    });\n    return { transaction: updated };\n  });\n}\n",
"server/src/lib/prisma.js": "import { PrismaPg } from '@prisma/adapter-pg';\nimport { PrismaClient } from '@prisma/client';\nimport { env } from '../config/env.js';\n\nconst adapter = new PrismaPg({ connectionString: env.databaseUrl, max: env.dbPoolMax });\n\nexport const prisma = new PrismaClient({\n  adapter,\n  log: env.isProd ? ['error'] : ['warn', 'error'],\n});\n",
"server/src/utils/dates.js": "const ISO_DATE = /^\\d{4}-\\d{2}-\\d{2}$/;\nconst DAY_MS = 86_400_000;\n\nexport const isIsoDate = (s) => typeof s === 'string' && ISO_DATE.test(s) && !Number.isNaN(Date.parse(`${s}T00:00:00Z`));\n\nconst toUtc = (iso) => Date.parse(`${iso}T00:00:00Z`);\nconst fromUtc = (ms) => new Date(ms).toISOString().slice(0, 10);\n\nexport const addDays = (iso, n) => fromUtc(toUtc(iso) + n * DAY_MS);\nexport const diffDays = (fromIso, toIso) => Math.round((toUtc(toIso) - toUtc(fromIso)) / DAY_MS);\n\n/** Today's date (YYYY-MM-DD) in the given IANA timezone. */\nexport function todayIn(timeZone) {\n  const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());\n  return parts; // en-CA formats as YYYY-MM-DD\n}\n\n/** Describe the selected period and the equally long period right before it. */\nexport function comparePeriods(from, to) {\n  const days = diffDays(from, to) + 1;\n  return {\n    from,\n    to,\n    days,\n    prevFrom: addDays(from, -days),\n    prevTo: addDays(from, -1),\n    granularity: days === 1 ? 'hour' : days <= 120 ? 'day' : 'week',\n  };\n}\n\n/** ISO weekday Monday on/before the date (matches Postgres date_trunc('week')). */\nexport function mondayOf(iso) {\n  const dow = new Date(toUtc(iso)).getUTCDay(); // 0 = Sunday\n  return addDays(iso, -((dow + 6) % 7));\n}\n\nconst MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\nconst shortDate = (iso) => `${Number(iso.slice(8, 10))} ${MONTHS[Number(iso.slice(5, 7)) - 1]}`;\n\n/** Every bucket key in a period so charts have no gaps. Keys match the SQL `to_char` format. */\nexport function bucketsFor(from, to, granularity) {\n  const out = [];\n  if (granularity === 'hour') {\n    for (let h = 0; h < 24; h += 1) {\n      const hh = String(h).padStart(2, '0');\n      out.push({ key: `${from}T${hh}:00`, label: `${hh}:00` });\n    }\n  } else if (granularity === 'day') {\n    for (let d = from; d <= to; d = addDays(d, 1)) out.push({ key: `${d}T00:00`, label: shortDate(d) });\n  } else {\n    for (let d = mondayOf(from); d <= to; d = addDays(d, 7)) out.push({ key: `${d}T00:00`, label: `Wk ${shortDate(d)}` });\n  }\n  return out;\n}\n",
"server/src/utils/http.js": "const DEFAULT_CODES = {\n  400: 'BAD_REQUEST',\n  401: 'UNAUTHENTICATED',\n  403: 'FORBIDDEN',\n  404: 'NOT_FOUND',\n  409: 'CONFLICT',\n  422: 'UNPROCESSABLE',\n  429: 'RATE_LIMITED',\n};\n\nexport class HttpError extends Error {\n  constructor(status, message, code, details) {\n    super(message);\n    this.name = 'HttpError';\n    this.status = status;\n    this.code = code || DEFAULT_CODES[status] || 'ERROR';\n    this.details = details;\n  }\n}\n\n/** Forwards async errors to Express' error middleware (Express 4 does not do this natively). */\nexport const asyncHandler = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);\n\nexport const notFound = (what = 'Resource') => new HttpError(404, `${what} not found`);\n",
"server/src/utils/pricing.js": "/**\n * Bill calculation engine — shared verbatim by the POS client (client/src/lib/pricing.js)\n * and the API, so a bill rung up offline recomputes to the exact same paise on the server.\n *\n * Order of operations (mirrors the store blueprint):\n *   line subtotal → automatic line markdown → bill discount (allocated across lines) → GST on the remainder\n *\n * All money is handled as integer paise; quantities are rounded to 3 decimals (grams).\n */\n\nexport const toPaise = (rupees) => Math.round(Number(rupees || 0) * 100);\nexport const fromPaise = (paise) => Math.round(paise) / 100;\nexport const roundQty = (qty) => Math.round(Number(qty || 0) * 1000) / 1000;\n\nconst clamp = (n, min, max) => Math.min(max, Math.max(min, Number.isFinite(n) ? n : 0));\n\n/** Split `total` across `weights` proportionally using the largest-remainder method (sums exactly). */\nexport function allocate(total, weights) {\n  const sum = weights.reduce((a, b) => a + b, 0);\n  if (total <= 0 || sum <= 0) return weights.map(() => 0);\n  const raw = weights.map((w) => (total * w) / sum);\n  const floors = raw.map(Math.floor);\n  let remainder = total - floors.reduce((a, b) => a + b, 0);\n  const order = raw\n    .map((r, i) => [r - floors[i], i])\n    .sort((a, b) => b[0] - a[0] || a[1] - b[1]);\n  for (let k = 0; k < order.length && remainder > 0; k += 1, remainder -= 1) {\n    floors[order[k][1]] += 1;\n  }\n  return floors;\n}\n\n/**\n * @param {object} input\n * @param {Array<{quantity:number, unitPrice:number, discountPercent?:number}>} input.items\n * @param {{type:'PERCENT'|'FLAT', value:number}} [input.billDiscount]\n * @param {number} input.taxRate  e.g. 5 for 5% GST\n */\nexport function computeBill({ items, billDiscount, taxRate }) {\n  const lines = items.map((item) => {\n    const quantity = roundQty(item.quantity);\n    const unitPaise = toPaise(item.unitPrice);\n    const discountPercent = clamp(Number(item.discountPercent || 0), 0, 100);\n    const lineSubtotal = Math.round(unitPaise * quantity);\n    const lineDiscount = Math.round((lineSubtotal * discountPercent) / 100);\n    return { ...item, quantity, discountPercent, lineSubtotal, lineDiscount, afterMarkdown: lineSubtotal - lineDiscount };\n  });\n\n  const subtotal = lines.reduce((s, l) => s + l.lineSubtotal, 0);\n  const itemDiscount = lines.reduce((s, l) => s + l.lineDiscount, 0);\n  const afterMarkdowns = subtotal - itemDiscount;\n\n  const type = billDiscount?.type === 'FLAT' ? 'FLAT' : 'PERCENT';\n  const value = Math.max(0, Number(billDiscount?.value || 0));\n  const billDiscountPaise =\n    type === 'PERCENT'\n      ? Math.round((afterMarkdowns * clamp(value, 0, 100)) / 100)\n      : Math.min(afterMarkdowns, toPaise(value));\n\n  const shares = allocate(billDiscountPaise, lines.map((l) => l.afterMarkdown));\n  const finalLines = lines.map((l, i) => ({\n    ...l,\n    billDiscountShare: shares[i],\n    netAmount: l.afterMarkdown - shares[i],\n  }));\n\n  const rate = clamp(Number(taxRate || 0), 0, 100);\n  const taxableAmount = afterMarkdowns - billDiscountPaise;\n  const taxTotal = Math.round((taxableAmount * rate) / 100);\n  const grandTotal = taxableAmount + taxTotal;\n\n  return {\n    lines: finalLines,\n    subtotal,\n    itemDiscount,\n    billDiscount: billDiscountPaise,\n    afterMarkdowns,\n    discountTotal: itemDiscount + billDiscountPaise,\n    billDiscountEffectivePct: afterMarkdowns > 0 ? (billDiscountPaise / afterMarkdowns) * 100 : 0,\n    taxRate: rate,\n    taxableAmount,\n    taxTotal,\n    grandTotal,\n  };\n}\n",
"server/src/utils/serialize.js": "const num = (d) => (d === null || d === undefined ? null : Number(d));\n\nexport const publicUser = (u) => ({\n  id: u.id,\n  name: u.name,\n  email: u.email,\n  role: u.role,\n  isActive: u.isActive,\n  createdAt: u.createdAt,\n});\n\nexport const serializeCategory = (c) => ({\n  id: c.id,\n  name: c.name,\n  slug: c.slug,\n  icon: c.icon,\n  sortOrder: c.sortOrder,\n  parentId: c.parentId,\n  productCount: c._count?.products,\n});\n\nexport const serializeProduct = (p) => ({\n  id: p.id,\n  code: p.code,\n  barcode: p.barcode,\n  name: p.name,\n  description: p.description,\n  categoryId: p.categoryId,\n  categoryName: p.category?.name,\n  price: num(p.price),\n  unit: p.unit,\n  soldByWeight: p.soldByWeight,\n  stock: num(p.stock),\n  lowStockThreshold: num(p.lowStockThreshold),\n  discountPercent: num(p.discountPercent),\n  isQuickKey: p.isQuickKey,\n  imageUrl: p.imageUrl,\n  isActive: p.isActive,\n  updatedAt: p.updatedAt,\n});\n\nexport const serializeSettings = (s) => ({\n  storeName: s.storeName,\n  tagline: s.tagline,\n  gstin: s.gstin,\n  address: s.address,\n  phone: s.phone,\n  upiVpa: s.upiVpa,\n  upiPayeeName: s.upiPayeeName,\n  currency: s.currency,\n  taxRate: num(s.taxRate),\n  maxCashierDiscountPct: num(s.maxCashierDiscountPct),\n  receiptFooter: s.receiptFooter,\n  updatedAt: s.updatedAt,\n});\n\nexport const serializeTransaction = (t) => ({\n  id: t.id,\n  clientId: t.clientId,\n  invoiceNo: t.invoiceNo,\n  terminalId: t.terminalId,\n  cashier: t.cashier ? { id: t.cashier.id, name: t.cashier.name } : undefined,\n  status: t.status,\n  paymentMethod: t.paymentMethod,\n  customerPhone: t.customerPhone,\n  subtotal: num(t.subtotal),\n  itemDiscount: num(t.itemDiscount),\n  billDiscount: num(t.billDiscount),\n  discountReason: t.discountReason,\n  taxRate: num(t.taxRate),\n  taxableAmount: num(t.taxableAmount),\n  taxTotal: num(t.taxTotal),\n  grandTotal: num(t.grandTotal),\n  amountTendered: num(t.amountTendered),\n  changeDue: num(t.changeDue),\n  wasOffline: t.wasOffline,\n  soldAt: t.soldAt,\n  syncedAt: t.syncedAt,\n  voidedAt: t.voidedAt,\n  voidReason: t.voidReason,\n  itemCount: t._count?.items ?? t.items?.length,\n  items: t.items?.map((i) => ({\n    id: i.id,\n    productId: i.productId,\n    productName: i.productName,\n    productCode: i.productCode,\n    unit: i.unit,\n    soldByWeight: i.soldByWeight,\n    quantity: num(i.quantity),\n    unitPrice: num(i.unitPrice),\n    discountPercent: num(i.discountPercent),\n    lineSubtotal: num(i.lineSubtotal),\n    lineDiscount: num(i.lineDiscount),\n    billDiscountShare: num(i.billDiscountShare),\n    netAmount: num(i.netAmount),\n  })),\n});\n",
"server/src/routes/auth.routes.js": "import bcrypt from 'bcryptjs';\nimport rateLimit from 'express-rate-limit';\nimport { Router } from 'express';\nimport { z } from 'zod';\nimport { prisma } from '../lib/prisma.js';\nimport { authenticate, signToken } from '../middleware/auth.js';\nimport { validate } from '../middleware/validate.js';\nimport { asyncHandler, HttpError } from '../utils/http.js';\nimport { publicUser } from '../utils/serialize.js';\n\nconst router = Router();\n\n// Compared against when the email is unknown, so response time doesn't reveal which accounts exist.\nconst TIMING_HASH = bcrypt.hashSync('freshflow-timing-guard', 10);\n\nconst loginLimiter = rateLimit({\n  windowMs: 15 * 60 * 1000,\n  limit: 20,\n  standardHeaders: 'draft-7',\n  legacyHeaders: false,\n  message: { error: { code: 'RATE_LIMITED', message: 'Too many sign-in attempts. Wait 15 minutes and try again.' } },\n});\n\nconst loginSchema = z.object({\n  email: z.string().trim().toLowerCase().email('Enter a valid email address'),\n  password: z.string().min(1, 'Enter your password').max(200),\n});\n\nrouter.post(\n  '/login',\n  loginLimiter,\n  validate({ body: loginSchema }),\n  asyncHandler(async (req, res) => {\n    const { email, password } = req.body;\n    const user = await prisma.user.findUnique({ where: { email } });\n    const passwordOk = await bcrypt.compare(password, user?.passwordHash ?? TIMING_HASH);\n\n    if (!user || !passwordOk) throw new HttpError(401, 'Email or password is incorrect', 'INVALID_CREDENTIALS');\n    if (!user.isActive) throw new HttpError(403, 'This account has been deactivated. Contact your store admin.', 'ACCOUNT_DISABLED');\n\n    const organization = await prisma.organization.findUnique({\n      where: { id: user.organizationId },\n      select: { id: true, name: true, slug: true },\n    });\n    res.json({ token: signToken(user), user: publicUser(user), organization });\n  }),\n);\n\nrouter.get(\n  '/me',\n  authenticate,\n  asyncHandler(async (req, res) => {\n    const user = await prisma.user.findUnique({ where: { id: req.user.id } });\n    if (!user) throw new HttpError(401, 'Sign in to continue', 'UNAUTHENTICATED');\n    res.json({\n      user: publicUser(user),\n      organization: req.organization\n        ? { id: req.organization.id, name: req.organization.name, slug: req.organization.slug }\n        : null,\n    });\n  }),\n);\n\nexport default router;\n",
"server/src/routes/billing.routes.js": "import { Router } from 'express';\nimport express from 'express';\nimport { z } from 'zod';\nimport { MAX_SEATS, MIN_SEATS, quote } from '../config/plans.js';\nimport { prisma } from '../lib/prisma.js';\nimport { authenticate, authorize, ROLES } from '../middleware/auth.js';\nimport { validate } from '../middleware/validate.js';\nimport {\n  activatePaidPlan,\n  createOrder,\n  describeSubscription,\n  markPaymentFailed,\n  razorpayConfigured,\n  verifyPaymentSignature,\n  verifyWebhookSignature,\n} from '../services/billing.service.js';\nimport { asyncHandler, HttpError } from '../utils/http.js';\n\nconst router = Router();\n\n/**\n * Razorpay webhook. Mounted before the JSON body parser and given the raw body, because the\n * signature covers the exact bytes sent. Unsigned or wrongly signed calls are rejected.\n */\nexport const webhookRouter = Router();\nwebhookRouter.post(\n  '/webhook',\n  express.raw({ type: 'application/json', limit: '256kb' }),\n  asyncHandler(async (req, res) => {\n    const signature = req.get('x-razorpay-signature');\n    if (!verifyWebhookSignature(req.body, signature)) {\n      return res.status(400).json({ error: { code: 'INVALID_SIGNATURE', message: 'Signature check failed' } });\n    }\n    let event;\n    try {\n      event = JSON.parse(req.body.toString('utf8'));\n    } catch {\n      return res.status(400).json({ error: { code: 'INVALID_JSON', message: 'Body is not valid JSON' } });\n    }\n\n    const payment = event?.payload?.payment?.entity;\n    if (event?.event === 'payment.captured' && payment?.order_id) {\n      await activatePaidPlan({ organizationId: null, razorpayOrderId: payment.order_id, razorpayPaymentId: payment.id });\n    } else if (event?.event === 'payment.failed' && payment?.order_id) {\n      await markPaymentFailed(payment.order_id, payment.error_description);\n    }\n    // Always 200 once the signature is good, so Razorpay stops retrying.\n    return res.json({ received: true });\n  }),\n);\n\nrouter.use(authenticate);\n\n/** Everyone signed in can see what plan the store is on (the app shows a banner). */\nrouter.get(\n  '/subscription',\n  asyncHandler(async (req, res) => {\n    const seatsUsed = await prisma.user.count({ where: { organizationId: req.user.organizationId, isActive: true } });\n    res.json({\n      subscription: describeSubscription(req.subscription, seatsUsed),\n      paymentsEnabled: razorpayConfigured(),\n    });\n  }),\n);\n\nrouter.use(authorize(ROLES.ADMIN));\n\nconst planSchema = z.object({\n  plan: z.enum(['STANDARD', 'CUSTOM']),\n  interval: z.enum(['MONTHLY', 'YEARLY']),\n  seats: z.coerce.number().int().min(MIN_SEATS).max(MAX_SEATS),\n});\n\nrouter.post(\n  '/checkout',\n  validate({ body: planSchema }),\n  asyncHandler(async (req, res) => {\n    const { plan, interval, seats } = req.body;\n    const result = await createOrder({ organizationId: req.user.organizationId, plan, interval, seats });\n    res.json({\n      orderId: result.order.id,\n      amount: result.order.amount,\n      currency: result.order.currency,\n      keyId: result.keyId,\n      quote: result.quote,\n      customer: { name: req.user.name, storeName: req.organization?.name },\n    });\n  }),\n);\n\n/** Called by the browser right after Razorpay checkout succeeds. */\nrouter.post(\n  '/verify',\n  validate({\n    body: z.object({\n      razorpay_order_id: z.string().min(4),\n      razorpay_payment_id: z.string().min(4),\n      razorpay_signature: z.string().min(8),\n    }),\n  }),\n  asyncHandler(async (req, res) => {\n    const orderId = req.body.razorpay_order_id;\n    const paymentId = req.body.razorpay_payment_id;\n    if (!verifyPaymentSignature({ orderId, paymentId, signature: req.body.razorpay_signature })) {\n      await markPaymentFailed(orderId, 'Signature verification failed');\n      throw new HttpError(400, 'We could not verify that payment. Nothing was charged to your plan.', 'INVALID_SIGNATURE');\n    }\n    const { subscription } = await activatePaidPlan({\n      organizationId: req.user.organizationId,\n      razorpayOrderId: orderId,\n      razorpayPaymentId: paymentId,\n    });\n    const seatsUsed = await prisma.user.count({ where: { organizationId: req.user.organizationId, isActive: true } });\n    res.json({ subscription: describeSubscription(subscription, seatsUsed) });\n  }),\n);\n\nrouter.get(\n  '/quote',\n  validate({ query: planSchema }),\n  (req, res) => {\n    res.json({ quote: quote(req.query) });\n  },\n);\n\nrouter.get(\n  '/payments',\n  asyncHandler(async (req, res) => {\n    const payments = await prisma.payment.findMany({\n      where: { organizationId: req.user.organizationId },\n      orderBy: { createdAt: 'desc' },\n      take: 24,\n    });\n    res.json({\n      payments: payments.map((p) => ({\n        id: p.id,\n        plan: p.plan,\n        interval: p.interval,\n        seats: p.seats,\n        amount: Number(p.amount),\n        currency: p.currency,\n        status: p.status,\n        reference: p.razorpayPaymentId ?? p.razorpayOrderId,\n        createdAt: p.createdAt,\n      })),\n    });\n  }),\n);\n\nexport default router;\n",
"server/src/routes/categories.routes.js": "import { Router } from 'express';\nimport { z } from 'zod';\nimport { prisma } from '../lib/prisma.js';\nimport { authorize, ROLES } from '../middleware/auth.js';\nimport { requireActiveSubscription } from '../middleware/subscription.js';\nimport { validate } from '../middleware/validate.js';\nimport { asyncHandler, HttpError, notFound } from '../utils/http.js';\nimport { serializeCategory } from '../utils/serialize.js';\nimport { emptyToNull, idParam } from './schemas.js';\n\nconst router = Router();\n\nconst slugify = (s) =>\n  s\n    .toLowerCase()\n    .normalize('NFKD')\n    .replace(/[^\\w\\s-]/g, '')\n    .trim()\n    .replace(/[\\s_-]+/g, '-')\n    .slice(0, 60) || 'category';\n\nconst categorySchema = z.object({\n  name: z.string().trim().min(1, 'Name is required').max(60),\n  icon: emptyToNull(z.string().trim().max(8)),\n  parentId: emptyToNull(z.string().uuid()),\n  sortOrder: z.coerce.number().int().min(0).max(100000).default(0),\n});\n\nasync function assertValidParent(organizationId, parentId, selfId) {\n  if (!parentId) return;\n  if (parentId === selfId) throw new HttpError(400, 'A category cannot be its own parent');\n  const parent = await prisma.category.findFirst({ where: { id: parentId, organizationId }, select: { parentId: true } });\n  if (!parent) throw new HttpError(400, 'Parent category not found');\n  if (parent.parentId) throw new HttpError(400, 'Sub-categories can only be one level deep');\n  if (selfId) {\n    const children = await prisma.category.count({ where: { parentId: selfId } });\n    if (children) throw new HttpError(400, 'A category with sub-categories cannot itself become a sub-category');\n  }\n}\n\nasync function uniqueSlug(organizationId, name, parentId, excludeId) {\n  let prefix = '';\n  if (parentId) {\n    const parent = await prisma.category.findUnique({ where: { id: parentId }, select: { slug: true } });\n    prefix = parent ? `${parent.slug}-` : '';\n  }\n  const base = `${prefix}${slugify(name)}`;\n  for (let n = 1; n < 1000; n += 1) {\n    const slug = n === 1 ? base : `${base}-${n}`;\n    const taken = await prisma.category.findFirst({\n      where: { organizationId, slug, NOT: excludeId ? { id: excludeId } : undefined },\n      select: { id: true },\n    });\n    if (!taken) return slug;\n  }\n  throw new HttpError(409, 'Could not generate a unique category slug');\n}\n\nrouter.get(\n  '/',\n  authorize(ROLES.ADMIN, ROLES.CASHIER),\n  asyncHandler(async (req, res) => {\n    const categories = await prisma.category.findMany({\n      where: { organizationId: req.user.organizationId },\n      orderBy: [{ sortOrder: 'asc' }, { name: 'asc' }],\n      include: { _count: { select: { products: { where: { isActive: true } } } } },\n    });\n    res.json({ categories: categories.map(serializeCategory) });\n  }),\n);\n\nrouter.post(\n  '/',\n  authorize(ROLES.ADMIN),\n  requireActiveSubscription,\n  validate({ body: categorySchema }),\n  asyncHandler(async (req, res) => {\n    const organizationId = req.user.organizationId;\n    await assertValidParent(organizationId, req.body.parentId);\n    const category = await prisma.category.create({\n      data: { ...req.body, organizationId, slug: await uniqueSlug(organizationId, req.body.name, req.body.parentId) },\n    });\n    res.status(201).json({ category: serializeCategory(category) });\n  }),\n);\n\nrouter.put(\n  '/:id',\n  authorize(ROLES.ADMIN),\n  requireActiveSubscription,\n  validate({ params: idParam, body: categorySchema }),\n  asyncHandler(async (req, res) => {\n    const organizationId = req.user.organizationId;\n    const existing = await prisma.category.findFirst({ where: { id: req.params.id, organizationId } });\n    if (!existing) throw notFound('Category');\n    await assertValidParent(organizationId, req.body.parentId, req.params.id);\n    const slugChanged = existing.name !== req.body.name || existing.parentId !== (req.body.parentId ?? null);\n    const category = await prisma.category.update({\n      where: { id: req.params.id },\n      data: {\n        ...req.body,\n        ...(slugChanged ? { slug: await uniqueSlug(organizationId, req.body.name, req.body.parentId, req.params.id) } : {}),\n      },\n    });\n    res.json({ category: serializeCategory(category) });\n  }),\n);\n\nrouter.delete(\n  '/:id',\n  authorize(ROLES.ADMIN),\n  requireActiveSubscription,\n  validate({ params: idParam }),\n  asyncHandler(async (req, res) => {\n    const category = await prisma.category.findFirst({\n      where: { id: req.params.id, organizationId: req.user.organizationId },\n      include: { _count: { select: { products: true, children: true, soldItems: true } } },\n    });\n    if (!category) throw notFound('Category');\n    const { products, children, soldItems } = category._count;\n    if (children) throw new HttpError(409, `Move or delete its ${children} sub-categories first`, 'IN_USE');\n    if (products) throw new HttpError(409, `Move its ${products} products to another category first`, 'IN_USE');\n    if (soldItems) throw new HttpError(409, 'This category appears on past bills and is kept for reporting', 'IN_USE');\n    await prisma.category.delete({ where: { id: req.params.id } });\n    res.status(204).end();\n  }),\n);\n\nexport default router;\n",
"server/src/routes/products.routes.js": "import { Router } from 'express';\nimport { z } from 'zod';\nimport { prisma } from '../lib/prisma.js';\nimport { authorize, ROLES } from '../middleware/auth.js';\nimport { requireActiveSubscription } from '../middleware/subscription.js';\nimport { validate } from '../middleware/validate.js';\nimport { asyncHandler, HttpError, notFound } from '../utils/http.js';\nimport { roundQty } from '../utils/pricing.js';\nimport { serializeProduct } from '../utils/serialize.js';\nimport { emptyToNull, idParam, pagination } from './schemas.js';\n\nconst router = Router();\n\nconst productSchema = z\n  .object({\n    code: z.string().trim().min(1, 'Code is required').max(20).regex(/^[A-Za-z0-9-]+$/, 'Code can use letters, digits and -'),\n    barcode: emptyToNull(z.string().trim().min(4).max(32).regex(/^[A-Za-z0-9]+$/, 'Barcode can use letters and digits')),\n    name: z.string().trim().min(1, 'Name is required').max(120),\n    description: emptyToNull(z.string().trim().max(500)),\n    categoryId: z.string().uuid('Choose a category'),\n    price: z.coerce.number().min(0).max(10_000_000),\n    unit: z.string().trim().min(1).max(12).default('pcs'),\n    soldByWeight: z.coerce.boolean().default(false),\n    lowStockThreshold: z.coerce.number().min(0).max(1_000_000).default(5),\n    discountPercent: z.coerce.number().min(0).max(100).default(0),\n    isQuickKey: z.coerce.boolean().default(false),\n    imageUrl: emptyToNull(z.string().trim().url('Image must be a full https:// URL').max(500)),\n    isActive: z.coerce.boolean().default(true),\n  });\n\nconst createSchema = productSchema.extend({\n  stock: z.coerce.number().min(0).max(1_000_000).default(0),\n});\n\nconst listQuery = z.object({\n  ...pagination,\n  q: z.string().trim().max(100).default(''),\n  categoryId: emptyToNull(z.string().uuid()),\n  stock: z.enum(['all', 'low', 'out']).default('all'),\n  status: z.enum(['active', 'inactive', 'all']).default('active'),\n  sort: z.enum(['name', 'stock', 'price', 'updated']).default('name'),\n});\n\nconst stockSchema = z.object({\n  mode: z.enum(['ADD', 'REMOVE', 'SET']),\n  quantity: z.coerce.number().min(0).max(1_000_000),\n  reason: z.string().trim().min(2, 'Add a short reason').max(200),\n});\n\nconst SORTS = {\n  name: { name: 'asc' },\n  stock: { stock: 'asc' },\n  price: { price: 'desc' },\n  updated: { updatedAt: 'desc' },\n};\n\nasync function assertLeafCategory(organizationId, categoryId) {\n  const category = await prisma.category.findFirst({\n    where: { id: categoryId, organizationId },\n    include: { _count: { select: { children: true } } },\n  });\n  if (!category) throw new HttpError(400, 'Category not found');\n  if (category._count.children) throw new HttpError(400, `\"${category.name}\" has sub-categories. Choose one of them.`);\n}\n\n/** Compact catalog for POS terminals (cached in IndexedDB for offline selling). */\nrouter.get(\n  '/catalog',\n  authorize(ROLES.ADMIN, ROLES.CASHIER),\n  asyncHandler(async (req, res) => {\n    const products = await prisma.product.findMany({\n      where: { organizationId: req.user.organizationId, isActive: true },\n      orderBy: { name: 'asc' },\n      select: {\n        id: true, code: true, barcode: true, name: true, categoryId: true, price: true, unit: true,\n        soldByWeight: true, stock: true, lowStockThreshold: true, discountPercent: true, isQuickKey: true, imageUrl: true,\n      },\n    });\n    res.json({ products: products.map(serializeProduct), generatedAt: new Date().toISOString() });\n  }),\n);\n\nrouter.get(\n  '/',\n  authorize(ROLES.ADMIN),\n  validate({ query: listQuery }),\n  asyncHandler(async (req, res) => {\n    const { page, pageSize, q, categoryId, stock, status, sort } = req.query;\n    const where = {\n      organizationId: req.user.organizationId,\n      ...(status === 'all' ? {} : { isActive: status === 'active' }),\n      ...(categoryId ? { categoryId } : {}),\n      ...(q\n        ? { OR: [{ name: { contains: q, mode: 'insensitive' } }, { code: { equals: q, mode: 'insensitive' } }, { barcode: q }] }\n        : {}),\n      ...(stock === 'out' ? { stock: { lte: 0 } } : {}),\n      ...(stock === 'low' ? { stock: { gt: 0, lte: prisma.product.fields.lowStockThreshold } } : {}),\n    };\n    const [total, products] = await Promise.all([\n      prisma.product.count({ where }),\n      prisma.product.findMany({\n        where,\n        orderBy: [SORTS[sort], { id: 'asc' }],\n        skip: (page - 1) * pageSize,\n        take: pageSize,\n        include: { category: { select: { name: true } } },\n      }),\n    ]);\n    res.json({ page, pageSize, total, products: products.map(serializeProduct) });\n  }),\n);\n\nrouter.post(\n  '/',\n  authorize(ROLES.ADMIN),\n  requireActiveSubscription,\n  validate({ body: createSchema }),\n  asyncHandler(async (req, res) => {\n    const organizationId = req.user.organizationId;\n    await assertLeafCategory(organizationId, req.body.categoryId);\n    const { stock, ...data } = req.body;\n    const product = await prisma.$transaction(async (db) => {\n      const created = await db.product.create({ data: { ...data, organizationId, stock: roundQty(stock).toFixed(3) } });\n      if (stock > 0) {\n        await db.stockMovement.create({\n          data: {\n            organizationId,\n            productId: created.id,\n            type: 'RESTOCK',\n            quantity: roundQty(stock).toFixed(3),\n            reason: 'Opening stock',\n            userId: req.user.id,\n          },\n        });\n      }\n      return db.product.findUnique({ where: { id: created.id }, include: { category: { select: { name: true } } } });\n    });\n    res.status(201).json({ product: serializeProduct(product) });\n  }),\n);\n\nrouter.put(\n  '/:id',\n  authorize(ROLES.ADMIN),\n  requireActiveSubscription,\n  validate({ params: idParam, body: productSchema }),\n  asyncHandler(async (req, res) => {\n    const exists = await prisma.product.findFirst({\n      where: { id: req.params.id, organizationId: req.user.organizationId },\n      select: { id: true },\n    });\n    if (!exists) throw notFound('Product');\n    await assertLeafCategory(req.user.organizationId, req.body.categoryId);\n    const product = await prisma.product.update({\n      where: { id: req.params.id },\n      data: req.body,\n      include: { category: { select: { name: true } } },\n    });\n    res.json({ product: serializeProduct(product) });\n  }),\n);\n\n/** Stock ledger adjustment. Row-locked so a concurrent sale cannot be overwritten by a \"set\". */\nrouter.patch(\n  '/:id/stock',\n  authorize(ROLES.ADMIN),\n  requireActiveSubscription,\n  validate({ params: idParam, body: stockSchema }),\n  asyncHandler(async (req, res) => {\n    const { mode, quantity, reason } = req.body;\n    const product = await prisma.$transaction(async (db) => {\n      const [locked] = await db.$queryRaw`\n        SELECT stock::float8 AS stock FROM products\n        WHERE id = ${req.params.id}::text AND organization_id = ${req.user.organizationId}::text\n        FOR UPDATE`;\n      if (!locked) throw notFound('Product');\n      const current = roundQty(locked.stock);\n      const next = mode === 'SET' ? roundQty(quantity) : mode === 'ADD' ? roundQty(current + quantity) : roundQty(current - quantity);\n      const change = roundQty(next - current);\n      if (change === 0) throw new HttpError(400, 'Stock is already at that level');\n\n      await db.product.update({ where: { id: req.params.id }, data: { stock: next.toFixed(3) } });\n      await db.stockMovement.create({\n        data: {\n          organizationId: req.user.organizationId,\n          productId: req.params.id,\n          type: mode === 'ADD' ? 'RESTOCK' : 'ADJUSTMENT',\n          quantity: change.toFixed(3),\n          reason,\n          userId: req.user.id,\n        },\n      });\n      return db.product.findUnique({ where: { id: req.params.id }, include: { category: { select: { name: true } } } });\n    });\n    res.json({ product: serializeProduct(product) });\n  }),\n);\n\nrouter.get(\n  '/:id/movements',\n  authorize(ROLES.ADMIN),\n  validate({ params: idParam, query: z.object({ limit: z.coerce.number().int().min(1).max(200).default(50) }) }),\n  asyncHandler(async (req, res) => {\n    const movements = await prisma.stockMovement.findMany({\n      where: { productId: req.params.id, organizationId: req.user.organizationId },\n      orderBy: { createdAt: 'desc' },\n      take: req.query.limit,\n    });\n    res.json({\n      movements: movements.map((m) => ({ ...m, quantity: Number(m.quantity) })),\n    });\n  }),\n);\n\n/** Products on past bills are never hard-deleted; deactivating hides them from terminals. */\nrouter.delete(\n  '/:id',\n  authorize(ROLES.ADMIN),\n  requireActiveSubscription,\n  validate({ params: idParam }),\n  asyncHandler(async (req, res) => {\n    const target = await prisma.product.findFirst({\n      where: { id: req.params.id, organizationId: req.user.organizationId },\n      select: { id: true },\n    });\n    if (!target) throw notFound('Product');\n    const product = await prisma.product.update({\n      where: { id: req.params.id },\n      data: { isActive: false, isQuickKey: false },\n      include: { category: { select: { name: true } } },\n    });\n    res.json({ product: serializeProduct(product) });\n  }),\n);\n\nexport default router;\n",
"server/src/routes/public.routes.js": "import rateLimit from 'express-rate-limit';\nimport { Router } from 'express';\nimport { z } from 'zod';\nimport { publicPlans, quote, isValidPlan, MAX_SEATS, MIN_SEATS } from '../config/plans.js';\nimport { signToken } from '../middleware/auth.js';\nimport { validate } from '../middleware/validate.js';\nimport { createOrganization } from '../services/organization.service.js';\nimport { describeSubscription } from '../services/billing.service.js';\nimport { asyncHandler, HttpError } from '../utils/http.js';\nimport { publicUser } from '../utils/serialize.js';\n\nconst router = Router();\n\nconst signupLimiter = rateLimit({\n  windowMs: 60 * 60 * 1000,\n  limit: 10,\n  standardHeaders: 'draft-7',\n  legacyHeaders: false,\n  message: { error: { code: 'RATE_LIMITED', message: 'Too many sign-ups from this network. Try again later.' } },\n});\n\nrouter.get('/plans', (_req, res) => {\n  res.json(publicPlans());\n});\n\nrouter.get(\n  '/quote',\n  validate({\n    query: z.object({\n      plan: z.enum(['STANDARD', 'CUSTOM']),\n      interval: z.enum(['MONTHLY', 'YEARLY']),\n      seats: z.coerce.number().int().min(MIN_SEATS).max(MAX_SEATS),\n    }),\n  }),\n  (req, res) => {\n    const { plan, interval, seats } = req.query;\n    if (!isValidPlan(plan, interval)) throw new HttpError(400, 'Unknown plan');\n    res.json({ quote: quote({ plan, interval, seats }) });\n  },\n);\n\nconst signupSchema = z.object({\n  storeName: z.string().trim().min(2, 'Enter your store name').max(80),\n  name: z.string().trim().min(2, 'Enter your name').max(80),\n  email: z.string().trim().toLowerCase().email('Enter a valid email address'),\n  phone: z.string().trim().max(20).regex(/^[+\\d\\s-]*$/, 'Phone can only contain digits, spaces, + and -').optional().or(z.literal('')),\n  password: z.string().min(8, 'Use at least 8 characters').max(128),\n});\n\n/** Start a free trial. Returns a session so the new admin lands straight in the app. */\nrouter.post(\n  '/signup',\n  signupLimiter,\n  validate({ body: signupSchema }),\n  asyncHandler(async (req, res) => {\n    const { organization, user, subscription } = await createOrganization(req.body);\n    res.status(201).json({\n      token: signToken(user),\n      user: publicUser(user),\n      organization: { id: organization.id, name: organization.name, slug: organization.slug },\n      subscription: describeSubscription(subscription, 1),\n    });\n  }),\n);\n\nexport default router;\n",
"server/src/routes/reports.routes.js": "import { Router } from 'express';\nimport { z } from 'zod';\nimport { authorize, ROLES } from '../middleware/auth.js';\nimport { validate } from '../middleware/validate.js';\nimport { categoryReport, overviewReport, productReport } from '../services/report.service.js';\nimport { asyncHandler } from '../utils/http.js';\nimport { dateRangeQuery, pagination } from './schemas.js';\n\nconst router = Router();\n\n// Daily Business Report & Analytics are admin-only; cashiers receive 403 for every route below.\nrouter.use(authorize(ROLES.ADMIN));\n\nrouter.get(\n  '/overview',\n  validate({ query: dateRangeQuery }),\n  asyncHandler(async (req, res) => {\n    res.json(await overviewReport(req.user.organizationId, req.query.from, req.query.to));\n  }),\n);\n\nrouter.get(\n  '/categories',\n  validate({ query: z.intersection(dateRangeQuery, z.object({ level: z.enum(['leaf', 'top']).default('leaf') })) }),\n  asyncHandler(async (req, res) => {\n    res.json(await categoryReport(req.user.organizationId, req.query.from, req.query.to, req.query.level));\n  }),\n);\n\nrouter.get(\n  '/products',\n  validate({\n    query: z.intersection(\n      dateRangeQuery,\n      z.object({\n        ...pagination,\n        q: z.string().trim().max(100).default(''),\n        sort: z.enum(['revenue', 'units', 'growth', 'stock', 'name']).default('revenue'),\n      }),\n    ),\n  }),\n  asyncHandler(async (req, res) => {\n    res.json(await productReport(req.user.organizationId, req.query));\n  }),\n);\n\nexport default router;\n",
"server/src/routes/schemas.js": "import { z } from 'zod';\nimport { diffDays, isIsoDate } from '../utils/dates.js';\n\nexport const idParam = z.object({ id: z.string().uuid('Invalid id') });\n\nexport const pagination = {\n  page: z.coerce.number().int().min(1).default(1),\n  pageSize: z.coerce.number().int().min(1).max(200).default(25),\n};\n\nexport const dateRangeQuery = z\n  .object({\n    from: z.string().refine(isIsoDate, 'Use YYYY-MM-DD'),\n    to: z.string().refine(isIsoDate, 'Use YYYY-MM-DD'),\n  })\n  .refine((v) => v.from <= v.to, { message: '\"from\" must be on or before \"to\"', path: ['from'] })\n  .refine((v) => diffDays(v.from, v.to) <= 730, { message: 'Choose a period of two years or less', path: ['to'] });\n\nexport const emptyToNull = (schema) =>\n  z.preprocess((v) => (typeof v === 'string' && v.trim() === '' ? null : v), schema.nullish());\n",
"server/src/routes/settings.routes.js": "import { Router } from 'express';\nimport { z } from 'zod';\nimport { authorize, ROLES } from '../middleware/auth.js';\nimport { validate } from '../middleware/validate.js';\nimport { getSettings, updateSettings } from '../services/settings.service.js';\nimport { asyncHandler } from '../utils/http.js';\nimport { serializeSettings } from '../utils/serialize.js';\nimport { emptyToNull } from './schemas.js';\n\nconst router = Router();\n\nconst settingsSchema = z.object({\n  storeName: z.string().trim().min(1, 'Store name is required').max(80),\n  tagline: emptyToNull(z.string().trim().max(120)),\n  gstin: emptyToNull(\n    z\n      .string()\n      .trim()\n      .toUpperCase()\n      .regex(/^\\d{2}[A-Z]{5}\\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/, 'GSTIN must be 15 characters, e.g. 29ABCDE1234F1Z5'),\n  ),\n  address: emptyToNull(z.string().trim().max(250)),\n  phone: emptyToNull(z.string().trim().max(20).regex(/^[+\\d\\s-]+$/, 'Phone can only contain digits, spaces, + and -')),\n  upiVpa: emptyToNull(\n    z\n      .string()\n      .trim()\n      .regex(/^[a-zA-Z0-9.\\-_]{2,256}@[a-zA-Z]{2,64}$/, 'UPI ID looks like name@bank'),\n  ),\n  upiPayeeName: emptyToNull(z.string().trim().max(60)),\n  currency: z.string().trim().length(3).toUpperCase().default('INR'),\n  taxRate: z.coerce.number().min(0).max(50),\n  maxCashierDiscountPct: z.coerce.number().min(0).max(100),\n  receiptFooter: emptyToNull(z.string().trim().max(200)),\n});\n\nrouter.get(\n  '/',\n  authorize(ROLES.ADMIN, ROLES.CASHIER),\n  asyncHandler(async (req, res) => {\n    res.json({ settings: serializeSettings(await getSettings(req.user.organizationId)) });\n  }),\n);\n\nrouter.put(\n  '/',\n  authorize(ROLES.ADMIN),\n  validate({ body: settingsSchema }),\n  asyncHandler(async (req, res) => {\n    res.json({ settings: serializeSettings(await updateSettings(req.user.organizationId, req.body)) });\n  }),\n);\n\nexport default router;\n",
"server/src/routes/transactions.routes.js": "import { Router } from 'express';\nimport { z } from 'zod';\nimport { prisma } from '../lib/prisma.js';\nimport { authorize, ROLES } from '../middleware/auth.js';\nimport { validate } from '../middleware/validate.js';\nimport { periodBounds } from '../services/report.service.js';\nimport { getSettings } from '../services/settings.service.js';\nimport { ingestTransaction, voidTransaction } from '../services/transaction.service.js';\nimport { asyncHandler, HttpError, notFound } from '../utils/http.js';\nimport { serializeTransaction } from '../utils/serialize.js';\nimport { dateRangeQuery, emptyToNull, idParam, pagination } from './schemas.js';\n\nconst router = Router();\n\n/**\n * Upload bills from a terminal's outbox. Every bill (online or queued offline) goes through here.\n * Bills are validated individually so one bad bill doesn't block the rest of the queue.\n */\nrouter.post(\n  '/sync',\n  authorize(ROLES.CASHIER, ROLES.ADMIN),\n  validate({ body: z.object({ transactions: z.array(z.unknown()).min(1).max(50) }) }),\n  asyncHandler(async (req, res) => {\n    const settings = await getSettings(req.user.organizationId);\n    const results = [];\n    for (const tx of req.body.transactions) {\n      results.push(await ingestTransaction(tx, req.user, settings));\n    }\n    res.json({ results });\n  }),\n);\n\nconst ledgerQuery = z\n  .object({\n    ...pagination,\n    from: z.string(),\n    to: z.string(),\n    method: z.enum(['ALL', 'CASH', 'UPI', 'CARD']).default('ALL'),\n    status: z.enum(['ALL', 'COMPLETED', 'VOIDED']).default('ALL'),\n    q: z.string().trim().max(40).default(''),\n  })\n  .superRefine((v, ctx) => {\n    const r = dateRangeQuery.safeParse({ from: v.from, to: v.to });\n    if (!r.success) r.error.issues.forEach((i) => ctx.addIssue(i));\n  });\n\nrouter.get(\n  '/',\n  authorize(ROLES.ADMIN),\n  validate({ query: ledgerQuery }),\n  asyncHandler(async (req, res) => {\n    const { page, pageSize, from, to, method, status, q } = req.query;\n    const { start, end } = await periodBounds(from, to);\n    const invoiceNo = /^\\d{1,9}$/.test(q.replace(/^#|^INV-?/i, '')) ? Number(q.replace(/^#|^INV-?/i, '')) : null;\n\n    const where = {\n      organizationId: req.user.organizationId,\n      soldAt: { gte: start, lt: end },\n      ...(method !== 'ALL' ? { paymentMethod: method } : {}),\n      ...(status !== 'ALL' ? { status } : {}),\n      ...(q ? { OR: [...(invoiceNo ? [{ invoiceNo }] : []), { customerPhone: { contains: q } }] } : {}),\n    };\n\n    const [total, rows] = await Promise.all([\n      prisma.transaction.count({ where }),\n      prisma.transaction.findMany({\n        where,\n        orderBy: { soldAt: 'desc' },\n        skip: (page - 1) * pageSize,\n        take: pageSize,\n        include: { cashier: { select: { id: true, name: true } }, _count: { select: { items: true } } },\n      }),\n    ]);\n    res.json({ page, pageSize, total, transactions: rows.map(serializeTransaction) });\n  }),\n);\n\nrouter.get(\n  '/:id',\n  authorize(ROLES.ADMIN),\n  validate({ params: idParam }),\n  asyncHandler(async (req, res) => {\n    const tx = await prisma.transaction.findFirst({\n      where: { id: req.params.id, organizationId: req.user.organizationId },\n      include: { items: { orderBy: { productName: 'asc' } }, cashier: { select: { id: true, name: true } } },\n    });\n    if (!tx) throw notFound('Transaction');\n    res.json({ transaction: serializeTransaction(tx) });\n  }),\n);\n\nrouter.post(\n  '/:id/void',\n  authorize(ROLES.ADMIN),\n  validate({ params: idParam, body: z.object({ reason: emptyToNull(z.string().trim().min(3).max(200)) }) }),\n  asyncHandler(async (req, res) => {\n    if (!req.body.reason) throw new HttpError(400, 'Add a reason for voiding this bill');\n    const result = await voidTransaction(req.params.id, req.body.reason, req.user);\n    if (result.error === 'NOT_FOUND') throw notFound('Transaction');\n    if (result.error === 'ALREADY_VOIDED') throw new HttpError(409, 'This bill is already voided');\n    res.json({ transaction: serializeTransaction(result.transaction) });\n  }),\n);\n\nexport default router;\n",
"server/src/routes/users.routes.js": "import bcrypt from 'bcryptjs';\nimport { Router } from 'express';\nimport { z } from 'zod';\nimport { prisma } from '../lib/prisma.js';\nimport { authorize, invalidateUserCache, ROLES } from '../middleware/auth.js';\nimport { requireActiveSubscription } from '../middleware/subscription.js';\nimport { validate } from '../middleware/validate.js';\nimport { assertSeatsAvailable } from '../services/billing.service.js';\nimport { asyncHandler, HttpError } from '../utils/http.js';\nimport { publicUser } from '../utils/serialize.js';\nimport { idParam } from './schemas.js';\n\nconst router = Router();\nrouter.use(authorize(ROLES.ADMIN));\n\nconst password = z.string().min(8, 'Password needs at least 8 characters').max(128);\n\nconst createSchema = z.object({\n  name: z.string().trim().min(1, 'Name is required').max(80),\n  email: z.string().trim().toLowerCase().email('Enter a valid email address'),\n  password,\n  role: z.enum(['CASHIER', 'ADMIN']).default('CASHIER'),\n});\n\nconst updateSchema = z.object({\n  name: z.string().trim().min(1).max(80).optional(),\n  role: z.enum(['CASHIER', 'ADMIN']).optional(),\n  isActive: z.boolean().optional(),\n  password: password.optional(),\n});\n\nrouter.get(\n  '/',\n  asyncHandler(async (req, res) => {\n    const users = await prisma.user.findMany({\n      where: { organizationId: req.user.organizationId },\n      orderBy: [{ role: 'desc' }, { name: 'asc' }],\n    });\n    res.json({ users: users.map(publicUser) });\n  }),\n);\n\nrouter.post(\n  '/',\n  requireActiveSubscription,\n  validate({ body: createSchema }),\n  asyncHandler(async (req, res) => {\n    const { password: plain, ...data } = req.body;\n    await assertSeatsAvailable(req.user.organizationId, 1);\n    const user = await prisma.user.create({\n      data: { ...data, organizationId: req.user.organizationId, passwordHash: await bcrypt.hash(plain, 12) },\n    });\n    res.status(201).json({ user: publicUser(user) });\n  }),\n);\n\nrouter.patch(\n  '/:id',\n  validate({ params: idParam, body: updateSchema }),\n  asyncHandler(async (req, res) => {\n    const { password: plain, ...data } = req.body;\n    if (req.params.id === req.user.id && (data.isActive === false || data.role === 'CASHIER')) {\n      throw new HttpError(400, 'You cannot deactivate or demote your own account');\n    }\n    const target = await prisma.user.findFirst({\n      where: { id: req.params.id, organizationId: req.user.organizationId },\n      select: { id: true, isActive: true },\n    });\n    if (!target) throw new HttpError(404, 'Team member not found');\n    // Reactivating someone takes a seat, so check the plan covers it.\n    if (data.isActive === true && !target.isActive) await assertSeatsAvailable(req.user.organizationId, 1);\n    const user = await prisma.user.update({\n      where: { id: req.params.id },\n      data: { ...data, ...(plain ? { passwordHash: await bcrypt.hash(plain, 12) } : {}) },\n    });\n    invalidateUserCache(user.id);\n    res.json({ user: publicUser(user) });\n  }),\n);\n\nexport default router;\n",
"server/tests/billing.test.js": "import assert from 'node:assert/strict';\nimport crypto from 'node:crypto';\nimport { test } from 'node:test';\nimport { PLANS, quote } from '../src/config/plans.js';\nimport { subscriptionActive, verifyPaymentSignature, verifyWebhookSignature } from '../src/services/billing.service.js';\n\nconst SECRET = 'rzp_test_secret_value';\n\ntest('published pricing matches the plan sheet', () => {\n  assert.deepEqual(PLANS.STANDARD.intervals.MONTHLY, { listPrice: 850, price: 650 });\n  assert.deepEqual(PLANS.STANDARD.intervals.YEARLY, { listPrice: 650, price: 550 });\n  assert.deepEqual(PLANS.CUSTOM.intervals.MONTHLY, { listPrice: 1300, price: 1000 });\n  assert.deepEqual(PLANS.CUSTOM.intervals.YEARLY, { listPrice: 1000, price: 800 });\n});\n\ntest('quotes multiply by seats, and yearly bills twelve months up front', () => {\n  const monthly = quote({ plan: 'STANDARD', interval: 'MONTHLY', seats: 4 });\n  assert.equal(monthly.total, 650 * 4);\n  assert.equal(monthly.listTotal, 850 * 4);\n  assert.equal(monthly.savings, 200 * 4);\n\n  const yearly = quote({ plan: 'CUSTOM', interval: 'YEARLY', seats: 3 });\n  assert.equal(yearly.months, 12);\n  assert.equal(yearly.total, 800 * 3 * 12);\n  assert.equal(yearly.savings, 200 * 3 * 12);\n});\n\ntest('seat counts are clamped to the allowed range', () => {\n  assert.equal(quote({ plan: 'STANDARD', interval: 'MONTHLY', seats: 0 }).seats, 1);\n  assert.equal(quote({ plan: 'STANDARD', interval: 'MONTHLY', seats: 10_000 }).seats, 500);\n});\n\ntest('a genuine Razorpay payment signature verifies', () => {\n  const orderId = 'order_ABC123';\n  const paymentId = 'pay_XYZ789';\n  const signature = crypto.createHmac('sha256', SECRET).update(`${orderId}|${paymentId}`).digest('hex');\n  assert.equal(verifyPaymentSignature({ orderId, paymentId, signature }, SECRET), true);\n});\n\ntest('tampered, swapped or missing payment signatures are rejected', () => {\n  const orderId = 'order_ABC123';\n  const paymentId = 'pay_XYZ789';\n  const good = crypto.createHmac('sha256', SECRET).update(`${orderId}|${paymentId}`).digest('hex');\n  assert.equal(verifyPaymentSignature({ orderId, paymentId, signature: `${good.slice(0, -1)}0` }, SECRET), false);\n  assert.equal(verifyPaymentSignature({ orderId: 'order_OTHER', paymentId, signature: good }, SECRET), false);\n  assert.equal(verifyPaymentSignature({ orderId, paymentId: 'pay_OTHER', signature: good }, SECRET), false);\n  assert.equal(verifyPaymentSignature({ orderId, paymentId, signature: good }, 'wrong-secret'), false);\n  assert.equal(verifyPaymentSignature({ orderId, paymentId, signature: '' }, SECRET), false);\n  assert.equal(verifyPaymentSignature({ orderId, paymentId, signature: good }, ''), false);\n});\n\ntest('webhook signatures cover the exact raw body', () => {\n  const body = Buffer.from(JSON.stringify({ event: 'payment.captured', payload: {} }));\n  const signature = crypto.createHmac('sha256', SECRET).update(body).digest('hex');\n  assert.equal(verifyWebhookSignature(body, signature, SECRET), true);\n  assert.equal(verifyWebhookSignature(Buffer.from(`${body.toString()} `), signature, SECRET), false);\n  assert.equal(verifyWebhookSignature(body, 'deadbeef', SECRET), false);\n});\n\ntest('access follows the trial and paid period', () => {\n  const future = new Date(Date.now() + 86_400_000);\n  const past = new Date(Date.now() - 86_400_000);\n  assert.equal(subscriptionActive({ status: 'TRIALING', trialEndsAt: future }), true);\n  assert.equal(subscriptionActive({ status: 'TRIALING', trialEndsAt: past }), false);\n  assert.equal(subscriptionActive({ status: 'ACTIVE', currentPeriodEnd: future }), true);\n  assert.equal(subscriptionActive({ status: 'ACTIVE', currentPeriodEnd: past }), false);\n  assert.equal(subscriptionActive({ status: 'CANCELLED', currentPeriodEnd: future }), false);\n  assert.equal(subscriptionActive(null), false);\n});\n",
"server/tests/pricing.test.js": "import assert from 'node:assert/strict';\nimport { test } from 'node:test';\nimport { allocate, computeBill } from '../src/utils/pricing.js';\n\ntest('allocate distributes remainders so parts always sum to the total', () => {\n  const parts = allocate(100, [1, 1, 1]);\n  assert.equal(parts.reduce((a, b) => a + b, 0), 100);\n  assert.deepEqual(parts, [34, 33, 33]);\n  assert.deepEqual(allocate(0, [5, 5]), [0, 0]);\n});\n\ntest('weighed produce with markdown, bill discount and GST', () => {\n  const bill = computeBill({\n    items: [\n      { productId: 'a', quantity: 1.25, unitPrice: 160, discountPercent: 0 }, // 200.00\n      { productId: 'b', quantity: 1, unitPrice: 48, discountPercent: 20 }, // 48.00 − 9.60\n    ],\n    billDiscount: { type: 'PERCENT', value: 10 },\n    taxRate: 5,\n  });\n  assert.equal(bill.subtotal, 24800);\n  assert.equal(bill.itemDiscount, 960);\n  assert.equal(bill.billDiscount, 2384); // 10% of 238.40\n  assert.equal(bill.taxableAmount, 21456);\n  assert.equal(bill.taxTotal, 1073); // 5% of 214.56 = 10.728\n  assert.equal(bill.grandTotal, 22529);\n  assert.equal(bill.lines.reduce((s, l) => s + l.netAmount, 0), bill.taxableAmount);\n});\n\ntest('flat discount cannot exceed the bill', () => {\n  const bill = computeBill({ items: [{ quantity: 2, unitPrice: 10 }], billDiscount: { type: 'FLAT', value: 500 }, taxRate: 5 });\n  assert.equal(bill.billDiscount, 2000);\n  assert.equal(bill.grandTotal, 0);\n});\n\ntest('floating point quantities round to grams', () => {\n  const bill = computeBill({ items: [{ quantity: 0.1 + 0.2, unitPrice: 99.99 }], taxRate: 0 });\n  assert.equal(bill.lines[0].quantity, 0.3);\n  assert.equal(bill.grandTotal, 3000); // 99.99 × 0.3 = 29.997 → 30.00\n});\n",
"client/.env.example": "# Leave empty to call the API on the same origin (/api), which is how the Vite proxy and nginx are set up.\nVITE_API_URL=\n# Where `npm run dev` proxies /api requests\nVITE_DEV_API_TARGET=http://localhost:4000\n",
"client/.gitignore": "node_modules/\ndist/\nbuild/\n.env\n.env.local\n.env.*.local\n*.log\nnpm-debug.log*\n.DS_Store\n.vscode/\n.idea/\ncoverage/\n*.tgz\n",
"client/index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.svg\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\" />\n    <meta name=\"theme-color\" content=\"#059669\" />\n    <meta name=\"description\" content=\"FreshFlow grocery point of sale and back office\" />\n    <title>FreshFlow POS</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <div id=\"print-root\" aria-hidden=\"true\"></div>\n    <script type=\"module\" src=\"/src/main.jsx\"></script>\n  </body>\n</html>\n",
"client/package.json": "{\n  \"name\": \"freshflow-client\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview --port 4173\"\n  },\n  \"dependencies\": {\n    \"axios\": \"^1.7.9\",\n    \"qrcode\": \"^1.5.4\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"react-icons\": \"^5.4.0\",\n    \"react-router-dom\": \"^6.28.1\",\n    \"zustand\": \"^5.0.2\"\n  },\n  \"devDependencies\": {\n    \"@vitejs/plugin-react\": \"^4.3.4\",\n    \"autoprefixer\": \"^10.4.20\",\n    \"postcss\": \"^8.4.49\",\n    \"tailwindcss\": \"^3.4.17\",\n    \"vite\": \"^5.4.11\"\n  }\n}\n",
"client/postcss.config.js": "export default {\n  plugins: {\n    tailwindcss: {},\n    autoprefixer: {},\n  },\n};\n",
"client/tailwind.config.js": "/** @type {import('tailwindcss').Config} */\nexport default {\n  content: ['./index.html', './src/**/*.{js,jsx}'],\n  theme: {\n    /*\n     * Typography is locked to exactly four sizes. `fontSize` replaces (not extends) Tailwind's scale,\n     * so classes like text-lg or text-xs do not exist and cannot drift into the UI.\n     */\n    fontSize: {\n      h1: ['18px', { lineHeight: '24px', letterSpacing: '-0.012em' }],\n      h2: ['16px', { lineHeight: '22px', letterSpacing: '-0.008em' }],\n      body: ['14px', { lineHeight: '20px', letterSpacing: '-0.003em' }],\n      desc: ['12px', { lineHeight: '16px' }],\n    },\n    extend: {\n      colors: {\n        brand: {\n          DEFAULT: '#059669',\n          50: '#ECFDF5',\n          100: '#D1FAE5',\n          200: '#A7F3D0',\n          500: '#10B981',\n          600: '#059669',\n          700: '#047857',\n          800: '#065F46',\n        },\n      },\n      fontFamily: {\n        sans: ['-apple-system', 'BlinkMacSystemFont', '\"SF Pro Text\"', '\"Inter\"', '\"Segoe UI\"', 'Roboto', '\"Helvetica Neue\"', 'Arial', 'sans-serif'],\n      },\n      boxShadow: {\n        card: '0 1px 2px rgba(15, 23, 42, 0.04), 0 4px 16px rgba(15, 23, 42, 0.04)',\n        lift: '0 12px 40px rgba(15, 23, 42, 0.12)',\n        glass: '0 24px 64px rgba(15, 23, 42, 0.18)',\n      },\n      borderRadius: {\n        '4xl': '2rem',\n      },\n      keyframes: {\n        'sheet-in': { from: { transform: 'translateY(16px)', opacity: '0' }, to: { transform: 'translateY(0)', opacity: '1' } },\n        'fade-in': { from: { opacity: '0' }, to: { opacity: '1' } },\n        pop: { '0%': { transform: 'scale(1)' }, '40%': { transform: 'scale(1.18)' }, '100%': { transform: 'scale(1)' } },\n      },\n      animation: {\n        'sheet-in': 'sheet-in 180ms cubic-bezier(0.2, 0.8, 0.2, 1)',\n        'fade-in': 'fade-in 150ms ease-out',\n        pop: 'pop 220ms ease-out',\n      },\n    },\n  },\n  plugins: [],\n};\n",
"client/vite.config.js": "import react from '@vitejs/plugin-react';\nimport { defineConfig, loadEnv } from 'vite';\n\nexport default defineConfig(({ mode }) => {\n  const env = loadEnv(mode, process.cwd(), '');\n  return {\n    plugins: [react()],\n    server: {\n      port: 5173,\n      host: true,\n      proxy: {\n        '/api': { target: env.VITE_DEV_API_TARGET || 'http://localhost:4000', changeOrigin: true },\n      },\n    },\n    preview: {\n      port: 4173,\n      proxy: {\n        '/api': { target: env.VITE_DEV_API_TARGET || 'http://localhost:4000', changeOrigin: true },\n      },\n    },\n    build: {\n      target: 'es2020',\n      sourcemap: false,\n      chunkSizeWarningLimit: 700,\n    },\n  };\n});\n",
"client/src/App.jsx": "import { lazy, useEffect } from 'react';\nimport { Navigate, Route, Routes } from 'react-router-dom';\nimport { AppShell } from './components/layout/AppShell';\nimport { Toaster } from './components/ui/Toaster';\nimport LandingPage from './pages/LandingPage';\nimport LoginPage from './pages/LoginPage';\nimport PosPage from './pages/PosPage';\nimport PricingPage from './pages/PricingPage';\nimport SignupPage from './pages/SignupPage';\nimport { RequireAuth, RequireRole } from './routes/guards';\nimport { useAuthStore } from './store/authStore';\n\n// Admin areas load on demand, so a cashier's till never downloads them.\nconst ReportsPage = lazy(() => import('./pages/ReportsPage'));\nconst InventoryPage = lazy(() => import('./pages/InventoryPage'));\nconst SettingsPage = lazy(() => import('./pages/SettingsPage'));\nconst BillingPage = lazy(() => import('./pages/BillingPage'));\n\nexport default function App() {\n  const refreshProfile = useAuthStore((s) => s.refreshProfile);\n\n  useEffect(() => {\n    refreshProfile();\n  }, [refreshProfile]);\n\n  return (\n    <>\n      <Routes>\n        {/* Public site */}\n        <Route path=\"/\" element={<LandingPage />} />\n        <Route path=\"/pricing\" element={<PricingPage />} />\n        <Route path=\"/signup\" element={<SignupPage />} />\n        <Route path=\"/login\" element={<LoginPage />} />\n\n        {/* The application */}\n        <Route\n          path=\"/app\"\n          element={\n            <RequireAuth>\n              <AppShell />\n            </RequireAuth>\n          }\n        >\n          <Route index element={<PosPage />} />\n          <Route element={<RequireRole roles={['ADMIN']} />}>\n            <Route path=\"reports\" element={<ReportsPage />} />\n            <Route path=\"inventory\" element={<InventoryPage />} />\n            <Route path=\"settings\" element={<SettingsPage />} />\n            <Route path=\"billing\" element={<BillingPage />} />\n          </Route>\n        </Route>\n\n        <Route path=\"*\" element={<Navigate to=\"/\" replace />} />\n      </Routes>\n      <Toaster />\n    </>\n  );\n}\n",
"client/src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n@layer base {\n  html,\n  body,\n  #root {\n    height: 100%;\n  }\n  body {\n    @apply bg-slate-50 font-sans text-body text-slate-900 antialiased;\n    -webkit-tap-highlight-color: transparent;\n  }\n  h1 {\n    @apply text-h1 font-semibold;\n  }\n  h2 {\n    @apply text-h2 font-semibold;\n  }\n  h3 {\n    @apply text-body font-semibold;\n  }\n  input,\n  select,\n  textarea,\n  button {\n    @apply text-body;\n  }\n  :focus-visible {\n    @apply outline-none ring-2 ring-brand/60 ring-offset-2 ring-offset-white;\n  }\n  ::selection {\n    @apply bg-brand-100 text-brand-800;\n  }\n}\n\n@layer components {\n  .tabular {\n    font-variant-numeric: tabular-nums;\n  }\n  .field {\n    @apply block w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-body text-slate-900 placeholder:text-slate-400 transition focus:border-brand focus:outline-none focus:ring-4 focus:ring-brand/10 disabled:bg-slate-50 disabled:text-slate-500;\n  }\n  .label {\n    @apply mb-1.5 block text-desc font-medium text-slate-600;\n  }\n  .glass {\n    @apply border border-white/60 bg-white/80 backdrop-blur-xl;\n  }\n  .scroll-thin {\n    scrollbar-width: thin;\n    scrollbar-color: #cbd5e1 transparent;\n  }\n  .no-scrollbar {\n    scrollbar-width: none;\n  }\n  .no-scrollbar::-webkit-scrollbar {\n    display: none;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    animation-duration: 1ms !important;\n    transition-duration: 1ms !important;\n  }\n}\n\n/* 80 mm thermal receipt printing */\n#print-root {\n  display: none;\n}\n@media print {\n  @page {\n    size: 80mm auto;\n    margin: 4mm;\n  }\n  body > *:not(#print-root) {\n    display: none !important;\n  }\n  #print-root {\n    display: block !important;\n  }\n}\n",
"client/src/main.jsx": "import React from 'react';\nimport { createRoot } from 'react-dom/client';\nimport { BrowserRouter } from 'react-router-dom';\nimport App from './App';\nimport './index.css';\nimport { configureApi } from './lib/api';\nimport { startSyncEngine } from './lib/sync';\nimport { useAuthStore } from './store/authStore';\nimport { toast } from './store/toastStore';\n\nconfigureApi({\n  getToken: () => useAuthStore.getState().token,\n  onUnauthorized: (code) => {\n    if (!useAuthStore.getState().token) return;\n    const message =\n      code === 'ACCOUNT_DISABLED'\n        ? 'This account has been deactivated. Ask your store admin.'\n        : code === 'ROLE_CHANGED'\n          ? 'Your role changed. Sign in again to continue.'\n          : 'Your session expired. Sign in again.';\n    useAuthStore.getState().logout(message);\n    toast.warn(message);\n  },\n});\n\nstartSyncEngine();\n\nif ('serviceWorker' in navigator && import.meta.env.PROD) {\n  window.addEventListener('load', () => {\n    navigator.serviceWorker.register('/sw.js').catch(() => {});\n  });\n}\n\ncreateRoot(document.getElementById('root')).render(\n  <React.StrictMode>\n    <BrowserRouter>\n      <App />\n    </BrowserRouter>\n  </React.StrictMode>,\n);\n",
"client/src/components/admin/CategoryManager.jsx": "import { useState } from 'react';\nimport { LuChevronRight, LuPencil, LuPlus, LuTrash2 } from 'react-icons/lu';\nimport { api, errorMessage } from '../../lib/api';\nimport { toast } from '../../store/toastStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { EmptyState } from '../ui/States';\n\nconst SUGGESTED_ICONS = ['🥩', '🐟', '🍗', '🥦', '🍎', '🥛', '🍞', '🌾', '🥤', '🧴', '🧹', '✏️', '🧊', '🍫'];\n\nfunction CategoryForm({ open, category, parent, categories, onClose, onSaved }) {\n  const [name, setName] = useState('');\n  const [icon, setIcon] = useState('');\n  const [parentId, setParentId] = useState('');\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState(null);\n  const [ready, setReady] = useState(false);\n\n  if (open && !ready) {\n    setName(category?.name ?? '');\n    setIcon(category?.icon ?? '');\n    setParentId(category?.parentId ?? parent?.id ?? '');\n    setError(null);\n    setReady(true);\n  }\n  if (!open && ready) setReady(false);\n\n  const tops = categories.filter((c) => !c.parentId && c.id !== category?.id);\n\n  const save = async () => {\n    setSaving(true);\n    setError(null);\n    try {\n      const body = { name, icon, parentId: parentId || null, sortOrder: category?.sortOrder ?? 0 };\n      if (category) await api.put(`/categories/${category.id}`, body);\n      else await api.post('/categories', body);\n      toast.success(category ? 'Category updated' : `${name} added`);\n      onSaved();\n      onClose();\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  return (\n    <Modal\n      open={open}\n      onClose={onClose}\n      size=\"sm\"\n      title={category ? 'Edit category' : parent ? `Add under ${parent.name}` : 'Add category'}\n      footer={\n        <Button className=\"w-full\" onClick={save} loading={saving} disabled={name.trim().length < 1}>\n          {category ? 'Save changes' : 'Add category'}\n        </Button>\n      }\n    >\n      <div className=\"space-y-4\">\n        <div>\n          <label htmlFor=\"cat-name\" className=\"label\">Name</label>\n          <input id=\"cat-name\" className=\"field\" value={name} onChange={(e) => setName(e.target.value)} placeholder=\"Meat\" maxLength={60} autoFocus />\n        </div>\n        <div>\n          <label htmlFor=\"cat-icon\" className=\"label\">Icon shown on the register</label>\n          <input id=\"cat-icon\" className=\"field\" value={icon} onChange={(e) => setIcon(e.target.value.slice(0, 4))} placeholder=\"🥩\" />\n          <div className=\"mt-2 flex flex-wrap gap-1.5\">\n            {SUGGESTED_ICONS.map((emoji) => (\n              <button\n                key={emoji}\n                type=\"button\"\n                onClick={() => setIcon(emoji)}\n                className={`grid h-9 w-9 place-items-center rounded-xl text-h2 transition ${icon === emoji ? 'bg-brand-50 ring-2 ring-brand' : 'bg-slate-50 hover:bg-slate-100'}`}\n                aria-label={`Use ${emoji}`}\n              >\n                {emoji}\n              </button>\n            ))}\n          </div>\n        </div>\n        <div>\n          <label htmlFor=\"cat-parent\" className=\"label\">Sits under</label>\n          <select id=\"cat-parent\" className=\"field\" value={parentId} onChange={(e) => setParentId(e.target.value)}>\n            <option value=\"\">Top level department</option>\n            {tops.map((c) => (\n              <option key={c.id} value={c.id}>\n                {c.icon ? `${c.icon} ` : ''}\n                {c.name}\n              </option>\n            ))}\n          </select>\n          <p className=\"mt-1 text-desc text-slate-500\">Departments can hold sub-categories one level deep.</p>\n        </div>\n        {error ? <p className=\"rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">{error}</p> : null}\n      </div>\n    </Modal>\n  );\n}\n\n/** Admin screen for building the category tree, e.g. adding Meat with Poultry under it. */\nexport function CategoryManager({ open, onClose, categories, onChanged }) {\n  const [editing, setEditing] = useState(null);\n  const [addingUnder, setAddingUnder] = useState(null);\n  const [creating, setCreating] = useState(false);\n  const [confirmDelete, setConfirmDelete] = useState(null);\n\n  const tops = categories.filter((c) => !c.parentId);\n  const childrenOf = (id) => categories.filter((c) => c.parentId === id);\n\n  const remove = async (category) => {\n    try {\n      await api.delete(`/categories/${category.id}`);\n      toast.success(`${category.name} removed`);\n      onChanged();\n    } catch (err) {\n      toast.error(errorMessage(err));\n    } finally {\n      setConfirmDelete(null);\n    }\n  };\n\n  const Row = ({ category, nested }) => (\n    <li className={`flex items-center gap-2 py-2 ${nested ? 'pl-7' : ''}`}>\n      {nested ? <LuChevronRight className=\"shrink-0 text-slate-300\" aria-hidden /> : null}\n      <span className=\"grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-slate-50 text-h2\" aria-hidden>\n        {category.icon || category.name[0]}\n      </span>\n      <div className=\"min-w-0 flex-1\">\n        <p className=\"truncate font-medium\">{category.name}</p>\n        <p className=\"text-desc text-slate-500\">\n          {category.productCount ?? 0} product{category.productCount === 1 ? '' : 's'}\n        </p>\n      </div>\n      {!nested ? (\n        <Button size=\"sm\" variant=\"ghost\" onClick={() => setAddingUnder(category)}>\n          <LuPlus aria-hidden /> <span className=\"hidden sm:inline\">Sub</span>\n        </Button>\n      ) : null}\n      <Button size=\"iconSm\" variant=\"ghost\" aria-label={`Edit ${category.name}`} onClick={() => setEditing(category)}>\n        <LuPencil aria-hidden />\n      </Button>\n      {confirmDelete === category.id ? (\n        <Button size=\"sm\" variant=\"danger\" onClick={() => remove(category)}>\n          Confirm\n        </Button>\n      ) : (\n        <Button size=\"iconSm\" variant=\"ghost\" aria-label={`Delete ${category.name}`} onClick={() => setConfirmDelete(category.id)}>\n          <LuTrash2 aria-hidden />\n        </Button>\n      )}\n    </li>\n  );\n\n  return (\n    <>\n      <Modal\n        open={open}\n        onClose={onClose}\n        title=\"Categories\"\n        description=\"Group what you sell. Cashiers browse these on the register.\"\n        footer={\n          <Button className=\"w-full\" onClick={() => setCreating(true)}>\n            <LuPlus aria-hidden /> Add category\n          </Button>\n        }\n      >\n        {tops.length ? (\n          <ul className=\"divide-y divide-slate-100\">\n            {tops.map((top) => (\n              <li key={top.id}>\n                <ul className=\"divide-y divide-slate-50\">\n                  <Row category={top} />\n                  {childrenOf(top.id).map((child) => (\n                    <Row key={child.id} category={child} nested />\n                  ))}\n                </ul>\n              </li>\n            ))}\n          </ul>\n        ) : (\n          <EmptyState title=\"No categories yet\" description=\"Add your first one, such as Meat, Vegetables or Dairy.\" />\n        )}\n      </Modal>\n\n      <CategoryForm open={creating} category={null} parent={null} categories={categories} onClose={() => setCreating(false)} onSaved={onChanged} />\n      <CategoryForm open={Boolean(addingUnder)} category={null} parent={addingUnder} categories={categories} onClose={() => setAddingUnder(null)} onSaved={onChanged} />\n      <CategoryForm open={Boolean(editing)} category={editing} parent={null} categories={categories} onClose={() => setEditing(null)} onSaved={onChanged} />\n    </>\n  );\n}\n",
"client/src/components/admin/ProductForm.jsx": "import { useEffect, useState } from 'react';\nimport { api, errorMessage } from '../../lib/api';\nimport { toast } from '../../store/toastStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\n\nconst BLANK = {\n  code: '', barcode: '', name: '', description: '', categoryId: '', price: '', unit: 'pcs',\n  soldByWeight: false, stock: '0', lowStockThreshold: '5', discountPercent: '0', isQuickKey: false, imageUrl: '', isActive: true,\n};\n\nexport function ProductForm({ open, product, categories, onClose, onSaved }) {\n  const [form, setForm] = useState(BLANK);\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState(null);\n  const editing = Boolean(product);\n  const leafCategories = categories.filter((c) => !categories.some((other) => other.parentId === c.id));\n\n  useEffect(() => {\n    if (!open) return;\n    setError(null);\n    setForm(\n      product\n        ? {\n            code: product.code, barcode: product.barcode ?? '', name: product.name, description: product.description ?? '',\n            categoryId: product.categoryId, price: String(product.price), unit: product.unit, soldByWeight: product.soldByWeight,\n            stock: String(product.stock), lowStockThreshold: String(product.lowStockThreshold), discountPercent: String(product.discountPercent),\n            isQuickKey: product.isQuickKey, imageUrl: product.imageUrl ?? '', isActive: product.isActive,\n          }\n        : BLANK,\n    );\n  }, [open, product]);\n\n  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.type === 'checkbox' ? e.target.checked : e.target.value }));\n\n  const save = async () => {\n    setSaving(true);\n    setError(null);\n    const { stock, ...rest } = form;\n    const payload = {\n      ...rest,\n      price: Number(form.price),\n      lowStockThreshold: Number(form.lowStockThreshold),\n      discountPercent: Number(form.discountPercent),\n    };\n    try {\n      if (editing) await api.put(`/products/${product.id}`, payload);\n      else await api.post('/products', { ...payload, stock: Number(stock) });\n      toast.success(editing ? 'Product updated' : `${form.name} added to the catalog`);\n      onSaved();\n      onClose();\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  const valid = form.name.trim() && form.code.trim() && form.categoryId && form.price !== '';\n\n  return (\n    <Modal\n      open={open}\n      onClose={onClose}\n      title={editing ? 'Edit product' : 'Add product'}\n      description={editing ? 'Changes reach registers the next time they refresh the catalog' : undefined}\n      footer={\n        <div className=\"flex gap-2\">\n          <Button variant=\"secondary\" className=\"flex-1\" onClick={onClose}>\n            Cancel\n          </Button>\n          <Button className=\"flex-1\" onClick={save} loading={saving} disabled={!valid}>\n            {editing ? 'Save changes' : 'Add product'}\n          </Button>\n        </div>\n      }\n    >\n      <div className=\"space-y-4\">\n        <div>\n          <label htmlFor=\"p-name\" className=\"label\">Product name</label>\n          <input id=\"p-name\" className=\"field\" value={form.name} onChange={set('name')} maxLength={120} />\n        </div>\n\n        <div className=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label htmlFor=\"p-code\" className=\"label\">Quick code</label>\n            <input id=\"p-code\" className=\"field tabular\" value={form.code} onChange={set('code')} placeholder=\"101\" maxLength={20} />\n          </div>\n          <div>\n            <label htmlFor=\"p-barcode\" className=\"label\">Barcode (optional)</label>\n            <input id=\"p-barcode\" className=\"field tabular\" value={form.barcode} onChange={set('barcode')} placeholder=\"890123450001\" maxLength={32} />\n          </div>\n        </div>\n\n        <div>\n          <label htmlFor=\"p-category\" className=\"label\">Category</label>\n          <select id=\"p-category\" className=\"field\" value={form.categoryId} onChange={set('categoryId')}>\n            <option value=\"\">Choose a category</option>\n            {leafCategories.map((c) => (\n              <option key={c.id} value={c.id}>\n                {categories.find((p) => p.id === c.parentId)?.name ? `${categories.find((p) => p.id === c.parentId).name} › ` : ''}\n                {c.name}\n              </option>\n            ))}\n          </select>\n        </div>\n\n        <div className=\"grid grid-cols-3 gap-3\">\n          <div>\n            <label htmlFor=\"p-price\" className=\"label\">Price</label>\n            <input id=\"p-price\" inputMode=\"decimal\" className=\"field tabular\" value={form.price} onChange={set('price')} placeholder=\"0.00\" />\n          </div>\n          <div>\n            <label htmlFor=\"p-unit\" className=\"label\">Unit</label>\n            <input id=\"p-unit\" className=\"field\" value={form.unit} onChange={set('unit')} placeholder=\"kg, pcs, pack\" maxLength={12} />\n          </div>\n          <div>\n            <label htmlFor=\"p-markdown\" className=\"label\">Markdown %</label>\n            <input id=\"p-markdown\" inputMode=\"decimal\" className=\"field tabular\" value={form.discountPercent} onChange={set('discountPercent')} />\n          </div>\n        </div>\n\n        <div className=\"grid grid-cols-2 gap-3\">\n          {!editing ? (\n            <div>\n              <label htmlFor=\"p-stock\" className=\"label\">Opening stock</label>\n              <input id=\"p-stock\" inputMode=\"decimal\" className=\"field tabular\" value={form.stock} onChange={set('stock')} />\n            </div>\n          ) : null}\n          <div>\n            <label htmlFor=\"p-low\" className=\"label\">Warn below</label>\n            <input id=\"p-low\" inputMode=\"decimal\" className=\"field tabular\" value={form.lowStockThreshold} onChange={set('lowStockThreshold')} />\n          </div>\n        </div>\n\n        <div>\n          <label htmlFor=\"p-image\" className=\"label\">Image URL (optional)</label>\n          <input id=\"p-image\" className=\"field\" value={form.imageUrl} onChange={set('imageUrl')} placeholder=\"https://…\" />\n        </div>\n\n        <div className=\"space-y-2 rounded-2xl bg-slate-50 p-3\">\n          <label className=\"flex items-center gap-2.5\">\n            <input type=\"checkbox\" className=\"h-4 w-4 rounded border-slate-300 text-brand focus:ring-brand\" checked={form.soldByWeight} onChange={set('soldByWeight')} />\n            <span className=\"text-body\">Sold by weight (opens the scale)</span>\n          </label>\n          <label className=\"flex items-center gap-2.5\">\n            <input type=\"checkbox\" className=\"h-4 w-4 rounded border-slate-300 text-brand focus:ring-brand\" checked={form.isQuickKey} onChange={set('isQuickKey')} />\n            <span className=\"text-body\">Show as a quick key on the register</span>\n          </label>\n          {editing ? (\n            <label className=\"flex items-center gap-2.5\">\n              <input type=\"checkbox\" className=\"h-4 w-4 rounded border-slate-300 text-brand focus:ring-brand\" checked={form.isActive} onChange={set('isActive')} />\n              <span className=\"text-body\">Available for sale</span>\n            </label>\n          ) : null}\n        </div>\n\n        {error ? <p className=\"rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">{error}</p> : null}\n      </div>\n    </Modal>\n  );\n}\n",
"client/src/components/admin/StockAdjustModal.jsx": "import { useEffect, useState } from 'react';\nimport { api, errorMessage } from '../../lib/api';\nimport { formatNumber } from '../../lib/format';\nimport { toast } from '../../store/toastStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { Segmented } from '../ui/Segmented';\n\nexport function StockAdjustModal({ product, onClose, onSaved }) {\n  const [mode, setMode] = useState('ADD');\n  const [quantity, setQuantity] = useState('');\n  const [reason, setReason] = useState('');\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    setMode('ADD');\n    setQuantity('');\n    setReason('');\n    setError(null);\n  }, [product?.id]);\n\n  if (!product) return null;\n\n  const qty = Number(quantity) || 0;\n  const next = mode === 'SET' ? qty : mode === 'ADD' ? product.stock + qty : product.stock - qty;\n\n  const save = async () => {\n    setSaving(true);\n    setError(null);\n    try {\n      await api.patch(`/products/${product.id}/stock`, { mode, quantity: qty, reason });\n      toast.success(`${product.name} stock updated`);\n      onSaved();\n      onClose();\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  return (\n    <Modal\n      open\n      onClose={onClose}\n      size=\"sm\"\n      title=\"Update stock\"\n      description={product.name}\n      footer={\n        <Button className=\"w-full\" onClick={save} loading={saving} disabled={qty <= 0 || reason.trim().length < 2}>\n          Update to {formatNumber(Math.max(0, next))} {product.unit}\n        </Button>\n      }\n    >\n      <div className=\"rounded-2xl bg-slate-50 px-3 py-2 text-body\">\n        On shelf now: <span className=\"font-semibold tabular\">{formatNumber(product.stock)} {product.unit}</span>\n      </div>\n\n      <div className=\"mt-4\">\n        <Segmented\n          className=\"w-full\"\n          ariaLabel=\"Adjustment type\"\n          value={mode}\n          onChange={setMode}\n          options={[\n            { value: 'ADD', label: 'Received' },\n            { value: 'REMOVE', label: 'Removed' },\n            { value: 'SET', label: 'Counted' },\n          ]}\n        />\n      </div>\n\n      <div className=\"mt-4\">\n        <label htmlFor=\"stock-qty\" className=\"label\">\n          {mode === 'SET' ? `Counted stock (${product.unit})` : `Quantity (${product.unit})`}\n        </label>\n        <input id=\"stock-qty\" inputMode=\"decimal\" className=\"field tabular\" value={quantity} onChange={(e) => setQuantity(e.target.value.replace(/[^\\d.]/g, ''))} autoFocus />\n      </div>\n\n      <div className=\"mt-4\">\n        <label htmlFor=\"stock-reason\" className=\"label\">Reason</label>\n        <input id=\"stock-reason\" className=\"field\" value={reason} onChange={(e) => setReason(e.target.value)} placeholder={mode === 'ADD' ? 'Morning delivery' : mode === 'REMOVE' ? 'Damaged in storage' : 'Stock count'} maxLength={200} />\n      </div>\n\n      {next < 0 ? <p className=\"mt-3 rounded-xl bg-amber-50 px-3 py-2 text-desc text-amber-800\">That is more than the shelf holds. Stock will be set to 0.</p> : null}\n      {error ? <p className=\"mt-3 rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">{error}</p> : null}\n    </Modal>\n  );\n}\n",
"client/src/components/ui/Button.jsx": "import { forwardRef } from 'react';\nimport { LuLoaderCircle } from 'react-icons/lu';\n\nconst VARIANTS = {\n  primary: 'bg-brand text-white hover:bg-brand-700 active:bg-brand-800 disabled:bg-slate-200 disabled:text-slate-400',\n  secondary: 'bg-white text-slate-800 border border-slate-200 hover:bg-slate-50 active:bg-slate-100 disabled:text-slate-400',\n  soft: 'bg-brand-50 text-brand-700 hover:bg-brand-100 active:bg-brand-200 disabled:bg-slate-100 disabled:text-slate-400',\n  ghost: 'bg-transparent text-slate-600 hover:bg-slate-100 active:bg-slate-200 disabled:text-slate-300',\n  danger: 'bg-rose-600 text-white hover:bg-rose-700 active:bg-rose-800 disabled:bg-slate-200 disabled:text-slate-400',\n  dangerSoft: 'bg-rose-50 text-rose-700 hover:bg-rose-100 disabled:text-slate-400',\n};\n\nconst SIZES = {\n  sm: 'h-8 px-3 gap-1.5 text-desc',\n  md: 'h-10 px-4 gap-2 text-body',\n  lg: 'h-12 px-6 gap-2 text-h2',\n  icon: 'h-10 w-10 justify-center',\n  iconSm: 'h-8 w-8 justify-center',\n};\n\nexport const Button = forwardRef(function Button(\n  { variant = 'primary', size = 'md', loading = false, className = '', children, disabled, type = 'button', ...props },\n  ref,\n) {\n  return (\n    <button\n      ref={ref}\n      type={type}\n      disabled={disabled || loading}\n      className={`inline-flex shrink-0 select-none items-center justify-center rounded-full font-semibold transition-colors disabled:cursor-not-allowed ${VARIANTS[variant]} ${SIZES[size]} ${className}`}\n      {...props}\n    >\n      {loading ? <LuLoaderCircle className=\"animate-spin\" aria-hidden /> : null}\n      {children}\n    </button>\n  );\n});\n",
"client/src/components/ui/ErrorBoundary.jsx": "import { Component } from 'react';\nimport { Button } from './Button';\n\n/** Keeps a crash in one screen from taking down the register. */\nexport class ErrorBoundary extends Component {\n  constructor(props) {\n    super(props);\n    this.state = { error: null };\n  }\n\n  static getDerivedStateFromError(error) {\n    return { error };\n  }\n\n  componentDidCatch(error, info) {\n    console.error('Screen crashed:', error, info);\n  }\n\n  componentDidUpdate(prevProps) {\n    if (this.state.error && prevProps.resetKey !== this.props.resetKey) {\n      this.setState({ error: null });\n    }\n  }\n\n  render() {\n    if (!this.state.error) return this.props.children;\n    return (\n      <div className=\"grid h-full place-items-center p-6\">\n        <div className=\"max-w-sm text-center\">\n          <h1>This screen ran into a problem</h1>\n          <p className=\"mt-2 text-desc text-slate-500\">\n            Nothing was lost. Completed bills are saved on this register and upload on their own.\n          </p>\n          <div className=\"mt-5 flex justify-center gap-2\">\n            <Button variant=\"secondary\" onClick={() => this.setState({ error: null })}>\n              Try again\n            </Button>\n            <Button onClick={() => window.location.reload()}>Reload</Button>\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n",
"client/src/components/ui/Modal.jsx": "import { useEffect, useId, useRef } from 'react';\nimport { createPortal } from 'react-dom';\nimport { LuX } from 'react-icons/lu';\n\n/**\n * Glass overlay. Centered dialog on tablets/desktop, bottom sheet on phones.\n * Escape closes; focus moves into the dialog and returns to the trigger on close.\n */\nexport function Modal({ open, onClose, title, description, children, footer, size = 'md', dismissible = true, initialFocusRef }) {\n  const panelRef = useRef(null);\n  const titleId = useId();\n  const descId = useId();\n\n  useEffect(() => {\n    if (!open) return undefined;\n    const previouslyFocused = document.activeElement;\n    const target = initialFocusRef?.current || panelRef.current?.querySelector('input, select, textarea, button:not([data-close])') || panelRef.current;\n    requestAnimationFrame(() => target?.focus?.());\n\n    const onKey = (e) => {\n      if (e.key === 'Escape' && dismissible) {\n        e.stopPropagation();\n        onClose?.();\n      }\n      if (e.key === 'Tab' && panelRef.current) {\n        const focusable = [...panelRef.current.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex=\"-1\"])')].filter((el) => !el.disabled);\n        if (!focusable.length) return;\n        const first = focusable[0];\n        const last = focusable[focusable.length - 1];\n        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }\n        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }\n      }\n    };\n    document.addEventListener('keydown', onKey, true);\n    const { overflow } = document.body.style;\n    document.body.style.overflow = 'hidden';\n    return () => {\n      document.removeEventListener('keydown', onKey, true);\n      document.body.style.overflow = overflow;\n      previouslyFocused?.focus?.();\n    };\n  }, [open, dismissible, onClose, initialFocusRef]);\n\n  if (!open) return null;\n\n  const widths = { sm: 'sm:max-w-sm', md: 'sm:max-w-lg', lg: 'sm:max-w-2xl', xl: 'sm:max-w-4xl' };\n\n  return createPortal(\n    <div className=\"fixed inset-0 z-50 flex items-end justify-center sm:items-center sm:p-6\" role=\"presentation\">\n      <div\n        className=\"absolute inset-0 animate-fade-in bg-slate-900/25 backdrop-blur-[6px]\"\n        onClick={dismissible ? onClose : undefined}\n        aria-hidden\n      />\n      <div\n        ref={panelRef}\n        role=\"dialog\"\n        aria-modal=\"true\"\n        aria-labelledby={title ? titleId : undefined}\n        aria-describedby={description ? descId : undefined}\n        tabIndex={-1}\n        className={`glass relative flex max-h-[92dvh] w-full animate-sheet-in flex-col rounded-t-4xl shadow-glass outline-none sm:rounded-4xl ${widths[size]}`}\n      >\n        {title ? (\n          <header className=\"flex items-start gap-3 px-5 pb-3 pt-5 sm:px-6\">\n            <div className=\"min-w-0 flex-1\">\n              <h2 id={titleId}>{title}</h2>\n              {description ? <p id={descId} className=\"mt-0.5 text-desc text-slate-500\">{description}</p> : null}\n            </div>\n            {dismissible ? (\n              <button\n                type=\"button\"\n                data-close\n                onClick={onClose}\n                className=\"-mr-1 grid h-8 w-8 place-items-center rounded-full bg-slate-900/5 text-slate-600 hover:bg-slate-900/10\"\n                aria-label=\"Close\"\n              >\n                <LuX />\n              </button>\n            ) : null}\n          </header>\n        ) : null}\n        <div className=\"scroll-thin min-h-0 flex-1 overflow-y-auto px-5 pb-5 sm:px-6\">{children}</div>\n        {footer ? <footer className=\"border-t border-slate-900/5 px-5 py-4 pb-[max(1rem,env(safe-area-inset-bottom))] sm:px-6\">{footer}</footer> : null}\n      </div>\n    </div>,\n    document.body,\n  );\n}\n",
"client/src/components/ui/Pagination.jsx": "import { LuChevronLeft, LuChevronRight } from 'react-icons/lu';\nimport { Button } from './Button';\n\nexport function Pagination({ page, pageSize, total, onPage }) {\n  const pages = Math.max(1, Math.ceil(total / pageSize));\n  const start = total ? (page - 1) * pageSize + 1 : 0;\n  const end = Math.min(total, page * pageSize);\n  return (\n    <div className=\"flex items-center justify-between gap-3 px-1 pt-3\">\n      <p className=\"text-desc text-slate-500 tabular\">\n        {start}–{end} of {total.toLocaleString('en-IN')}\n      </p>\n      <div className=\"flex items-center gap-1\">\n        <Button variant=\"ghost\" size=\"iconSm\" onClick={() => onPage(page - 1)} disabled={page <= 1} aria-label=\"Previous page\">\n          <LuChevronLeft />\n        </Button>\n        <span className=\"min-w-[4rem] text-center text-desc text-slate-600 tabular\">\n          {page} / {pages}\n        </span>\n        <Button variant=\"ghost\" size=\"iconSm\" onClick={() => onPage(page + 1)} disabled={page >= pages} aria-label=\"Next page\">\n          <LuChevronRight />\n        </Button>\n      </div>\n    </div>\n  );\n}\n",
"client/src/components/ui/Segmented.jsx": "export function Segmented({ options, value, onChange, size = 'md', className = '', ariaLabel }) {\n  return (\n    <div role=\"radiogroup\" aria-label={ariaLabel} className={`inline-flex rounded-full bg-slate-100 p-1 ${className}`}>\n      {options.map((opt) => {\n        const active = opt.value === value;\n        const Icon = opt.icon;\n        return (\n          <button\n            key={opt.value}\n            type=\"button\"\n            role=\"radio\"\n            aria-checked={active}\n            onClick={() => onChange(opt.value)}\n            className={`inline-flex flex-1 items-center justify-center gap-1.5 whitespace-nowrap rounded-full font-medium transition ${\n              size === 'sm' ? 'h-7 px-3 text-desc' : 'h-9 px-4 text-body'\n            } ${active ? 'bg-white text-slate-900 shadow-card' : 'text-slate-500 hover:text-slate-800'}`}\n          >\n            {Icon ? <Icon aria-hidden /> : null}\n            {opt.label}\n          </button>\n        );\n      })}\n    </div>\n  );\n}\n",
"client/src/components/ui/States.jsx": "import { LuCircleAlert, LuLoaderCircle } from 'react-icons/lu';\nimport { Button } from './Button';\n\nexport function Spinner({ label = 'Loading' }) {\n  return (\n    <div className=\"flex items-center justify-center gap-2 py-10 text-body text-slate-500\" role=\"status\">\n      <LuLoaderCircle className=\"animate-spin text-brand\" aria-hidden />\n      {label}\n    </div>\n  );\n}\n\nexport function EmptyState({ icon: Icon, title, description, action }) {\n  return (\n    <div className=\"flex flex-col items-center justify-center px-6 py-12 text-center\">\n      {Icon ? (\n        <div className=\"mb-3 grid h-12 w-12 place-items-center rounded-full bg-brand-50 text-brand\">\n          <Icon size={22} aria-hidden />\n        </div>\n      ) : null}\n      <h3 className=\"text-slate-800\">{title}</h3>\n      {description ? <p className=\"mt-1 max-w-xs text-desc text-slate-500\">{description}</p> : null}\n      {action ? <div className=\"mt-4\">{action}</div> : null}\n    </div>\n  );\n}\n\nexport function ErrorState({ message, onRetry }) {\n  return (\n    <div className=\"flex flex-col items-center gap-3 px-6 py-10 text-center\">\n      <LuCircleAlert className=\"text-rose-500\" size={22} aria-hidden />\n      <p className=\"max-w-sm text-body text-slate-700\">{message}</p>\n      {onRetry ? (\n        <Button variant=\"secondary\" size=\"sm\" onClick={onRetry}>\n          Try again\n        </Button>\n      ) : null}\n    </div>\n  );\n}\n\nexport function Skeleton({ className = '' }) {\n  return <div className={`animate-pulse rounded-xl bg-slate-100 ${className}`} />;\n}\n",
"client/src/components/ui/Toaster.jsx": "import { LuCircleAlert, LuCircleCheck, LuInfo, LuTriangleAlert } from 'react-icons/lu';\nimport { useToastStore } from '../../store/toastStore';\n\nconst TONES = {\n  neutral: { icon: LuInfo, className: 'text-slate-500' },\n  success: { icon: LuCircleCheck, className: 'text-brand' },\n  warn: { icon: LuTriangleAlert, className: 'text-amber-500' },\n  error: { icon: LuCircleAlert, className: 'text-rose-600' },\n};\n\nexport function Toaster() {\n  const { toasts, dismiss } = useToastStore();\n  return (\n    <div className=\"pointer-events-none fixed inset-x-0 bottom-24 z-[60] flex flex-col items-center gap-2 px-4 md:bottom-6\" aria-live=\"polite\">\n      {toasts.map((t) => {\n        const { icon: Icon, className } = TONES[t.tone] || TONES.neutral;\n        return (\n          <button\n            type=\"button\"\n            key={t.id}\n            onClick={() => dismiss(t.id)}\n            className=\"glass pointer-events-auto flex max-w-md animate-sheet-in items-center gap-2.5 rounded-full py-2.5 pl-3.5 pr-4 text-left text-body text-slate-800 shadow-lift\"\n          >\n            <Icon className={`shrink-0 ${className}`} aria-hidden />\n            <span>{t.message}</span>\n          </button>\n        );\n      })}\n    </div>\n  );\n}\n",
"client/src/components/layout/AppShell.jsx": "import { Suspense, useState } from 'react';\nimport { NavLink, Outlet, useLocation, useNavigate } from 'react-router-dom';\nimport { LuChartColumn, LuCreditCard, LuEllipsis, LuLeaf, LuLogOut, LuPackage, LuScanBarcode, LuSettings } from 'react-icons/lu';\nimport { useAuthStore } from '../../store/authStore';\nimport { ErrorBoundary } from '../ui/ErrorBoundary';\nimport { Modal } from '../ui/Modal';\nimport { Spinner } from '../ui/States';\nimport { SubscriptionBanner } from './SubscriptionBanner';\nimport { SyncCenter, useSyncSummary } from './SyncCenter';\n\nconst NAV = [\n  { to: '/app', label: 'Register', icon: LuScanBarcode, end: true, roles: ['CASHIER', 'ADMIN'] },\n  { to: '/app/reports', label: 'Reports', icon: LuChartColumn, roles: ['ADMIN'] },\n  { to: '/app/inventory', label: 'Inventory', icon: LuPackage, roles: ['ADMIN'] },\n  { to: '/app/billing', label: 'Billing', icon: LuCreditCard, roles: ['ADMIN'] },\n  { to: '/app/settings', label: 'Settings', icon: LuSettings, roles: ['ADMIN'] },\n];\n\nfunction initials(name = '') {\n  return name.split(/\\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]?.toUpperCase()).join('');\n}\n\nexport function SyncPill({ onClick, tone = 'light' }) {\n  const { label, dot, pending, failed, syncing } = useSyncSummary();\n  const count = pending + failed;\n  const onGreen = tone === 'onBrand';\n  return (\n    <button\n      type=\"button\"\n      onClick={onClick}\n      className={`inline-flex h-8 items-center gap-2 rounded-full px-3 text-desc font-medium transition ${\n        onGreen ? 'bg-white/15 text-white hover:bg-white/25' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'\n      }`}\n      aria-label={`Sync status: ${label}${count ? `, ${count} bills waiting` : ''}`}\n    >\n      <span className={`h-2 w-2 rounded-full ${failed ? 'bg-rose-400' : dot} ${syncing ? 'animate-pulse' : ''}`} aria-hidden />\n      <span className=\"hidden sm:inline\">{label}</span>\n      {count ? <span className={`rounded-full px-1.5 tabular ${onGreen ? 'bg-white text-brand-700' : 'bg-amber-500 text-white'}`}>{count}</span> : null}\n    </button>\n  );\n}\n\nexport function AppShell() {\n  const user = useAuthStore((s) => s.user);\n  const organization = useAuthStore((s) => s.organization);\n  const logout = useAuthStore((s) => s.logout);\n  const navigate = useNavigate();\n  const location = useLocation();\n  const [syncOpen, setSyncOpen] = useState(false);\n  const [moreOpen, setMoreOpen] = useState(false);\n  const items = NAV.filter((n) => n.roles.includes(user?.role));\n  // A phone tab bar holds four comfortably; anything else moves into a More sheet.\n  const tabItems = items.slice(0, 4);\n  const overflowItems = items.slice(4);\n\n  const signOut = () => {\n    logout();\n    navigate('/login', { replace: true });\n  };\n\n  return (\n    <div className=\"flex h-[100dvh] bg-slate-50\">\n      {/* Tablet / desktop rail */}\n      <nav className=\"hidden w-[76px] shrink-0 flex-col items-center border-r border-slate-200/80 bg-white py-4 md:flex\" aria-label=\"Main\">\n        <div className=\"mb-6 grid h-10 w-10 place-items-center rounded-2xl bg-brand text-white\" title=\"FreshFlow\">\n          <LuLeaf size={20} aria-hidden />\n        </div>\n        <ul className=\"flex flex-1 flex-col gap-1\">\n          {items.map(({ to, label, icon: Icon, end }) => (\n            <li key={to}>\n              <NavLink\n                to={to}\n                end={end}\n                className={({ isActive }) =>\n                  `flex w-[60px] flex-col items-center gap-1 rounded-2xl py-2 text-desc transition ${\n                    isActive ? 'bg-brand-50 font-semibold text-brand-700' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'\n                  }`\n                }\n              >\n                <Icon size={20} aria-hidden />\n                {label}\n              </NavLink>\n            </li>\n          ))}\n        </ul>\n        <div className=\"flex flex-col items-center gap-3\">\n          <div className=\"grid h-9 w-9 place-items-center rounded-full bg-slate-100 text-desc font-semibold text-slate-700\" title={`${user?.name} (${user?.role?.toLowerCase()})`}>\n            {initials(user?.name)}\n          </div>\n          <button type=\"button\" onClick={signOut} className=\"grid h-9 w-9 place-items-center rounded-full text-slate-500 hover:bg-slate-100 hover:text-slate-800\" aria-label=\"Sign out\" title=\"Sign out\">\n            <LuLogOut aria-hidden />\n          </button>\n        </div>\n      </nav>\n\n      <main className=\"relative flex min-w-0 flex-1 flex-col pb-[calc(64px+env(safe-area-inset-bottom))] md:pb-0\">\n        <SubscriptionBanner />\n        <div className=\"min-h-0 flex-1\">\n        <ErrorBoundary resetKey={location.pathname}>\n          <Suspense fallback={<Spinner />}>\n            <Outlet context={{ openSync: () => setSyncOpen(true), signOut }} />\n          </Suspense>\n        </ErrorBoundary>\n        </div>\n      </main>\n\n      {/* Phone tab bar */}\n      <nav className=\"glass fixed inset-x-0 bottom-0 z-30 border-t border-slate-200/70 pb-[env(safe-area-inset-bottom)] md:hidden\" aria-label=\"Main\">\n        <ul className=\"flex h-16 items-stretch\">\n          {tabItems.map(({ to, label, icon: Icon, end }) => (\n            <li key={to} className=\"flex-1\">\n              <NavLink\n                to={to}\n                end={end}\n                className={({ isActive }) =>\n                  `relative flex h-full flex-col items-center justify-center gap-1 text-desc ${isActive ? 'font-semibold text-brand-700' : 'text-slate-500'}`\n                }\n              >\n                {({ isActive }) => (\n                  <>\n                    {isActive ? <span className=\"absolute top-0 h-0.5 w-10 rounded-full bg-brand\" aria-hidden /> : null}\n                    <Icon size={20} aria-hidden />\n                    {label}\n                  </>\n                )}\n              </NavLink>\n            </li>\n          ))}\n          <li className=\"flex-1\">\n            <button\n              type=\"button\"\n              onClick={() => setMoreOpen(true)}\n              className=\"flex h-full w-full flex-col items-center justify-center gap-1 text-desc text-slate-500\"\n            >\n              <LuEllipsis size={20} aria-hidden />\n              More\n            </button>\n          </li>\n        </ul>\n      </nav>\n\n      <Modal open={moreOpen} onClose={() => setMoreOpen(false)} title={user?.name} description={organization?.name}>\n        <ul className=\"divide-y divide-slate-100\">\n          {overflowItems.map(({ to, label, icon: Icon }) => (\n            <li key={to}>\n              <NavLink to={to} onClick={() => setMoreOpen(false)} className=\"flex items-center gap-3 py-3 text-body text-slate-700\">\n                <Icon size={20} className=\"text-slate-400\" aria-hidden />\n                {label}\n              </NavLink>\n            </li>\n          ))}\n          <li>\n            <button\n              type=\"button\"\n              onClick={() => {\n                setMoreOpen(false);\n                setSyncOpen(true);\n              }}\n              className=\"flex w-full items-center gap-3 py-3 text-left text-body text-slate-700\"\n            >\n              <LuScanBarcode size={20} className=\"text-slate-400\" aria-hidden />\n              Bill sync\n            </button>\n          </li>\n          <li>\n            <button type=\"button\" onClick={signOut} className=\"flex w-full items-center gap-3 py-3 text-left text-body text-rose-600\">\n              <LuLogOut size={20} aria-hidden />\n              Sign out\n            </button>\n          </li>\n        </ul>\n      </Modal>\n\n      <SyncCenter open={syncOpen} onClose={() => setSyncOpen(false)} />\n    </div>\n  );\n}\n",
"client/src/components/layout/SubscriptionBanner.jsx": "import { Link } from 'react-router-dom';\nimport { LuCircleAlert, LuClock } from 'react-icons/lu';\nimport { useAuthStore } from '../../store/authStore';\n\n/**\n * A quiet line at the top of the app when the trial is running out or the plan has lapsed.\n * Cashiers see what is happening but are pointed at their admin rather than a payment screen.\n */\nexport function SubscriptionBanner() {\n  const subscription = useAuthStore((s) => s.subscription);\n  const isAdmin = useAuthStore((s) => s.user?.role === 'ADMIN');\n  if (!subscription) return null;\n\n  const lapsed = !subscription.active;\n  const endingSoon = subscription.active && subscription.daysLeft <= 7;\n  if (!lapsed && !endingSoon) return null;\n\n  const Icon = lapsed ? LuCircleAlert : LuClock;\n  const tone = lapsed ? 'bg-rose-50 text-rose-800' : 'bg-amber-50 text-amber-900';\n\n  const message = lapsed\n    ? isAdmin\n      ? 'Your subscription has ended. Bills still upload, but adding products, categories and staff is paused.'\n      : 'This store’s subscription has ended. You can keep billing; ask your admin to renew.'\n    : isAdmin\n      ? `${subscription.isTrial ? 'Free trial' : 'Your plan'} ends in ${subscription.daysLeft} day${subscription.daysLeft === 1 ? '' : 's'}.`\n      : `${subscription.isTrial ? 'Free trial' : 'The plan'} ends in ${subscription.daysLeft} day${subscription.daysLeft === 1 ? '' : 's'}.`;\n\n  return (\n    <div className={`flex items-center gap-2 px-4 py-2 text-desc sm:px-6 ${tone}`} role=\"status\">\n      <Icon className=\"shrink-0\" aria-hidden />\n      <p className=\"min-w-0 flex-1\">{message}</p>\n      {isAdmin ? (\n        <Link to=\"/app/billing\" className=\"shrink-0 font-semibold underline underline-offset-2\">\n          {lapsed ? 'Choose a plan' : 'View plans'}\n        </Link>\n      ) : null}\n    </div>\n  );\n}\n",
"client/src/components/layout/SyncCenter.jsx": "import { useState } from 'react';\nimport { LuCloudUpload, LuRefreshCw, LuTrash2, LuWifiOff } from 'react-icons/lu';\nimport { formatDateTime, formatMoney, relativeTime } from '../../lib/format';\nimport { discardBill, flushOutbox, retryBill } from '../../lib/sync';\nimport { selectConnection, useSyncStore } from '../../store/syncStore';\nimport { toast } from '../../store/toastStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { EmptyState } from '../ui/States';\n\nconst STATUS_COPY = {\n  online: { dot: 'bg-brand', label: 'Online' },\n  unreachable: { dot: 'bg-amber-500', label: 'Server unreachable' },\n  offline: { dot: 'bg-slate-400', label: 'Offline' },\n};\n\nexport function useSyncSummary() {\n  const connection = useSyncStore(selectConnection);\n  const pending = useSyncStore((s) => s.pendingCount);\n  const failed = useSyncStore((s) => s.failedCount);\n  const syncing = useSyncStore((s) => s.syncing);\n  return { connection, pending, failed, syncing, ...STATUS_COPY[connection] };\n}\n\nexport function SyncCenter({ open, onClose }) {\n  const { entries, lastSyncAt, lastError, syncing } = useSyncStore();\n  const { connection, label, dot } = useSyncSummary();\n  const [confirmDiscard, setConfirmDiscard] = useState(null);\n\n  const syncNow = async () => {\n    const synced = await flushOutbox();\n    if (synced.length) toast.success(`${synced.length} bill${synced.length > 1 ? 's' : ''} uploaded`);\n  };\n\n  return (\n    <Modal\n      open={open}\n      onClose={onClose}\n      title=\"Bill sync\"\n      description={`Last upload ${relativeTime(lastSyncAt)}`}\n      footer={\n        <div className=\"flex items-center justify-between gap-3\">\n          <span className=\"inline-flex items-center gap-2 text-desc text-slate-600\">\n            <span className={`h-2 w-2 rounded-full ${dot}`} aria-hidden />\n            {label}\n          </span>\n          <Button onClick={syncNow} loading={syncing} disabled={connection === 'offline'}>\n            <LuRefreshCw aria-hidden /> Sync now\n          </Button>\n        </div>\n      }\n    >\n      {connection !== 'online' ? (\n        <div className=\"mb-4 flex gap-3 rounded-2xl bg-amber-50 p-3 text-desc text-amber-800\">\n          <LuWifiOff className=\"mt-0.5 shrink-0\" aria-hidden />\n          <p>Keep selling. Bills are saved on this device and upload automatically when the connection returns.</p>\n        </div>\n      ) : null}\n      {lastError && connection === 'online' ? <p className=\"mb-3 text-desc text-rose-600\">{lastError}</p> : null}\n\n      {entries.length === 0 ? (\n        <EmptyState icon={LuCloudUpload} title=\"Everything is uploaded\" description=\"Completed bills from this register are safely stored on the server.\" />\n      ) : (\n        <ul className=\"divide-y divide-slate-100\">\n          {entries.map((e) => (\n            <li key={e.clientId} className=\"flex items-start gap-3 py-3\">\n              <div className=\"min-w-0 flex-1\">\n                <div className=\"flex items-center gap-2\">\n                  <span className=\"font-semibold tabular\">{formatMoney(e.payload.grandTotal)}</span>\n                  <span className={`rounded-full px-2 py-0.5 text-desc font-medium ${e.status === 'failed' ? 'bg-rose-50 text-rose-700' : 'bg-amber-50 text-amber-700'}`}>\n                    {e.status === 'failed' ? 'Needs attention' : 'Waiting'}\n                  </span>\n                </div>\n                <p className=\"mt-0.5 text-desc text-slate-500\">\n                  {formatDateTime(e.payload.soldAt)}, {e.payload.items.length} items, {e.payload.paymentMethod}\n                </p>\n                {e.lastError ? <p className=\"mt-1 text-desc text-rose-600\">{e.lastError}</p> : null}\n              </div>\n              {e.status === 'failed' ? (\n                <div className=\"flex gap-1\">\n                  <Button size=\"sm\" variant=\"secondary\" onClick={() => retryBill(e.clientId)}>\n                    Retry\n                  </Button>\n                  {confirmDiscard === e.clientId ? (\n                    <Button\n                      size=\"sm\"\n                      variant=\"danger\"\n                      onClick={async () => {\n                        await discardBill(e.clientId);\n                        setConfirmDiscard(null);\n                        toast.info('Bill removed from this register');\n                      }}\n                    >\n                      Confirm\n                    </Button>\n                  ) : (\n                    <Button size=\"iconSm\" variant=\"ghost\" aria-label=\"Discard bill\" onClick={() => setConfirmDiscard(e.clientId)}>\n                      <LuTrash2 />\n                    </Button>\n                  )}\n                </div>\n              ) : null}\n            </li>\n          ))}\n        </ul>\n      )}\n    </Modal>\n  );\n}\n",
"client/src/components/reports/KpiCard.jsx": "import { LuArrowDown, LuArrowUp } from 'react-icons/lu';\nimport { formatPercentChange } from '../../lib/format';\n\nexport function KpiCard({ label, value, previous, current, hint, invertColors = false }) {\n  const change = previous === undefined ? null : formatPercentChange(current, previous);\n  const good = change && (invertColors ? change.direction === 'down' : change.direction === 'up');\n  const bad = change && (invertColors ? change.direction === 'up' : change.direction === 'down');\n  return (\n    <div className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03]\">\n      <p className=\"text-desc text-slate-500\">{label}</p>\n      <p className=\"mt-1 truncate text-h1 font-bold text-slate-900 tabular\">{value}</p>\n      <div className=\"mt-1.5 flex items-center gap-1.5\">\n        {change ? (\n          <span className={`inline-flex items-center gap-0.5 rounded-full px-1.5 py-0.5 text-desc font-semibold ${good ? 'bg-brand-50 text-brand-700' : bad ? 'bg-rose-50 text-rose-700' : 'bg-slate-100 text-slate-600'}`}>\n            {change.direction === 'up' ? <LuArrowUp size={11} aria-hidden /> : change.direction === 'down' ? <LuArrowDown size={11} aria-hidden /> : null}\n            {change.label}\n          </span>\n        ) : null}\n        {hint ? <span className=\"truncate text-desc text-slate-500\">{hint}</span> : null}\n      </div>\n    </div>\n  );\n}\n",
"client/src/components/reports/ProductPerformance.jsx": "import { useState } from 'react';\nimport { LuSearch } from 'react-icons/lu';\nimport { useApiQuery } from '../../hooks/useApiQuery';\nimport { useDebounce } from '../../hooks/useDebounce';\nimport { formatMoney, formatNumber, formatPercentChange } from '../../lib/format';\nimport { Pagination } from '../ui/Pagination';\nimport { Segmented } from '../ui/Segmented';\nimport { EmptyState, ErrorState, Spinner } from '../ui/States';\n\nconst SORTS = [\n  { value: 'revenue', label: 'Revenue' },\n  { value: 'units', label: 'Volume' },\n  { value: 'growth', label: 'Growth' },\n  { value: 'stock', label: 'Low stock' },\n];\n\nfunction StockPill({ row }) {\n  if (row.stock <= 0) return <span className=\"rounded-full bg-rose-50 px-2 py-0.5 text-desc font-medium text-rose-700\">Out of stock</span>;\n  if (row.stock <= row.lowStockThreshold) return <span className=\"rounded-full bg-amber-50 px-2 py-0.5 text-desc font-medium text-amber-700\">Low</span>;\n  return <span className=\"text-desc text-slate-500\">In stock</span>;\n}\n\nexport function ProductPerformance({ range, currency }) {\n  const [sort, setSort] = useState('revenue');\n  const [search, setSearch] = useState('');\n  const [page, setPage] = useState(1);\n  const q = useDebounce(search, 250);\n  const { data, loading, error, refetch } = useApiQuery('/reports/products', { from: range.from, to: range.to, sort, q, page, pageSize: 20 });\n  const rows = data?.rows ?? [];\n\n  return (\n    <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <div className=\"flex-1\">\n          <h2>Items sold and stock left</h2>\n          <p className=\"text-desc text-slate-500\">Sales in the period beside what is still on the shelf</p>\n        </div>\n        <Segmented size=\"sm\" ariaLabel=\"Sort products\" value={sort} onChange={(v) => { setSort(v); setPage(1); }} options={SORTS} />\n        <div className=\"relative min-w-[180px] flex-1 sm:max-w-[220px]\">\n          <LuSearch className=\"pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400\" aria-hidden />\n          <input className=\"field h-9 pl-9\" placeholder=\"Search products\" value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} aria-label=\"Search products\" />\n        </div>\n      </div>\n\n      {loading && !data ? <Spinner /> : null}\n      {error ? <ErrorState message={error} onRetry={refetch} /> : null}\n      {data && !rows.length ? <EmptyState title=\"No products match\" description=\"Try a different search or period.\" /> : null}\n\n      {rows.length ? (\n        <ul className=\"mt-3 space-y-2 md:hidden\">\n          {rows.map((r) => {\n            const change = formatPercentChange(r.revenue, r.prevRevenue);\n            return (\n              <li key={r.id} className=\"rounded-2xl bg-white p-3 ring-1 ring-slate-900/[0.04]\">\n                <div className=\"flex items-start gap-2\">\n                  <div className=\"min-w-0 flex-1\">\n                    <p className=\"truncate font-medium text-slate-800\">{r.name}</p>\n                    <p className=\"truncate text-desc text-slate-400\">{r.categoryName}</p>\n                  </div>\n                  <div className=\"shrink-0 text-right\">\n                    <p className=\"font-semibold tabular\">{formatMoney(r.revenue, currency)}</p>\n                    <p className={`text-desc tabular ${change.direction === 'up' ? 'text-brand-700' : change.direction === 'down' ? 'text-rose-600' : 'text-slate-400'}`}>\n                      {r.revenue || r.prevRevenue ? change.label : '—'}\n                    </p>\n                  </div>\n                </div>\n                <div className=\"mt-2 flex items-center gap-2 text-desc text-slate-500 tabular\">\n                  <span>Sold {formatNumber(r.quantity)} {r.unit}</span>\n                  <span>Left {formatNumber(r.stock)}</span>\n                  <div className=\"flex-1\" />\n                  <StockPill row={r} />\n                </div>\n              </li>\n            );\n          })}\n        </ul>\n      ) : null}\n\n      {rows.length ? (\n        <div className=\"mt-3 hidden overflow-x-auto md:block\">\n          <table className=\"w-full min-w-[640px] border-collapse\">\n            <thead>\n              <tr className=\"border-b border-slate-100 text-left text-desc text-slate-500\">\n                <th className=\"py-2 pr-3 font-medium\">Product</th>\n                <th className=\"py-2 pr-3 font-medium\">Category</th>\n                <th className=\"py-2 pr-3 text-right font-medium\">Sold</th>\n                <th className=\"py-2 pr-3 text-right font-medium\">Revenue</th>\n                <th className=\"py-2 pr-3 text-right font-medium\">vs before</th>\n                <th className=\"py-2 pr-3 text-right font-medium\">Stock left</th>\n                <th className=\"py-2 font-medium\">Status</th>\n              </tr>\n            </thead>\n            <tbody>\n              {rows.map((r) => {\n                const change = formatPercentChange(r.revenue, r.prevRevenue);\n                return (\n                  <tr key={r.id} className=\"border-b border-slate-50 text-body\">\n                    <td className=\"max-w-[220px] py-2.5 pr-3\">\n                      <p className=\"truncate font-medium text-slate-800\">{r.name}</p>\n                      <p className=\"text-desc text-slate-400 tabular\">\n                        #{r.code} · {formatMoney(r.price, currency)}/{r.unit}\n                      </p>\n                    </td>\n                    <td className=\"max-w-[140px] truncate py-2.5 pr-3 text-desc text-slate-500\">{r.categoryName}</td>\n                    <td className=\"py-2.5 pr-3 text-right tabular\">\n                      {formatNumber(r.quantity)} <span className=\"text-desc text-slate-400\">{r.unit}</span>\n                    </td>\n                    <td className=\"py-2.5 pr-3 text-right font-semibold tabular\">{formatMoney(r.revenue, currency)}</td>\n                    <td className={`py-2.5 pr-3 text-right text-desc tabular ${change.direction === 'up' ? 'text-brand-700' : change.direction === 'down' ? 'text-rose-600' : 'text-slate-400'}`}>\n                      {r.revenue || r.prevRevenue ? change.label : '—'}\n                    </td>\n                    <td className=\"py-2.5 pr-3 text-right tabular\">{formatNumber(r.stock)}</td>\n                    <td className=\"py-2.5\">\n                      <StockPill row={r} />\n                    </td>\n                  </tr>\n                );\n              })}\n            </tbody>\n          </table>\n        </div>\n      ) : null}\n\n      {data && data.total > data.pageSize ? <Pagination page={data.page} pageSize={data.pageSize} total={data.total} onPage={setPage} /> : null}\n    </section>\n  );\n}\n",
"client/src/components/reports/RangePicker.jsx": "import { presetRange } from '../../lib/dates';\nimport { Segmented } from '../ui/Segmented';\n\nconst PRESETS = [\n  { value: 'today', label: 'Today' },\n  { value: 'yesterday', label: 'Yesterday' },\n  { value: '7d', label: '7 days' },\n  { value: '30d', label: '30 days' },\n  { value: '90d', label: '90 days' },\n];\n\nexport function RangePicker({ range, onChange }) {\n  const activePreset = PRESETS.find((p) => {\n    const r = presetRange(p.value);\n    return r.from === range.from && r.to === range.to;\n  })?.value;\n\n  return (\n    <div className=\"flex flex-wrap items-center gap-2\">\n      <Segmented\n        size=\"sm\"\n        ariaLabel=\"Date range preset\"\n        value={activePreset ?? ''}\n        onChange={(v) => onChange(presetRange(v))}\n        options={PRESETS}\n      />\n      <div className=\"flex items-center gap-1.5 rounded-full bg-white px-2 py-1 ring-1 ring-slate-200\">\n        <input\n          type=\"date\"\n          className=\"h-7 rounded-full border-0 bg-transparent px-1.5 text-desc text-slate-700 focus:outline-none\"\n          value={range.from}\n          max={range.to}\n          onChange={(e) => e.target.value && onChange({ ...range, from: e.target.value })}\n          aria-label=\"From date\"\n        />\n        <span className=\"text-desc text-slate-400\">to</span>\n        <input\n          type=\"date\"\n          className=\"h-7 rounded-full border-0 bg-transparent px-1.5 text-desc text-slate-700 focus:outline-none\"\n          value={range.to}\n          min={range.from}\n          onChange={(e) => e.target.value && onChange({ ...range, to: e.target.value })}\n          aria-label=\"To date\"\n        />\n      </div>\n    </div>\n  );\n}\n",
"client/src/components/reports/TransactionLedger.jsx": "import { useState } from 'react';\nimport { LuBan, LuReceipt, LuSearch } from 'react-icons/lu';\nimport { api, errorMessage } from '../../lib/api';\nimport { formatDateTime, formatMoney, invoiceLabel } from '../../lib/format';\nimport { useApiQuery } from '../../hooks/useApiQuery';\nimport { useDebounce } from '../../hooks/useDebounce';\nimport { toast } from '../../store/toastStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { Pagination } from '../ui/Pagination';\nimport { Segmented } from '../ui/Segmented';\nimport { EmptyState, ErrorState, Spinner } from '../ui/States';\n\nfunction VoidDialog({ transaction, onClose, onVoided, currency }) {\n  const [reason, setReason] = useState('');\n  const [saving, setSaving] = useState(false);\n\n  const submit = async () => {\n    setSaving(true);\n    try {\n      await api.post(`/transactions/${transaction.id}/void`, { reason });\n      toast.success(`${invoiceLabel(transaction.invoiceNo)} voided and stock returned`);\n      onVoided();\n      onClose();\n    } catch (err) {\n      toast.error(errorMessage(err));\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  return (\n    <Modal\n      open\n      onClose={onClose}\n      size=\"sm\"\n      title={`Void ${invoiceLabel(transaction.invoiceNo)}`}\n      description={`${formatMoney(transaction.grandTotal, currency)} will be removed from sales and the items returned to stock.`}\n      footer={\n        <div className=\"flex gap-2\">\n          <Button variant=\"secondary\" className=\"flex-1\" onClick={onClose}>\n            Keep bill\n          </Button>\n          <Button variant=\"danger\" className=\"flex-1\" disabled={reason.trim().length < 3} loading={saving} onClick={submit}>\n            Void bill\n          </Button>\n        </div>\n      }\n    >\n      <label htmlFor=\"void-reason\" className=\"label\">\n        Why is this bill being voided?\n      </label>\n      <input id=\"void-reason\" className=\"field\" value={reason} onChange={(e) => setReason(e.target.value)} placeholder=\"Customer returned everything\" maxLength={200} autoFocus />\n    </Modal>\n  );\n}\n\nfunction DetailDialog({ id, onClose, currency }) {\n  const { data, loading, error } = useApiQuery(`/transactions/${id}`, null);\n  const t = data?.transaction;\n  return (\n    <Modal open onClose={onClose} title={t ? invoiceLabel(t.invoiceNo) : 'Bill'} description={t ? formatDateTime(t.soldAt) : undefined}>\n      {loading ? <Spinner /> : null}\n      {error ? <ErrorState message={error} /> : null}\n      {t ? (\n        <>\n          <ul className=\"divide-y divide-slate-100\">\n            {t.items.map((i) => (\n              <li key={i.id} className=\"flex items-start gap-3 py-2.5\">\n                <div className=\"min-w-0 flex-1\">\n                  <p className=\"truncate font-medium\">{i.productName}</p>\n                  <p className=\"text-desc text-slate-500 tabular\">\n                    {i.soldByWeight ? i.quantity.toFixed(3) : i.quantity} {i.unit} × {formatMoney(i.unitPrice, currency)}\n                    {i.discountPercent > 0 ? `, −${i.discountPercent}%` : ''}\n                  </p>\n                </div>\n                <span className=\"font-medium tabular\">{formatMoney(i.lineSubtotal - i.lineDiscount, currency)}</span>\n              </li>\n            ))}\n          </ul>\n          <dl className=\"mt-3 space-y-1 border-t border-slate-100 pt-3 text-body tabular\">\n            <div className=\"flex justify-between text-slate-600\">\n              <dt>Subtotal</dt>\n              <dd>{formatMoney(t.subtotal, currency)}</dd>\n            </div>\n            {t.itemDiscount + t.billDiscount > 0 ? (\n              <div className=\"flex justify-between text-brand-700\">\n                <dt>Discounts{t.discountReason ? ` (${t.discountReason})` : ''}</dt>\n                <dd>−{formatMoney(t.itemDiscount + t.billDiscount, currency)}</dd>\n              </div>\n            ) : null}\n            <div className=\"flex justify-between text-slate-600\">\n              <dt>GST {t.taxRate}%</dt>\n              <dd>{formatMoney(t.taxTotal, currency)}</dd>\n            </div>\n            <div className=\"flex justify-between font-semibold\">\n              <dt>Total, paid by {t.paymentMethod.toLowerCase()}</dt>\n              <dd>{formatMoney(t.grandTotal, currency)}</dd>\n            </div>\n          </dl>\n          <p className=\"mt-3 text-desc text-slate-500\">\n            {t.cashier?.name} · {t.terminalId}\n            {t.wasOffline ? ' · made offline' : ''}\n            {t.customerPhone ? ` · ${t.customerPhone}` : ''}\n          </p>\n          {t.status === 'VOIDED' ? <p className=\"mt-2 rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\">Voided: {t.voidReason}</p> : null}\n        </>\n      ) : null}\n    </Modal>\n  );\n}\n\nexport function TransactionLedger({ range, currency }) {\n  const [page, setPage] = useState(1);\n  const [method, setMethod] = useState('ALL');\n  const [search, setSearch] = useState('');\n  const q = useDebounce(search, 250);\n  const { data, loading, error, refetch } = useApiQuery('/transactions', { from: range.from, to: range.to, method, q, page, pageSize: 20 });\n\n  const [detailId, setDetailId] = useState(null);\n  const [voiding, setVoiding] = useState(null);\n\n  const rows = data?.transactions ?? [];\n\n  return (\n    <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <h2 className=\"flex-1\">Bills</h2>\n        <Segmented\n          size=\"sm\"\n          ariaLabel=\"Payment method\"\n          value={method}\n          onChange={(v) => { setMethod(v); setPage(1); }}\n          options={[\n            { value: 'ALL', label: 'All' },\n            { value: 'UPI', label: 'UPI' },\n            { value: 'CASH', label: 'Cash' },\n            { value: 'CARD', label: 'Card' },\n          ]}\n        />\n        <div className=\"relative min-w-[180px] flex-1 sm:max-w-[220px]\">\n          <LuSearch className=\"pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400\" aria-hidden />\n          <input\n            className=\"field h-9 pl-9\"\n            placeholder=\"Invoice or phone\"\n            value={search}\n            onChange={(e) => { setSearch(e.target.value); setPage(1); }}\n            aria-label=\"Search bills by invoice number or phone\"\n          />\n        </div>\n      </div>\n\n      {loading && !data ? <Spinner /> : null}\n      {error ? <ErrorState message={error} onRetry={refetch} /> : null}\n      {data && !rows.length ? <EmptyState icon={LuReceipt} title=\"No bills in this period\" description=\"Sales made on the register appear here as soon as they sync.\" /> : null}\n\n      {rows.length ? (\n        <ul className=\"mt-3 space-y-2 md:hidden\">\n          {rows.map((t) => (\n            <li key={t.id} className={`rounded-2xl p-3 ring-1 ring-slate-900/[0.04] ${t.status === 'VOIDED' ? 'bg-slate-50' : 'bg-white'}`}>\n              <div className=\"flex items-start gap-2\">\n                <button type=\"button\" onClick={() => setDetailId(t.id)} className=\"min-w-0 flex-1 text-left\">\n                  <p className=\"font-semibold text-brand-700 tabular\">\n                    {invoiceLabel(t.invoiceNo)}\n                    {t.status === 'VOIDED' ? <span className=\"ml-1.5 rounded-full bg-rose-50 px-1.5 py-0.5 text-desc text-rose-700\">Voided</span> : null}\n                    {t.wasOffline ? <span className=\"ml-1.5 rounded-full bg-slate-100 px-1.5 py-0.5 text-desc text-slate-500\">Offline</span> : null}\n                  </p>\n                  <p className=\"truncate text-desc text-slate-500\">\n                    {formatDateTime(t.soldAt)} · {t.cashier?.name}\n                  </p>\n                </button>\n                <span className=\"shrink-0 font-semibold tabular\">{formatMoney(t.grandTotal, currency)}</span>\n              </div>\n              <div className=\"mt-2 flex items-center gap-2 text-desc text-slate-500\">\n                <span>{t.itemCount} items</span>\n                <span>{t.paymentMethod}</span>\n                {t.itemDiscount + t.billDiscount > 0 ? <span className=\"text-brand-700\">−{formatMoney(t.itemDiscount + t.billDiscount, currency)}</span> : null}\n                <div className=\"flex-1\" />\n                {t.status === 'COMPLETED' ? (\n                  <button type=\"button\" onClick={() => setVoiding(t)} className=\"rounded-full px-2 py-1 font-medium text-rose-600 hover:bg-rose-50\">\n                    Void\n                  </button>\n                ) : null}\n              </div>\n            </li>\n          ))}\n        </ul>\n      ) : null}\n\n      {rows.length ? (\n        <div className=\"mt-3 hidden overflow-x-auto md:block\">\n          <table className=\"w-full min-w-[620px] border-collapse\">\n            <thead>\n              <tr className=\"border-b border-slate-100 text-left text-desc text-slate-500\">\n                <th className=\"py-2 pr-3 font-medium\">Invoice</th>\n                <th className=\"py-2 pr-3 font-medium\">Time</th>\n                <th className=\"py-2 pr-3 font-medium\">Cashier</th>\n                <th className=\"py-2 pr-3 font-medium\">Payment</th>\n                <th className=\"py-2 pr-3 text-right font-medium\">Items</th>\n                <th className=\"py-2 pr-3 text-right font-medium\">Discount</th>\n                <th className=\"py-2 pr-3 text-right font-medium\">Total</th>\n                <th className=\"py-2 w-8\" aria-label=\"Actions\" />\n              </tr>\n            </thead>\n            <tbody>\n              {rows.map((t) => (\n                <tr key={t.id} className={`border-b border-slate-50 text-body ${t.status === 'VOIDED' ? 'text-slate-400' : 'text-slate-700'}`}>\n                  <td className=\"py-2.5 pr-3\">\n                    <button type=\"button\" onClick={() => setDetailId(t.id)} className=\"font-medium text-brand-700 hover:underline tabular\">\n                      {invoiceLabel(t.invoiceNo)}\n                    </button>\n                    {t.status === 'VOIDED' ? <span className=\"ml-1.5 rounded-full bg-rose-50 px-1.5 py-0.5 text-desc text-rose-700\">Voided</span> : null}\n                    {t.wasOffline ? <span className=\"ml-1.5 rounded-full bg-slate-100 px-1.5 py-0.5 text-desc text-slate-500\">Offline</span> : null}\n                  </td>\n                  <td className=\"py-2.5 pr-3 text-desc tabular\">{formatDateTime(t.soldAt)}</td>\n                  <td className=\"max-w-[140px] truncate py-2.5 pr-3 text-desc\">{t.cashier?.name}</td>\n                  <td className=\"py-2.5 pr-3 text-desc\">{t.paymentMethod}</td>\n                  <td className=\"py-2.5 pr-3 text-right tabular\">{t.itemCount}</td>\n                  <td className=\"py-2.5 pr-3 text-right tabular\">{t.itemDiscount + t.billDiscount > 0 ? `−${formatMoney(t.itemDiscount + t.billDiscount, currency)}` : '—'}</td>\n                  <td className=\"py-2.5 pr-3 text-right font-semibold tabular\">{formatMoney(t.grandTotal, currency)}</td>\n                  <td className=\"py-2.5\">\n                    {t.status === 'COMPLETED' ? (\n                      <button type=\"button\" onClick={() => setVoiding(t)} className=\"grid h-7 w-7 place-items-center rounded-full text-slate-400 hover:bg-rose-50 hover:text-rose-600\" aria-label={`Void ${invoiceLabel(t.invoiceNo)}`}>\n                        <LuBan aria-hidden />\n                      </button>\n                    ) : null}\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </div>\n      ) : null}\n\n      {data && data.total > data.pageSize ? <Pagination page={data.page} pageSize={data.pageSize} total={data.total} onPage={setPage} /> : null}\n\n      {detailId ? <DetailDialog id={detailId} currency={currency} onClose={() => setDetailId(null)} /> : null}\n      {voiding ? <VoidDialog transaction={voiding} currency={currency} onClose={() => setVoiding(null)} onVoided={refetch} /> : null}\n    </section>\n  );\n}\n",
"client/src/components/pricing/PricingPlans.jsx": "import { useState } from 'react';\nimport { LuCheck, LuMinus, LuPlus } from 'react-icons/lu';\nimport { formatMoney } from '../../lib/format';\nimport { Button } from '../ui/Button';\nimport { Segmented } from '../ui/Segmented';\n\nconst monthsFor = (interval) => (interval === 'YEARLY' ? 12 : 1);\n\nexport function SeatStepper({ seats, onChange, min = 1, max = 500, label = 'Staff accounts' }) {\n  return (\n    <div className=\"flex items-center gap-3\">\n      <span className=\"text-body text-slate-600\">{label}</span>\n      <div className=\"flex items-center gap-2\">\n        <button\n          type=\"button\"\n          onClick={() => onChange(Math.max(min, seats - 1))}\n          disabled={seats <= min}\n          className=\"grid h-9 w-9 place-items-center rounded-full bg-slate-100 text-slate-600 transition hover:bg-slate-200 disabled:opacity-40\"\n          aria-label=\"One less staff account\"\n        >\n          <LuMinus aria-hidden />\n        </button>\n        <input\n          type=\"text\"\n          inputMode=\"numeric\"\n          value={seats}\n          onChange={(e) => {\n            const n = Number(e.target.value.replace(/\\D/g, ''));\n            onChange(Math.max(min, Math.min(max, n || min)));\n          }}\n          className=\"h-9 w-14 rounded-xl border border-slate-200 text-center font-semibold tabular\"\n          aria-label=\"Number of staff accounts\"\n        />\n        <button\n          type=\"button\"\n          onClick={() => onChange(Math.min(max, seats + 1))}\n          disabled={seats >= max}\n          className=\"grid h-9 w-9 place-items-center rounded-full bg-brand text-white transition hover:bg-brand-700 disabled:opacity-40\"\n          aria-label=\"One more staff account\"\n        >\n          <LuPlus aria-hidden />\n        </button>\n      </div>\n    </div>\n  );\n}\n\nexport function PlanCard({ plan, interval, seats, currency = 'INR', highlight, cta, onSelect, busy, currentLabel }) {\n  const rate = plan.intervals[interval];\n  const months = monthsFor(interval);\n  const total = rate.price * seats * months;\n  const saving = (rate.listPrice - rate.price) * seats * months;\n\n  return (\n    <div\n      className={`flex flex-col rounded-4xl bg-white p-6 ring-1 transition ${\n        highlight ? 'shadow-lift ring-brand' : 'shadow-card ring-slate-900/[0.05]'\n      }`}\n    >\n      <div className=\"flex items-center gap-2\">\n        <h2>{plan.name}</h2>\n        {highlight ? <span className=\"rounded-full bg-brand-50 px-2 py-0.5 text-desc font-semibold text-brand-700\">Most popular</span> : null}\n        {currentLabel ? <span className=\"rounded-full bg-slate-100 px-2 py-0.5 text-desc font-semibold text-slate-600\">{currentLabel}</span> : null}\n      </div>\n      <p className=\"mt-1 text-desc text-slate-500\">{plan.blurb}</p>\n\n      <div className=\"mt-4 flex items-end gap-2\">\n        <span className=\"text-h1 font-bold text-slate-900 tabular\">{formatMoney(rate.price, currency)}</span>\n        <span className=\"pb-0.5 text-desc text-slate-500\">per user / month</span>\n      </div>\n      <p className=\"mt-0.5 text-desc text-slate-400\">\n        <span className=\"line-through tabular\">{formatMoney(rate.listPrice, currency)}</span> before the launch discount\n      </p>\n\n      <div className=\"mt-4 rounded-2xl bg-slate-50 p-3\">\n        <div className=\"flex items-baseline justify-between\">\n          <span className=\"text-desc text-slate-600\">\n            {seats} user{seats === 1 ? '' : 's'}, {interval === 'YEARLY' ? 'billed yearly' : 'billed monthly'}\n          </span>\n          <span className=\"text-h2 font-bold tabular\">{formatMoney(total, currency)}</span>\n        </div>\n        {saving > 0 ? <p className=\"mt-1 text-desc text-brand-700 tabular\">You save {formatMoney(saving, currency)}</p> : null}\n      </div>\n\n      <ul className=\"mt-4 flex-1 space-y-2\">\n        {plan.features.map((f) => (\n          <li key={f} className=\"flex gap-2 text-body text-slate-700\">\n            <LuCheck className=\"mt-0.5 shrink-0 text-brand\" aria-hidden />\n            {f}\n          </li>\n        ))}\n      </ul>\n\n      <Button\n        className=\"mt-5 w-full\"\n        size=\"lg\"\n        variant={highlight ? 'primary' : 'secondary'}\n        onClick={() => onSelect?.(plan.tier)}\n        loading={busy}\n      >\n        {cta}\n      </Button>\n    </div>\n  );\n}\n\nexport function IntervalToggle({ interval, onChange }) {\n  return (\n    <Segmented\n      ariaLabel=\"Billing interval\"\n      value={interval}\n      onChange={onChange}\n      options={[\n        { value: 'MONTHLY', label: 'Monthly' },\n        { value: 'YEARLY', label: 'Yearly, save more' },\n      ]}\n    />\n  );\n}\n\nexport function usePlanSelection(defaultSeats = 3) {\n  const [interval, setInterval] = useState('MONTHLY');\n  const [seats, setSeats] = useState(defaultSeats);\n  return { interval, setInterval, seats, setSeats };\n}\n",
"client/src/components/pos/CartLine.jsx": "import { memo } from 'react';\nimport { LuMinus, LuPlus, LuX } from 'react-icons/lu';\nimport { formatMoney } from '../../lib/format';\nimport { fromPaise } from '../../lib/pricing';\nimport { ProductThumb } from './ProductThumb';\n\nexport const CartLine = memo(function CartLine({ line, computed, currency, highlight, onIncrement, onDecrement, onRemove }) {\n  const amount = fromPaise(computed.lineSubtotal - computed.lineDiscount);\n  return (\n    <li className={`flex items-center gap-3 rounded-2xl p-2 transition-colors ${highlight ? 'bg-brand-50/70' : ''}`}>\n      <div className=\"h-14 w-14 shrink-0 overflow-hidden rounded-xl bg-brand-50\">\n        <ProductThumb src={line.imageUrl} name={line.name} />\n      </div>\n      <div className=\"min-w-0 flex-1\">\n        <p className=\"truncate font-semibold text-slate-900\">{line.name}</p>\n        <p className=\"truncate text-desc text-slate-500 tabular\">\n          {formatMoney(line.unitPrice, currency)}/{line.unit}\n          {line.discountPercent > 0 ? `, ${line.discountPercent}% off` : ''}\n        </p>\n        <p className=\"font-semibold text-brand-700 tabular\">{formatMoney(amount, currency)}</p>\n      </div>\n      {line.soldByWeight ? (\n        <div className=\"flex items-center gap-1\">\n          <span className=\"rounded-full bg-slate-100 px-2.5 py-1 text-desc font-medium text-slate-700 tabular\">\n            {line.quantity.toFixed(3)} {line.unit}\n          </span>\n          <button\n            type=\"button\"\n            onClick={() => onRemove(line.lineId)}\n            className=\"grid h-8 w-8 place-items-center rounded-full text-slate-400 hover:bg-rose-50 hover:text-rose-600\"\n            aria-label={`Remove ${line.name}`}\n          >\n            <LuX aria-hidden />\n          </button>\n        </div>\n      ) : (\n        <div className=\"flex items-center gap-2\" role=\"group\" aria-label={`Quantity of ${line.name}`}>\n          <button\n            type=\"button\"\n            onClick={() => onDecrement(line)}\n            className=\"grid h-8 w-8 place-items-center rounded-full bg-slate-100 text-slate-600 hover:bg-slate-200\"\n            aria-label={line.quantity === 1 ? `Remove ${line.name}` : `One less ${line.name}`}\n          >\n            <LuMinus aria-hidden />\n          </button>\n          <span className=\"w-6 text-center font-semibold tabular\" aria-live=\"polite\">\n            {line.quantity}\n          </span>\n          <button\n            type=\"button\"\n            onClick={() => onIncrement(line)}\n            className=\"grid h-8 w-8 place-items-center rounded-full bg-brand text-white hover:bg-brand-700\"\n            aria-label={`One more ${line.name}`}\n          >\n            <LuPlus aria-hidden />\n          </button>\n        </div>\n      )}\n    </li>\n  );\n});\n",
"client/src/components/pos/CartPanel.jsx": "import { LuPause, LuPercent, LuShoppingBasket, LuTrash2, LuX } from 'react-icons/lu';\nimport { useBill } from '../../hooks/useBill';\nimport { formatMoney } from '../../lib/format';\nimport { fromPaise } from '../../lib/pricing';\nimport { useCartStore } from '../../store/cartStore';\nimport { Button } from '../ui/Button';\nimport { EmptyState } from '../ui/States';\nimport { CartLine } from './CartLine';\n\nexport function CartPanel({ onCheckout, onHold, onDiscount, inSheet = false }) {\n  const { lines, billDiscount, bill, itemCount, currency } = useBill();\n  const { setQuantity, removeLine, clear, setBillDiscount, lastAddedLineId } = useCartStore();\n\n  const increment = (line) => setQuantity(line.lineId, line.quantity + 1);\n  const decrement = (line) => setQuantity(line.lineId, line.quantity - 1);\n\n  return (\n    <div className=\"flex h-full min-h-0 flex-col bg-white\">\n      <header className={`flex items-center gap-2 ${inSheet ? 'pb-2' : 'px-5 pb-3 pt-5'}`}>\n        {inSheet ? (\n          <p className=\"flex-1 text-desc text-slate-500\">\n            {itemCount} item{itemCount === 1 ? '' : 's'}\n          </p>\n        ) : (\n          <div className=\"min-w-0 flex-1\">\n            <h2>Current bill</h2>\n            <p className=\"text-desc text-slate-500\">\n              {itemCount} item{itemCount === 1 ? '' : 's'}\n            </p>\n          </div>\n        )}\n        <Button variant=\"soft\" size=\"sm\" onClick={onHold} disabled={!lines.length}>\n          <LuPause aria-hidden /> Hold\n        </Button>\n        <Button variant=\"ghost\" size=\"iconSm\" onClick={clear} disabled={!lines.length} aria-label=\"Clear bill\" title=\"Clear bill\">\n          <LuTrash2 aria-hidden />\n        </Button>\n      </header>\n\n      <div className={`scroll-thin min-h-0 flex-1 overflow-y-auto ${inSheet ? '' : 'px-3'}`}>\n        {lines.length ? (\n          <ul className=\"space-y-1 pb-2\">\n            {lines.map((line, i) => (\n              <CartLine\n                key={line.lineId}\n                line={line}\n                computed={bill.lines[i]}\n                currency={currency}\n                highlight={line.lineId === lastAddedLineId}\n                onIncrement={increment}\n                onDecrement={decrement}\n                onRemove={removeLine}\n              />\n            ))}\n          </ul>\n        ) : (\n          <EmptyState icon={LuShoppingBasket} title=\"No items yet\" description=\"Scan a barcode, type a product code, or tap a product to start the bill.\" />\n        )}\n      </div>\n\n      <footer className={`space-y-3 border-t border-slate-100 pt-3 ${inSheet ? 'pb-1' : 'px-5 pb-5'}`}>\n        {bill.billDiscount > 0 ? (\n          <div className=\"flex items-center gap-2 rounded-2xl bg-brand-50 px-3 py-2\">\n            <LuPercent className=\"shrink-0 text-brand\" aria-hidden />\n            <button type=\"button\" onClick={onDiscount} className=\"min-w-0 flex-1 text-left\">\n              <p className=\"truncate text-desc font-semibold text-brand-800\">\n                {billDiscount.type === 'PERCENT' ? `${billDiscount.value}% bill discount` : `${formatMoney(billDiscount.value, currency)} off the bill`}\n              </p>\n              {billDiscount.reason ? <p className=\"truncate text-desc text-brand-700/80\">{billDiscount.reason}</p> : null}\n            </button>\n            <button\n              type=\"button\"\n              onClick={() => setBillDiscount({ value: 0 })}\n              className=\"grid h-7 w-7 place-items-center rounded-full text-brand-700 hover:bg-brand-100\"\n              aria-label=\"Remove bill discount\"\n            >\n              <LuX aria-hidden />\n            </button>\n          </div>\n        ) : (\n          <button\n            type=\"button\"\n            onClick={onDiscount}\n            disabled={!lines.length}\n            className=\"inline-flex items-center gap-1.5 text-desc font-semibold text-brand-700 hover:text-brand-800 disabled:text-slate-300\"\n          >\n            <LuPercent aria-hidden /> Add bill discount\n          </button>\n        )}\n\n        <dl className=\"space-y-1 text-body tabular\">\n          <div className=\"flex justify-between text-slate-600\">\n            <dt>Subtotal</dt>\n            <dd>{formatMoney(fromPaise(bill.subtotal), currency)}</dd>\n          </div>\n          {bill.itemDiscount > 0 ? (\n            <div className=\"flex justify-between text-brand-700\">\n              <dt>Markdowns</dt>\n              <dd>−{formatMoney(fromPaise(bill.itemDiscount), currency)}</dd>\n            </div>\n          ) : null}\n          {bill.billDiscount > 0 ? (\n            <div className=\"flex justify-between text-brand-700\">\n              <dt>Bill discount</dt>\n              <dd>−{formatMoney(fromPaise(bill.billDiscount), currency)}</dd>\n            </div>\n          ) : null}\n          <div className=\"flex justify-between text-slate-600\">\n            <dt>GST {bill.taxRate}%</dt>\n            <dd>{formatMoney(fromPaise(bill.taxTotal), currency)}</dd>\n          </div>\n        </dl>\n\n        <div className=\"flex items-center gap-4 pt-1\">\n          <div className=\"min-w-0\">\n            <p className=\"text-desc text-slate-500\">Total price</p>\n            <p className=\"truncate text-h1 font-bold text-slate-900 tabular\">{formatMoney(fromPaise(bill.grandTotal), currency)}</p>\n          </div>\n          <Button size=\"lg\" className=\"flex-1\" onClick={onCheckout} disabled={!lines.length}>\n            Checkout\n          </Button>\n        </div>\n        {!inSheet ? <p className=\"hidden text-center text-desc text-slate-400 lg:block\">F2 search, F4 hold, F8 checkout, F9 held bills</p> : null}\n      </footer>\n    </div>\n  );\n}\n",
"client/src/components/pos/CategoryRail.jsx": "import { useMemo } from 'react';\nimport { LuLayoutGrid } from 'react-icons/lu';\n\nexport function CategoryRail({ categories, selected, onSelect, selectedSub, onSelectSub }) {\n  const { tops, childrenOf } = useMemo(() => {\n    const map = new Map();\n    const topList = [];\n    for (const c of categories) {\n      if (c.parentId) {\n        if (!map.has(c.parentId)) map.set(c.parentId, []);\n        map.get(c.parentId).push(c);\n      } else topList.push(c);\n    }\n    return { tops: topList, childrenOf: map };\n  }, [categories]);\n\n  const subs = selected !== 'all' ? childrenOf.get(selected) || [] : [];\n\n  const Tile = ({ id, label, icon }) => {\n    const active = selected === id;\n    return (\n      <button\n        type=\"button\"\n        onClick={() => onSelect(id)}\n        aria-pressed={active}\n        className=\"flex w-[72px] shrink-0 flex-col items-center gap-1.5 rounded-2xl py-1\"\n      >\n        <span\n          className={`grid h-14 w-14 place-items-center rounded-full text-h1 transition ${\n            active ? 'bg-brand-50 ring-2 ring-brand' : 'bg-white shadow-card ring-1 ring-slate-900/[0.04] hover:ring-brand/40'\n          }`}\n          aria-hidden\n        >\n          {icon}\n        </span>\n        <span className={`line-clamp-2 text-center text-desc leading-4 ${active ? 'font-semibold text-brand-700' : 'text-slate-600'}`}>{label}</span>\n      </button>\n    );\n  };\n\n  return (\n    <div>\n      <div className=\"no-scrollbar -mx-4 flex gap-1 overflow-x-auto px-4 pb-1 sm:-mx-6 sm:px-6\" role=\"toolbar\" aria-label=\"Categories\">\n        <Tile id=\"all\" label=\"All items\" icon={<LuLayoutGrid className=\"text-brand\" size={22} />} />\n        {tops.map((c) => (\n          <Tile key={c.id} id={c.id} label={c.name} icon={c.icon || c.name[0]} />\n        ))}\n      </div>\n      {subs.length ? (\n        <div className=\"no-scrollbar -mx-4 mt-3 flex gap-2 overflow-x-auto px-4 sm:-mx-6 sm:px-6\" role=\"toolbar\" aria-label=\"Sub-categories\">\n          {[{ id: 'all', name: 'All' }, ...subs].map((s) => {\n            const active = selectedSub === s.id;\n            return (\n              <button\n                key={s.id}\n                type=\"button\"\n                onClick={() => onSelectSub(s.id)}\n                aria-pressed={active}\n                className={`h-8 shrink-0 rounded-full px-3.5 text-desc font-medium transition ${\n                  active ? 'bg-slate-900 text-white' : 'bg-white text-slate-600 ring-1 ring-slate-200 hover:ring-slate-300'\n                }`}\n              >\n                {s.icon ? `${s.icon} ` : ''}\n                {s.name}\n              </button>\n            );\n          })}\n        </div>\n      ) : null}\n    </div>\n  );\n}\n",
"client/src/components/pos/DiscountModal.jsx": "import { useEffect, useState } from 'react';\nimport { formatMoney } from '../../lib/format';\nimport { fromPaise, toPaise } from '../../lib/pricing';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { Segmented } from '../ui/Segmented';\n\nconst PRESETS = [5, 10, 15, 20];\n\nexport function DiscountModal({ open, onClose, afterMarkdownsPaise, current, maxCashierPct, isAdmin, currency, onApply }) {\n  const [type, setType] = useState('PERCENT');\n  const [value, setValue] = useState('');\n  const [reason, setReason] = useState('');\n\n  useEffect(() => {\n    if (!open) return;\n    setType(current?.type || 'PERCENT');\n    setValue(current?.value ? String(current.value) : '');\n    setReason(current?.reason || '');\n  }, [open, current]);\n\n  const numeric = Math.max(0, Number(value) || 0);\n  const discountPaise =\n    type === 'PERCENT' ? Math.round((afterMarkdownsPaise * Math.min(100, numeric)) / 100) : Math.min(afterMarkdownsPaise, toPaise(numeric));\n  const effectivePct = afterMarkdownsPaise > 0 ? (discountPaise / afterMarkdownsPaise) * 100 : 0;\n  const overCap = !isAdmin && effectivePct > maxCashierPct + 0.005;\n  const invalid = numeric <= 0 || (type === 'PERCENT' && numeric > 100);\n\n  return (\n    <Modal\n      open={open}\n      onClose={onClose}\n      size=\"sm\"\n      title=\"Bill discount\"\n      description={isAdmin ? 'Applied after item markdowns, before GST' : `Cashiers can give up to ${maxCashierPct}% off the bill`}\n      footer={\n        <div className=\"flex gap-2\">\n          {current?.value ? (\n            <Button variant=\"dangerSoft\" onClick={() => onApply({ type: 'PERCENT', value: 0, reason: '' })}>\n              Remove\n            </Button>\n          ) : null}\n          <Button className=\"flex-1\" disabled={invalid || overCap} onClick={() => onApply({ type, value: numeric, reason })}>\n            Apply {discountPaise > 0 ? formatMoney(fromPaise(discountPaise), currency) : 'discount'}\n          </Button>\n        </div>\n      }\n    >\n      <Segmented\n        className=\"w-full\"\n        ariaLabel=\"Discount type\"\n        value={type}\n        onChange={(v) => { setType(v); setValue(''); }}\n        options={[\n          { value: 'PERCENT', label: 'Percent' },\n          { value: 'FLAT', label: 'Amount' },\n        ]}\n      />\n\n      <div className=\"mt-4\">\n        <label htmlFor=\"discount-value\" className=\"label\">\n          {type === 'PERCENT' ? 'Discount (%)' : `Discount (${currency})`}\n        </label>\n        <input\n          id=\"discount-value\"\n          inputMode=\"decimal\"\n          className=\"field tabular\"\n          value={value}\n          onChange={(e) => setValue(e.target.value.replace(/[^\\d.]/g, ''))}\n          placeholder={type === 'PERCENT' ? '10' : '50'}\n        />\n      </div>\n\n      {type === 'PERCENT' ? (\n        <div className=\"mt-3 grid grid-cols-4 gap-2\">\n          {PRESETS.map((p) => (\n            <Button\n              key={p}\n              size=\"sm\"\n              variant={numeric === p ? 'primary' : 'secondary'}\n              disabled={!isAdmin && p > maxCashierPct}\n              onClick={() => setValue(String(p))}\n            >\n              {p}%\n            </Button>\n          ))}\n        </div>\n      ) : null}\n\n      <div className=\"mt-4\">\n        <label htmlFor=\"discount-reason\" className=\"label\">\n          Reason (printed on the bill record)\n        </label>\n        <input id=\"discount-reason\" className=\"field\" maxLength={200} value={reason} onChange={(e) => setReason(e.target.value)} placeholder=\"Loyal customer, damaged pack…\" />\n      </div>\n\n      {overCap ? (\n        <p className=\"mt-3 rounded-xl bg-amber-50 px-3 py-2 text-desc text-amber-800\" role=\"alert\">\n          That is {effectivePct.toFixed(1)}% of the bill. Ask an admin to apply discounts above {maxCashierPct}%.\n        </p>\n      ) : null}\n    </Modal>\n  );\n}\n",
"client/src/components/pos/HeldBillsModal.jsx": "import { LuLayers, LuTrash2 } from 'react-icons/lu';\nimport { formatMoney, relativeTime } from '../../lib/format';\nimport { computeBill, fromPaise } from '../../lib/pricing';\nimport { useCartStore } from '../../store/cartStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { EmptyState } from '../ui/States';\n\nexport function HeldBillsModal({ open, onClose, taxRate, currency }) {\n  const { heldBills, resumeHeld, discardHeld } = useCartStore();\n\n  return (\n    <Modal open={open} onClose={onClose} title=\"Held bills\" description=\"Parked carts waiting on this register\">\n      {heldBills.length === 0 ? (\n        <EmptyState icon={LuLayers} title=\"No held bills\" description=\"Park a bill when a customer steps away, then pick it up again here.\" />\n      ) : (\n        <ul className=\"divide-y divide-slate-100\">\n          {heldBills.map((bill) => {\n            const total = computeBill({ items: bill.lines, billDiscount: bill.billDiscount, taxRate });\n            return (\n              <li key={bill.id} className=\"flex items-center gap-3 py-3\">\n                <div className=\"min-w-0 flex-1\">\n                  <p className=\"truncate font-semibold\">{bill.label}</p>\n                  <p className=\"truncate text-desc text-slate-500\">\n                    {bill.lines.length} item{bill.lines.length === 1 ? '' : 's'}, {relativeTime(bill.heldAt)}\n                  </p>\n                  <p className=\"text-desc text-brand-700 tabular\">{formatMoney(fromPaise(total.grandTotal), currency)}</p>\n                </div>\n                <Button\n                  size=\"sm\"\n                  onClick={async () => {\n                    await resumeHeld(bill.id);\n                    onClose();\n                  }}\n                >\n                  Resume\n                </Button>\n                <Button size=\"iconSm\" variant=\"ghost\" aria-label={`Discard ${bill.label}`} onClick={() => discardHeld(bill.id)}>\n                  <LuTrash2 aria-hidden />\n                </Button>\n              </li>\n            );\n          })}\n        </ul>\n      )}\n    </Modal>\n  );\n}\n",
"client/src/components/pos/PaymentModal.jsx": "import QRCode from 'qrcode';\nimport { useEffect, useMemo, useState } from 'react';\nimport { LuBanknote, LuCreditCard, LuQrCode } from 'react-icons/lu';\nimport { formatMoney } from '../../lib/format';\nimport { buildUpiUri } from '../../lib/upi';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { Segmented } from '../ui/Segmented';\n\nfunction quickCashAmounts(total) {\n  const options = new Set([Math.ceil(total)]);\n  [10, 50, 100, 500, 2000].forEach((step) => options.add(Math.ceil(total / step) * step));\n  return [...options].filter((v) => v >= total).sort((a, b) => a - b).slice(0, 4);\n}\n\nexport function PaymentModal({ open, onClose, total, itemCount, settings, isAdmin, submitting, onConfirm }) {\n  const currency = settings?.currency || 'INR';\n  const upiReady = Boolean(settings?.upiVpa);\n  const [method, setMethod] = useState('CASH');\n  const [tendered, setTendered] = useState('');\n  const [phone, setPhone] = useState('');\n  const [qr, setQr] = useState(null);\n  const [reference] = useState(() => `B${Date.now().toString(36).toUpperCase()}`);\n\n  useEffect(() => {\n    if (!open) return;\n    setMethod(upiReady ? 'UPI' : 'CASH');\n    setTendered('');\n    setPhone('');\n  }, [open, upiReady]);\n\n  const upiUri = useMemo(\n    () =>\n      upiReady\n        ? buildUpiUri({ vpa: settings.upiVpa, payeeName: settings.upiPayeeName || settings.storeName, amount: total, reference, note: `${settings.storeName} bill` })\n        : null,\n    [upiReady, settings, total, reference],\n  );\n\n  useEffect(() => {\n    let cancelled = false;\n    if (open && method === 'UPI' && upiUri) {\n      QRCode.toDataURL(upiUri, { width: 440, margin: 1, errorCorrectionLevel: 'M', color: { dark: '#0F172A', light: '#FFFFFF' } })\n        .then((url) => !cancelled && setQr(url))\n        .catch(() => !cancelled && setQr(null));\n    }\n    return () => {\n      cancelled = true;\n    };\n  }, [open, method, upiUri]);\n\n  const tenderedNum = Number(tendered) || 0;\n  const cashShort = method === 'CASH' && tendered !== '' && tenderedNum + 0.0001 < total;\n  const change = method === 'CASH' ? Math.max(0, tenderedNum - total) : 0;\n  const canConfirm = !submitting && (method !== 'CASH' || tendered === '' || !cashShort) && (method !== 'UPI' || upiReady);\n\n  const confirm = () => {\n    if (!canConfirm) return;\n    onConfirm({ paymentMethod: method, amountTendered: method === 'CASH' ? (tendered === '' ? total : tenderedNum) : null, customerPhone: phone });\n  };\n\n  const confirmLabel = { UPI: 'Payment received', CASH: 'Complete sale', CARD: 'Card approved' }[method];\n\n  return (\n    <Modal\n      open={open}\n      onClose={submitting ? undefined : onClose}\n      dismissible={!submitting}\n      title=\"Take payment\"\n      description={`${itemCount} item${itemCount === 1 ? '' : 's'}`}\n      footer={\n        <div className=\"flex items-center gap-3\">\n          <div className=\"min-w-0 flex-1\">\n            <p className=\"text-desc text-slate-500\">Total due</p>\n            <p className=\"text-h1 font-bold tabular\">{formatMoney(total, currency)}</p>\n          </div>\n          <Button size=\"lg\" onClick={confirm} disabled={!canConfirm} loading={submitting}>\n            {confirmLabel}\n          </Button>\n        </div>\n      }\n    >\n      <div\n        onKeyDown={(e) => {\n          if (e.key === 'Enter' && e.target.tagName !== 'BUTTON') {\n            e.preventDefault();\n            confirm();\n          }\n        }}\n      >\n        <Segmented\n          className=\"w-full\"\n          ariaLabel=\"Payment method\"\n          value={method}\n          onChange={setMethod}\n          options={[\n            { value: 'UPI', label: 'UPI', icon: LuQrCode },\n            { value: 'CASH', label: 'Cash', icon: LuBanknote },\n            { value: 'CARD', label: 'Card', icon: LuCreditCard },\n          ]}\n        />\n\n        {method === 'UPI' ? (\n          <div className=\"mt-4 flex flex-col items-center text-center\">\n            {upiReady ? (\n              <>\n                <div className=\"rounded-3xl bg-white p-3 shadow-card ring-1 ring-slate-900/5\">\n                  {qr ? <img src={qr} alt={`UPI QR code for ${formatMoney(total, currency)}`} className=\"h-[220px] w-[220px]\" /> : <div className=\"h-[220px] w-[220px] animate-pulse rounded-2xl bg-slate-100\" />}\n                </div>\n                <p className=\"mt-3 text-body font-semibold\">Scan with any UPI app</p>\n                <p className=\"mt-0.5 text-desc text-slate-500\">\n                  Pays {formatMoney(total, currency)} to {settings.upiVpa}. Confirm once the customer’s app shows success.\n                </p>\n              </>\n            ) : (\n              <div className=\"w-full rounded-2xl bg-amber-50 p-4 text-left text-desc text-amber-800\">\n                {isAdmin ? 'Add the store’s UPI ID in Settings to show a payment QR here.' : 'UPI QR is not set up yet. Ask an admin to add the store’s UPI ID, or take cash or card.'}\n              </div>\n            )}\n          </div>\n        ) : null}\n\n        {method === 'CASH' ? (\n          <div className=\"mt-4\">\n            <label htmlFor=\"cash-tendered\" className=\"label\">\n              Cash received\n            </label>\n            <input\n              id=\"cash-tendered\"\n              inputMode=\"decimal\"\n              autoFocus\n              className=\"field tabular\"\n              placeholder={total.toFixed(2)}\n              value={tendered}\n              onChange={(e) => setTendered(e.target.value.replace(/[^\\d.]/g, ''))}\n            />\n            <div className=\"mt-2 grid grid-cols-4 gap-2\">\n              {quickCashAmounts(total).map((amt) => (\n                <Button key={amt} size=\"sm\" variant={tenderedNum === amt ? 'primary' : 'secondary'} onClick={() => setTendered(String(amt))}>\n                  {formatMoney(amt, currency).replace(/\\.00$/, '')}\n                </Button>\n              ))}\n            </div>\n            <div className={`mt-4 flex items-center justify-between rounded-2xl px-4 py-3 ${cashShort ? 'bg-rose-50' : 'bg-brand-50'}`}>\n              <span className={`text-body font-medium ${cashShort ? 'text-rose-700' : 'text-brand-800'}`}>{cashShort ? 'Still due' : 'Change to return'}</span>\n              <span className={`text-h2 font-bold tabular ${cashShort ? 'text-rose-700' : 'text-brand-800'}`}>\n                {formatMoney(cashShort ? total - tenderedNum : change, currency)}\n              </span>\n            </div>\n          </div>\n        ) : null}\n\n        {method === 'CARD' ? (\n          <div className=\"mt-4 rounded-2xl bg-slate-50 p-4 text-body text-slate-700\">\n            Charge <span className=\"font-semibold tabular\">{formatMoney(total, currency)}</span> on the card machine, then confirm here once it is approved.\n          </div>\n        ) : null}\n\n        <div className=\"mt-4\">\n          <label htmlFor=\"customer-phone\" className=\"label\">\n            Customer mobile (optional, for a WhatsApp receipt)\n          </label>\n          <input\n            id=\"customer-phone\"\n            type=\"tel\"\n            inputMode=\"tel\"\n            className=\"field\"\n            placeholder=\"98765 43210\"\n            maxLength={16}\n            value={phone}\n            onChange={(e) => setPhone(e.target.value.replace(/[^\\d+\\s-]/g, ''))}\n          />\n        </div>\n      </div>\n    </Modal>\n  );\n}\n",
"client/src/components/pos/ProductCard.jsx": "import { memo } from 'react';\nimport { LuPlus, LuScale } from 'react-icons/lu';\nimport { formatMoney, formatNumber } from '../../lib/format';\nimport { ProductThumb } from './ProductThumb';\n\nfunction stockNote(p) {\n  if (p.stock <= 0) return { text: 'Out of stock', className: 'text-rose-600' };\n  if (p.stock <= p.lowStockThreshold) return { text: `Only ${formatNumber(p.stock)} ${p.unit} left`, className: 'text-amber-600' };\n  return { text: `${formatNumber(p.stock)} ${p.unit} in stock`, className: 'text-slate-500' };\n}\n\nexport const ProductCard = memo(function ProductCard({ product, inCartQty, currency, onSelect }) {\n  const effective = product.price * (1 - (product.discountPercent || 0) / 100);\n  const stock = stockNote(product);\n  return (\n    <button\n      type=\"button\"\n      onClick={() => onSelect(product)}\n      className=\"group flex flex-col rounded-3xl bg-white p-2 text-left shadow-card ring-1 ring-slate-900/[0.03] transition-shadow hover:shadow-lift\"\n      aria-label={`Add ${product.name}, ${formatMoney(effective, currency)} per ${product.unit}`}\n    >\n      <div className=\"relative aspect-[4/3] overflow-hidden rounded-2xl bg-brand-50\">\n        <ProductThumb src={product.imageUrl} name={product.name} className=\"transition-transform duration-300 group-hover:scale-[1.03]\" />\n        {product.discountPercent > 0 ? (\n          <span className=\"absolute left-2 top-2 rounded-full bg-white/90 px-2 py-0.5 text-desc font-semibold text-brand-700\">\n            {formatNumber(product.discountPercent)}% off\n          </span>\n        ) : null}\n        {inCartQty ? (\n          <span key={inCartQty} className=\"absolute right-2 top-2 grid h-6 min-w-6 animate-pop place-items-center rounded-full bg-brand px-1.5 text-desc font-semibold text-white tabular\">\n            {product.soldByWeight ? '✓' : inCartQty}\n          </span>\n        ) : null}\n      </div>\n      <div className=\"flex flex-1 flex-col px-1.5 pb-1 pt-2.5\">\n        <h3 className=\"line-clamp-2 min-h-[40px] text-body font-semibold leading-5 text-slate-900\">{product.name}</h3>\n        <p className={`mt-0.5 truncate text-desc ${stock.className}`}>{stock.text}</p>\n        <div className=\"mt-2 flex items-end justify-between gap-2\">\n          <div className=\"min-w-0\">\n            {product.discountPercent > 0 ? (\n              <p className=\"text-desc text-slate-400 line-through tabular\">{formatMoney(product.price, currency)}</p>\n            ) : (\n              <p className=\"text-desc text-slate-400\">Code {product.code}</p>\n            )}\n            <p className=\"truncate tabular\">\n              <span className=\"text-body font-semibold text-brand-700\">{formatMoney(effective, currency)}</span>\n              <span className=\"text-desc text-slate-500\">/{product.unit}</span>\n            </p>\n          </div>\n          <span className=\"grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-brand text-white transition group-hover:bg-brand-700\" aria-hidden>\n            {product.soldByWeight ? <LuScale size={16} /> : <LuPlus size={16} />}\n          </span>\n        </div>\n      </div>\n    </button>\n  );\n});\n",
"client/src/components/pos/ProductThumb.jsx": "import { useState } from 'react';\n\nexport function ProductThumb({ src, name, className = '' }) {\n  const [failed, setFailed] = useState(false);\n  if (!src || failed) {\n    return (\n      <div className={`grid h-full w-full place-items-center text-h2 font-semibold text-brand-700 ${className}`} aria-hidden>\n        {name?.[0]?.toUpperCase() ?? '?'}\n      </div>\n    );\n  }\n  return (\n    <img\n      src={src}\n      alt=\"\"\n      loading=\"lazy\"\n      decoding=\"async\"\n      onError={() => setFailed(true)}\n      className={`h-full w-full object-cover mix-blend-multiply ${className}`}\n    />\n  );\n}\n",
"client/src/components/pos/ReceiptModal.jsx": "import { createPortal } from 'react-dom';\nimport { useEffect, useState } from 'react';\nimport { LuCircleCheck, LuCloudUpload, LuPrinter, LuReceipt, LuSend, LuUsb } from 'react-icons/lu';\nimport { receiptToWhatsAppText, whatsappLink } from '../../lib/checkout';\nimport { receiptToEscPos } from '../../lib/escpos';\nimport { formatMoney } from '../../lib/format';\nimport { useHardwareStore } from '../../store/hardwareStore';\nimport { toast } from '../../store/toastStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\n\nfunction ThermalReceipt({ r }) {\n  const cur = (n) => formatMoney(n, r.store?.currency || 'INR');\n  return (\n    <div className=\"mx-auto w-[72mm] font-mono text-[11px] leading-[1.35] text-black\">\n      <div className=\"text-center\">\n        <p className=\"text-[14px] font-bold\">{r.store?.storeName}</p>\n        {r.store?.address ? <p>{r.store.address}</p> : null}\n        {r.store?.gstin ? <p>GSTIN {r.store.gstin}</p> : null}\n        {r.store?.phone ? <p>Ph {r.store.phone}</p> : null}\n      </div>\n      <p className=\"my-1\">{'-'.repeat(42)}</p>\n      <div className=\"flex justify-between\">\n        <span>{r.reference}</span>\n        <span>{r.dateLabel}</span>\n      </div>\n      <p>\n        Cashier {r.cashierName} · {r.terminalId}\n      </p>\n      <p className=\"my-1\">{'-'.repeat(42)}</p>\n      {r.lines.map((l, i) => (\n        <div key={i} className=\"mb-0.5\">\n          <p>{l.name}</p>\n          <div className=\"flex justify-between\">\n            <span>\n              {'  '}\n              {l.quantityLabel} × {cur(l.unitPrice)}\n              {l.discountPercent ? ` (−${l.discountPercent}%)` : ''}\n            </span>\n            <span>{cur(l.amount)}</span>\n          </div>\n        </div>\n      ))}\n      <p className=\"my-1\">{'-'.repeat(42)}</p>\n      <div className=\"flex justify-between\">\n        <span>Subtotal</span>\n        <span>{cur(r.totals.subtotal)}</span>\n      </div>\n      {r.totals.discountTotal ? (\n        <div className=\"flex justify-between\">\n          <span>Discounts</span>\n          <span>−{cur(r.totals.discountTotal)}</span>\n        </div>\n      ) : null}\n      <div className=\"flex justify-between\">\n        <span>CGST {r.totals.taxRate / 2}%</span>\n        <span>{cur(r.totals.cgst)}</span>\n      </div>\n      <div className=\"flex justify-between\">\n        <span>SGST {r.totals.taxRate / 2}%</span>\n        <span>{cur(r.totals.sgst)}</span>\n      </div>\n      <div className=\"flex justify-between text-[13px] font-bold\">\n        <span>TOTAL</span>\n        <span>{cur(r.totals.grandTotal)}</span>\n      </div>\n      <div className=\"flex justify-between\">\n        <span>Paid by {r.paymentMethod}</span>\n        <span>{cur(r.amountTendered ?? r.totals.grandTotal)}</span>\n      </div>\n      {r.changeDue ? (\n        <div className=\"flex justify-between\">\n          <span>Change</span>\n          <span>{cur(r.changeDue)}</span>\n        </div>\n      ) : null}\n      <p className=\"my-1\">{'-'.repeat(42)}</p>\n      <p className=\"text-center\">{r.store?.receiptFooter || 'Thank you for shopping with us.'}</p>\n      {r.pending ? <p className=\"mt-1 text-center\">Bill saved on this register; syncs automatically</p> : null}\n    </div>\n  );\n}\n\nexport function ReceiptModal({ receipt, onClose }) {\n  const { printer, printBytes, connectPrinter, serialSupported } = useHardwareStore();\n  const [sending, setSending] = useState(false);\n\n  useEffect(() => {\n    if (!receipt) return undefined;\n    const onKey = (e) => {\n      if (e.key === 'Enter') {\n        e.preventDefault();\n        onClose();\n      }\n    };\n    window.addEventListener('keydown', onKey);\n    return () => window.removeEventListener('keydown', onKey);\n  }, [receipt, onClose]);\n\n  if (!receipt) return null;\n  const currency = receipt.store?.currency || 'INR';\n\n  const printThermal = async () => {\n    setSending(true);\n    try {\n      if (printer.status !== 'connected') await connectPrinter();\n      if (useHardwareStore.getState().printer.status !== 'connected') return;\n      await printBytes(receiptToEscPos(receipt));\n      toast.success('Sent to the receipt printer');\n    } catch (err) {\n      toast.error(err.message);\n    } finally {\n      setSending(false);\n    }\n  };\n\n  return (\n    <>\n      <Modal\n        open\n        onClose={onClose}\n        size=\"sm\"\n        title=\"Sale complete\"\n        footer={\n          <div className=\"space-y-2\">\n            <div className=\"grid grid-cols-2 gap-2\">\n              <Button variant=\"secondary\" onClick={() => window.print()}>\n                <LuPrinter aria-hidden /> Print\n              </Button>\n              {receipt.customerPhone ? (\n                <Button\n                  variant=\"secondary\"\n                  onClick={() => window.open(whatsappLink(receipt.customerPhone, receiptToWhatsAppText(receipt)), '_blank', 'noopener')}\n                >\n                  <LuSend aria-hidden /> WhatsApp\n                </Button>\n              ) : (\n                <Button variant=\"secondary\" onClick={printThermal} loading={sending} disabled={!serialSupported}>\n                  <LuUsb aria-hidden /> Thermal\n                </Button>\n              )}\n            </div>\n            <Button className=\"w-full\" size=\"lg\" onClick={onClose}>\n              New bill\n            </Button>\n          </div>\n        }\n      >\n        <div className=\"flex flex-col items-center text-center\">\n          <div className=\"grid h-12 w-12 place-items-center rounded-full bg-brand-50 text-brand\">\n            <LuCircleCheck size={24} aria-hidden />\n          </div>\n          <p className=\"mt-3 text-h1 font-bold tabular\">{formatMoney(receipt.totals.grandTotal, currency)}</p>\n          <p className=\"mt-0.5 text-desc text-slate-500\">{receipt.reference}</p>\n          {receipt.changeDue ? (\n            <p className=\"mt-3 rounded-full bg-brand-50 px-4 py-1.5 text-body font-semibold text-brand-800 tabular\">\n              Return {formatMoney(receipt.changeDue, currency)} change\n            </p>\n          ) : null}\n          {receipt.totals.discountTotal ? (\n            <p className=\"mt-2 text-desc text-brand-700\">Customer saved {formatMoney(receipt.totals.discountTotal, currency)}</p>\n          ) : null}\n          {receipt.pending ? (\n            <p className=\"mt-3 flex items-center gap-1.5 rounded-xl bg-amber-50 px-3 py-2 text-desc text-amber-800\">\n              <LuCloudUpload aria-hidden /> Saved on this register. The invoice number is assigned when it uploads.\n            </p>\n          ) : null}\n        </div>\n\n        <details className=\"mt-5 rounded-2xl bg-slate-50 p-3\">\n          <summary className=\"cursor-pointer list-none text-desc font-semibold text-slate-600\">\n            <span className=\"inline-flex items-center gap-1.5\">\n              <LuReceipt aria-hidden /> View receipt\n            </span>\n          </summary>\n          <div className=\"mt-3 overflow-x-auto rounded-xl bg-white p-3\">\n            <ThermalReceipt r={receipt} />\n          </div>\n        </details>\n\n        {printer.status === 'connected' && receipt.customerPhone ? (\n          <button type=\"button\" onClick={printThermal} className=\"mt-3 inline-flex items-center gap-1.5 text-desc font-semibold text-brand-700\">\n            <LuUsb aria-hidden /> Also print on the thermal printer\n          </button>\n        ) : null}\n      </Modal>\n      {createPortal(<ThermalReceipt r={receipt} />, document.getElementById('print-root'))}\n    </>\n  );\n}\n",
"client/src/components/pos/ScaleModal.jsx": "import { useEffect, useMemo, useState } from 'react';\nimport { LuMinus, LuPlug, LuPlus, LuScale } from 'react-icons/lu';\nimport { formatMoney } from '../../lib/format';\nimport { computeBill, fromPaise, roundQty } from '../../lib/pricing';\nimport { useHardwareStore } from '../../store/hardwareStore';\nimport { Button } from '../ui/Button';\nimport { Modal } from '../ui/Modal';\nimport { ProductThumb } from './ProductThumb';\n\nconst STEP_KG = 0.25;\nconst LIVE_STALE_MS = 2500;\n\nexport function ScaleModal({ product, currency, onClose, onAdd }) {\n  const { serialSupported, scale, connectScale } = useHardwareStore();\n  const [manualGross, setManualGross] = useState(0);\n  const [manualText, setManualText] = useState('');\n  const [tare, setTare] = useState(0);\n  const [, tick] = useState(0);\n\n  useEffect(() => {\n    setManualGross(0);\n    setManualText('');\n    setTare(0);\n  }, [product?.id]);\n\n  // Re-evaluate \"live\" freshness while a scale is connected.\n  useEffect(() => {\n    if (scale.status !== 'connected') return undefined;\n    const t = setInterval(() => tick((n) => n + 1), 500);\n    return () => clearInterval(t);\n  }, [scale.status]);\n\n  const live = scale.status === 'connected' && scale.reading && Date.now() - scale.reading.at < LIVE_STALE_MS;\n  const gross = live ? scale.reading.kg : manualGross;\n  const net = roundQty(Math.max(0, gross - tare));\n\n  const amount = useMemo(() => {\n    if (!product) return 0;\n    const bill = computeBill({ items: [{ quantity: net, unitPrice: product.price, discountPercent: product.discountPercent }], taxRate: 0 });\n    return fromPaise(bill.grandTotal);\n  }, [net, product]);\n\n  const setGross = (kg) => {\n    const v = roundQty(Math.max(0, kg));\n    setManualGross(v);\n    setManualText(v ? v.toFixed(3) : '');\n  };\n\n  const add = () => {\n    if (net > 0) onAdd(product, net);\n  };\n\n  if (!product) return null;\n\n  return (\n    <Modal\n      open={Boolean(product)}\n      onClose={onClose}\n      title=\"Weigh item\"\n      description={live ? 'Reading live from the connected scale' : 'Enter or adjust the weight on the platter'}\n      footer={\n        <div className=\"flex items-center gap-3\">\n          <div className=\"min-w-0 flex-1\">\n            <p className=\"text-desc text-slate-500\">Amount</p>\n            <p className=\"text-h1 font-bold tabular\">{formatMoney(amount, currency)}</p>\n          </div>\n          <Button variant=\"secondary\" onClick={onClose}>\n            Cancel\n          </Button>\n          <Button onClick={add} disabled={net <= 0}>\n            Add to bill\n          </Button>\n        </div>\n      }\n    >\n      <div\n        onKeyDown={(e) => {\n          if (e.key === 'Enter') {\n            e.preventDefault();\n            add();\n          }\n        }}\n      >\n        <div className=\"flex items-center gap-3\">\n          <div className=\"h-14 w-14 shrink-0 overflow-hidden rounded-2xl bg-brand-50\">\n            <ProductThumb src={product.imageUrl} name={product.name} />\n          </div>\n          <div className=\"min-w-0\">\n            <h3 className=\"truncate\">{product.name}</h3>\n            <p className=\"text-desc text-slate-500 tabular\">\n              {formatMoney(product.price, currency)} per {product.unit}\n              {product.discountPercent > 0 ? `, ${product.discountPercent}% markdown applied` : ''}\n            </p>\n          </div>\n        </div>\n\n        <div className=\"mt-4 rounded-3xl bg-brand-50 p-5 text-center\">\n          <p className=\"text-desc font-medium text-brand-700\">Net weight</p>\n          <p className=\"mt-1 text-h1 font-bold text-brand-800 tabular\" aria-live=\"polite\">\n            {net.toFixed(3)} kg\n          </p>\n          <div className=\"mt-2 flex justify-center gap-4 text-desc text-brand-700/80 tabular\">\n            <span>Gross {gross.toFixed(3)} kg</span>\n            <span>Tare {tare.toFixed(3)} kg</span>\n          </div>\n          <p className=\"mt-3 inline-flex items-center gap-1.5 rounded-full bg-white/70 px-2.5 py-1 text-desc text-slate-600\">\n            <span className={`h-1.5 w-1.5 rounded-full ${live ? (scale.reading.stable ? 'bg-brand' : 'animate-pulse bg-amber-500') : 'bg-slate-400'}`} aria-hidden />\n            {live ? (scale.reading.stable ? 'Stable reading' : 'Settling') : 'Manual entry'}\n          </p>\n        </div>\n\n        <div className=\"mt-4 grid grid-cols-4 gap-2\">\n          <Button variant=\"secondary\" onClick={() => setGross(manualGross - STEP_KG)} disabled={live || manualGross <= 0} className=\"!px-2\">\n            <LuMinus aria-hidden /> 250 g\n          </Button>\n          <Button variant=\"secondary\" onClick={() => setGross(manualGross + STEP_KG)} disabled={live} className=\"!px-2\">\n            <LuPlus aria-hidden /> 250 g\n          </Button>\n          <Button variant=\"soft\" onClick={() => setTare(gross)} disabled={gross <= 0} className=\"!px-2\">\n            Tare\n          </Button>\n          <Button variant=\"ghost\" onClick={() => { setTare(0); if (!live) setGross(0); }} className=\"!px-2\">\n            Zero\n          </Button>\n        </div>\n\n        {!live ? (\n          <div className=\"mt-4\">\n            <label htmlFor=\"gross-weight\" className=\"label\">\n              Gross weight on platter (kg)\n            </label>\n            <input\n              id=\"gross-weight\"\n              inputMode=\"decimal\"\n              className=\"field tabular\"\n              placeholder=\"0.000\"\n              value={manualText}\n              onChange={(e) => {\n                const text = e.target.value.replace(/[^\\d.]/g, '');\n                setManualText(text);\n                setManualGross(roundQty(Number(text) || 0));\n              }}\n            />\n          </div>\n        ) : null}\n\n        {serialSupported && scale.status !== 'connected' ? (\n          <button\n            type=\"button\"\n            onClick={() => connectScale()}\n            className=\"mt-4 inline-flex items-center gap-1.5 text-desc font-semibold text-brand-700 hover:text-brand-800\"\n          >\n            <LuPlug aria-hidden /> Connect a USB or RS-232 scale\n          </button>\n        ) : null}\n        {scale.error ? <p className=\"mt-2 text-desc text-rose-600\">{scale.error}</p> : null}\n        {!serialSupported ? (\n          <p className=\"mt-4 flex items-center gap-1.5 text-desc text-slate-500\">\n            <LuScale aria-hidden /> Live scale readings need Chrome or Edge on a computer.\n          </p>\n        ) : null}\n      </div>\n    </Modal>\n  );\n}\n",
"client/src/components/charts/CategoryDensityChart.jsx": "import { useMemo, useState } from 'react';\nimport { useElementSize } from '../../hooks/useElementSize';\nimport { formatMoney } from '../../lib/format';\n\n/**\n * Every category in one screen, however many there are.\n *\n * Rows work up to ~40 categories. Past that the same data is drawn as a packed column grid —\n * one thin bar per category, sorted by revenue, with the previous period as a faint marker.\n * A thousand categories fit in a few hundred pixels instead of a thousand table rows.\n */\nexport function CategoryDensityChart({ rows: allRows, currency, height = 260 }) {\n  const [wrapRef, { width }] = useElementSize();\n  const [hover, setHover] = useState(null);\n\n  /*\n   * Categories with no sales in either period would render as a blank row each. At 1,000+ categories\n   * that is most of the chart, so they are counted in a footnote instead of drawn.\n   */\n  const rows = useMemo(() => allRows.filter((r) => r.revenue > 0 || r.prevRevenue > 0), [allRows]);\n  const idleCount = allRows.length - rows.length;\n\n  const max = Math.max(1, ...rows.map((r) => Math.max(r.revenue, r.prevRevenue)));\n  const dense = rows.length > 40;\n\n  const layout = useMemo(() => {\n    if (!dense || !width) return null;\n    const gap = 1;\n    const minBar = 2;\n    const perColumn = Math.max(1, Math.floor((width + gap) / (minBar + gap)));\n    const columns = Math.min(rows.length, perColumn);\n    const barW = Math.max(minBar, (width - (columns - 1) * gap) / columns - gap);\n    const rowsCount = Math.ceil(rows.length / columns);\n    const bandH = Math.min(64, Math.max(30, (height - 4) / rowsCount));\n    return { columns, barW: barW + gap, bandH, rowsCount };\n  }, [dense, width, rows.length, height]);\n\n  const Footnote = ({ children }) => (\n    <p className=\"mt-2 text-desc text-slate-400\">\n      {children}\n      {idleCount ? `${children ? ' ' : ''}${idleCount.toLocaleString('en-IN')} more had no sales in either period.` : ''}\n    </p>\n  );\n\n  if (!rows.length) {\n    return (\n      <div ref={wrapRef}>\n        <p className=\"py-6 text-center text-desc text-slate-500\">No category sold anything in this period.</p>\n      </div>\n    );\n  }\n\n  if (!dense) {\n    return (\n      <div ref={wrapRef}>\n      <ul className=\"space-y-1.5\">\n        {rows.map((r) => {\n          const pct = (r.revenue / max) * 100;\n          const prevPct = (r.prevRevenue / max) * 100;\n          return (\n            <li key={r.id} className=\"grid grid-cols-[minmax(96px,1.1fr)_3fr_auto] items-center gap-3\">\n              <span className=\"truncate text-desc text-slate-600\" title={r.parentName ? `${r.parentName} › ${r.name}` : r.name}>\n                {r.icon ? `${r.icon} ` : ''}\n                {r.name}\n              </span>\n              <span className=\"relative h-4 rounded-full bg-slate-100\">\n                <span className=\"absolute inset-y-0 left-0 rounded-full bg-brand\" style={{ width: `${pct}%` }} />\n                {r.prevRevenue > 0 ? (\n                  <span className=\"absolute inset-y-0 w-0.5 bg-slate-400\" style={{ left: `calc(${prevPct}% - 1px)` }} title={`Previous ${formatMoney(r.prevRevenue, currency)}`} />\n                ) : null}\n              </span>\n              <span className=\"w-20 text-right text-desc font-medium text-slate-800 tabular\">{formatMoney(r.revenue, currency)}</span>\n            </li>\n          );\n        })}\n      </ul>\n      <Footnote />\n      </div>\n    );\n  }\n\n  const totalHeight = layout ? layout.rowsCount * layout.bandH : height;\n\n  return (\n    <div ref={wrapRef} className=\"relative w-full\">\n      {layout ? (\n        <>\n          <svg\n            width={width}\n            height={totalHeight}\n            role=\"img\"\n            aria-label={`Revenue for ${rows.length} categories, highest first`}\n            onMouseLeave={() => setHover(null)}\n          >\n            {rows.map((r, i) => {\n              const col = i % layout.columns;\n              const row = Math.floor(i / layout.columns);\n              const track = layout.bandH - 5;\n              // Square-root scale: a long tail of small categories stays visible next to the leaders.\n              const barH = r.revenue > 0 ? Math.max(3, Math.sqrt(r.revenue / max) * track) : 0;\n              const prevH = r.prevRevenue > 0 ? Math.max(2, Math.sqrt(r.prevRevenue / max) * track) : 0;\n              const x = col * layout.barW;\n              const baseline = row * layout.bandH + layout.bandH - 3;\n              return (\n                <g key={r.id} onMouseEnter={() => setHover(i)}>\n                  <rect x={x} y={row * layout.bandH} width={layout.barW} height={layout.bandH} fill=\"transparent\" />\n                  <rect x={x} y={baseline - barH} width={Math.max(1.5, layout.barW - 1)} height={barH} rx=\"1\" fill={hover === i ? '#047857' : '#10B981'} />\n                  {prevH > 0.5 ? <rect x={x} y={baseline - prevH} width={Math.max(1.5, layout.barW - 1)} height={0.8} fill=\"#64748B\" opacity=\"0.75\" /> : null}\n                </g>\n              );\n            })}\n          </svg>\n          <Footnote>\n            {`${rows.length.toLocaleString('en-IN')} categories sold, highest first. Heights use a square-root scale so smaller categories stay visible; the grey tick marks the previous period.`}\n          </Footnote>\n        </>\n      ) : (\n        <div style={{ height }} />\n      )}\n\n      {hover !== null && layout ? (\n        <div\n          className=\"glass pointer-events-none absolute z-10 max-w-[220px] rounded-xl px-2.5 py-1.5 text-desc shadow-card\"\n          style={{\n            left: Math.min((hover % layout.columns) * layout.barW, Math.max(0, width - 220)),\n            top: Math.max(0, Math.floor(hover / layout.columns) * layout.bandH - 54),\n          }}\n        >\n          <p className=\"truncate font-semibold text-slate-800\">{rows[hover].name}</p>\n          {rows[hover].parentName ? <p className=\"truncate text-slate-500\">{rows[hover].parentName}</p> : null}\n          <p className=\"text-brand-700 tabular\">{formatMoney(rows[hover].revenue, currency)}</p>\n          <p className=\"text-slate-500 tabular\">was {formatMoney(rows[hover].prevRevenue, currency)}</p>\n        </div>\n      ) : null}\n    </div>\n  );\n}\n",
"client/src/components/charts/SplitBar.jsx": "import { formatMoney } from '../../lib/format';\n\nconst COLORS = { UPI: '#059669', CASH: '#0EA5E9', CARD: '#F59E0B' };\n\n/** Payment mix as a single stacked bar — one row instead of a pie that needs its own panel. */\nexport function SplitBar({ data, currency }) {\n  const total = data.reduce((s, d) => s + d.revenue, 0);\n  if (!total) return <p className=\"py-4 text-desc text-slate-500\">No payments in this period.</p>;\n\n  return (\n    <div>\n      <div className=\"flex h-3 w-full overflow-hidden rounded-full bg-slate-100\" role=\"img\" aria-label=\"Share of revenue by payment method\">\n        {data.map((d) =>\n          d.revenue > 0 ? <div key={d.method} style={{ width: `${(d.revenue / total) * 100}%`, background: COLORS[d.method] }} title={`${d.method}: ${formatMoney(d.revenue, currency)}`} /> : null,\n        )}\n      </div>\n      <ul className=\"mt-3 space-y-1.5\">\n        {data.map((d) => (\n          <li key={d.method} className=\"flex items-center gap-2 text-desc\">\n            <span className=\"h-2 w-2 shrink-0 rounded-full\" style={{ background: COLORS[d.method] }} aria-hidden />\n            <span className=\"flex-1 text-slate-600\">{d.method}</span>\n            <span className=\"text-slate-500 tabular\">{Math.round((d.revenue / total) * 100)}%</span>\n            <span className=\"w-20 text-right font-medium text-slate-800 tabular\">{formatMoney(d.revenue, currency)}</span>\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n",
"client/src/components/charts/TrendChart.jsx": "import { useMemo, useState } from 'react';\nimport { useElementSize } from '../../hooks/useElementSize';\nimport { formatCompactMoney, formatMoney } from '../../lib/format';\n\n/**\n * Revenue over time with the previous period behind it for comparison.\n * Bars for short periods (they read as discrete days/hours); a line once there are too many\n * buckets for bars to stay legible.\n */\nexport function TrendChart({ current, previous, currency, height = 200 }) {\n  const [wrapRef, { width }] = useElementSize();\n  const [hover, setHover] = useState(null);\n\n  const max = Math.max(1, ...current.map((d) => d.revenue), ...previous.map((d) => d.revenue));\n  const asLine = current.length > 45;\n  const padding = { top: 12, right: 8, bottom: 22, left: 46 };\n  const innerW = Math.max(40, width - padding.left - padding.right);\n  const innerH = height - padding.top - padding.bottom;\n  const step = innerW / Math.max(1, current.length);\n\n  const x = (i) => padding.left + step * (i + 0.5);\n  const y = (v) => padding.top + innerH - (v / max) * innerH;\n\n  const path = (series) =>\n    series.map((d, i) => `${i === 0 ? 'M' : 'L'} ${x(i).toFixed(1)} ${y(d.revenue).toFixed(1)}`).join(' ');\n\n  const ticks = useMemo(() => [0, max / 2, max], [max]);\n  const labelEvery = Math.ceil(current.length / Math.max(2, Math.floor(innerW / 64)));\n\n  return (\n    <div ref={wrapRef} className=\"relative w-full\">\n      {width > 0 ? (\n        <svg width={width} height={height} role=\"img\" aria-label={`Revenue trend across ${current.length} periods`} onMouseLeave={() => setHover(null)}>\n          {ticks.map((t, i) => (\n            <g key={i}>\n              <line x1={padding.left} x2={width - padding.right} y1={y(t)} y2={y(t)} stroke=\"#E2E8F0\" strokeDasharray={i === 0 ? '0' : '3 3'} />\n              <text x={padding.left - 8} y={y(t) + 4} textAnchor=\"end\" fontSize=\"10\" fill=\"#94A3B8\">\n                {formatCompactMoney(t, currency)}\n              </text>\n            </g>\n          ))}\n\n          {asLine ? (\n            <>\n              <path d={path(previous)} fill=\"none\" stroke=\"#CBD5E1\" strokeWidth=\"1.5\" />\n              <path d={path(current)} fill=\"none\" stroke=\"#059669\" strokeWidth=\"2\" strokeLinejoin=\"round\" />\n            </>\n          ) : (\n            current.map((d, i) => {\n              const barW = Math.max(3, Math.min(26, step * 0.56));\n              const prev = previous[i]?.revenue ?? 0;\n              return (\n                <g key={d.key}>\n                  {prev > 0 ? (\n                    <rect x={x(i) - barW / 2 - 2} y={y(prev)} width={barW} height={Math.max(1, innerH - (y(prev) - padding.top))} rx=\"3\" fill=\"#E2E8F0\" />\n                  ) : null}\n                  <rect\n                    x={x(i) - barW / 2 + 2}\n                    y={y(d.revenue)}\n                    width={barW}\n                    height={Math.max(d.revenue > 0 ? 2 : 0, innerH - (y(d.revenue) - padding.top))}\n                    rx=\"3\"\n                    fill={hover === i ? '#047857' : '#059669'}\n                  />\n                </g>\n              );\n            })\n          )}\n\n          {current.map((d, i) => (\n            <rect\n              key={`hit-${d.key}`}\n              x={padding.left + step * i}\n              y={padding.top}\n              width={step}\n              height={innerH}\n              fill=\"transparent\"\n              onMouseEnter={() => setHover(i)}\n            />\n          ))}\n\n          {hover !== null ? <line x1={x(hover)} x2={x(hover)} y1={padding.top} y2={padding.top + innerH} stroke=\"#059669\" strokeWidth=\"1\" strokeDasharray=\"3 3\" /> : null}\n\n          {current.map((d, i) =>\n            i % labelEvery === 0 ? (\n              <text key={`lbl-${d.key}`} x={x(i)} y={height - 6} textAnchor=\"middle\" fontSize=\"10\" fill=\"#94A3B8\">\n                {d.label}\n              </text>\n            ) : null,\n          )}\n        </svg>\n      ) : (\n        <div style={{ height }} />\n      )}\n\n      {hover !== null ? (\n        <div\n          className=\"glass pointer-events-none absolute top-1 rounded-xl px-2.5 py-1.5 text-desc shadow-card\"\n          style={{ left: Math.min(Math.max(0, x(hover) - 60), Math.max(0, width - 130)) }}\n        >\n          <p className=\"font-semibold text-slate-800\">{current[hover].label}</p>\n          <p className=\"text-brand-700 tabular\">{formatMoney(current[hover].revenue, currency)}</p>\n          <p className=\"text-slate-500 tabular\">was {formatMoney(previous[hover]?.revenue ?? 0, currency)}</p>\n          <p className=\"text-slate-500 tabular\">{current[hover].orders} bills</p>\n        </div>\n      ) : null}\n    </div>\n  );\n}\n",
"client/src/hooks/useApiQuery.js": "import { useCallback, useEffect, useRef, useState } from 'react';\nimport { api, errorMessage } from '../lib/api';\n\n/** GET with cancellation of stale requests; re-runs whenever `params` (serialised) changes. */\nexport function useApiQuery(url, params, { enabled = true } = {}) {\n  const [state, setState] = useState({ data: null, loading: enabled, error: null });\n  const controllerRef = useRef(null);\n  const key = JSON.stringify(params ?? {});\n\n  const run = useCallback(async () => {\n    controllerRef.current?.abort();\n    const controller = new AbortController();\n    controllerRef.current = controller;\n    setState((s) => ({ ...s, loading: true, error: null }));\n    try {\n      const { data } = await api.get(url, { params: JSON.parse(key), signal: controller.signal });\n      setState({ data, loading: false, error: null });\n    } catch (err) {\n      if (controller.signal.aborted) return;\n      setState((s) => ({ ...s, loading: false, error: errorMessage(err) }));\n    }\n  }, [url, key]);\n\n  useEffect(() => {\n    if (enabled) run();\n    return () => controllerRef.current?.abort();\n  }, [run, enabled]);\n\n  return { ...state, refetch: run };\n}\n",
"client/src/hooks/useBarcodeScanner.js": "import { useEffect, useRef } from 'react';\n\n/**\n * Keyboard-wedge barcode scanners \"type\" the code very fast and finish with Enter.\n * This listens globally so a scan works even when the search box isn't focused,\n * while ignoring normal human typing inside form fields.\n */\nexport function useBarcodeScanner(onScan, { enabled = true, minLength = 4, maxGapMs = 40 } = {}) {\n  const buffer = useRef('');\n  const lastTime = useRef(0);\n  const handler = useRef(onScan);\n  handler.current = onScan;\n\n  useEffect(() => {\n    if (!enabled) return undefined;\n    const onKeyDown = (e) => {\n      const target = e.target;\n      const typingInField = target instanceof HTMLElement && (target.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName));\n      if (typingInField || e.ctrlKey || e.metaKey || e.altKey) return;\n      if (document.querySelector('[role=\"dialog\"]')) return;\n\n      const now = performance.now();\n      if (now - lastTime.current > maxGapMs) buffer.current = '';\n      lastTime.current = now;\n\n      if (e.key === 'Enter') {\n        if (buffer.current.length >= minLength) {\n          e.preventDefault();\n          handler.current(buffer.current);\n        }\n        buffer.current = '';\n      } else if (e.key.length === 1) {\n        buffer.current += e.key;\n      }\n    };\n    window.addEventListener('keydown', onKeyDown);\n    return () => window.removeEventListener('keydown', onKeyDown);\n  }, [enabled, minLength, maxGapMs]);\n}\n",
"client/src/hooks/useBill.js": "import { useMemo } from 'react';\nimport { computeBill } from '../lib/pricing';\nimport { useCartStore } from '../store/cartStore';\nimport { useCatalogStore } from '../store/catalogStore';\n\nexport function useBill() {\n  const lines = useCartStore((s) => s.lines);\n  const billDiscount = useCartStore((s) => s.billDiscount);\n  const settings = useCatalogStore((s) => s.settings);\n  const taxRate = Number(settings?.taxRate ?? 0);\n  const bill = useMemo(() => computeBill({ items: lines, billDiscount, taxRate }), [lines, billDiscount, taxRate]);\n  const itemCount = lines.reduce((n, l) => n + (l.soldByWeight ? 1 : l.quantity), 0);\n  return { lines, billDiscount, bill, itemCount, settings, currency: settings?.currency || 'INR' };\n}\n",
"client/src/hooks/useDebounce.js": "import { useEffect, useState } from 'react';\n\nexport function useDebounce(value, delay = 200) {\n  const [debounced, setDebounced] = useState(value);\n  useEffect(() => {\n    const t = setTimeout(() => setDebounced(value), delay);\n    return () => clearTimeout(t);\n  }, [value, delay]);\n  return debounced;\n}\n",
"client/src/hooks/useElementSize.js": "import { useEffect, useRef, useState } from 'react';\n\nexport function useElementSize() {\n  const ref = useRef(null);\n  const [size, setSize] = useState({ width: 0, height: 0 });\n  useEffect(() => {\n    const el = ref.current;\n    if (!el) return undefined;\n    const observer = new ResizeObserver(([entry]) => {\n      const { width, height } = entry.contentRect;\n      setSize((prev) => (prev.width === Math.round(width) && prev.height === Math.round(height) ? prev : { width: Math.round(width), height: Math.round(height) }));\n    });\n    observer.observe(el);\n    return () => observer.disconnect();\n  }, []);\n  return [ref, size];\n}\n",
"client/src/hooks/useHotkeys.js": "import { useEffect, useRef } from 'react';\n\n/** Map of key (e.g. \"F2\", \"F8\") → handler. Ignored while a dialog is open. */\nexport function useHotkeys(map, enabled = true) {\n  const ref = useRef(map);\n  ref.current = map;\n  useEffect(() => {\n    if (!enabled) return undefined;\n    const onKey = (e) => {\n      const fn = ref.current[e.key];\n      if (!fn || document.querySelector('[role=\"dialog\"]')) return;\n      e.preventDefault();\n      fn(e);\n    };\n    window.addEventListener('keydown', onKey);\n    return () => window.removeEventListener('keydown', onKey);\n  }, [enabled]);\n}\n",
"client/src/store/authStore.js": "import { create } from 'zustand';\nimport { createJSONStorage, persist } from 'zustand/middleware';\nimport { api } from '../lib/api';\n\nexport const useAuthStore = create(\n  persist(\n    (set, get) => ({\n      token: null,\n      user: null,\n      organization: null,\n      subscription: null,\n      sessionMessage: null,\n\n      async login(email, password) {\n        const { data } = await api.post('/auth/login', { email, password }, { skipAuthHandling: true });\n        set({ token: data.token, user: data.user, organization: data.organization ?? null, sessionMessage: null });\n        get().refreshSubscription();\n        return data.user;\n      },\n\n      /** Create a store and its first admin, then sign straight in. */\n      async signup(details) {\n        const { data } = await api.post('/public/signup', details, { skipAuthHandling: true });\n        set({\n          token: data.token,\n          user: data.user,\n          organization: data.organization,\n          subscription: data.subscription,\n          sessionMessage: null,\n        });\n        return data.user;\n      },\n\n      async refreshSubscription() {\n        if (!get().token) return null;\n        try {\n          const { data } = await api.get('/billing/subscription');\n          set({ subscription: data.subscription, paymentsEnabled: data.paymentsEnabled });\n          return data.subscription;\n        } catch {\n          return null;\n        }\n      },\n\n      /** Refresh the profile when online; offline terminals keep their cached session so selling continues. */\n      async refreshProfile() {\n        if (!get().token || !navigator.onLine) return;\n        try {\n          const { data } = await api.get('/auth/me');\n          set({ user: data.user, organization: data.organization ?? get().organization });\n          get().refreshSubscription();\n        } catch {\n          /* 401s are handled by the API interceptor; network errors keep the cached session */\n        }\n      },\n\n      logout(message = null) {\n        // Deliberately does NOT clear the IndexedDB outbox: unsynced bills upload after the next sign-in.\n        set({ token: null, user: null, organization: null, subscription: null, sessionMessage: message });\n      },\n    }),\n    {\n      name: 'ff_auth',\n      storage: createJSONStorage(() => localStorage),\n      partialize: (s) => ({ token: s.token, user: s.user, organization: s.organization, subscription: s.subscription }),\n    },\n  ),\n);\n\nexport const selectIsAdmin = (s) => s.user?.role === 'ADMIN';\n",
"client/src/store/cartStore.js": "import { create } from 'zustand';\nimport { createJSONStorage, persist } from 'zustand/middleware';\nimport { idb } from '../lib/idb';\nimport { uuid } from '../lib/ids';\nimport { roundQty } from '../lib/pricing';\n\nconst EMPTY_DISCOUNT = { type: 'PERCENT', value: 0, reason: '' };\n\nconst lineFromProduct = (product, quantity) => ({\n  lineId: uuid(),\n  productId: product.id,\n  code: product.code,\n  name: product.name,\n  unit: product.unit,\n  soldByWeight: product.soldByWeight,\n  unitPrice: product.price,\n  discountPercent: product.discountPercent || 0,\n  imageUrl: product.imageUrl,\n  categoryId: product.categoryId,\n  quantity,\n});\n\nexport const useCartStore = create(\n  persist(\n    (set, get) => ({\n      lines: [],\n      billDiscount: EMPTY_DISCOUNT,\n      lastAddedLineId: null,\n      heldBills: [],\n\n      /** Piece items merge into one line; each weighing becomes its own line (like a printed scale label). */\n      addProduct(product, quantity = 1) {\n        const qty = roundQty(quantity);\n        if (qty <= 0) return;\n        const lines = get().lines;\n        if (!product.soldByWeight) {\n          const existing = lines.find((l) => l.productId === product.id);\n          if (existing) {\n            set({ lines: lines.map((l) => (l.lineId === existing.lineId ? { ...l, quantity: l.quantity + qty } : l)), lastAddedLineId: existing.lineId });\n            return;\n          }\n        }\n        const line = lineFromProduct(product, qty);\n        set({ lines: [line, ...lines], lastAddedLineId: line.lineId });\n      },\n\n      setQuantity(lineId, quantity) {\n        const qty = roundQty(quantity);\n        if (qty <= 0) return get().removeLine(lineId);\n        set({ lines: get().lines.map((l) => (l.lineId === lineId ? { ...l, quantity: qty } : l)) });\n      },\n\n      removeLine(lineId) {\n        set({ lines: get().lines.filter((l) => l.lineId !== lineId) });\n      },\n\n      setBillDiscount(discount) {\n        set({ billDiscount: { ...EMPTY_DISCOUNT, ...discount } });\n      },\n\n      clear() {\n        set({ lines: [], billDiscount: EMPTY_DISCOUNT, lastAddedLineId: null });\n      },\n\n      async loadHeldBills() {\n        const bills = await idb.getAll('heldBills').catch(() => []);\n        set({ heldBills: bills.sort((a, b) => b.heldAt - a.heldAt) });\n      },\n\n      async holdCurrent(label) {\n        const { lines, billDiscount } = get();\n        if (!lines.length) return null;\n        const bill = { id: uuid(), label: label?.trim() || `Bill ${new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}`, lines, billDiscount, heldAt: Date.now() };\n        await idb.put('heldBills', bill);\n        get().clear();\n        await get().loadHeldBills();\n        return bill;\n      },\n\n      /** Resume a parked bill. If a bill is in progress, it is parked first so nothing is lost. */\n      async resumeHeld(id) {\n        const bill = get().heldBills.find((b) => b.id === id);\n        if (!bill) return;\n        if (get().lines.length) await get().holdCurrent('Swapped bill');\n        await idb.delete('heldBills', id);\n        set({ lines: bill.lines, billDiscount: bill.billDiscount || EMPTY_DISCOUNT, lastAddedLineId: null });\n        await get().loadHeldBills();\n      },\n\n      async discardHeld(id) {\n        await idb.delete('heldBills', id);\n        await get().loadHeldBills();\n      },\n    }),\n    {\n      name: 'ff_cart',\n      storage: createJSONStorage(() => localStorage),\n      partialize: (s) => ({ lines: s.lines, billDiscount: s.billDiscount }),\n    },\n  ),\n);\n",
"client/src/store/catalogStore.js": "import { create } from 'zustand';\nimport { api, errorMessage } from '../lib/api';\nimport { idb } from '../lib/idb';\nimport { roundQty } from '../lib/pricing';\n\nconst CACHE_KEY = 'catalog-v1';\n\nfunction indexProducts(products) {\n  const byBarcode = new Map();\n  const byCode = new Map();\n  for (const p of products) {\n    if (p.barcode) byBarcode.set(p.barcode, p);\n    byCode.set(p.code.toLowerCase(), p);\n  }\n  return { byBarcode, byCode };\n}\n\nexport const useCatalogStore = create((set, get) => ({\n  products: [],\n  categories: [],\n  settings: null,\n  status: 'idle', // idle | loading | ready | error\n  source: null, // network | cache\n  error: null,\n  loadedAt: null,\n  _index: { byBarcode: new Map(), byCode: new Map() },\n\n  /** Network first; fall back to the last snapshot in IndexedDB so the register keeps working offline. */\n  async load({ silent = false } = {}) {\n    if (!silent) set({ status: get().products.length ? 'ready' : 'loading', error: null });\n    try {\n      const [products, categories, settings] = await Promise.all([\n        api.get('/products/catalog'),\n        api.get('/categories'),\n        api.get('/settings'),\n      ]);\n      const snapshot = {\n        products: products.data.products,\n        categories: categories.data.categories,\n        settings: settings.data.settings,\n        loadedAt: Date.now(),\n      };\n      set({ ...snapshot, _index: indexProducts(snapshot.products), status: 'ready', source: 'network', error: null });\n      idb.put('cache', snapshot, CACHE_KEY).catch(() => {});\n    } catch (err) {\n      const cached = await idb.get('cache', CACHE_KEY).catch(() => null);\n      if (cached) {\n        set({ ...cached, _index: indexProducts(cached.products), status: 'ready', source: 'cache', error: errorMessage(err) });\n      } else {\n        set({ status: 'error', error: errorMessage(err) });\n      }\n    }\n  },\n\n  /** Exact lookup for scanners and typed codes: barcode, product code, or \"#101\". */\n  lookup(input) {\n    const term = String(input || '').trim().replace(/^#/, '');\n    if (!term) return null;\n    const { byBarcode, byCode } = get()._index;\n    return byBarcode.get(term) || byCode.get(term.toLowerCase()) || null;\n  },\n\n  /** Reflect a sale locally so stock badges stay honest while offline. */\n  applySale(lines) {\n    const sold = new Map();\n    lines.forEach((l) => sold.set(l.productId, (sold.get(l.productId) || 0) + l.quantity));\n    const products = get().products.map((p) => (sold.has(p.id) ? { ...p, stock: roundQty(p.stock - sold.get(p.id)) } : p));\n    set({ products, _index: indexProducts(products) });\n    idb.put('cache', { products, categories: get().categories, settings: get().settings, loadedAt: get().loadedAt }, CACHE_KEY).catch(() => {});\n  },\n}));\n",
"client/src/store/hardwareStore.js": "/**\n * Web Serial integrations for RS-232/USB weighing scales and ESC/POS receipt printers.\n * Web Serial needs Chrome/Edge on desktop and a secure context (https:// or localhost).\n */\nimport { create } from 'zustand';\n\nconst hasSerial = typeof navigator !== 'undefined' && 'serial' in navigator;\n\n// Handles common continuous-output formats, e.g. \"ST,GS,+  1.250kg\", \"US,NT, 0.845 kg\", \"  1250 g\".\nexport function parseScaleLine(line) {\n  const match = line.match(/([-+]?\\s*\\d+(?:\\.\\d+)?)\\s*(kg|g|lb)?/i);\n  if (!match) return null;\n  let value = Number(match[1].replace(/\\s/g, ''));\n  const unit = (match[2] || 'kg').toLowerCase();\n  if (unit === 'g') value /= 1000;\n  if (unit === 'lb') value *= 0.45359237;\n  if (!Number.isFinite(value)) return null;\n  return { kg: Math.round(value * 1000) / 1000, stable: !/\\bUS\\b|unstable/i.test(line) };\n}\n\nlet scaleReader = null;\n\nexport const useHardwareStore = create((set, get) => ({\n  serialSupported: hasSerial,\n  scale: { port: null, status: 'disconnected', reading: null, error: null, baudRate: 9600 },\n  printer: { port: null, status: 'disconnected', error: null, baudRate: 9600 },\n\n  async connectScale(baudRate = get().scale.baudRate) {\n    if (!hasSerial) return;\n    try {\n      const port = await navigator.serial.requestPort();\n      await port.open({ baudRate });\n      set({ scale: { ...get().scale, port, baudRate, status: 'connected', error: null } });\n      get()._readScale(port);\n    } catch (err) {\n      if (err.name !== 'NotFoundError') set({ scale: { ...get().scale, status: 'error', error: err.message } });\n    }\n  },\n\n  async _readScale(port) {\n    const decoder = new TextDecoderStream();\n    const closed = port.readable.pipeTo(decoder.writable).catch(() => {});\n    scaleReader = decoder.readable.getReader();\n    let buffer = '';\n    try {\n      for (;;) {\n        const { value, done } = await scaleReader.read();\n        if (done) break;\n        buffer += value;\n        const parts = buffer.split(/\\r?\\n|\\r/);\n        buffer = parts.pop();\n        for (const line of parts) {\n          const reading = parseScaleLine(line);\n          if (reading) set({ scale: { ...get().scale, reading: { ...reading, at: Date.now() } } });\n        }\n      }\n    } catch (err) {\n      set({ scale: { ...get().scale, status: 'error', error: err.message } });\n    } finally {\n      scaleReader?.releaseLock();\n      await closed;\n    }\n  },\n\n  async disconnectScale() {\n    const { port } = get().scale;\n    try {\n      await scaleReader?.cancel();\n      await port?.close();\n    } catch {\n      /* port already closed */\n    }\n    scaleReader = null;\n    set({ scale: { ...get().scale, port: null, status: 'disconnected', reading: null } });\n  },\n\n  async connectPrinter(baudRate = get().printer.baudRate) {\n    if (!hasSerial) return;\n    try {\n      const port = await navigator.serial.requestPort();\n      await port.open({ baudRate });\n      set({ printer: { ...get().printer, port, baudRate, status: 'connected', error: null } });\n    } catch (err) {\n      if (err.name !== 'NotFoundError') set({ printer: { ...get().printer, status: 'error', error: err.message } });\n    }\n  },\n\n  async disconnectPrinter() {\n    try {\n      await get().printer.port?.close();\n    } catch {\n      /* already closed */\n    }\n    set({ printer: { ...get().printer, port: null, status: 'disconnected' } });\n  },\n\n  async printBytes(bytes) {\n    const { port } = get().printer;\n    if (!port?.writable) throw new Error('Connect a receipt printer first');\n    const writer = port.writable.getWriter();\n    try {\n      await writer.write(bytes);\n    } finally {\n      writer.releaseLock();\n    }\n  },\n}));\n",
"client/src/store/syncStore.js": "import { create } from 'zustand';\n\nexport const useSyncStore = create((set) => ({\n  online: typeof navigator === 'undefined' ? true : navigator.onLine,\n  serverReachable: true,\n  syncing: false,\n  pendingCount: 0,\n  failedCount: 0,\n  entries: [],\n  lastSyncAt: null,\n  lastError: null,\n  set: (patch) => set(patch),\n}));\n\nexport const selectConnection = (s) => {\n  if (!s.online) return 'offline';\n  if (!s.serverReachable) return 'unreachable';\n  return 'online';\n};\n",
"client/src/store/toastStore.js": "import { create } from 'zustand';\n\nlet nextId = 1;\n\nexport const useToastStore = create((set, get) => ({\n  toasts: [],\n  push(message, tone = 'neutral', duration = 3200) {\n    const id = nextId++;\n    set({ toasts: [...get().toasts.slice(-3), { id, message, tone }] });\n    setTimeout(() => get().dismiss(id), duration);\n    return id;\n  },\n  dismiss(id) {\n    set({ toasts: get().toasts.filter((t) => t.id !== id) });\n  },\n}));\n\nexport const toast = {\n  info: (m) => useToastStore.getState().push(m, 'neutral'),\n  success: (m) => useToastStore.getState().push(m, 'success'),\n  error: (m) => useToastStore.getState().push(m, 'error', 5000),\n  warn: (m) => useToastStore.getState().push(m, 'warn', 4500),\n};\n",
"client/src/lib/api.js": "import axios from 'axios';\n\nexport const api = axios.create({\n  baseURL: import.meta.env.VITE_API_URL || '/api',\n  timeout: 15000,\n});\n\nlet getToken = () => null;\nlet onUnauthorized = () => {};\n\n/** Wired up in main.jsx so this module doesn't import the auth store (avoids a circular import). */\nexport function configureApi(handlers) {\n  getToken = handlers.getToken;\n  onUnauthorized = handlers.onUnauthorized;\n}\n\napi.interceptors.request.use((config) => {\n  const token = getToken();\n  if (token) config.headers.Authorization = `Bearer ${token}`;\n  return config;\n});\n\napi.interceptors.response.use(\n  (response) => response,\n  (error) => {\n    const status = error.response?.status;\n    const code = error.response?.data?.error?.code;\n    if (status === 401 && !error.config?.skipAuthHandling) onUnauthorized(code);\n    return Promise.reject(error);\n  },\n);\n\nexport const isNetworkError = (err) => Boolean(err) && !err.response && !axios.isCancel(err);\n\nexport function errorMessage(err, fallback = 'Something went wrong. Try again.') {\n  if (!err) return fallback;\n  if (axios.isCancel(err)) return 'Request cancelled';\n  if (isNetworkError(err)) return 'Cannot reach the server. Check the connection and try again.';\n  return err.response?.data?.error?.message || err.message || fallback;\n}\n",
"client/src/lib/checkout.js": "import { formatDateTime, formatQuantity, invoiceLabel } from './format';\nimport { terminalId, uuid } from './ids';\nimport { computeBill, fromPaise } from './pricing';\nimport { enqueueBill, flushOutbox } from './sync';\n\nconst WAIT_FOR_INVOICE_MS = 6000;\n\nexport function buildReceipt({ payload, bill, lines, settings, cashierName, invoiceNo }) {\n  const cgst = Math.floor(bill.taxTotal / 2);\n  return {\n    clientId: payload.clientId,\n    invoiceNo,\n    pending: invoiceNo == null,\n    reference: invoiceNo != null ? invoiceLabel(invoiceNo) : `Ref ${payload.clientId.slice(0, 8).toUpperCase()}`,\n    soldAt: payload.soldAt,\n    dateLabel: formatDateTime(payload.soldAt),\n    cashierName,\n    terminalId: payload.terminalId,\n    paymentMethod: payload.paymentMethod,\n    amountTendered: payload.amountTendered,\n    changeDue: payload.amountTendered != null ? Math.max(0, payload.amountTendered - fromPaise(bill.grandTotal)) : null,\n    customerPhone: payload.customerPhone,\n    store: settings,\n    lines: bill.lines.map((line, i) => ({\n      name: lines[i].name,\n      quantityLabel: formatQuantity(line.quantity, lines[i].unit, lines[i].soldByWeight),\n      unitPrice: Number(line.unitPrice),\n      discountPercent: line.discountPercent,\n      amount: fromPaise(line.lineSubtotal - line.lineDiscount),\n    })),\n    totals: {\n      subtotal: fromPaise(bill.subtotal),\n      itemDiscount: fromPaise(bill.itemDiscount),\n      billDiscount: fromPaise(bill.billDiscount),\n      discountTotal: fromPaise(bill.discountTotal),\n      taxRate: bill.taxRate,\n      taxableAmount: fromPaise(bill.taxableAmount),\n      cgst: fromPaise(cgst),\n      sgst: fromPaise(bill.taxTotal - cgst),\n      taxTotal: fromPaise(bill.taxTotal),\n      grandTotal: fromPaise(bill.grandTotal),\n    },\n  };\n}\n\n/**\n * Complete a sale: persist the bill to the IndexedDB outbox first, then try to upload it.\n * The sale is final as soon as it is in the outbox — the receipt shows a provisional reference\n * until the server assigns an invoice number.\n */\nexport async function completeSale({ lines, billDiscount, settings, user, paymentMethod, amountTendered, customerPhone }) {\n  const taxRate = Number(settings?.taxRate ?? 0);\n  const bill = computeBill({ items: lines, billDiscount, taxRate });\n  const hasBillDiscount = bill.billDiscount > 0;\n\n  const payload = {\n    clientId: uuid(),\n    terminalId: terminalId(),\n    cashierId: user.id,\n    soldAt: new Date().toISOString(),\n    paymentMethod,\n    customerPhone: customerPhone?.trim() || null,\n    amountTendered: paymentMethod === 'CASH' && amountTendered !== '' && amountTendered != null ? Math.round(Number(amountTendered) * 100) / 100 : null,\n    taxRate,\n    billDiscount: hasBillDiscount\n      ? { type: billDiscount.type, value: Number(billDiscount.value), reason: billDiscount.reason?.trim() || null }\n      : { type: 'PERCENT', value: 0 },\n    grandTotal: fromPaise(bill.grandTotal),\n    wasOffline: !navigator.onLine,\n    items: lines.map((l) => ({\n      productId: l.productId,\n      quantity: l.quantity,\n      unitPrice: Number(l.unitPrice),\n      discountPercent: Number(l.discountPercent || 0),\n    })),\n  };\n\n  await enqueueBill(payload);\n\n  const synced = await Promise.race([\n    flushOutbox(),\n    new Promise((resolve) => setTimeout(() => resolve([]), WAIT_FOR_INVOICE_MS)),\n  ]);\n  const result = synced.find((r) => r.clientId === payload.clientId);\n\n  return buildReceipt({ payload, bill, lines, settings, cashierName: user.name, invoiceNo: result?.invoiceNo ?? null });\n}\n\nexport function receiptToWhatsAppText(r) {\n  const cur = (n) => `Rs.${Number(n).toFixed(2)}`;\n  const rows = r.lines.map((l) => `${l.name}\\n  ${l.quantityLabel} x ${cur(l.unitPrice)} = ${cur(l.amount)}`);\n  return [\n    `*${r.store?.storeName ?? 'Receipt'}*`,\n    `${r.reference}, ${r.dateLabel}`,\n    '',\n    ...rows,\n    '',\n    `Subtotal: ${cur(r.totals.subtotal)}`,\n    r.totals.discountTotal ? `You saved: ${cur(r.totals.discountTotal)}` : null,\n    `GST ${r.totals.taxRate}%: ${cur(r.totals.taxTotal)}`,\n    `*Total: ${cur(r.totals.grandTotal)}* (${r.paymentMethod})`,\n    '',\n    r.store?.receiptFooter || 'Thank you for shopping with us.',\n  ]\n    .filter((x) => x !== null)\n    .join('\\n');\n}\n\nexport function whatsappLink(phone, text) {\n  let digits = String(phone || '').replace(/\\D/g, '');\n  if (digits.length === 10) digits = `91${digits}`;\n  return `https://wa.me/${digits}?text=${encodeURIComponent(text)}`;\n}\n",
"client/src/lib/dates.js": "const pad = (n) => String(n).padStart(2, '0');\n\nexport const localIsoDate = (d = new Date()) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;\n\nexport function addDays(iso, n) {\n  const [y, m, d] = iso.split('-').map(Number);\n  const date = new Date(Date.UTC(y, m - 1, d + n));\n  return date.toISOString().slice(0, 10);\n}\n\nexport function presetRange(preset) {\n  const today = localIsoDate();\n  switch (preset) {\n    case 'yesterday':\n      return { from: addDays(today, -1), to: addDays(today, -1) };\n    case '7d':\n      return { from: addDays(today, -6), to: today };\n    case '30d':\n      return { from: addDays(today, -29), to: today };\n    case '90d':\n      return { from: addDays(today, -89), to: today };\n    default:\n      return { from: today, to: today };\n  }\n}\n\nconst MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\nexport const shortDate = (iso) => `${Number(iso.slice(8, 10))} ${MONTHS[Number(iso.slice(5, 7)) - 1]} ${iso.slice(0, 4)}`;\n\nexport function describeRange(from, to) {\n  return from === to ? shortDate(from) : `${shortDate(from)} – ${shortDate(to)}`;\n}\n",
"client/src/lib/escpos.js": "/**\n * Minimal ESC/POS encoder for 80 mm (48-column) thermal printers connected over Web Serial / USB-serial.\n * Only ASCII is sent; the rupee sign is written as \"Rs.\" since most printer code pages lack it.\n */\nconst ESC = 0x1b;\nconst GS = 0x1d;\nconst COLS = 48;\n\nconst ascii = (text) => String(text).normalize('NFKD').replace(/₹/g, 'Rs.').replace(/[^\\x20-\\x7E]/g, '');\n\nexport class EscPosBuilder {\n  constructor() {\n    this.bytes = [ESC, 0x40]; // initialise printer\n  }\n  raw(...b) { this.bytes.push(...b); return this; }\n  align(where) { return this.raw(ESC, 0x61, { left: 0, center: 1, right: 2 }[where] ?? 0); }\n  bold(on) { return this.raw(ESC, 0x45, on ? 1 : 0); }\n  doubleHeight(on) { return this.raw(GS, 0x21, on ? 0x01 : 0x00); }\n  text(line = '') { for (const ch of ascii(line)) this.bytes.push(ch.charCodeAt(0)); return this.raw(0x0a); }\n  rule(char = '-') { return this.text(char.repeat(COLS)); }\n  pair(left, right) {\n    const l = ascii(left);\n    const r = ascii(right);\n    const space = Math.max(1, COLS - l.length - r.length);\n    return this.text(`${l.slice(0, COLS - r.length - 1)}${' '.repeat(space)}${r}`);\n  }\n  feed(lines = 3) { return this.raw(ESC, 0x64, lines); }\n  cut() { return this.raw(GS, 0x56, 0x42, 0x00); }\n  build() { return new Uint8Array(this.bytes); }\n}\n\nconst rs = (n) => `Rs.${Number(n).toFixed(2)}`;\n\nexport function receiptToEscPos(receipt) {\n  const { store, lines, totals } = receipt;\n  const p = new EscPosBuilder().align('center').bold(true).doubleHeight(true).text(store.storeName).doubleHeight(false).bold(false);\n  if (store.address) p.text(store.address);\n  if (store.gstin) p.text(`GSTIN ${store.gstin}`);\n  if (store.phone) p.text(`Ph ${store.phone}`);\n  p.align('left').rule();\n  p.pair(receipt.reference, receipt.dateLabel);\n  p.text(`Cashier ${receipt.cashierName}   ${receipt.terminalId}`);\n  p.rule();\n  for (const line of lines) {\n    p.text(line.name.slice(0, COLS));\n    p.pair(`  ${line.quantityLabel} x ${rs(line.unitPrice)}${line.discountPercent ? ` (-${line.discountPercent}%)` : ''}`, rs(line.amount));\n  }\n  p.rule();\n  p.pair('Subtotal', rs(totals.subtotal));\n  if (totals.discountTotal) p.pair('Discounts', `-${rs(totals.discountTotal)}`);\n  p.pair(`CGST ${totals.taxRate / 2}%`, rs(totals.cgst));\n  p.pair(`SGST ${totals.taxRate / 2}%`, rs(totals.sgst));\n  p.bold(true).pair('TOTAL', rs(totals.grandTotal)).bold(false);\n  p.pair(`Paid by ${receipt.paymentMethod}`, receipt.amountTendered ? rs(receipt.amountTendered) : rs(totals.grandTotal));\n  if (receipt.changeDue) p.pair('Change', rs(receipt.changeDue));\n  p.rule().align('center');\n  if (store.receiptFooter) p.text(store.receiptFooter);\n  if (receipt.pending) p.text('Bill saved offline - syncs automatically');\n  return p.feed(4).cut().build();\n}\n",
"client/src/lib/format.js": "const currencyFormatters = new Map();\n\nexport function formatMoney(value, currency = 'INR') {\n  if (!currencyFormatters.has(currency)) {\n    currencyFormatters.set(currency, new Intl.NumberFormat('en-IN', { style: 'currency', currency, minimumFractionDigits: 2, maximumFractionDigits: 2 }));\n  }\n  return currencyFormatters.get(currency).format(Number(value || 0));\n}\n\nconst compactFormatters = new Map();\nexport function formatCompactMoney(value, currency = 'INR') {\n  if (!compactFormatters.has(currency)) {\n    compactFormatters.set(currency, new Intl.NumberFormat('en-IN', { style: 'currency', currency, notation: 'compact', maximumFractionDigits: 1 }));\n  }\n  return compactFormatters.get(currency).format(Number(value || 0));\n}\n\nconst numberFmt = new Intl.NumberFormat('en-IN', { maximumFractionDigits: 3 });\nexport const formatNumber = (n) => numberFmt.format(Number(n || 0));\n\nexport function formatQuantity(quantity, unit, soldByWeight) {\n  if (soldByWeight) return `${Number(quantity).toFixed(3)} ${unit}`;\n  return `${formatNumber(quantity)} ${unit}`;\n}\n\nexport function formatPercentChange(current, previous) {\n  if (!previous) return current ? { label: 'New', direction: 'up' } : { label: '0%', direction: 'flat' };\n  const change = ((current - previous) / previous) * 100;\n  const rounded = Math.abs(change) >= 100 ? Math.round(change) : Math.round(change * 10) / 10;\n  return { label: `${rounded > 0 ? '+' : ''}${rounded}%`, direction: rounded > 0 ? 'up' : rounded < 0 ? 'down' : 'flat', value: change };\n}\n\nconst dateTimeFmt = new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });\nexport const formatDateTime = (d) => dateTimeFmt.format(new Date(d));\n\nconst timeFmt = new Intl.DateTimeFormat('en-IN', { hour: '2-digit', minute: '2-digit' });\nexport const formatTime = (d) => timeFmt.format(new Date(d));\n\nexport const invoiceLabel = (invoiceNo) => `INV-${String(invoiceNo).padStart(6, '0')}`;\n\nexport function relativeTime(ms) {\n  if (!ms) return 'never';\n  const seconds = Math.round((Date.now() - ms) / 1000);\n  if (seconds < 10) return 'just now';\n  if (seconds < 60) return `${seconds}s ago`;\n  const minutes = Math.round(seconds / 60);\n  if (minutes < 60) return `${minutes} min ago`;\n  const hours = Math.round(minutes / 60);\n  if (hours < 24) return `${hours} h ago`;\n  return formatDateTime(ms);\n}\n",
"client/src/lib/idb.js": "/**\n * Minimal promise wrapper over IndexedDB.\n * Stores:\n *   outbox     – bills waiting to upload (keyPath clientId)\n *   heldBills  – parked carts on this terminal (keyPath id)\n *   cache      – catalog / categories / settings snapshots for offline selling\n * Writes resolve only after the IDB transaction commits, so a resolved write survives a crash.\n */\nconst DB_NAME = 'freshflow-pos';\nconst DB_VERSION = 1;\n\nlet dbPromise = null;\n\nfunction openDb() {\n  if (!('indexedDB' in window)) return Promise.reject(new Error('This browser does not support offline storage'));\n  if (!dbPromise) {\n    dbPromise = new Promise((resolve, reject) => {\n      const request = indexedDB.open(DB_NAME, DB_VERSION);\n      request.onupgradeneeded = () => {\n        const db = request.result;\n        if (!db.objectStoreNames.contains('outbox')) {\n          db.createObjectStore('outbox', { keyPath: 'clientId' }).createIndex('createdAt', 'createdAt');\n        }\n        if (!db.objectStoreNames.contains('heldBills')) db.createObjectStore('heldBills', { keyPath: 'id' });\n        if (!db.objectStoreNames.contains('cache')) db.createObjectStore('cache');\n      };\n      request.onsuccess = () => {\n        const db = request.result;\n        db.onversionchange = () => db.close();\n        resolve(db);\n      };\n      request.onerror = () => {\n        dbPromise = null;\n        reject(request.error);\n      };\n    });\n  }\n  return dbPromise;\n}\n\nfunction run(storeName, mode, operation) {\n  return openDb().then(\n    (db) =>\n      new Promise((resolve, reject) => {\n        const tx = db.transaction(storeName, mode);\n        const request = operation(tx.objectStore(storeName));\n        let result;\n        if (request) request.onsuccess = () => { result = request.result; };\n        tx.oncomplete = () => resolve(result);\n        tx.onerror = () => reject(tx.error);\n        tx.onabort = () => reject(tx.error || new Error('Storage transaction aborted'));\n      }),\n  );\n}\n\nexport const idb = {\n  get: (store, key) => run(store, 'readonly', (os) => os.get(key)),\n  getAll: (store) => run(store, 'readonly', (os) => os.getAll()),\n  put: (store, value, key) => run(store, 'readwrite', (os) => (key === undefined ? os.put(value) : os.put(value, key))),\n  delete: (store, key) => run(store, 'readwrite', (os) => os.delete(key)),\n  count: (store) => run(store, 'readonly', (os) => os.count()),\n};\n",
"client/src/lib/ids.js": "/** RFC 4122 v4 UUID. crypto.randomUUID only exists on HTTPS/localhost; LAN terminals over http need the fallback. */\nexport function uuid() {\n  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();\n  const bytes = crypto.getRandomValues(new Uint8Array(16));\n  bytes[6] = (bytes[6] & 0x0f) | 0x40;\n  bytes[8] = (bytes[8] & 0x3f) | 0x80;\n  const hex = [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');\n  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;\n}\n\nconst TERMINAL_KEY = 'ff_terminal_id';\n\n/** Stable per-device register id, e.g. \"T-8K2Q\". */\nexport function terminalId() {\n  let id = localStorage.getItem(TERMINAL_KEY);\n  if (!id) {\n    const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n    const random = crypto.getRandomValues(new Uint8Array(4));\n    id = `T-${[...random].map((b) => alphabet[b % alphabet.length]).join('')}`;\n    localStorage.setItem(TERMINAL_KEY, id);\n  }\n  return id;\n}\n",
"client/src/lib/pricing.js": "// Mirrors server/src/utils/pricing.js exactly — keep both files identical.\n/**\n * Bill calculation engine — shared verbatim by the POS client (client/src/lib/pricing.js)\n * and the API, so a bill rung up offline recomputes to the exact same paise on the server.\n *\n * Order of operations (mirrors the store blueprint):\n *   line subtotal → automatic line markdown → bill discount (allocated across lines) → GST on the remainder\n *\n * All money is handled as integer paise; quantities are rounded to 3 decimals (grams).\n */\n\nexport const toPaise = (rupees) => Math.round(Number(rupees || 0) * 100);\nexport const fromPaise = (paise) => Math.round(paise) / 100;\nexport const roundQty = (qty) => Math.round(Number(qty || 0) * 1000) / 1000;\n\nconst clamp = (n, min, max) => Math.min(max, Math.max(min, Number.isFinite(n) ? n : 0));\n\n/** Split `total` across `weights` proportionally using the largest-remainder method (sums exactly). */\nexport function allocate(total, weights) {\n  const sum = weights.reduce((a, b) => a + b, 0);\n  if (total <= 0 || sum <= 0) return weights.map(() => 0);\n  const raw = weights.map((w) => (total * w) / sum);\n  const floors = raw.map(Math.floor);\n  let remainder = total - floors.reduce((a, b) => a + b, 0);\n  const order = raw\n    .map((r, i) => [r - floors[i], i])\n    .sort((a, b) => b[0] - a[0] || a[1] - b[1]);\n  for (let k = 0; k < order.length && remainder > 0; k += 1, remainder -= 1) {\n    floors[order[k][1]] += 1;\n  }\n  return floors;\n}\n\n/**\n * @param {object} input\n * @param {Array<{quantity:number, unitPrice:number, discountPercent?:number}>} input.items\n * @param {{type:'PERCENT'|'FLAT', value:number}} [input.billDiscount]\n * @param {number} input.taxRate  e.g. 5 for 5% GST\n */\nexport function computeBill({ items, billDiscount, taxRate }) {\n  const lines = items.map((item) => {\n    const quantity = roundQty(item.quantity);\n    const unitPaise = toPaise(item.unitPrice);\n    const discountPercent = clamp(Number(item.discountPercent || 0), 0, 100);\n    const lineSubtotal = Math.round(unitPaise * quantity);\n    const lineDiscount = Math.round((lineSubtotal * discountPercent) / 100);\n    return { ...item, quantity, discountPercent, lineSubtotal, lineDiscount, afterMarkdown: lineSubtotal - lineDiscount };\n  });\n\n  const subtotal = lines.reduce((s, l) => s + l.lineSubtotal, 0);\n  const itemDiscount = lines.reduce((s, l) => s + l.lineDiscount, 0);\n  const afterMarkdowns = subtotal - itemDiscount;\n\n  const type = billDiscount?.type === 'FLAT' ? 'FLAT' : 'PERCENT';\n  const value = Math.max(0, Number(billDiscount?.value || 0));\n  const billDiscountPaise =\n    type === 'PERCENT'\n      ? Math.round((afterMarkdowns * clamp(value, 0, 100)) / 100)\n      : Math.min(afterMarkdowns, toPaise(value));\n\n  const shares = allocate(billDiscountPaise, lines.map((l) => l.afterMarkdown));\n  const finalLines = lines.map((l, i) => ({\n    ...l,\n    billDiscountShare: shares[i],\n    netAmount: l.afterMarkdown - shares[i],\n  }));\n\n  const rate = clamp(Number(taxRate || 0), 0, 100);\n  const taxableAmount = afterMarkdowns - billDiscountPaise;\n  const taxTotal = Math.round((taxableAmount * rate) / 100);\n  const grandTotal = taxableAmount + taxTotal;\n\n  return {\n    lines: finalLines,\n    subtotal,\n    itemDiscount,\n    billDiscount: billDiscountPaise,\n    afterMarkdowns,\n    discountTotal: itemDiscount + billDiscountPaise,\n    billDiscountEffectivePct: afterMarkdowns > 0 ? (billDiscountPaise / afterMarkdowns) * 100 : 0,\n    taxRate: rate,\n    taxableAmount,\n    taxTotal,\n    grandTotal,\n  };\n}\n",
"client/src/lib/razorpay.js": "const SCRIPT_SRC = 'https://checkout.razorpay.com/v1/checkout.js';\nlet loader = null;\n\n/** Load Razorpay's hosted checkout once, on demand. */\nexport function loadRazorpay() {\n  if (window.Razorpay) return Promise.resolve(window.Razorpay);\n  if (!loader) {\n    loader = new Promise((resolve, reject) => {\n      const script = document.createElement('script');\n      script.src = SCRIPT_SRC;\n      script.async = true;\n      script.onload = () => resolve(window.Razorpay);\n      script.onerror = () => {\n        loader = null;\n        reject(new Error('Could not load the payment window. Check your connection and try again.'));\n      };\n      document.head.appendChild(script);\n    });\n  }\n  return loader;\n}\n\n/**\n * Open Razorpay checkout for an order created by the API.\n * Resolves with the handover fields, which the API verifies before changing the plan.\n */\nexport async function openCheckout({ order, customer, description }) {\n  const Razorpay = await loadRazorpay();\n  return new Promise((resolve, reject) => {\n    const checkout = new Razorpay({\n      key: order.keyId,\n      order_id: order.orderId,\n      amount: order.amount,\n      currency: order.currency,\n      name: customer?.storeName || 'FreshFlow POS',\n      description,\n      theme: { color: '#059669' },\n      prefill: { name: customer?.name, email: customer?.email, contact: customer?.phone },\n      handler: (response) => resolve(response),\n      modal: {\n        ondismiss: () => reject(Object.assign(new Error('Payment window closed before paying'), { dismissed: true })),\n      },\n    });\n    checkout.on('payment.failed', (event) => {\n      reject(new Error(event?.error?.description || 'The payment did not go through'));\n    });\n    checkout.open();\n  });\n}\n",
"client/src/lib/sync.js": "/**\n * Outbox sync engine.\n *\n * Every completed bill is written to IndexedDB first (durable), then uploaded. This single path\n * handles both online and offline selling: if the upload fails for a transient reason (no network,\n * server down, expired session) the bill stays queued and retries on reconnect, on an interval, and\n * when the tab regains focus. The server de-duplicates by clientId, so retries never double-count.\n */\nimport { api, errorMessage, isNetworkError } from './api';\nimport { idb } from './idb';\nimport { useSyncStore } from '../store/syncStore';\n\nconst STORE = 'outbox';\nconst BATCH_SIZE = 25;\nconst RETRY_INTERVAL_MS = 30_000;\n\nlet inFlight = null;\nlet started = false;\nconst listeners = new Set();\n\n/** Subscribe to per-bill results as they sync (used to show invoice numbers on receipts). */\nexport function onBillSynced(fn) {\n  listeners.add(fn);\n  return () => listeners.delete(fn);\n}\n\nexport async function refreshOutboxState() {\n  try {\n    const entries = await idb.getAll(STORE);\n    entries.sort((a, b) => a.createdAt - b.createdAt);\n    useSyncStore.getState().set({\n      entries,\n      pendingCount: entries.filter((e) => e.status === 'pending').length,\n      failedCount: entries.filter((e) => e.status === 'failed').length,\n    });\n  } catch (err) {\n    useSyncStore.getState().set({ lastError: err.message });\n  }\n}\n\nexport async function enqueueBill(payload) {\n  await idb.put(STORE, { clientId: payload.clientId, payload, status: 'pending', attempts: 0, lastError: null, createdAt: Date.now() });\n  await refreshOutboxState();\n}\n\nasync function uploadPending() {\n  const store = useSyncStore.getState();\n  const pending = (await idb.getAll(STORE)).filter((e) => e.status === 'pending').sort((a, b) => a.createdAt - b.createdAt);\n  const synced = [];\n  if (!pending.length) return synced;\n\n  store.set({ syncing: true });\n  try {\n    for (let i = 0; i < pending.length; i += BATCH_SIZE) {\n      const batch = pending.slice(i, i + BATCH_SIZE);\n      let response;\n      try {\n        response = await api.post('/transactions/sync', { transactions: batch.map((e) => e.payload) }, { timeout: 30_000 });\n      } catch (err) {\n        const status = err.response?.status;\n        const transient = isNetworkError(err) || status === 401 || status === 408 || status === 429 || status >= 500;\n        const message = errorMessage(err);\n        await Promise.all(\n          batch.map((e) => idb.put(STORE, { ...e, attempts: e.attempts + 1, lastError: message, status: transient ? 'pending' : 'failed' })),\n        );\n        store.set({ lastError: message, serverReachable: !isNetworkError(err) });\n        if (transient) break; // stop; try again later in order\n        continue;\n      }\n\n      store.set({ serverReachable: true, lastError: null });\n      for (const result of response.data.results) {\n        const entry = batch.find((e) => e.clientId === result.clientId);\n        if (!entry) continue;\n        if (result.status === 'created' || result.status === 'duplicate') {\n          await idb.delete(STORE, entry.clientId);\n          synced.push(result);\n        } else {\n          await idb.put(STORE, { ...entry, status: 'failed', attempts: entry.attempts + 1, lastError: result.error?.message || 'Rejected by the server' });\n        }\n      }\n      store.set({ lastSyncAt: Date.now() });\n    }\n  } finally {\n    store.set({ syncing: false });\n    await refreshOutboxState();\n  }\n  return synced;\n}\n\n/** Upload queued bills now. Concurrent callers (and other open tabs) share one run. */\nexport function flushOutbox() {\n  if (inFlight) return inFlight;\n  const run = async () => {\n    if (!navigator.onLine) {\n      await refreshOutboxState();\n      return [];\n    }\n    return navigator.locks?.request ? navigator.locks.request('freshflow-outbox', uploadPending) : uploadPending();\n  };\n  inFlight = run()\n    .then((synced) => {\n      synced.forEach((r) => listeners.forEach((fn) => fn(r)));\n      return synced;\n    })\n    .catch((err) => {\n      useSyncStore.getState().set({ lastError: err.message, syncing: false });\n      return [];\n    })\n    .finally(() => {\n      inFlight = null;\n    });\n  return inFlight;\n}\n\nexport async function retryBill(clientId) {\n  const entry = await idb.get(STORE, clientId);\n  if (entry) await idb.put(STORE, { ...entry, status: 'pending', lastError: null });\n  await refreshOutboxState();\n  return flushOutbox();\n}\n\nexport async function discardBill(clientId) {\n  await idb.delete(STORE, clientId);\n  await refreshOutboxState();\n}\n\nasync function pingServer() {\n  try {\n    await api.get('/health', { timeout: 5000, skipAuthHandling: true });\n    useSyncStore.getState().set({ serverReachable: true });\n    return true;\n  } catch (err) {\n    useSyncStore.getState().set({ serverReachable: !isNetworkError(err) && err.response?.status < 500 });\n    return false;\n  }\n}\n\nexport function startSyncEngine() {\n  if (started) return;\n  started = true;\n  const store = useSyncStore.getState();\n\n  window.addEventListener('online', async () => {\n    store.set({ online: true });\n    if (await pingServer()) flushOutbox();\n  });\n  window.addEventListener('offline', () => store.set({ online: false }));\n  document.addEventListener('visibilitychange', () => {\n    if (document.visibilityState === 'visible') flushOutbox();\n  });\n  setInterval(async () => {\n    if (!navigator.onLine) return;\n    const reachable = await pingServer();\n    if (reachable && useSyncStore.getState().pendingCount > 0) flushOutbox();\n  }, RETRY_INTERVAL_MS);\n\n  refreshOutboxState().then(() => flushOutbox());\n}\n",
"client/src/lib/upi.js": "/** Build a UPI deep link (NPCI \"upi://pay\" spec) that any UPI app can scan. */\nexport function buildUpiUri({ vpa, payeeName, amount, reference, note }) {\n  const params = new URLSearchParams({\n    pa: vpa,\n    pn: payeeName || 'Store',\n    am: Number(amount).toFixed(2),\n    cu: 'INR',\n  });\n  if (note) params.set('tn', note.slice(0, 50));\n  if (reference) params.set('tr', reference.slice(0, 35));\n  // URLSearchParams encodes spaces as \"+\", which some UPI apps show literally.\n  return `upi://pay?${params.toString().replace(/\\+/g, '%20')}`;\n}\n",
"client/src/pages/BillingPage.jsx": "import { useEffect, useState } from 'react';\nimport { useOutletContext, useSearchParams } from 'react-router-dom';\nimport { LuCircleCheck, LuCreditCard, LuTriangleAlert } from 'react-icons/lu';\nimport { SyncPill } from '../components/layout/AppShell';\nimport { IntervalToggle, PlanCard, SeatStepper } from '../components/pricing/PricingPlans';\nimport { Button } from '../components/ui/Button';\nimport { ErrorState, Spinner } from '../components/ui/States';\nimport { useApiQuery } from '../hooks/useApiQuery';\nimport { api, errorMessage } from '../lib/api';\nimport { formatDateTime, formatMoney } from '../lib/format';\nimport { openCheckout } from '../lib/razorpay';\nimport { useAuthStore } from '../store/authStore';\nimport { toast } from '../store/toastStore';\n\nconst STATUS_COPY = {\n  TRIALING: { tone: 'bg-brand-50 text-brand-800', label: 'Free trial' },\n  ACTIVE: { tone: 'bg-brand-50 text-brand-800', label: 'Active' },\n  PAST_DUE: { tone: 'bg-amber-50 text-amber-800', label: 'Payment due' },\n  CANCELLED: { tone: 'bg-slate-100 text-slate-700', label: 'Cancelled' },\n  EXPIRED: { tone: 'bg-rose-50 text-rose-700', label: 'Ended' },\n};\n\nexport default function BillingPage() {\n  const { openSync } = useOutletContext();\n  const [params] = useSearchParams();\n  const user = useAuthStore((s) => s.user);\n  const organization = useAuthStore((s) => s.organization);\n  const refreshSubscription = useAuthStore((s) => s.refreshSubscription);\n\n  const plans = useApiQuery('/public/plans', null);\n  const subscription = useApiQuery('/billing/subscription', null);\n  const payments = useApiQuery('/billing/payments', null);\n\n  const [interval, setIntervalValue] = useState(params.get('interval') === 'YEARLY' ? 'YEARLY' : 'MONTHLY');\n  const [seats, setSeats] = useState(Number(params.get('seats')) || 3);\n  const [busyTier, setBusyTier] = useState(null);\n  const [error, setError] = useState(null);\n\n  const current = subscription.data?.subscription;\n  const paymentsEnabled = subscription.data?.paymentsEnabled;\n\n  useEffect(() => {\n    if (current && !params.get('seats')) setSeats(Math.max(current.seatsUsed, current.seats || 3));\n  }, [current, params]);\n\n  const pay = async (tier) => {\n    setError(null);\n    setBusyTier(tier);\n    try {\n      const { data: order } = await api.post('/billing/checkout', { plan: tier, interval, seats });\n      const handover = await openCheckout({\n        order,\n        customer: { name: user?.name, email: user?.email, storeName: organization?.name },\n        description: `${tier === 'STANDARD' ? 'Standard' : 'Custom'} plan, ${seats} user${seats === 1 ? '' : 's'}`,\n      });\n      await api.post('/billing/verify', handover);\n      toast.success('Payment received. Your plan is active.');\n      subscription.refetch();\n      payments.refetch();\n      refreshSubscription();\n    } catch (err) {\n      if (err?.dismissed) toast.info('Payment cancelled. Nothing was charged.');\n      else setError(errorMessage(err));\n    } finally {\n      setBusyTier(null);\n    }\n  };\n\n  const status = STATUS_COPY[current?.status] ?? STATUS_COPY.EXPIRED;\n\n  return (\n    <div className=\"scroll-thin h-full overflow-y-auto\">\n      <header className=\"sticky top-0 z-20 border-b border-slate-200/70 bg-slate-50/85 px-4 pb-3 pt-4 backdrop-blur-xl sm:px-6\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"min-w-0 flex-1\">\n            <h1>Billing</h1>\n            <p className=\"truncate text-desc text-slate-500\">{organization?.name}</p>\n          </div>\n          <SyncPill onClick={openSync} />\n        </div>\n      </header>\n\n      <div className=\"mx-auto max-w-5xl space-y-4 px-4 py-4 sm:px-6\">\n        {subscription.loading && !current ? <Spinner label=\"Loading your plan\" /> : null}\n        {subscription.error ? <ErrorState message={subscription.error} onRetry={subscription.refetch} /> : null}\n\n        {current ? (\n          <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n            <div className=\"flex flex-wrap items-start gap-3\">\n              <div className=\"min-w-0 flex-1\">\n                <div className=\"flex items-center gap-2\">\n                  <h2>{current.planName}</h2>\n                  <span className={`rounded-full px-2 py-0.5 text-desc font-semibold ${status.tone}`}>{status.label}</span>\n                </div>\n                <p className=\"mt-1 text-desc text-slate-500\">\n                  {current.active\n                    ? `${current.isTrial ? 'Free until' : 'Renews on'} ${current.renewsOn ? formatDateTime(current.renewsOn).split(',')[0] : '—'}, ${current.daysLeft} day${current.daysLeft === 1 ? '' : 's'} left`\n                    : 'Choose a plan below to carry on using the register.'}\n                </p>\n              </div>\n              <div className=\"grid grid-cols-2 gap-3 sm:grid-cols-3\">\n                <div className=\"rounded-2xl bg-slate-50 px-3 py-2\">\n                  <p className=\"text-desc text-slate-500\">Seats used</p>\n                  <p className=\"font-semibold tabular\">\n                    {current.seatsUsed} / {current.seats}\n                  </p>\n                </div>\n                <div className=\"rounded-2xl bg-slate-50 px-3 py-2\">\n                  <p className=\"text-desc text-slate-500\">Per user</p>\n                  <p className=\"font-semibold tabular\">{formatMoney(current.pricePerUser, current.currency)}</p>\n                </div>\n                <div className=\"col-span-2 rounded-2xl bg-slate-50 px-3 py-2 sm:col-span-1\">\n                  <p className=\"text-desc text-slate-500\">Billing</p>\n                  <p className=\"font-semibold\">{current.interval === 'YEARLY' ? 'Yearly' : 'Monthly'}</p>\n                </div>\n              </div>\n            </div>\n\n            {!current.active ? (\n              <p className=\"mt-3 flex items-start gap-2 rounded-2xl bg-amber-50 p-3 text-desc text-amber-800\">\n                <LuTriangleAlert className=\"mt-0.5 shrink-0\" aria-hidden />\n                New products, categories and staff accounts are paused until you pick a plan. Bills taken on a till still\n                upload, and all your data is exactly where you left it.\n              </p>\n            ) : null}\n            {current.seatsLeft === 0 && current.active ? (\n              <p className=\"mt-3 flex items-start gap-2 rounded-2xl bg-slate-50 p-3 text-desc text-slate-600\">\n                <LuCircleCheck className=\"mt-0.5 shrink-0 text-brand\" aria-hidden />\n                Every seat on your plan is in use. Add seats below to invite more staff.\n              </p>\n            ) : null}\n          </section>\n        ) : null}\n\n        {!paymentsEnabled && current ? (\n          <p className=\"rounded-2xl bg-slate-100 px-4 py-3 text-desc text-slate-600\">\n            Online payment is not switched on for this deployment yet. Add your Razorpay keys to the server environment\n            (<span className=\"font-mono\">RAZORPAY_KEY_ID</span> and <span className=\"font-mono\">RAZORPAY_KEY_SECRET</span>) to accept payments here.\n          </p>\n        ) : null}\n\n        <section>\n          <div className=\"flex flex-col items-start gap-3 sm:flex-row sm:items-center sm:justify-between\">\n            <div>\n              <h2>Choose a plan</h2>\n              <p className=\"text-desc text-slate-500\">Priced per staff account. You pay only for active people.</p>\n            </div>\n            <div className=\"flex flex-wrap items-center gap-3\">\n              <IntervalToggle interval={interval} onChange={setIntervalValue} />\n              <SeatStepper seats={seats} onChange={setSeats} min={Math.max(1, current?.seatsUsed ?? 1)} label=\"Seats\" />\n            </div>\n          </div>\n\n          {error ? <p className=\"mt-3 rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">{error}</p> : null}\n\n          <div className=\"mt-4 grid gap-4 lg:grid-cols-2\">\n            {(plans.data?.plans ?? []).map((plan) => (\n              <PlanCard\n                key={plan.tier}\n                plan={plan}\n                interval={interval}\n                seats={seats}\n                currency={current?.currency}\n                highlight={plan.tier === 'STANDARD'}\n                currentLabel={current?.plan === plan.tier && current?.interval === interval ? 'Current plan' : null}\n                busy={busyTier === plan.tier}\n                cta={paymentsEnabled ? `Pay ${formatMoney(plan.intervals[interval].price * seats * (interval === 'YEARLY' ? 12 : 1))}` : 'Payments not set up'}\n                onSelect={paymentsEnabled ? pay : undefined}\n              />\n            ))}\n          </div>\n          <p className=\"mt-3 text-desc text-slate-500\">\n            Payments are handled by Razorpay. Prices exclude GST. Yearly plans are charged twelve months up front.\n          </p>\n        </section>\n\n        <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n          <h2>Payment history</h2>\n          {payments.data?.payments?.length ? (\n            <ul className=\"mt-3 divide-y divide-slate-100\">\n              {payments.data.payments.map((p) => (\n                <li key={p.id} className=\"flex items-center gap-3 py-2.5\">\n                  <LuCreditCard className=\"shrink-0 text-slate-400\" aria-hidden />\n                  <div className=\"min-w-0 flex-1\">\n                    <p className=\"truncate font-medium\">\n                      {p.plan === 'CUSTOM' ? 'Custom' : 'Standard'}, {p.seats} user{p.seats === 1 ? '' : 's'}, {p.interval === 'YEARLY' ? 'yearly' : 'monthly'}\n                    </p>\n                    <p className=\"truncate text-desc text-slate-500\">\n                      {formatDateTime(p.createdAt)} · {p.reference}\n                    </p>\n                  </div>\n                  <span className=\"font-semibold tabular\">{formatMoney(p.amount, p.currency)}</span>\n                  <span\n                    className={`rounded-full px-2 py-0.5 text-desc font-medium ${\n                      p.status === 'PAID' ? 'bg-brand-50 text-brand-700' : p.status === 'FAILED' ? 'bg-rose-50 text-rose-700' : 'bg-slate-100 text-slate-600'\n                    }`}\n                  >\n                    {p.status === 'PAID' ? 'Paid' : p.status === 'FAILED' ? 'Failed' : 'Started'}\n                  </span>\n                </li>\n              ))}\n            </ul>\n          ) : (\n            <p className=\"mt-2 text-desc text-slate-500\">No payments yet. Your free trial does not need one.</p>\n          )}\n        </section>\n      </div>\n    </div>\n  );\n}\n",
"client/src/pages/InventoryPage.jsx": "import { useState } from 'react';\nimport { useOutletContext } from 'react-router-dom';\nimport { LuLayers, LuPackagePlus, LuPencil, LuSearch, LuBoxes } from 'react-icons/lu';\nimport { SyncPill } from '../components/layout/AppShell';\nimport { CategoryManager } from '../components/admin/CategoryManager';\nimport { ProductForm } from '../components/admin/ProductForm';\nimport { StockAdjustModal } from '../components/admin/StockAdjustModal';\nimport { Button } from '../components/ui/Button';\nimport { Pagination } from '../components/ui/Pagination';\nimport { Segmented } from '../components/ui/Segmented';\nimport { EmptyState, ErrorState, Spinner } from '../components/ui/States';\nimport { useApiQuery } from '../hooks/useApiQuery';\nimport { useDebounce } from '../hooks/useDebounce';\nimport { formatMoney, formatNumber } from '../lib/format';\nimport { useCatalogStore } from '../store/catalogStore';\n\nexport default function InventoryPage() {\n  const { openSync } = useOutletContext();\n  const { categories, settings, load: reloadCatalog } = useCatalogStore();\n  const currency = settings?.currency || 'INR';\n\n  const [search, setSearch] = useState('');\n  const [stock, setStock] = useState('all');\n  const [categoryId, setCategoryId] = useState('');\n  const [page, setPage] = useState(1);\n  const q = useDebounce(search, 250);\n\n  const { data, loading, error, refetch } = useApiQuery('/products', { q, stock, categoryId, page, pageSize: 20, status: 'all', sort: 'name' });\n  const [editing, setEditing] = useState(null);\n  const [creating, setCreating] = useState(false);\n  const [adjusting, setAdjusting] = useState(null);\n  const [managingCategories, setManagingCategories] = useState(false);\n\n  const refresh = () => {\n    refetch();\n    reloadCatalog({ silent: true });\n  };\n\n  const rows = data?.products ?? [];\n\n  return (\n    <div className=\"scroll-thin h-full overflow-y-auto\">\n      <header className=\"sticky top-0 z-20 border-b border-slate-200/70 bg-slate-50/85 px-4 pb-3 pt-4 backdrop-blur-xl sm:px-6\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"min-w-0 flex-1\">\n            <h1>Inventory</h1>\n            <p className=\"truncate text-desc text-slate-500\">Catalog and stock levels</p>\n          </div>\n          <SyncPill onClick={openSync} />\n          <Button size=\"sm\" variant=\"secondary\" onClick={() => setManagingCategories(true)}>\n            <LuLayers aria-hidden /> <span className=\"hidden sm:inline\">Categories</span>\n          </Button>\n          <Button size=\"sm\" onClick={() => setCreating(true)}>\n            <LuPackagePlus aria-hidden /> <span className=\"hidden sm:inline\">Add product</span>\n          </Button>\n        </div>\n\n        <div className=\"mt-3 flex flex-wrap items-center gap-2\">\n          <div className=\"relative min-w-[190px] flex-1\">\n            <LuSearch className=\"pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400\" aria-hidden />\n            <input className=\"field h-9 pl-9\" placeholder=\"Search by name, code or barcode\" value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} aria-label=\"Search products\" />\n          </div>\n          <select className=\"field h-9 w-auto py-0\" value={categoryId} onChange={(e) => { setCategoryId(e.target.value); setPage(1); }} aria-label=\"Filter by category\">\n            <option value=\"\">All categories</option>\n            {categories.map((c) => (\n              <option key={c.id} value={c.id}>\n                {c.parentId ? '— ' : ''}\n                {c.name}\n              </option>\n            ))}\n          </select>\n          <Segmented\n            size=\"sm\"\n            ariaLabel=\"Stock filter\"\n            value={stock}\n            onChange={(v) => { setStock(v); setPage(1); }}\n            options={[\n              { value: 'all', label: 'All' },\n              { value: 'low', label: 'Low' },\n              { value: 'out', label: 'Out' },\n            ]}\n          />\n        </div>\n      </header>\n\n      <div className=\"px-4 py-4 sm:px-6\">\n        {loading && !data ? <Spinner /> : null}\n        {error ? <ErrorState message={error} onRetry={refetch} /> : null}\n        {data && !rows.length ? (\n          <EmptyState icon={LuBoxes} title=\"No products here\" description=\"Try another search or filter, or add a new product.\" action={<Button size=\"sm\" onClick={() => setCreating(true)}>Add product</Button>} />\n        ) : null}\n\n        {rows.length ? (\n          <>\n          {/* Phones get cards; the table needs more width than a phone has. */}\n          <ul className=\"space-y-2 md:hidden\">\n            {rows.map((p) => {\n              const low = p.stock > 0 && p.stock <= p.lowStockThreshold;\n              const out = p.stock <= 0;\n              return (\n                <li key={p.id} className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03]\">\n                  <div className=\"flex items-start gap-3\">\n                    <div className=\"min-w-0 flex-1\">\n                      <p className=\"truncate font-semibold text-slate-900\">\n                        {p.name}\n                        {!p.isActive ? <span className=\"ml-2 rounded-full bg-slate-100 px-1.5 py-0.5 text-desc text-slate-500\">Hidden</span> : null}\n                      </p>\n                      <p className=\"truncate text-desc text-slate-400 tabular\">\n                        #{p.code}\n                        {p.categoryName ? ` · ${p.categoryName}` : ''}\n                      </p>\n                    </div>\n                    <span className=\"shrink-0 font-semibold tabular\">\n                      {formatMoney(p.price, currency)}\n                      <span className=\"text-desc font-normal text-slate-400\">/{p.unit}</span>\n                    </span>\n                  </div>\n                  <div className=\"mt-3 flex items-center gap-2\">\n                    <span className={`rounded-full px-2.5 py-1 text-desc font-medium tabular ${out ? 'bg-rose-50 text-rose-700' : low ? 'bg-amber-50 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>\n                      {formatNumber(p.stock)} {p.unit} {out ? 'out of stock' : low ? 'left, low' : 'in stock'}\n                    </span>\n                    <div className=\"flex-1\" />\n                    <Button size=\"sm\" variant=\"soft\" onClick={() => setAdjusting(p)}>\n                      Stock\n                    </Button>\n                    <Button size=\"iconSm\" variant=\"ghost\" aria-label={`Edit ${p.name}`} onClick={() => setEditing(p)}>\n                      <LuPencil aria-hidden />\n                    </Button>\n                  </div>\n                </li>\n              );\n            })}\n            {data.total > data.pageSize ? <Pagination page={data.page} pageSize={data.pageSize} total={data.total} onPage={setPage} /> : null}\n          </ul>\n\n          <div className=\"hidden overflow-x-auto rounded-3xl bg-white p-2 shadow-card ring-1 ring-slate-900/[0.03] md:block sm:p-4\">\n            <table className=\"w-full min-w-[680px] border-collapse\">\n              <thead>\n                <tr className=\"border-b border-slate-100 text-left text-desc text-slate-500\">\n                  <th className=\"py-2 pr-3 font-medium\">Product</th>\n                  <th className=\"py-2 pr-3 font-medium\">Category</th>\n                  <th className=\"py-2 pr-3 text-right font-medium\">Price</th>\n                  <th className=\"py-2 pr-3 text-right font-medium\">Stock</th>\n                  <th className=\"py-2 pr-3 text-right font-medium\">Stock value</th>\n                  <th className=\"py-2 w-24\" aria-label=\"Actions\" />\n                </tr>\n              </thead>\n              <tbody>\n                {rows.map((p) => {\n                  const low = p.stock > 0 && p.stock <= p.lowStockThreshold;\n                  const out = p.stock <= 0;\n                  return (\n                    <tr key={p.id} className=\"border-b border-slate-50 text-body\">\n                      <td className=\"max-w-[240px] py-2.5 pr-3\">\n                        <p className=\"truncate font-medium text-slate-800\">\n                          {p.name}\n                          {!p.isActive ? <span className=\"ml-2 rounded-full bg-slate-100 px-1.5 py-0.5 text-desc text-slate-500\">Hidden</span> : null}\n                        </p>\n                        <p className=\"text-desc text-slate-400 tabular\">\n                          #{p.code}\n                          {p.barcode ? ` · ${p.barcode}` : ''}\n                          {p.discountPercent > 0 ? ` · ${formatNumber(p.discountPercent)}% markdown` : ''}\n                        </p>\n                      </td>\n                      <td className=\"max-w-[150px] truncate py-2.5 pr-3 text-desc text-slate-500\">{p.categoryName}</td>\n                      <td className=\"py-2.5 pr-3 text-right tabular\">\n                        {formatMoney(p.price, currency)}\n                        <span className=\"text-desc text-slate-400\">/{p.unit}</span>\n                      </td>\n                      <td className={`py-2.5 pr-3 text-right font-medium tabular ${out ? 'text-rose-600' : low ? 'text-amber-600' : 'text-slate-700'}`}>\n                        {formatNumber(p.stock)} <span className=\"text-desc font-normal text-slate-400\">{p.unit}</span>\n                      </td>\n                      <td className=\"py-2.5 pr-3 text-right tabular\">{formatMoney(Math.max(0, p.stock) * p.price, currency)}</td>\n                      <td className=\"py-2.5\">\n                        <div className=\"flex justify-end gap-1\">\n                          <Button size=\"sm\" variant=\"soft\" onClick={() => setAdjusting(p)}>\n                            Stock\n                          </Button>\n                          <Button size=\"iconSm\" variant=\"ghost\" aria-label={`Edit ${p.name}`} onClick={() => setEditing(p)}>\n                            <LuPencil aria-hidden />\n                          </Button>\n                        </div>\n                      </td>\n                    </tr>\n                  );\n                })}\n              </tbody>\n            </table>\n            {data.total > data.pageSize ? <Pagination page={data.page} pageSize={data.pageSize} total={data.total} onPage={setPage} /> : null}\n          </div>\n          </>\n        ) : null}\n      </div>\n\n      <ProductForm open={creating} product={null} categories={categories} onClose={() => setCreating(false)} onSaved={refresh} />\n      <ProductForm open={Boolean(editing)} product={editing} categories={categories} onClose={() => setEditing(null)} onSaved={refresh} />\n      <StockAdjustModal product={adjusting} onClose={() => setAdjusting(null)} onSaved={refresh} />\n      <CategoryManager\n        open={managingCategories}\n        onClose={() => setManagingCategories(false)}\n        categories={categories}\n        onChanged={() => reloadCatalog({ silent: true })}\n      />\n    </div>\n  );\n}\n",
"client/src/pages/LandingPage.jsx": "import { Link } from 'react-router-dom';\nimport {\n  LuChartColumn, LuCloudUpload, LuLeaf, LuPackage, LuQrCode, LuScale, LuScanBarcode, LuUsers, LuWifiOff,\n} from 'react-icons/lu';\nimport { Button } from '../components/ui/Button';\nimport { useAuthStore } from '../store/authStore';\n\nconst FEATURES = [\n  { icon: LuScanBarcode, title: 'Fast register', body: 'Scan a barcode or type a code and the item is on the bill. Quick codes for what sells all day.' },\n  { icon: LuWifiOff, title: 'Sells without internet', body: 'Bills are saved on the till and upload themselves when the connection returns. Nothing is lost.' },\n  { icon: LuScale, title: 'Loose produce', body: 'Weighing scales over USB, with tare and manual entry when the scale is busy elsewhere.' },\n  { icon: LuQrCode, title: 'UPI, cash and card', body: 'A UPI QR is generated for the exact bill amount. Cash tendering works out the change for you.' },\n  { icon: LuPackage, title: 'Stock that stays honest', body: 'Every sale, return and delivery moves stock and is recorded in the ledger with a reason.' },\n  { icon: LuChartColumn, title: 'Know your day', body: 'Revenue, baskets, categories and products, always compared with the period before.' },\n];\n\nexport default function LandingPage() {\n  const token = useAuthStore((s) => s.token);\n\n  return (\n    <div className=\"min-h-[100dvh] bg-white\">\n      <header className=\"sticky top-0 z-30 border-b border-slate-200/70 bg-white/85 backdrop-blur-xl\">\n        <nav className=\"mx-auto flex h-16 max-w-6xl items-center gap-3 px-4 sm:px-6\">\n          <Link to=\"/\" className=\"flex items-center gap-2\">\n            <span className=\"grid h-9 w-9 place-items-center rounded-2xl bg-brand text-white\">\n              <LuLeaf size={18} aria-hidden />\n            </span>\n            <span className=\"text-h2 font-semibold\">FreshFlow</span>\n          </Link>\n          <div className=\"flex-1\" />\n          <Link to=\"/pricing\" className=\"hidden px-3 text-body font-medium text-slate-600 hover:text-slate-900 sm:block\">\n            Pricing\n          </Link>\n          {token ? (\n            <Link to=\"/app\">\n              <Button size=\"sm\">Open register</Button>\n            </Link>\n          ) : (\n            <>\n              <Link to=\"/login\" className=\"px-3 text-body font-medium text-slate-600 hover:text-slate-900\">\n                Sign in\n              </Link>\n              <Link to=\"/signup\">\n                <Button size=\"sm\">Start free</Button>\n              </Link>\n            </>\n          )}\n        </nav>\n      </header>\n\n      <section className=\"relative overflow-hidden\">\n        <div className=\"absolute inset-x-0 top-0 h-[420px] bg-gradient-to-b from-brand-50 to-white\" aria-hidden />\n        <div className=\"relative mx-auto max-w-6xl px-4 pb-16 pt-14 sm:px-6 sm:pt-20\">\n          <div className=\"max-w-2xl\">\n            <span className=\"inline-flex items-center gap-1.5 rounded-full bg-white px-3 py-1 text-desc font-semibold text-brand-700 shadow-card\">\n              <LuLeaf aria-hidden /> Built for grocery and kirana stores\n            </span>\n            <h1 className=\"mt-4 text-h1 font-bold leading-7 text-slate-900\">\n              The till that keeps selling when the internet does not.\n            </h1>\n            <p className=\"mt-3 max-w-xl text-h2 leading-6 text-slate-600\">\n              FreshFlow runs your counter, your stock and your daily numbers. Scan, weigh, take UPI, and see exactly\n              how the day went, across every register in the shop.\n            </p>\n            <div className=\"mt-6 flex flex-wrap items-center gap-3\">\n              <Link to=\"/signup\">\n                <Button size=\"lg\">Start one month free</Button>\n              </Link>\n              <Link to=\"/pricing\">\n                <Button size=\"lg\" variant=\"secondary\">\n                  See pricing\n                </Button>\n              </Link>\n            </div>\n            <p className=\"mt-3 text-desc text-slate-500\">No card needed to start. Add your team when you are ready.</p>\n          </div>\n        </div>\n      </section>\n\n      <section className=\"mx-auto max-w-6xl px-4 pb-16 sm:px-6\">\n        <div className=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n          {FEATURES.map(({ icon: Icon, title, body }) => (\n            <div key={title} className=\"rounded-3xl bg-white p-5 shadow-card ring-1 ring-slate-900/[0.04]\">\n              <span className=\"grid h-10 w-10 place-items-center rounded-2xl bg-brand-50 text-brand\">\n                <Icon size={20} aria-hidden />\n              </span>\n              <h2 className=\"mt-3\">{title}</h2>\n              <p className=\"mt-1 text-desc leading-5 text-slate-600\">{body}</p>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      <section className=\"bg-slate-50 py-16\">\n        <div className=\"mx-auto max-w-6xl px-4 sm:px-6\">\n          <div className=\"grid items-center gap-8 lg:grid-cols-2\">\n            <div>\n              <h2>Made for more than one person behind the counter</h2>\n              <p className=\"mt-2 text-body leading-6 text-slate-600\">\n                Give every cashier their own sign-in. They get the register and nothing else. Owners and managers get\n                reports, stock, pricing and the team list. Change someone's role and it applies on their next action.\n              </p>\n              <ul className=\"mt-4 space-y-2.5\">\n                {[\n                  { icon: LuUsers, text: 'Separate accounts for cashiers and admins, billed per user' },\n                  { icon: LuCloudUpload, text: 'Several registers in one shop, all syncing to the same books' },\n                  { icon: LuPackage, text: 'Your own categories, from Meat and Bakery to anything you stock' },\n                ].map(({ icon: Icon, text }) => (\n                  <li key={text} className=\"flex items-start gap-2.5 text-body text-slate-700\">\n                    <Icon className=\"mt-0.5 shrink-0 text-brand\" aria-hidden />\n                    {text}\n                  </li>\n                ))}\n              </ul>\n            </div>\n            <div className=\"rounded-4xl bg-white p-6 shadow-card ring-1 ring-slate-900/[0.04]\">\n              <p className=\"text-desc font-semibold text-slate-500\">A day at the counter</p>\n              <dl className=\"mt-3 space-y-3\">\n                {[\n                  ['Bill a customer', 'Scan, weigh the produce, take UPI, print. A few seconds.'],\n                  ['Power cut or dead link', 'Keep billing. The till stores every sale and uploads later.'],\n                  ['Close of day', 'Revenue, top categories, what ran low, compared with yesterday.'],\n                ].map(([term, detail]) => (\n                  <div key={term} className=\"rounded-2xl bg-slate-50 p-3\">\n                    <dt className=\"font-semibold text-slate-800\">{term}</dt>\n                    <dd className=\"mt-0.5 text-desc text-slate-600\">{detail}</dd>\n                  </div>\n                ))}\n              </dl>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <section className=\"mx-auto max-w-6xl px-4 py-16 sm:px-6\">\n        <div className=\"rounded-4xl bg-brand p-8 text-center text-white sm:p-12\">\n          <h2 className=\"text-h1 font-bold\">Try it on your counter for a month, free</h2>\n          <p className=\"mx-auto mt-2 max-w-lg text-body text-white/85\">\n            Set up your products, run real bills, and see the numbers at closing. Pay only if it earns its place.\n          </p>\n          <Link to=\"/signup\" className=\"mt-6 inline-block\">\n            <Button size=\"lg\" variant=\"secondary\">\n              Create your store\n            </Button>\n          </Link>\n        </div>\n      </section>\n\n      <footer className=\"border-t border-slate-200 py-8\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-2 px-4 text-desc text-slate-500 sm:flex-row sm:px-6\">\n          <span className=\"flex items-center gap-1.5\">\n            <LuLeaf className=\"text-brand\" aria-hidden /> FreshFlow POS\n          </span>\n          <div className=\"flex-1\" />\n          <div className=\"flex gap-4\">\n            <Link to=\"/pricing\" className=\"hover:text-slate-800\">Pricing</Link>\n            <Link to=\"/login\" className=\"hover:text-slate-800\">Sign in</Link>\n            <Link to=\"/signup\" className=\"hover:text-slate-800\">Start free</Link>\n          </div>\n        </div>\n      </footer>\n    </div>\n  );\n}\n",
"client/src/pages/LoginPage.jsx": "import { useState } from 'react';\nimport { Link, Navigate, useLocation, useNavigate } from 'react-router-dom';\nimport { LuEye, LuEyeOff, LuLeaf } from 'react-icons/lu';\nimport { Button } from '../components/ui/Button';\nimport { errorMessage } from '../lib/api';\nimport { useAuthStore } from '../store/authStore';\n\nexport default function LoginPage() {\n  const { token, login, sessionMessage } = useAuthStore();\n  const navigate = useNavigate();\n  const location = useLocation();\n  const [email, setEmail] = useState('');\n  const [password, setPassword] = useState('');\n  const [showPassword, setShowPassword] = useState(false);\n  const [error, setError] = useState(null);\n  const [loading, setLoading] = useState(false);\n\n  if (token) return <Navigate to=\"/app\" replace />;\n\n  const submit = async (e) => {\n    e.preventDefault();\n    setError(null);\n    setLoading(true);\n    try {\n      const user = await login(email, password);\n      const from = location.state?.from;\n      navigate(user.role === 'ADMIN' && from?.startsWith('/app') ? from : '/app', { replace: true });\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <div className=\"relative min-h-[100dvh] bg-slate-50\">\n      <div className=\"absolute inset-x-0 top-0 h-[42dvh] rounded-b-[2.5rem] bg-brand\" aria-hidden />\n      <div className=\"relative mx-auto flex min-h-[100dvh] max-w-md flex-col px-5 pb-10 pt-[9dvh]\">\n        <div className=\"mb-8 text-center text-white\">\n          <div className=\"mx-auto mb-4 grid h-14 w-14 place-items-center rounded-3xl bg-white/15\">\n            <LuLeaf size={28} aria-hidden />\n          </div>\n          <h1>FreshFlow POS</h1>\n          <p className=\"mt-1 text-desc text-white/80\">Sign in to open the register</p>\n        </div>\n\n        <div className=\"rounded-4xl bg-white p-6 shadow-lift\">\n          {/* noValidate: the API returns specific, friendly validation messages */}\n          <form onSubmit={submit} noValidate aria-label=\"Sign in\">\n            <div className=\"space-y-4\">\n              <div>\n                <label htmlFor=\"email\" className=\"label\">\n                  Email address\n                </label>\n                <input\n                  id=\"email\"\n                  type=\"email\"\n                  autoComplete=\"username\"\n                  className=\"field\"\n                  value={email}\n                  onChange={(e) => setEmail(e.target.value)}\n                  placeholder=\"you@store.com\"\n                />\n              </div>\n              <div>\n                <label htmlFor=\"password\" className=\"label\">\n                  Password\n                </label>\n                <div className=\"relative\">\n                  <input\n                    id=\"password\"\n                    type={showPassword ? 'text' : 'password'}\n                    autoComplete=\"current-password\"\n                    className=\"field pr-11\"\n                    value={password}\n                    onChange={(e) => setPassword(e.target.value)}\n                    />\n                  <button\n                    type=\"button\"\n                    onClick={() => setShowPassword((v) => !v)}\n                    className=\"absolute inset-y-0 right-1 my-auto grid h-9 w-9 place-items-center rounded-full text-slate-400 hover:text-slate-700\"\n                    aria-label={showPassword ? 'Hide password' : 'Show password'}\n                  >\n                    {showPassword ? <LuEyeOff aria-hidden /> : <LuEye aria-hidden />}\n                  </button>\n                </div>\n              </div>\n              {error || sessionMessage ? (\n                <p className=\"rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">\n                  {error || sessionMessage}\n                </p>\n              ) : null}\n              <Button type=\"submit\" className=\"w-full\" size=\"lg\" loading={loading} disabled={!email || !password}>\n                Sign in\n              </Button>\n            </div>\n          </form>\n        </div>\n        <p className=\"mt-6 text-center text-desc text-slate-500\">Bills made while offline upload after you sign in.</p>\n        <p className=\"mt-2 text-center text-desc text-slate-500\">\n          New here?{' '}\n          <Link to=\"/signup\" className=\"font-semibold text-brand-700 hover:underline\">\n            Start a free month\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n",
"client/src/pages/PosPage.jsx": "import { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport { useOutletContext } from 'react-router-dom';\nimport { LuLayers, LuScanBarcode, LuSearch, LuShoppingBasket, LuX } from 'react-icons/lu';\nimport { SyncPill } from '../components/layout/AppShell';\nimport { CartPanel } from '../components/pos/CartPanel';\nimport { CategoryRail } from '../components/pos/CategoryRail';\nimport { DiscountModal } from '../components/pos/DiscountModal';\nimport { HeldBillsModal } from '../components/pos/HeldBillsModal';\nimport { PaymentModal } from '../components/pos/PaymentModal';\nimport { ProductCard } from '../components/pos/ProductCard';\nimport { ReceiptModal } from '../components/pos/ReceiptModal';\nimport { ScaleModal } from '../components/pos/ScaleModal';\nimport { Button } from '../components/ui/Button';\nimport { Modal } from '../components/ui/Modal';\nimport { EmptyState, ErrorState, Spinner } from '../components/ui/States';\nimport { useBarcodeScanner } from '../hooks/useBarcodeScanner';\nimport { useBill } from '../hooks/useBill';\nimport { useDebounce } from '../hooks/useDebounce';\nimport { useHotkeys } from '../hooks/useHotkeys';\nimport { completeSale } from '../lib/checkout';\nimport { errorMessage } from '../lib/api';\nimport { formatMoney } from '../lib/format';\nimport { fromPaise } from '../lib/pricing';\nimport { useAuthStore } from '../store/authStore';\nimport { useCartStore } from '../store/cartStore';\nimport { useCatalogStore } from '../store/catalogStore';\nimport { toast } from '../store/toastStore';\n\nfunction beep(frequency = 1760) {\n  try {\n    const Ctx = window.AudioContext || window.webkitAudioContext;\n    if (!Ctx) return;\n    const ctx = new Ctx();\n    const osc = ctx.createOscillator();\n    const gain = ctx.createGain();\n    osc.type = 'sine';\n    osc.frequency.value = frequency;\n    gain.gain.setValueAtTime(0.06, ctx.currentTime);\n    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.09);\n    osc.connect(gain).connect(ctx.destination);\n    osc.start();\n    osc.stop(ctx.currentTime + 0.1);\n    setTimeout(() => ctx.close(), 300);\n  } catch {\n    /* audio is a nicety, never block a sale for it */\n  }\n}\n\nexport default function PosPage() {\n  const { openSync } = useOutletContext();\n  const user = useAuthStore((s) => s.user);\n  const isAdmin = user?.role === 'ADMIN';\n  const { products, categories, settings, status, source, error, load, lookup, applySale } = useCatalogStore();\n  const { lines, billDiscount, bill, itemCount, currency } = useBill();\n  const { addProduct, clear, holdCurrent, loadHeldBills, heldBills, setBillDiscount } = useCartStore();\n\n  const [query, setQuery] = useState('');\n  const [category, setCategory] = useState('all');\n  const [subCategory, setSubCategory] = useState('all');\n  const [scaleProduct, setScaleProduct] = useState(null);\n  const [showPayment, setShowPayment] = useState(false);\n  const [showDiscount, setShowDiscount] = useState(false);\n  const [showHeld, setShowHeld] = useState(false);\n  const [showCart, setShowCart] = useState(false);\n  const [receipt, setReceipt] = useState(null);\n  const [submitting, setSubmitting] = useState(false);\n  const searchRef = useRef(null);\n  const debouncedQuery = useDebounce(query, 150);\n\n  useEffect(() => {\n    load();\n    loadHeldBills();\n  }, [load, loadHeldBills]);\n\n  const select = useCallback(\n    (product) => {\n      if (product.soldByWeight) {\n        setScaleProduct(product);\n        return;\n      }\n      addProduct(product, 1);\n      beep();\n    },\n    [addProduct],\n  );\n\n  const addByCode = useCallback(\n    (code) => {\n      const product = lookup(code);\n      if (!product) {\n        beep(320);\n        toast.error(`No product matches “${code}”`);\n        return;\n      }\n      setQuery('');\n      select(product);\n    },\n    [lookup, select],\n  );\n\n  useBarcodeScanner(addByCode, { enabled: !receipt && !showPayment && !scaleProduct });\n\n  useHotkeys(\n    {\n      F2: () => searchRef.current?.focus(),\n      F4: () => lines.length && holdCurrent().then(() => toast.info('Bill parked')),\n      F8: () => lines.length && setShowPayment(true),\n      F9: () => setShowHeld(true),\n    },\n    !receipt,\n  );\n\n  const quickKeys = useMemo(() => products.filter((p) => p.isQuickKey).slice(0, 12), [products]);\n\n  const visibleProducts = useMemo(() => {\n    const term = debouncedQuery.trim().toLowerCase();\n    const childIds = new Set(categories.filter((c) => c.parentId === category).map((c) => c.id));\n    return products.filter((p) => {\n      if (category !== 'all') {\n        const inBranch = p.categoryId === category || childIds.has(p.categoryId);\n        if (!inBranch) return false;\n        if (subCategory !== 'all' && p.categoryId !== subCategory) return false;\n      }\n      if (!term) return true;\n      return p.name.toLowerCase().includes(term) || p.code.toLowerCase() === term || p.barcode === term;\n    });\n  }, [products, categories, category, subCategory, debouncedQuery]);\n\n  const inCartQty = useMemo(() => {\n    const map = new Map();\n    lines.forEach((l) => map.set(l.productId, (map.get(l.productId) || 0) + l.quantity));\n    return map;\n  }, [lines]);\n\n  const onSearchKeyDown = (e) => {\n    if (e.key !== 'Enter') return;\n    const term = query.trim();\n    if (!term) return;\n    const exact = lookup(term);\n    if (exact) {\n      setQuery('');\n      select(exact);\n    } else if (visibleProducts.length === 1) {\n      setQuery('');\n      select(visibleProducts[0]);\n    } else if (!visibleProducts.length) {\n      beep(320);\n      toast.error(`No product matches “${term}”`);\n    }\n  };\n\n  const confirmPayment = async (details) => {\n    setSubmitting(true);\n    try {\n      const sale = await completeSale({ lines, billDiscount, settings, user, ...details });\n      applySale(lines.map((l) => ({ productId: l.productId, quantity: l.quantity })));\n      clear();\n      setShowPayment(false);\n      setShowCart(false);\n      setReceipt(sale);\n    } catch (err) {\n      toast.error(errorMessage(err, 'Could not save this bill. Try again.'));\n    } finally {\n      setSubmitting(false);\n    }\n  };\n\n  if (status === 'loading') return <Spinner label=\"Loading the catalog\" />;\n  if (status === 'error') return <ErrorState message={error} onRetry={load} />;\n\n  const totalDue = fromPaise(bill.grandTotal);\n\n  return (\n    <div className=\"flex h-full min-h-0\">\n      <section className=\"flex min-w-0 flex-1 flex-col\">\n        <header className=\"sticky top-0 z-20 border-b border-slate-200/70 bg-slate-50/85 px-4 pb-3 pt-4 backdrop-blur-xl sm:px-6\">\n          <div className=\"flex items-center gap-3\">\n            <div className=\"min-w-0 flex-1\">\n              <h1 className=\"truncate\">{settings?.storeName || 'Register'}</h1>\n              <p className=\"truncate text-desc text-slate-500\">\n                {user?.name}\n                {source === 'cache' ? ' · offline catalog' : ''}\n              </p>\n            </div>\n            <SyncPill onClick={openSync} />\n            <Button variant=\"secondary\" size=\"sm\" onClick={() => setShowHeld(true)} className=\"relative\">\n              <LuLayers aria-hidden />\n              <span className=\"hidden sm:inline\">Held</span>\n              {heldBills.length ? (\n                <span className=\"ml-0.5 rounded-full bg-amber-500 px-1.5 text-desc font-semibold text-white tabular\">{heldBills.length}</span>\n              ) : null}\n            </Button>\n          </div>\n\n          <div className=\"relative mt-3\">\n            <LuSearch className=\"pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400\" aria-hidden />\n            <input\n              ref={searchRef}\n              className=\"field h-11 pl-10 pr-10\"\n              placeholder=\"Scan barcode or search products\"\n              value={query}\n              onChange={(e) => setQuery(e.target.value)}\n              onKeyDown={onSearchKeyDown}\n              aria-label=\"Scan barcode or search products\"\n              autoComplete=\"off\"\n            />\n            {query ? (\n              <button\n                type=\"button\"\n                onClick={() => setQuery('')}\n                className=\"absolute right-2 top-1/2 grid h-7 w-7 -translate-y-1/2 place-items-center rounded-full text-slate-400 hover:bg-slate-100\"\n                aria-label=\"Clear search\"\n              >\n                <LuX aria-hidden />\n              </button>\n            ) : (\n              <LuScanBarcode className=\"pointer-events-none absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-300\" aria-hidden />\n            )}\n          </div>\n\n          {quickKeys.length ? (\n            <div className=\"no-scrollbar -mx-4 mt-2.5 flex gap-2 overflow-x-auto px-4 sm:-mx-6 sm:px-6\" aria-label=\"Quick codes\">\n              {quickKeys.map((p) => (\n                <button\n                  key={p.id}\n                  type=\"button\"\n                  onClick={() => select(p)}\n                  className=\"h-8 shrink-0 rounded-full bg-white px-3 text-desc font-medium text-slate-700 ring-1 ring-slate-200 transition hover:ring-brand/50\"\n                >\n                  <span className=\"text-slate-400 tabular\">#{p.code}</span> {p.name.split(' ').slice(0, 2).join(' ')}\n                </button>\n              ))}\n            </div>\n          ) : null}\n        </header>\n\n        <div className={`scroll-thin min-h-0 flex-1 overflow-y-auto px-4 pt-4 sm:px-6 ${lines.length ? \"pb-24 lg:pb-4\" : \"pb-4\"}`}>\n          <CategoryRail\n            categories={categories}\n            selected={category}\n            onSelect={(id) => {\n              setCategory(id);\n              setSubCategory('all');\n            }}\n            selectedSub={subCategory}\n            onSelectSub={setSubCategory}\n          />\n\n          {visibleProducts.length ? (\n            <div className=\"mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4 2xl:grid-cols-5\">\n              {visibleProducts.map((p) => (\n                <ProductCard key={p.id} product={p} inCartQty={inCartQty.get(p.id)} currency={currency} onSelect={select} />\n              ))}\n            </div>\n          ) : (\n            <EmptyState\n              icon={LuSearch}\n              title=\"Nothing matches that\"\n              description={query ? `No products found for “${query}”.` : 'This category has no products yet.'}\n              action={\n                query ? (\n                  <Button variant=\"secondary\" size=\"sm\" onClick={() => setQuery('')}>\n                    Clear search\n                  </Button>\n                ) : null\n              }\n            />\n          )}\n        </div>\n      </section>\n\n      {/* Bill panel: docked on large screens, bottom sheet on phones and tablets */}\n      <aside className=\"hidden w-[380px] shrink-0 border-l border-slate-200/80 bg-white lg:flex xl:w-[420px]\">\n        <CartPanel onCheckout={() => setShowPayment(true)} onHold={() => holdCurrent().then(() => toast.info('Bill parked'))} onDiscount={() => setShowDiscount(true)} />\n      </aside>\n\n      {lines.length ? (\n        <div className=\"fixed inset-x-0 bottom-[calc(64px+env(safe-area-inset-bottom))] z-30 px-4 pb-3 md:bottom-0 md:px-6 md:pb-4 lg:hidden\">\n          <button\n            type=\"button\"\n            onClick={() => setShowCart(true)}\n            aria-label=\"Open current bill\"\n            className=\"flex h-14 w-full items-center gap-3 rounded-full bg-brand px-5 text-white shadow-lift\"\n          >\n            <span className=\"grid h-8 w-8 place-items-center rounded-full bg-white/20\">\n              <LuShoppingBasket aria-hidden />\n            </span>\n            <span className=\"flex-1 text-left font-semibold\">\n              {itemCount} item{itemCount === 1 ? '' : 's'}\n            </span>\n            <span className=\"text-h2 font-bold tabular\">{formatMoney(totalDue, currency)}</span>\n          </button>\n        </div>\n      ) : null}\n\n      <Modal open={showCart} onClose={() => setShowCart(false)} title=\"Current bill\" size=\"md\">\n        <CartPanel\n          inSheet\n          onCheckout={() => setShowPayment(true)}\n          onHold={async () => {\n            await holdCurrent();\n            setShowCart(false);\n            toast.info('Bill parked');\n          }}\n          onDiscount={() => setShowDiscount(true)}\n        />\n      </Modal>\n\n      <ScaleModal\n        product={scaleProduct}\n        currency={currency}\n        onClose={() => setScaleProduct(null)}\n        onAdd={(product, weight) => {\n          addProduct(product, weight);\n          setScaleProduct(null);\n          beep();\n        }}\n      />\n\n      <DiscountModal\n        open={showDiscount}\n        onClose={() => setShowDiscount(false)}\n        afterMarkdownsPaise={bill.afterMarkdowns}\n        current={billDiscount}\n        maxCashierPct={Number(settings?.maxCashierDiscountPct ?? 10)}\n        isAdmin={isAdmin}\n        currency={currency}\n        onApply={(d) => {\n          setBillDiscount(d);\n          setShowDiscount(false);\n        }}\n      />\n\n      <PaymentModal\n        open={showPayment}\n        onClose={() => setShowPayment(false)}\n        total={totalDue}\n        itemCount={itemCount}\n        settings={settings}\n        isAdmin={isAdmin}\n        submitting={submitting}\n        onConfirm={confirmPayment}\n      />\n\n      <HeldBillsModal open={showHeld} onClose={() => setShowHeld(false)} taxRate={Number(settings?.taxRate ?? 0)} currency={currency} />\n\n      <ReceiptModal receipt={receipt} onClose={() => setReceipt(null)} />\n    </div>\n  );\n}\n",
"client/src/pages/PricingPage.jsx": "import { useState } from 'react';\nimport { Link, useNavigate } from 'react-router-dom';\nimport { LuArrowLeft, LuLeaf } from 'react-icons/lu';\nimport { IntervalToggle, PlanCard, SeatStepper } from '../components/pricing/PricingPlans';\nimport { Button } from '../components/ui/Button';\nimport { ErrorState, Spinner } from '../components/ui/States';\nimport { useApiQuery } from '../hooks/useApiQuery';\nimport { useAuthStore } from '../store/authStore';\n\nconst FAQ = [\n  ['What counts as a user?', 'Every staff account that can sign in: each cashier and each admin. You can deactivate someone to free their seat at any time.'],\n  ['What happens after the free month?', 'Billing pauses until you choose a plan. Your data stays put, and bills already taken on a till still upload.'],\n  ['Can I change plans later?', 'Yes. Pick a new plan or seat count in Billing and pay the difference from that point.'],\n  ['How do I pay?', 'Through Razorpay: UPI, cards, net banking and wallets. Payment is verified before your plan changes.'],\n];\n\nexport default function PricingPage() {\n  const { data, loading, error, refetch } = useApiQuery('/public/plans', null);\n  const navigate = useNavigate();\n  const token = useAuthStore((s) => s.token);\n  const isAdmin = useAuthStore((s) => s.user?.role === 'ADMIN');\n  const [interval, setIntervalValue] = useState('MONTHLY');\n  const [seats, setSeats] = useState(3);\n\n  const choose = (tier) => {\n    if (token && isAdmin) navigate(`/app/billing?plan=${tier}&interval=${interval}&seats=${seats}`);\n    else navigate(`/signup?plan=${tier}&interval=${interval}&seats=${seats}`);\n  };\n\n  return (\n    <div className=\"min-h-[100dvh] bg-slate-50\">\n      <header className=\"sticky top-0 z-30 border-b border-slate-200/70 bg-white/85 backdrop-blur-xl\">\n        <nav className=\"mx-auto flex h-16 max-w-6xl items-center gap-3 px-4 sm:px-6\">\n          <Link to=\"/\" className=\"flex items-center gap-2\">\n            <span className=\"grid h-9 w-9 place-items-center rounded-2xl bg-brand text-white\">\n              <LuLeaf size={18} aria-hidden />\n            </span>\n            <span className=\"text-h2 font-semibold\">FreshFlow</span>\n          </Link>\n          <div className=\"flex-1\" />\n          {token ? (\n            <Link to=\"/app\">\n              <Button size=\"sm\" variant=\"secondary\">\n                Open register\n              </Button>\n            </Link>\n          ) : (\n            <Link to=\"/login\" className=\"px-3 text-body font-medium text-slate-600 hover:text-slate-900\">\n              Sign in\n            </Link>\n          )}\n        </nav>\n      </header>\n\n      <main className=\"mx-auto max-w-6xl px-4 py-10 sm:px-6\">\n        <Link to=\"/\" className=\"inline-flex items-center gap-1.5 text-desc font-medium text-slate-500 hover:text-slate-800\">\n          <LuArrowLeft aria-hidden /> Back\n        </Link>\n        <div className=\"mt-3 text-center\">\n          <h1>Pay for the people at the counter</h1>\n          <p className=\"mx-auto mt-2 max-w-xl text-body text-slate-600\">\n            Every plan starts with one month free. After that you pay per staff account, and only for the ones you keep active.\n          </p>\n        </div>\n\n        <div className=\"mt-6 flex flex-col items-center gap-4 sm:flex-row sm:justify-center\">\n          <IntervalToggle interval={interval} onChange={setIntervalValue} />\n          <SeatStepper seats={seats} onChange={setSeats} />\n        </div>\n\n        {loading && !data ? <Spinner label=\"Loading plans\" /> : null}\n        {error ? <ErrorState message={error} onRetry={refetch} /> : null}\n\n        {data ? (\n          <>\n            <div className=\"mt-8 grid gap-4 lg:grid-cols-3\">\n              <div className=\"flex flex-col rounded-4xl bg-white p-6 shadow-card ring-1 ring-slate-900/[0.05]\">\n                <h2>Free trial</h2>\n                <p className=\"mt-1 text-desc text-slate-500\">The whole thing, on your counter, for a month.</p>\n                <div className=\"mt-4 flex items-end gap-2\">\n                  <span className=\"text-h1 font-bold tabular\">₹0</span>\n                  <span className=\"pb-0.5 text-desc text-slate-500\">for {data.trial.days} days</span>\n                </div>\n                <ul className=\"mt-4 flex-1 space-y-2 text-body text-slate-700\">\n                  <li>Up to {data.trial.seats} staff accounts</li>\n                  <li>Every register feature, no limits on bills</li>\n                  <li>Reports, stock and offline selling included</li>\n                  <li>No card needed to start</li>\n                </ul>\n                <Button className=\"mt-5 w-full\" size=\"lg\" variant=\"secondary\" onClick={() => navigate('/signup')}>\n                  Start free\n                </Button>\n              </div>\n\n              {data.plans.map((plan) => (\n                <PlanCard\n                  key={plan.tier}\n                  plan={plan}\n                  interval={interval}\n                  seats={seats}\n                  highlight={plan.tier === 'STANDARD'}\n                  cta={token && isAdmin ? `Choose ${plan.name}` : 'Start free, then pay'}\n                  onSelect={choose}\n                />\n              ))}\n            </div>\n\n            <p className=\"mt-4 text-center text-desc text-slate-500\">\n              Prices are per user per month in Indian rupees, excluding GST. Yearly plans are charged twelve months up front.\n            </p>\n\n            <section className=\"mx-auto mt-12 max-w-3xl\">\n              <h2 className=\"text-center\">Questions people ask</h2>\n              <dl className=\"mt-4 space-y-3\">\n                {FAQ.map(([q, a]) => (\n                  <div key={q} className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.04]\">\n                    <dt className=\"font-semibold text-slate-800\">{q}</dt>\n                    <dd className=\"mt-1 text-desc leading-5 text-slate-600\">{a}</dd>\n                  </div>\n                ))}\n              </dl>\n            </section>\n          </>\n        ) : null}\n      </main>\n    </div>\n  );\n}\n",
"client/src/pages/ReportsPage.jsx": "import { useState } from 'react';\nimport { useOutletContext } from 'react-router-dom';\nimport { SyncPill } from '../components/layout/AppShell';\nimport { CategoryDensityChart } from '../components/charts/CategoryDensityChart';\nimport { SplitBar } from '../components/charts/SplitBar';\nimport { TrendChart } from '../components/charts/TrendChart';\nimport { KpiCard } from '../components/reports/KpiCard';\nimport { ProductPerformance } from '../components/reports/ProductPerformance';\nimport { RangePicker } from '../components/reports/RangePicker';\nimport { TransactionLedger } from '../components/reports/TransactionLedger';\nimport { Segmented } from '../components/ui/Segmented';\nimport { ErrorState, Skeleton } from '../components/ui/States';\nimport { useApiQuery } from '../hooks/useApiQuery';\nimport { describeRange, presetRange } from '../lib/dates';\nimport { formatMoney, formatNumber } from '../lib/format';\nimport { useCatalogStore } from '../store/catalogStore';\n\nexport default function ReportsPage() {\n  const { openSync } = useOutletContext();\n  const settings = useCatalogStore((s) => s.settings);\n  const currency = settings?.currency || 'INR';\n  const [range, setRange] = useState(() => presetRange('today'));\n  const [level, setLevel] = useState('leaf');\n\n  const overview = useApiQuery('/reports/overview', range);\n  const categories = useApiQuery('/reports/categories', { ...range, level });\n\n  const k = overview.data?.kpis;\n  const inv = overview.data?.inventory;\n\n  return (\n    <div className=\"scroll-thin h-full overflow-y-auto\">\n      <header className=\"sticky top-0 z-20 border-b border-slate-200/70 bg-slate-50/85 px-4 pb-3 pt-4 backdrop-blur-xl sm:px-6\">\n        <div className=\"flex items-start gap-3\">\n          <div className=\"min-w-0 flex-1\">\n            <h1>Daily business</h1>\n            <p className=\"truncate text-desc text-slate-500\">\n              {describeRange(range.from, range.to)}\n              {overview.data ? `, compared with the ${overview.data.period.days} day${overview.data.period.days === 1 ? '' : 's'} before` : ''}\n            </p>\n          </div>\n          <SyncPill onClick={openSync} />\n        </div>\n        <div className=\"mt-3\">\n          <RangePicker range={range} onChange={setRange} />\n        </div>\n      </header>\n\n      <div className=\"space-y-4 px-4 py-4 sm:px-6\">\n        {overview.error ? <ErrorState message={overview.error} onRetry={overview.refetch} /> : null}\n\n        <div className=\"grid grid-cols-2 gap-3 lg:grid-cols-4\">\n          {overview.loading && !k\n            ? Array.from({ length: 4 }, (_, i) => <Skeleton key={i} className=\"h-[104px] rounded-3xl\" />)\n            : k\n              ? [\n                  <KpiCard key=\"rev\" label=\"Revenue\" value={formatMoney(k.current.revenue, currency)} current={k.current.revenue} previous={k.previous.revenue} hint={`${k.current.orders} bills`} />,\n                  <KpiCard key=\"bask\" label=\"Average bill\" value={formatMoney(k.current.avgBasket, currency)} current={k.current.avgBasket} previous={k.previous.avgBasket} />,\n                  <KpiCard\n                    key=\"items\"\n                    label=\"Items sold\"\n                    value={k.current.units ? formatNumber(k.current.units) : `${formatNumber(k.current.weightKg)} kg`}\n                    current={k.current.units + k.current.weightKg}\n                    previous={k.previous.units + k.previous.weightKg}\n                    hint={\n                      k.current.units && k.current.weightKg\n                        ? `+ ${formatNumber(k.current.weightKg)} kg loose`\n                        : k.current.units\n                          ? 'packed items'\n                          : 'loose produce'\n                    }\n                  />,\n                  <KpiCard key=\"disc\" label=\"Discounts given\" value={formatMoney(k.current.discounts, currency)} current={k.current.discounts} previous={k.previous.discounts} invertColors hint=\"passed to customers\" />,\n                ]\n              : null}\n        </div>\n\n        <div className=\"grid gap-4 xl:grid-cols-[1.6fr_1fr]\">\n          <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n            <h2>Revenue</h2>\n            <p className=\"text-desc text-slate-500\">Green is this period, grey is the one before</p>\n            <div className=\"mt-3\">\n              {overview.data ? (\n                <TrendChart current={overview.data.series.current} previous={overview.data.series.previous} currency={currency} />\n              ) : (\n                <Skeleton className=\"h-[200px]\" />\n              )}\n            </div>\n          </section>\n\n          <div className=\"space-y-4\">\n            <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n              <h2>How customers paid</h2>\n              <div className=\"mt-3\">{overview.data ? <SplitBar data={overview.data.paymentSplit.current} currency={currency} /> : <Skeleton className=\"h-[120px]\" />}</div>\n            </section>\n\n            <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n              <h2>Stock on hand</h2>\n              {inv ? (\n                <>\n                  <p className=\"mt-1 text-h1 font-bold tabular\">{formatMoney(inv.value, currency)}</p>\n                  <p className=\"text-desc text-slate-500\">across {formatNumber(inv.skus)} products</p>\n                  <div className=\"mt-3 flex gap-2\">\n                    <span className=\"rounded-full bg-amber-50 px-2.5 py-1 text-desc font-medium text-amber-700 tabular\">{inv.lowStock} running low</span>\n                    <span className=\"rounded-full bg-rose-50 px-2.5 py-1 text-desc font-medium text-rose-700 tabular\">{inv.outOfStock} out of stock</span>\n                  </div>\n                </>\n              ) : (\n                <Skeleton className=\"mt-2 h-[92px]\" />\n              )}\n            </section>\n          </div>\n        </div>\n\n        <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n          <div className=\"flex flex-wrap items-center gap-3\">\n            <div className=\"flex-1\">\n              <h2>Categories</h2>\n              <p className=\"text-desc text-slate-500\">\n                {categories.data ? `${formatNumber(categories.data.rows.length)} categories tracked` : 'Loading categories'}\n              </p>\n            </div>\n            <Segmented\n              size=\"sm\"\n              ariaLabel=\"Category level\"\n              value={level}\n              onChange={setLevel}\n              options={[\n                { value: 'leaf', label: 'Detailed' },\n                { value: 'top', label: 'Departments' },\n              ]}\n            />\n          </div>\n          <div className=\"mt-4\">\n            {categories.error ? <ErrorState message={categories.error} onRetry={categories.refetch} /> : null}\n            {categories.data ? <CategoryDensityChart rows={categories.data.rows} currency={currency} /> : <Skeleton className=\"h-[240px]\" />}\n          </div>\n        </section>\n\n        <ProductPerformance range={range} currency={currency} />\n        <TransactionLedger range={range} currency={currency} />\n      </div>\n    </div>\n  );\n}\n",
"client/src/pages/SettingsPage.jsx": "import { useEffect, useState } from 'react';\nimport { useOutletContext } from 'react-router-dom';\nimport { LuPlug, LuPrinter, LuScale, LuUnplug, LuUserPlus } from 'react-icons/lu';\nimport { SyncPill } from '../components/layout/AppShell';\nimport { Button } from '../components/ui/Button';\nimport { Modal } from '../components/ui/Modal';\nimport { Spinner } from '../components/ui/States';\nimport { useApiQuery } from '../hooks/useApiQuery';\nimport { api, errorMessage } from '../lib/api';\nimport { terminalId } from '../lib/ids';\nimport { useCatalogStore } from '../store/catalogStore';\nimport { useHardwareStore } from '../store/hardwareStore';\nimport { toast } from '../store/toastStore';\n\nfunction Section({ title, description, children }) {\n  return (\n    <section className=\"rounded-3xl bg-white p-4 shadow-card ring-1 ring-slate-900/[0.03] sm:p-5\">\n      <h2>{title}</h2>\n      {description ? <p className=\"mt-0.5 text-desc text-slate-500\">{description}</p> : null}\n      <div className=\"mt-4\">{children}</div>\n    </section>\n  );\n}\n\nfunction UserDialog({ open, onClose, onSaved }) {\n  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'CASHIER' });\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    if (open) {\n      setForm({ name: '', email: '', password: '', role: 'CASHIER' });\n      setError(null);\n    }\n  }, [open]);\n\n  const save = async () => {\n    setSaving(true);\n    setError(null);\n    try {\n      await api.post('/users', form);\n      toast.success(`${form.name} can now sign in`);\n      onSaved();\n      onClose();\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  return (\n    <Modal\n      open={open}\n      onClose={onClose}\n      size=\"sm\"\n      title=\"Add a team member\"\n      footer={\n        <Button className=\"w-full\" onClick={save} loading={saving} disabled={!form.name || !form.email || form.password.length < 8}>\n          Create account\n        </Button>\n      }\n    >\n      <div className=\"space-y-4\">\n        <div>\n          <label htmlFor=\"u-name\" className=\"label\">Name</label>\n          <input id=\"u-name\" className=\"field\" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />\n        </div>\n        <div>\n          <label htmlFor=\"u-email\" className=\"label\">Email</label>\n          <input id=\"u-email\" type=\"email\" className=\"field\" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />\n        </div>\n        <div>\n          <label htmlFor=\"u-password\" className=\"label\">Temporary password</label>\n          <input id=\"u-password\" className=\"field\" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder=\"At least 8 characters\" />\n        </div>\n        <div>\n          <label htmlFor=\"u-role\" className=\"label\">Role</label>\n          <select id=\"u-role\" className=\"field\" value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>\n            <option value=\"CASHIER\">Cashier — register only</option>\n            <option value=\"ADMIN\">Admin — full access</option>\n          </select>\n        </div>\n        {error ? <p className=\"rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">{error}</p> : null}\n      </div>\n    </Modal>\n  );\n}\n\nexport default function SettingsPage() {\n  const { openSync } = useOutletContext();\n  const { settings, load } = useCatalogStore();\n  const [form, setForm] = useState(null);\n  const [saving, setSaving] = useState(false);\n  const [error, setError] = useState(null);\n  const [addingUser, setAddingUser] = useState(false);\n  const users = useApiQuery('/users', null);\n  const { serialSupported, scale, printer, connectScale, disconnectScale, connectPrinter, disconnectPrinter } = useHardwareStore();\n\n  useEffect(() => {\n    if (settings && !form) setForm({ ...settings });\n  }, [settings, form]);\n\n  if (!form) return <Spinner label=\"Loading settings\" />;\n\n  const set = (key) => (e) => setForm({ ...form, [key]: e.target.value });\n\n  const save = async () => {\n    setSaving(true);\n    setError(null);\n    try {\n      await api.put('/settings', {\n        ...form,\n        taxRate: Number(form.taxRate),\n        maxCashierDiscountPct: Number(form.maxCashierDiscountPct),\n      });\n      await load({ silent: true });\n      toast.success('Store details saved');\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  const toggleRole = async (user) => {\n    try {\n      await api.patch(`/users/${user.id}`, { role: user.role === 'ADMIN' ? 'CASHIER' : 'ADMIN' });\n      users.refetch();\n    } catch (err) {\n      toast.error(errorMessage(err));\n    }\n  };\n\n  const toggleActive = async (user) => {\n    try {\n      await api.patch(`/users/${user.id}`, { isActive: !user.isActive });\n      users.refetch();\n    } catch (err) {\n      toast.error(errorMessage(err));\n    }\n  };\n\n  return (\n    <div className=\"scroll-thin h-full overflow-y-auto\">\n      <header className=\"sticky top-0 z-20 border-b border-slate-200/70 bg-slate-50/85 px-4 pb-3 pt-4 backdrop-blur-xl sm:px-6\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"min-w-0 flex-1\">\n            <h1>Settings</h1>\n            <p className=\"truncate text-desc text-slate-500\">Register {terminalId()}</p>\n          </div>\n          <SyncPill onClick={openSync} />\n          <Button size=\"sm\" onClick={save} loading={saving}>\n            Save changes\n          </Button>\n        </div>\n      </header>\n\n      <div className=\"mx-auto max-w-3xl space-y-4 px-4 py-4 sm:px-6\">\n        <Section title=\"Store details\" description=\"Printed on every receipt\">\n          <div className=\"space-y-4\">\n            <div>\n              <label htmlFor=\"s-name\" className=\"label\">Store name</label>\n              <input id=\"s-name\" className=\"field\" value={form.storeName ?? ''} onChange={set('storeName')} maxLength={80} />\n            </div>\n            <div>\n              <label htmlFor=\"s-tagline\" className=\"label\">Tagline</label>\n              <input id=\"s-tagline\" className=\"field\" value={form.tagline ?? ''} onChange={set('tagline')} maxLength={120} />\n            </div>\n            <div>\n              <label htmlFor=\"s-address\" className=\"label\">Address</label>\n              <input id=\"s-address\" className=\"field\" value={form.address ?? ''} onChange={set('address')} maxLength={250} />\n            </div>\n            <div className=\"grid gap-3 sm:grid-cols-2\">\n              <div>\n                <label htmlFor=\"s-phone\" className=\"label\">Phone</label>\n                <input id=\"s-phone\" className=\"field\" value={form.phone ?? ''} onChange={set('phone')} maxLength={20} />\n              </div>\n              <div>\n                <label htmlFor=\"s-gstin\" className=\"label\">GSTIN</label>\n                <input id=\"s-gstin\" className=\"field tabular\" value={form.gstin ?? ''} onChange={set('gstin')} placeholder=\"29ABCDE1234F1Z5\" maxLength={15} />\n              </div>\n            </div>\n            <div>\n              <label htmlFor=\"s-footer\" className=\"label\">Receipt footer</label>\n              <input id=\"s-footer\" className=\"field\" value={form.receiptFooter ?? ''} onChange={set('receiptFooter')} maxLength={200} />\n            </div>\n          </div>\n        </Section>\n\n        <Section title=\"Payments and tax\" description=\"Used to calculate bills and build the UPI QR code\">\n          <div className=\"grid gap-3 sm:grid-cols-2\">\n            <div>\n              <label htmlFor=\"s-upi\" className=\"label\">UPI ID</label>\n              <input id=\"s-upi\" className=\"field\" value={form.upiVpa ?? ''} onChange={set('upiVpa')} placeholder=\"store@bank\" />\n            </div>\n            <div>\n              <label htmlFor=\"s-payee\" className=\"label\">Payee name shown in UPI apps</label>\n              <input id=\"s-payee\" className=\"field\" value={form.upiPayeeName ?? ''} onChange={set('upiPayeeName')} maxLength={60} />\n            </div>\n            <div>\n              <label htmlFor=\"s-tax\" className=\"label\">GST rate (%)</label>\n              <input id=\"s-tax\" inputMode=\"decimal\" className=\"field tabular\" value={form.taxRate ?? ''} onChange={set('taxRate')} />\n            </div>\n            <div>\n              <label htmlFor=\"s-cap\" className=\"label\">Cashier discount limit (%)</label>\n              <input id=\"s-cap\" inputMode=\"decimal\" className=\"field tabular\" value={form.maxCashierDiscountPct ?? ''} onChange={set('maxCashierDiscountPct')} />\n            </div>\n          </div>\n          {error ? <p className=\"mt-3 rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">{error}</p> : null}\n        </Section>\n\n        <Section title=\"Hardware on this register\" description=\"Connections are per device and stay until you close the browser\">\n          <div className=\"space-y-2\">\n            {[\n              { label: 'Weighing scale', icon: LuScale, state: scale, connect: connectScale, disconnect: disconnectScale, hint: 'Reads live weight over USB or RS-232' },\n              { label: 'Receipt printer', icon: LuPrinter, state: printer, connect: connectPrinter, disconnect: disconnectPrinter, hint: 'Prints 80 mm ESC/POS receipts' },\n            ].map(({ label, icon: Icon, state, connect, disconnect, hint }) => (\n              <div key={label} className=\"flex items-center gap-3 rounded-2xl bg-slate-50 px-3 py-2.5\">\n                <Icon className=\"shrink-0 text-slate-500\" aria-hidden />\n                <div className=\"min-w-0 flex-1\">\n                  <p className=\"font-medium\">{label}</p>\n                  <p className=\"truncate text-desc text-slate-500\">{state.status === 'connected' ? 'Connected' : state.error || hint}</p>\n                </div>\n                {state.status === 'connected' ? (\n                  <Button size=\"sm\" variant=\"secondary\" onClick={disconnect}>\n                    <LuUnplug aria-hidden /> Disconnect\n                  </Button>\n                ) : (\n                  <Button size=\"sm\" variant=\"soft\" onClick={() => connect()} disabled={!serialSupported}>\n                    <LuPlug aria-hidden /> Connect\n                  </Button>\n                )}\n              </div>\n            ))}\n            {!serialSupported ? <p className=\"text-desc text-slate-500\">Hardware connections need Chrome or Edge on a computer. You can still print receipts from the browser print dialog.</p> : null}\n          </div>\n        </Section>\n\n        <Section title=\"Team\" description=\"Cashiers can use the register. Admins also see reports, inventory and settings.\">\n          <div className=\"mb-3 flex justify-end\">\n            <Button size=\"sm\" variant=\"soft\" onClick={() => setAddingUser(true)}>\n              <LuUserPlus aria-hidden /> Add member\n            </Button>\n          </div>\n          {users.loading && !users.data ? <Spinner /> : null}\n          <ul className=\"divide-y divide-slate-100\">\n            {(users.data?.users ?? []).map((u) => (\n              <li key={u.id} className=\"flex items-center gap-3 py-2.5\">\n                <div className=\"min-w-0 flex-1\">\n                  <p className=\"truncate font-medium\">\n                    {u.name}\n                    {!u.isActive ? <span className=\"ml-2 rounded-full bg-slate-100 px-1.5 py-0.5 text-desc text-slate-500\">Deactivated</span> : null}\n                  </p>\n                  <p className=\"truncate text-desc text-slate-500\">{u.email}</p>\n                </div>\n                <button type=\"button\" onClick={() => toggleRole(u)} className={`rounded-full px-2.5 py-1 text-desc font-medium ${u.role === 'ADMIN' ? 'bg-brand-50 text-brand-700' : 'bg-slate-100 text-slate-600'}`}>\n                  {u.role === 'ADMIN' ? 'Admin' : 'Cashier'}\n                </button>\n                <Button size=\"sm\" variant=\"ghost\" onClick={() => toggleActive(u)}>\n                  {u.isActive ? 'Deactivate' : 'Restore'}\n                </Button>\n              </li>\n            ))}\n          </ul>\n        </Section>\n      </div>\n\n      <UserDialog open={addingUser} onClose={() => setAddingUser(false)} onSaved={users.refetch} />\n    </div>\n  );\n}\n",
"client/src/pages/SignupPage.jsx": "import { useState } from 'react';\nimport { Link, Navigate, useNavigate, useSearchParams } from 'react-router-dom';\nimport { LuCheck, LuEye, LuEyeOff, LuLeaf } from 'react-icons/lu';\nimport { Button } from '../components/ui/Button';\nimport { errorMessage } from '../lib/api';\nimport { useAuthStore } from '../store/authStore';\n\nconst PERKS = ['One month free, no card needed', 'Your own products and categories', 'Bills keep working without internet'];\n\nexport default function SignupPage() {\n  const { token, signup } = useAuthStore();\n  const navigate = useNavigate();\n  const [params] = useSearchParams();\n  const [form, setForm] = useState({ storeName: '', name: '', email: '', phone: '', password: '' });\n  const [showPassword, setShowPassword] = useState(false);\n  const [error, setError] = useState(null);\n  const [loading, setLoading] = useState(false);\n\n  if (token) return <Navigate to=\"/app\" replace />;\n\n  const set = (key) => (e) => setForm({ ...form, [key]: e.target.value });\n\n  const submit = async (e) => {\n    e.preventDefault();\n    setError(null);\n    setLoading(true);\n    try {\n      await signup(form);\n      const plan = params.get('plan');\n      navigate(plan ? `/app/billing?plan=${plan}&interval=${params.get('interval') || 'MONTHLY'}&seats=${params.get('seats') || 3}` : '/app', {\n        replace: true,\n      });\n    } catch (err) {\n      setError(errorMessage(err));\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const valid = form.storeName.trim().length > 1 && form.name.trim().length > 1 && form.email.includes('@') && form.password.length >= 8;\n\n  return (\n    <div className=\"min-h-[100dvh] bg-slate-50\">\n      <div className=\"mx-auto grid min-h-[100dvh] max-w-5xl items-center gap-8 px-4 py-10 sm:px-6 lg:grid-cols-2\">\n        <div className=\"hidden lg:block\">\n          <Link to=\"/\" className=\"flex items-center gap-2\">\n            <span className=\"grid h-10 w-10 place-items-center rounded-2xl bg-brand text-white\">\n              <LuLeaf size={20} aria-hidden />\n            </span>\n            <span className=\"text-h2 font-semibold\">FreshFlow</span>\n          </Link>\n          <h1 className=\"mt-8\">Set up your store in a minute</h1>\n          <p className=\"mt-2 text-body text-slate-600\">\n            Create the store, add your products, and start billing. You can invite your cashiers whenever you are ready.\n          </p>\n          <ul className=\"mt-6 space-y-2.5\">\n            {PERKS.map((p) => (\n              <li key={p} className=\"flex items-start gap-2.5 text-body text-slate-700\">\n                <LuCheck className=\"mt-0.5 shrink-0 text-brand\" aria-hidden />\n                {p}\n              </li>\n            ))}\n          </ul>\n        </div>\n\n        <div className=\"rounded-4xl bg-white p-6 shadow-lift sm:p-8\">\n          <div className=\"mb-5 flex items-center gap-2 lg:hidden\">\n            <span className=\"grid h-9 w-9 place-items-center rounded-2xl bg-brand text-white\">\n              <LuLeaf size={18} aria-hidden />\n            </span>\n            <span className=\"text-h2 font-semibold\">FreshFlow</span>\n          </div>\n          <h1>Start your free month</h1>\n          <p className=\"mt-1 text-desc text-slate-500\">No card needed. Cancel by simply not paying.</p>\n\n          <form onSubmit={submit} noValidate className=\"mt-5 space-y-4\">\n            <div>\n              <label htmlFor=\"storeName\" className=\"label\">Store name</label>\n              <input id=\"storeName\" className=\"field\" value={form.storeName} onChange={set('storeName')} placeholder=\"Sharma Super Market\" autoComplete=\"organization\" />\n            </div>\n            <div>\n              <label htmlFor=\"name\" className=\"label\">Your name</label>\n              <input id=\"name\" className=\"field\" value={form.name} onChange={set('name')} autoComplete=\"name\" />\n            </div>\n            <div>\n              <label htmlFor=\"email\" className=\"label\">Email address</label>\n              <input id=\"email\" type=\"email\" className=\"field\" value={form.email} onChange={set('email')} autoComplete=\"username\" placeholder=\"you@store.com\" />\n            </div>\n            <div>\n              <label htmlFor=\"phone\" className=\"label\">Mobile (optional)</label>\n              <input id=\"phone\" type=\"tel\" className=\"field\" value={form.phone} onChange={set('phone')} autoComplete=\"tel\" />\n            </div>\n            <div>\n              <label htmlFor=\"password\" className=\"label\">Password</label>\n              <div className=\"relative\">\n                <input\n                  id=\"password\"\n                  type={showPassword ? 'text' : 'password'}\n                  className=\"field pr-11\"\n                  value={form.password}\n                  onChange={set('password')}\n                  autoComplete=\"new-password\"\n                  placeholder=\"At least 8 characters\"\n                />\n                <button\n                  type=\"button\"\n                  onClick={() => setShowPassword((v) => !v)}\n                  className=\"absolute inset-y-0 right-1 my-auto grid h-9 w-9 place-items-center rounded-full text-slate-400 hover:text-slate-700\"\n                  aria-label={showPassword ? 'Hide password' : 'Show password'}\n                >\n                  {showPassword ? <LuEyeOff aria-hidden /> : <LuEye aria-hidden />}\n                </button>\n              </div>\n            </div>\n\n            {error ? <p className=\"rounded-xl bg-rose-50 px-3 py-2 text-desc text-rose-700\" role=\"alert\">{error}</p> : null}\n\n            <Button type=\"submit\" className=\"w-full\" size=\"lg\" loading={loading} disabled={!valid}>\n              Create store\n            </Button>\n          </form>\n\n          <p className=\"mt-4 text-center text-desc text-slate-500\">\n            Already have an account?{' '}\n            <Link to=\"/login\" className=\"font-semibold text-brand-700 hover:underline\">\n              Sign in\n            </Link>\n          </p>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
"client/src/routes/guards.jsx": "import { Link, Navigate, Outlet, useLocation, useOutletContext } from 'react-router-dom';\nimport { LuShieldAlert } from 'react-icons/lu';\nimport { useAuthStore } from '../store/authStore';\n\nexport function RequireAuth({ children }) {\n  const token = useAuthStore((s) => s.token);\n  const location = useLocation();\n  if (!token) return <Navigate to=\"/login\" replace state={{ from: location.pathname }} />;\n  return children;\n}\n\n/** UI-side role gate. The API enforces the same rule with 403s, so this is convenience, not security. */\nexport function RequireRole({ roles }) {\n  const role = useAuthStore((s) => s.user?.role);\n  // Nested outlets do not inherit context automatically; pass the shell's context through.\n  const context = useOutletContext();\n  if (!roles.includes(role)) {\n    return (\n      <div className=\"grid h-full place-items-center p-6\">\n        <div className=\"max-w-sm text-center\">\n          <div className=\"mx-auto mb-4 grid h-12 w-12 place-items-center rounded-full bg-amber-50 text-amber-600\">\n            <LuShieldAlert size={22} aria-hidden />\n          </div>\n          <h1>This area is for store admins</h1>\n          <p className=\"mt-2 text-desc text-slate-500\">\n            Reports, analytics, inventory and settings need an admin account. You can keep selling from the register.\n          </p>\n          <Link to=\"/app\" className=\"mt-5 inline-flex h-10 items-center rounded-full bg-brand px-5 font-semibold text-white hover:bg-brand-700\">\n            Back to register\n          </Link>\n        </div>\n      </div>\n    );\n  }\n  return <Outlet context={context} />;\n}\n",
"client/public/favicon.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"16\" fill=\"#059669\"/><path d=\"M18 40c0-12 9-22 28-24-1 17-10 28-22 28-2 0-4-1-6-4Z\" fill=\"#fff\"/><path d=\"M20 44c6-8 12-13 20-18\" stroke=\"#059669\" stroke-width=\"3\" stroke-linecap=\"round\" fill=\"none\"/></svg>\n",
"client/public/sw.js": "/*\n * FreshFlow app-shell service worker.\n * Lets a terminal reload the POS while the network is down. API calls are never cached here —\n * catalog data lives in IndexedDB and bills go through the outbox sync queue.\n */\nconst CACHE = 'freshflow-shell-v1';\nconst SHELL = ['/', '/index.html', '/favicon.svg'];\n\nself.addEventListener('install', (event) => {\n  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)));\n  self.skipWaiting();\n});\n\nself.addEventListener('activate', (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))),\n  );\n  self.clients.claim();\n});\n\nself.addEventListener('fetch', (event) => {\n  const { request } = event;\n  if (request.method !== 'GET') return;\n  const url = new URL(request.url);\n  if (url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return;\n\n  if (request.mode === 'navigate') {\n    event.respondWith(\n      fetch(request)\n        .then((response) => {\n          const copy = response.clone();\n          caches.open(CACHE).then((cache) => cache.put('/index.html', copy));\n          return response;\n        })\n        .catch(() => caches.match('/index.html')),\n    );\n    return;\n  }\n\n  if (url.pathname.startsWith('/assets/')) {\n    // Vite asset filenames are content-hashed, so cache-first is always correct.\n    event.respondWith(\n      caches.match(request).then(\n        (hit) =>\n          hit ||\n          fetch(request).then((response) => {\n            const copy = response.clone();\n            caches.open(CACHE).then((cache) => cache.put(request, copy));\n            return response;\n          }),\n      ),\n    );\n  }\n});\n"
};

async function writeProject() {
  const entries = Object.entries(FILES);
  for (const [relativePath, contents] of entries) {
    const target = path.join(projectDir, relativePath);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, contents, 'utf8');
  }
  return entries.length;
}

async function zipProject() {
  let archiver;
  try {
    ({ default: archiver } = await import('archiver'));
  } catch {
    return null;
  }
  const zipPath = path.join(outDir, `${projectName}.zip`);
  await new Promise((resolve, reject) => {
    const output = createWriteStream(zipPath);
    const archive = archiver('zip', { zlib: { level: 9 } });
    output.on('close', resolve);
    archive.on('error', reject);
    archive.pipe(output);
    archive.directory(projectDir, projectName);
    archive.finalize();
  });
  return zipPath;
}

const count = await writeProject();
console.log(`Wrote ${count} files to ${projectDir}`);

if (makeZip) {
  const zipPath = await zipProject();
  if (zipPath) console.log(`Created ${zipPath}`);
  else console.log('Skipped the archive: run `npm i archiver` first, or zip the folder yourself.');
}

console.log('');
console.log('Next steps:');
